-- Fast lookup of canonical genre tags for UI categorization
local GENRE_TAG_SET = {}
do
  for _, entry in ipairs(GENRE_KEYWORDS) do
    GENRE_TAG_SET[string.lower(entry.tag)] = true
  end
end

-- Map render performance: spatial grid + on-screen dot budget
local MAP_GRID_RES = 32
-- Safety cap only — libraries well under this draw every visible sample.
-- If over budget, a viewport-relative pick grid keeps on-screen density
-- roughly constant at every zoom instead of packing more dots when zoomed in.
local MAP_DOT_BUDGET = 40000
local MAP_ZOOM_MIN = 1.0
local MAP_ZOOM_MAX = 16.0

