function apply_seq_project_state(cfg)
  if type(cfg) ~= "table" then
    return
  end
  if cfg.seq_tracks and type(cfg.seq_tracks) == "table" then
    state.seq_tracks = {}
    for _, entry in ipairs(cfg.seq_tracks) do
      if type(entry) == "table" and entry.id then
        local slot = {
          id = entry.id,
          name = entry.name or "Track",
          reaper_track_guid = entry.reaper_track_guid,
          sample_path = entry.sample_path,
          sample_name = entry.sample_name,
          sample_tag = entry.sample_tag,
          volume = entry.volume,
          pan = entry.pan,
          mute = entry.mute,
          solo = entry.solo,
          overlap = entry.overlap,
          env = entry.env,
          layers = entry.layers,
          midi_lo = entry.midi_lo,
          midi_hi = entry.midi_hi,
        }
        seq_normalize_slot_mix(slot)
        table.insert(state.seq_tracks, slot)
        if type(entry.id) == "number" and entry.id >= state.seq_track_next_id then
          state.seq_track_next_id = entry.id + 1
        end
      end
    end
  end
  if cfg.selected_seq_track and type(cfg.selected_seq_track) == "number" then
    state.selected_seq_track = cfg.selected_seq_track
  end
  if type(cfg.seq_folder_guid) == "string" and cfg.seq_folder_guid ~= "" then
    state.seq_folder_guid = cfg.seq_folder_guid
  end
  if cfg.seq_panel_width and type(cfg.seq_panel_width) == "number" then
    state.seq_panel_width = cfg.seq_panel_width
  end
  if type(cfg.seq_follow_arrange) == "boolean" then
    state.seq_follow_arrange = cfg.seq_follow_arrange
  end
  if type(cfg.seq_view_start_qn) == "number" then
    state.seq_view_start_qn = cfg.seq_view_start_qn
  end
  if type(cfg.seq_view_span_qn) == "number" and cfg.seq_view_span_qn > 0 then
    state.seq_view_span_qn = cfg.seq_view_span_qn
  end
  if type(cfg.seq_grid_qn) == "number" and cfg.seq_grid_qn > 0 then
    state.seq_grid_qn = cfg.seq_grid_qn
  end
  if type(cfg.seq_gen_style) == "string" and cfg.seq_gen_style ~= "" then
    state.seq_gen_style = cfg.seq_gen_style
  end
  if type(cfg.seq_groove) == "string" and cfg.seq_groove ~= "" then
    state.seq_groove = cfg.seq_groove
  end
  if type(cfg.seq_lane_zoom) == "number" and cfg.seq_lane_zoom > 0 then
    state.seq_lane_zoom = cfg.seq_lane_zoom
  end
  if cfg.seq_regions and type(cfg.seq_regions) == "table" then
    state.seq_regions = cfg.seq_regions
    for _, region in ipairs(state.seq_regions) do
      if type(region) == "table" and type(region.id) == "number" and region.id >= state.seq_region_next_id then
        state.seq_region_next_id = region.id + 1
      end
    end
  end
  if cfg.seq_patterns and type(cfg.seq_patterns) == "table" then
    state.seq_patterns = cfg.seq_patterns
  end
  if type(cfg.seq_region_next_id) == "number" then
    state.seq_region_next_id = math.max(state.seq_region_next_id, cfg.seq_region_next_id)
  end
  if type(cfg.seq_pattern_next_id) == "number" then
    state.seq_pattern_next_id = cfg.seq_pattern_next_id
  end
  if type(cfg.seq_pool_next_id) == "number" then
    state.seq_pool_next_id = cfg.seq_pool_next_id
  end
  if type(cfg.selected_seq_region_id) == "number" then
    state.selected_seq_region_id = cfg.selected_seq_region_id
  end
  if cfg.seq_expanded_tracks and type(cfg.seq_expanded_tracks) == "table" then
    state.seq_expanded_tracks = cfg.seq_expanded_tracks
  end
  if cfg.seq_kit_history and type(cfg.seq_kit_history) == "table" then
    state.seq_kit_history = cfg.seq_kit_history
    for _, entry in ipairs(state.seq_kit_history) do
      if type(entry) == "table" and type(entry.id) == "number" and entry.id >= state.seq_kit_history_next_id then
        state.seq_kit_history_next_id = entry.id + 1
      end
    end
  end
  if type(cfg.seq_kit_history_next_id) == "number" then
    state.seq_kit_history_next_id = math.max(state.seq_kit_history_next_id, cfg.seq_kit_history_next_id)
  end
  migrate_seq_region_grooves()
end

function build_seq_project_state_payload()
  return {
    version = 1,
    seq_tracks = state.seq_tracks,
    selected_seq_track = state.selected_seq_track,
    seq_folder_guid = state.seq_folder_guid,
    seq_panel_width = state.seq_panel_width,
    seq_follow_arrange = state.seq_follow_arrange,
    seq_view_start_qn = state.seq_view_start_qn,
    seq_view_span_qn = state.seq_view_span_qn,
    seq_grid_qn = state.seq_grid_qn,
    seq_gen_style = state.seq_gen_style,
    seq_groove = state.seq_groove,
    seq_lane_zoom = state.seq_lane_zoom,
    seq_regions = state.seq_regions,
    seq_patterns = state.seq_patterns,
    seq_region_next_id = state.seq_region_next_id,
    seq_pattern_next_id = state.seq_pattern_next_id,
    seq_pool_next_id = state.seq_pool_next_id,
    selected_seq_region_id = state.selected_seq_region_id,
    seq_expanded_tracks = state.seq_expanded_tracks,
    seq_kit_history = state.seq_kit_history,
    seq_kit_history_next_id = state.seq_kit_history_next_id,
  }
end

function save_seq_project_state(proj)
  if not r.SetProjExtState then
    return
  end
  proj = proj or get_current_project()
  if not is_valid_project(proj) then
    return
  end
  local ok, serialized = pcall(json_encode, build_seq_project_state_payload())
  if ok and type(serialized) == "string" then
    pcall(r.SetProjExtState, proj, PROJ_EXT_SECTION, PROJ_EXT_KEY_SEQUENCER, serialized)
  end
end

function load_seq_project_state(proj)
  proj = proj or get_current_project()
  reset_seq_project_state()
  if not is_valid_project(proj) then
    return
  end
  local loaded = false
  if r.GetProjExtState then
    local ok, serialized = r.GetProjExtState(proj, PROJ_EXT_SECTION, PROJ_EXT_KEY_SEQUENCER)
    if ok and ok ~= 0 and serialized and serialized ~= "" then
      local parse_ok, cfg = pcall(json_decode, serialized)
      if parse_ok and type(cfg) == "table" then
        apply_seq_project_state(cfg)
        loaded = true
      end
    end
  end
  if loaded then
    legacy_seq_project_state = nil
  elseif legacy_seq_project_state and type(legacy_seq_project_state) == "table" then
    apply_seq_project_state(legacy_seq_project_state)
    legacy_seq_project_state = nil
    save_seq_project_state(proj)
  end
  if seq_apply_all_slot_mix_to_reaper then
    seq_apply_all_slot_mix_to_reaper()
  end
end

function sync_project_state_if_needed()
  local proj = get_current_project()
  if not proj then
    -- Project is closing or none is active; keep in-memory state.
    return
  end
  local token = tostring(proj)
  if loaded_project_token ~= token then
    if is_valid_project(loaded_project) then
      save_seq_project_state(loaded_project)
    end
    load_seq_project_state(proj)
    loaded_project = proj
    loaded_project_token = token
  end
end

local function load_config()
  local file = io.open(CONFIG_PATH, "r")
  if file then
    local content = file:read("*all")
    file:close()
    if content and content ~= "" then
      local success, cfg = pcall(json_decode, content)
      if success and cfg and type(cfg) == "table" then
        -- Ensure folders is an array of strings (normalized)
        if cfg.folders and type(cfg.folders) == "table" then
          state.folders = {}
          for i, folder in ipairs(cfg.folders) do
            if type(folder) == "string" then
              table.insert(state.folders, normalize_path(folder))
            end
          end
        else
          state.folders = {}
        end
        state.map_seed = cfg.map_seed or 1337
        -- Zoom and pan are not saved - always start at defaults
        -- Load dot customization settings
        state.dot_radius = cfg.dot_radius or 2.0
        state.dot_outline_size = cfg.dot_outline_size or 4.0
        state.dot_outline_thickness = cfg.dot_outline_thickness or 3.0
        -- Load colors (RGB format)
        if cfg.dot_color then
          state.dot_color = cfg.dot_color
        elseif cfg.dot_color_r then
          -- Convert old RGB component format to RGB color value
          state.dot_color = build_rgb(cfg.dot_color_r or 68, cfg.dot_color_g or 170, cfg.dot_color_b or 85)
        else
          state.dot_color = 0x44AA55
        end
        if cfg.dot_outline_color then
          state.dot_outline_color = cfg.dot_outline_color
        elseif cfg.dot_outline_color_r then
          state.dot_outline_color = build_rgb(cfg.dot_outline_color_r or 255, cfg.dot_outline_color_g or 0, cfg.dot_outline_color_b or 255)
        else
          state.dot_outline_color = 0xFF00FF
        end
        if cfg.dot_hover_color then
          state.dot_hover_color = cfg.dot_hover_color
        elseif cfg.dot_hover_color_r then
          state.dot_hover_color = build_rgb(cfg.dot_hover_color_r or 200, cfg.dot_hover_color_g or 76, cfg.dot_hover_color_b or 77)
        else
          state.dot_hover_color = 0xC84D
        end
        state.dot_detection_multiplier = cfg.dot_detection_multiplier or 16.0
        -- Load preview volume
        state.preview_volume = cfg.preview_volume or 1.0
        -- Load tag colors
        if cfg.tag_colors and type(cfg.tag_colors) == "table" then
          for tag, color in pairs(cfg.tag_colors) do
            if type(color) == "number" then
              state.tag_colors[tag] = color
            end
          end
        end
        if cfg.active_view == "sample_map" or cfg.active_view == "sequencer" then
          state.active_view = cfg.active_view
        end
        -- Sequencer scroll behavior
        if cfg.seq_scroll_mode == "v_as_h" or cfg.seq_scroll_mode == "natural" then
          state.seq_scroll_mode = cfg.seq_scroll_mode
        end
        if type(cfg.seq_follow_hovered_item) == "boolean" then
          state.seq_follow_hovered_item = cfg.seq_follow_hovered_item
        end
        if type(cfg.group_seq_tracks_in_folder) == "boolean" then
          state.group_seq_tracks_in_folder = cfg.group_seq_tracks_in_folder
        end
        -- Customizable mouse modifiers (validate each value)
        if cfg.mouse_mods and type(cfg.mouse_mods) == "table" then
          local valid = { none = true, shift = true, alt = true, ctrl = true, cmd = true }
          state.mouse_mods = state.mouse_mods or {}
          for action, default in pairs(MOUSE_MOD_DEFAULTS) do
            local v = cfg.mouse_mods[action]
            state.mouse_mods[action] = (type(v) == "string" and valid[v]) and v or default
          end
        end
        if cfg.collapse_children_tags == "on"
            or cfg.collapse_children_tags == "off"
            or cfg.collapse_children_tags == "dynamic" then
          state.collapse_children_tags = cfg.collapse_children_tags
        end
        if type(cfg.collapse_children_tags_width) == "number" then
          state.collapse_children_tags_width = math.max(400, math.min(4000, cfg.collapse_children_tags_width))
        end
        if type(cfg.seq_tracks) == "table"
            or type(cfg.seq_regions) == "table"
            or type(cfg.seq_patterns) == "table" then
          legacy_seq_project_state = {
            seq_tracks = cfg.seq_tracks,
            selected_seq_track = cfg.selected_seq_track,
            seq_panel_width = cfg.seq_panel_width,
            seq_follow_arrange = cfg.seq_follow_arrange,
            seq_view_start_qn = cfg.seq_view_start_qn,
            seq_view_span_qn = cfg.seq_view_span_qn,
            seq_grid_qn = cfg.seq_grid_qn,
            seq_gen_style = cfg.seq_gen_style,
            seq_groove = cfg.seq_groove,
            seq_lane_zoom = cfg.seq_lane_zoom,
            seq_regions = cfg.seq_regions,
            seq_patterns = cfg.seq_patterns,
            seq_region_next_id = cfg.seq_region_next_id,
            seq_pattern_next_id = cfg.seq_pattern_next_id,
            seq_pool_next_id = cfg.seq_pool_next_id,
            selected_seq_region_id = cfg.selected_seq_region_id,
            seq_expanded_tracks = cfg.seq_expanded_tracks,
            seq_kit_history = cfg.seq_kit_history,
            seq_kit_history_next_id = cfg.seq_kit_history_next_id,
          }
        end
        log("Loaded config: " .. #state.folders .. " folder(s)")
        if #state.folders > 0 then
          for i, folder in ipairs(state.folders) do
            log("  Folder " .. i .. ": " .. folder)
          end
        end
      else
        log("Config file exists but couldn't parse it: " .. tostring(cfg))
      end
    end
  else
    log("No config file found, starting fresh")
  end
end


local function serialize_table(t, indent)
  indent = indent or ""
  local result = "{\n"
  for k, v in pairs(t) do
    result = result .. indent .. "  "
    if type(k) == "string" then
      result = result .. '["' .. k .. '"]'
    else
      result = result .. '[' .. tostring(k) .. ']'
    end
    result = result .. " = "
    if type(v) == "table" then
      result = result .. serialize_table(v, indent .. "  ")
    elseif type(v) == "string" then
      result = result .. '"' .. v .. '"'
    else
      result = result .. tostring(v)
    end
    result = result .. ",\n"
  end
  result = result .. indent .. "}"
  return result
end

local function save_config()
  local cfg = {
    folders = state.folders,
    map_seed = state.map_seed,
    -- Save dot customization settings
    dot_radius = state.dot_radius,
    dot_outline_size = state.dot_outline_size,
    dot_outline_thickness = state.dot_outline_thickness,
    dot_color = state.dot_color,
    dot_outline_color = state.dot_outline_color,
    dot_hover_color = state.dot_hover_color,
    dot_detection_multiplier = state.dot_detection_multiplier,
    preview_volume = state.preview_volume,
    tag_colors = state.tag_colors,
    active_view = state.active_view,
    seq_scroll_mode = state.seq_scroll_mode,
    seq_follow_hovered_item = state.seq_follow_hovered_item == true,
    group_seq_tracks_in_folder = state.group_seq_tracks_in_folder ~= false,
    mouse_mods = state.mouse_mods,
    collapse_children_tags = state.collapse_children_tags,
    collapse_children_tags_width = state.collapse_children_tags_width,
  }
  local file = io.open(CONFIG_PATH, "w")
  if file then
    local json_str = json_encode(cfg)
    file:write(json_str)
    file:close()
    log("Saved config with " .. #state.folders .. " folder(s)")
  else
    log("Failed to save config file")
  end
  save_seq_project_state(loaded_project or get_current_project())
end


-- Run external Python analyzer to compute metadata (e.g., frequency/RMS)
-- Expected JSON output: { dominant_freq: number, rms_energy: number }
local function run_external_analyzer(path)
  local analyzer_start = r.time_precise()
  
  -- Validate analyzer script exists
  local t0 = r.time_precise()
  local fh = io.open(EXTERNAL_ANALYZER, "r")
  if not fh then
    return nil, "analyzer script missing"
  end
  fh:close()
  local check_time = (r.time_precise() - t0) * 1000

  local t1 = r.time_precise()
  local cmd = table.concat({
    shell_escape(PYTHON_BIN),
    shell_escape(EXTERNAL_ANALYZER),
    shell_escape(path)
  }, " ")

  -- Try to capture both stdout and stderr
  -- On macOS, we can redirect stderr to stdout with 2>&1
  local cmd_with_stderr = cmd .. " 2>&1"
  local pipe = io.popen(cmd_with_stderr, "r")
  if not pipe then
    return nil, "failed to start analyzer"
  end
  local spawn_time = (r.time_precise() - t1) * 1000

  local t2 = r.time_precise()
  local output = pipe:read("*all")
  local ok, why, code = pipe:close()
  local exec_time = (r.time_precise() - t2) * 1000
  
  if not ok then
    return nil, "analyzer process failed"
  end

  if not output or output == "" then
    return nil, "empty analyzer output"
  end

  local t3 = r.time_precise()
  local success, data = pcall(json_decode, output)
  local parse_time = (r.time_precise() - t3) * 1000
  
  local total_analyzer_time = (r.time_precise() - analyzer_start) * 1000
  
  if success and type(data) == "table" then
    -- Remove debug key before returning (don't store it in sample data)
    data._debug = nil
    
    -- Analyzer timing removed - use scan logs instead
    
    return data, nil
  end

  return nil, "invalid analyzer JSON"
end


-- Start an analyzer process for a file (non-blocking)
-- Returns true if process started successfully, false otherwise
local function start_analyzer_process(path, mode)
  -- Check if analyzer script exists
  local fh = io.open(EXTERNAL_ANALYZER, "r")
  if not fh then
    return false
  end
  fh:close()
  
  -- Build command
  local cmd_parts = {
    shell_escape(PYTHON_BIN),
    shell_escape(EXTERNAL_ANALYZER),
  }
  if mode == "transient" then
    table.insert(cmd_parts, "--transient")
  end
  table.insert(cmd_parts, shell_escape(path))
  local cmd = table.concat(cmd_parts, " ")
  
  local cmd_with_stderr = cmd .. " 2>&1"
  local pipe = io.popen(cmd_with_stderr, "r")
  
  if pipe then
    table.insert(state.active_processes, {
      path = path,
      pipe = pipe,
      start_time = r.time_precise(),
      mode = mode,
    })
    return true
  end
  
  return false
end


-- Check for completed analyzer processes and update analyzer_results
-- Only checks one process per call to avoid blocking (called each frame)
-- Returns true if a process was checked/completed, false if no processes to check
local function check_analyzer_processes()
  if #state.active_processes == 0 then
    return false
  end
  
  -- Check only the first process (oldest) to minimize blocking
  local proc = state.active_processes[1]
  local pipe = proc.pipe
  
  -- Check timeout first (non-blocking check)
  local elapsed = r.time_precise() - proc.start_time
  if elapsed > 30.0 then
    -- Timeout - close pipe and mark as failed
    local close_ok, close_err = pcall(function() return pipe:close() end)
    if not close_ok then
      add_scan_log(string.format("Warning: failed to close timed-out pipe for %s: %s", proc.path:match("([^/]+)$") or proc.path, tostring(close_err)))
    end
    state.analyzer_results[proc.path] = {data = nil, err = "analyzer timeout"}
    add_scan_log(string.format("Analyzer timeout on %s (continuing)", proc.path:match("([^/]+)$") or proc.path))
    table.remove(state.active_processes, 1)
    return true
  end
  
  -- Try to read from pipe (this may block briefly if process is still running)
  -- We only check one per frame to keep GUI responsive
  -- Use non-blocking check: try to read a line, but don't wait if process is still running
  local line = pipe:read("*line")
  
  if line then
    -- Process has output, read remaining
    local output = line
    local rest = pipe:read("*all")
    if rest then
      output = output .. "\n" .. rest
    end

    -- Always close the pipe after reading
    local ok, why, code = pcall(function() return pipe:close() end)
    if not ok then
      -- If close fails, log it but continue
      add_scan_log(string.format("Warning: failed to close pipe for %s: %s", proc.path:match("([^/]+)$") or proc.path, tostring(why)))
    end
    
    add_scan_log(string.format("Process closed: ok=%s, output_len=%d", tostring(ok), #output))

    if output and output ~= "" then
      local success, data = pcall(json_decode, output)
      if success and type(data) == "table" then
        data._debug = nil
        state.analyzer_results[proc.path] = {data = data, err = nil}

        if proc.mode == "transient" then
          add_scan_log(string.format("Transient scan: %s (onset=%.4f, transient_end=%.4f)", proc.path:match("([^/]+)$") or proc.path, data.onset or 0, data.transient_end or 0))
        else
          add_scan_log(string.format("Analyzer completed: %s (freq=%.1f, rms=%.3f, playback=%s)", proc.path:match("([^/]+)$") or proc.path, data.dominant_freq or 0, data.rms_energy or 0, tostring(data.playback_type or "?")))
        end
      else
        state.analyzer_results[proc.path] = {data = nil, err = "invalid analyzer JSON"}
        add_scan_log(string.format("Analyzer error on %s: invalid JSON: %s", proc.path:match("([^/]+)$") or proc.path, tostring(data)))
      end
    else
      state.analyzer_results[proc.path] = {data = nil, err = "analyzer process failed"}
      add_scan_log(string.format("Analyzer error on %s: process failed (ok=%s, why=%s, code=%s)", proc.path:match("([^/]+)$") or proc.path, tostring(ok), tostring(why), tostring(code)))
    end
  
    -- Remove from active processes
    table.remove(state.active_processes, 1)
    return true
  end
  
  -- Process still running, no output yet - pipe remains open (will be checked next frame)
  -- This is OK as long as we limit concurrent processes and handle timeouts
  return false
end


-- Manage the analyzer process pool: start new processes when slots available
local function process_analyzer_queue()
  if state.external_disabled then
    return
  end
  if #state.active_processes == 0 and #state.analyzer_queue == 0 then
    return
  end

  -- Check for completed processes (check one at a time to avoid blocking)
  check_analyzer_processes()

  -- Start new processes if we have slots available and files in queue
  while #state.active_processes < state.max_concurrent_analyzers and #state.analyzer_queue > 0 do
    local path = table.remove(state.analyzer_queue, 1)
    local mode = nil
    if state.analyzer_path_mode and path then
      mode = state.analyzer_path_mode[path]
      state.analyzer_path_mode[path] = nil
    end
    if not mode then
      mode = state.analyzer_mode
    end
    if start_analyzer_process(path, mode) then
      -- ok
    else
      local fh = io.open(EXTERNAL_ANALYZER, "r")
      if not fh then
        state.external_disabled = true
        state.analyzer_warned = true
        break
      end
      fh:close()
      state.analyzer_results[path] = {data = nil, err = "failed to start analyzer"}
    end
  end
end


local function folders_match(a, b)
  if type(a) ~= "table" or type(b) ~= "table" then return false end
  if #a ~= #b then return false end
  for i = 1, #a do
    -- Normalize paths before comparison
    local norm_a = normalize_path(a[i] or "")
    local norm_b = normalize_path(b[i] or "")
    if norm_a ~= norm_b then return false end
  end
  return true
end


-- Layout samples on the 2D map based on their audio characteristics
local function layout_samples()
  if #state.samples == 0 then return end

  -- Use Lua calculation (Python analyzer doesn't support layout calculations)
  -- Coordinates are cached after calculation, so this only runs when needed

  -- Calculate positioning scores for all samples
  local len_scores = {}
  local freq_scores = {}
  local rms_scores = {}
  local size_scores = {}

  -- Lua doesn't have log10, so use log(x) / log(10)
  local log10 = math.log(10)
  for _, s in ipairs(state.samples) do
    table.insert(len_scores, math.log(math.max(sample_map_duration(s), 0.01)) / log10)
    -- Use dominant frequency (log scale for better distribution)
    -- Clamp frequency to valid range (20Hz to 20kHz)
    -- Missing analyzer data falls back to 440Hz (A4) — clusters incomplete samples mid-band
    local freq = math.max(20.0, math.min(20000.0, s.dominant_freq or 440.0))
    table.insert(freq_scores, math.log(freq) / log10)
    -- Store RMS energy (use log scale for better distribution)
    local rms = math.max(1e-6, s.rms_energy or 0.0)
    table.insert(rms_scores, math.log(rms) / log10)
    -- Store file size (use log scale for better distribution)
    local size = math.max(1, s.file_size or 1)
    table.insert(size_scores, math.log(size) / log10)
  end

  -- Check if frequencies are too similar (all defaulting to 440Hz)
  local freq_min = freq_scores[1]
  local freq_max = freq_scores[1]
  for _, v in ipairs(freq_scores) do
    freq_min = math.min(freq_min, v)
    freq_max = math.max(freq_max, v)
  end
  local freq_range = freq_max - freq_min

  -- Check if RMS is all zeros
  local rms_min = rms_scores[1]
  local rms_max = rms_scores[1]
  for _, v in ipairs(rms_scores) do
    rms_min = math.min(rms_min, v)
    rms_max = math.max(rms_max, v)
  end
  local rms_range = rms_max - rms_min
  local rms_all_zero = rms_range < 1e-6  -- RMS is essentially zero

  -- Decide what to use for Y axis
  local use_rms_for_y = false
  local use_size_for_y = false

  if freq_range < 0.01 then
    -- Frequency range too small
    if rms_all_zero then
      -- RMS is also zero, use file size
      use_size_for_y = true
    else
      use_rms_for_y = true
    end
  end

  math.randomseed(state.map_seed)

  -- Ensure we use the full range: find min/max for both axes
  local len_min, len_max = len_scores[1], len_scores[1]
  local y_min, y_max

  for _, v in ipairs(len_scores) do
    len_min = math.min(len_min, v)
    len_max = math.max(len_max, v)
  end

  -- Use RMS, file size, or frequency for Y axis
  if use_size_for_y then
    y_min, y_max = size_scores[1], size_scores[1]
    for _, v in ipairs(size_scores) do
      y_min = math.min(y_min, v)
      y_max = math.max(y_max, v)
    end
  elseif use_rms_for_y then
    y_min, y_max = rms_scores[1], rms_scores[1]
    for _, v in ipairs(rms_scores) do
      y_min = math.min(y_min, v)
      y_max = math.max(y_max, v)
    end
  else
    y_min, y_max = freq_scores[1], freq_scores[1]
    for _, v in ipairs(freq_scores) do
      y_min = math.min(y_min, v)
      y_max = math.max(y_max, v)
    end
  end

  -- Normalize function that ensures full range usage with padding for better spread
  local function normalize(value, min_val, max_val, padding)
    padding = padding or 0.1  -- 10% padding on each side
    if max_val - min_val < 1e-9 then
      return 0.5  -- All same value, center it
    end
    -- Normalize to 0-1 range
    local normalized = (value - min_val) / (max_val - min_val)
    -- Scale to use more of the available space (with padding)
    -- Maps 0-1 to padding to (1-padding)
    return padding + normalized * (1.0 - 2.0 * padding)
  end

  -- Position each sample
  for i, s in ipairs(state.samples) do
    -- Preserve existing tags before modifying sample (make a copy, not a reference)
    local preserved_tags = nil
    if s.tags and type(s.tags) == "table" then
      preserved_tags = {}
      for _, tag in ipairs(s.tags) do
        table.insert(preserved_tags, tag)
      end
    end

    -- X-axis: duration (left = short, right = long)
    local x = normalize(len_scores[i], len_min, len_max, 0.05)  -- 5% padding
    -- Y-axis: dominant frequency, RMS energy, or file size (top = high, bottom = low)
    -- Use full range (0.0 padding) to spread from top to bottom
    local y_value
    if use_size_for_y then
      y_value = size_scores[i]
    elseif use_rms_for_y then
      y_value = rms_scores[i]
    else
      y_value = freq_scores[i]
    end
    local y_normalized = normalize(y_value, y_min, y_max, 0.0)  -- No padding - use full range
    local y = 1.0 - y_normalized  -- Invert so highest value is at top
    -- Add jitter to avoid clustering
    local jx = (math.random() - 0.5) * 0.04
    local jy = (math.random() - 0.5) * 0.04
    s.x = math.max(0.0, math.min(1.0, x + jx))
    s.y = math.max(0.0, math.min(1.0, y + jy))
    -- Use customizable dot color, with slight variation for mono samples
    local base_color = state.dot_color or 0x44AA55FF  -- RRGGBBAA format
    local base_r, base_g, base_b = extract_rgb_rrgbbaa(base_color)
    local base_alpha = math.floor(base_color % 256)
    if s.channels == 1 then
      -- Mono: use lighter version (add 50% to each component, clamped to 255)
      local mono_r = math.min(255, math.floor(base_r * 1.5))
      local mono_g = math.min(255, math.floor(base_g * 1.5))
      local mono_b = math.min(255, math.floor(base_b * 1.5))
      s.color = build_color_rrgbbaa(mono_r, mono_g, mono_b, base_alpha)
    else
      -- Stereo: use base customizable color directly
      s.color = base_color
    end
    -- Use customizable hover color directly (RRGGBBAA format)
    s.hot_color = state.dot_hover_color or 0xFFC84DFF

    -- Restore preserved tags
    if preserved_tags then
      s.tags = preserved_tags
    end
  end

  state.map_layout_version = (state.map_layout_version or 0) + 1

  -- Layout debug logs removed - happens during scanning
end


local function hydrate_sample_runtime(sample)
  if not sample then return end
  if sample.hot_color == nil then
    sample.hot_color = state.dot_hover_color or 0xFFC84DFF
  end
  if sample.samplerate == nil and sample.sample_rate ~= nil then
    sample.samplerate = sample.sample_rate
  end
  if sample.samplerate == nil then
    sample.samplerate = 44100
  end
  if sample.file_size == nil then
    local dur = sample.duration or 0
    local bps = sample.bps or 0
    sample.file_size = math.max(0, math.floor(bps * dur + 0.5))
  end
end

-- Prepare one cached sample. full_tag_backfill runs expensive genre/loop inference.
local function prepare_cached_sample(s, full_tag_backfill)
  if type(s) ~= "table" or not s.path or not s.name then
    return nil
  end
  s.path = normalize_path(s.path)
  if not s.x then s.x = 0.5 end
  if not s.y then s.y = 0.5 end

  if not s.tags or type(s.tags) ~= "table" then
    s.tags = infer_tags_from_path(s.path, s.folder or "")
  end

  if s.sample_type and (s.sample_type == "Drum" or s.sample_type == "Swell") then
    local has_tag = false
    for _, tag in ipairs(s.tags) do
      if tag == s.sample_type then
        has_tag = true
        break
      end
    end
    if not has_tag then
      table.insert(s.tags, s.sample_type)
    end
  end

  if full_tag_backfill then
    apply_loop_oneshot_tag(s, detect_loop_or_oneshot(s.path, s.folder or "", s.playback_type))
    s.tags = append_unique_tags(s.tags, infer_genre_tags_from_path(s.path, s.folder or ""))
  end

  hydrate_sample_runtime(s)
  return s
end

local function tag_schema_needs_backfill(data)
  local ver = tonumber(data and data.tag_schema_version) or 0
  if ver < TAG_SCHEMA_VERSION then
    return true, true
  end
  return false, false
end

local function is_library_loading()
  local job = state.library_load
  return job ~= nil and job.phase ~= "done" and job.phase ~= "miss"
end

local function begin_library_load()
  state.library_ready = false
  clear_genre_tag_dir_cache()
  state.library_load = {
    phase = "init",
    format = nil,
    path = nil,
    content = nil,
    data = nil,
    raw_samples = nil,
    cleaned = {},
    index = 1,
    needs_tag_backfill = false,
    stamp_schema = false,
    needs_layout = false,
    total = 0,
    started = r.time_precise(),
    message = "Loading sample library…",
    progress = 0,
  }
  log("Starting deferred library load")
end

local function finish_library_miss(reason)
  local job = state.library_load
  if job then
    job.phase = "miss"
    job.message = reason or "No sample cache"
    job.progress = 1
  end
  state.library_ready = true
  state.library_load = nil
  log(reason or "Library cache miss")
  refresh_scan_folder_availability()
  if #state.folders > 0 then
    state._enqueue_scan_after_load = true
  end
end

local function finish_library_hit(job)
  state.samples = job.cleaned

  local data = job.data or {}
  if data.scan_queue and type(data.scan_queue) == "table" and #data.scan_queue > 0 then
    state.scan_queue = data.scan_queue
    state.scan_total = data.scan_total or (#state.samples + #state.scan_queue)
    state.scan_started = data.scan_started or r.time_precise()
    log(string.format("Resuming interrupted scan: %d files remaining", #state.scan_queue))
  else
    state.scan_queue = {}
    state.scan_total = 0
  end

  if data.analyzer_queue and type(data.analyzer_queue) == "table" and #data.analyzer_queue > 0 then
    state.analyzer_queue = data.analyzer_queue
  else
    state.analyzer_queue = {}
  end
  if data.analyzer_results and type(data.analyzer_results) == "table" then
    state.analyzer_results = data.analyzer_results
  else
    state.analyzer_results = {}
  end
  state.analyzer_mode = data.analyzer_mode
  state.analyzer_path_mode = {}
  if state.analyzer_mode == "transient" then
    state.analyzer_job_label = "Scanning transient/sustain"
    for _, path in ipairs(state.analyzer_queue) do
      state.analyzer_path_mode[path] = "transient"
    end
  end
  if data.analyzer_pending and state.analyzer_mode ~= "transient" then
    for _, sample in ipairs(state.samples) do
      if not sample.dominant_freq then
        table.insert(state.analyzer_queue, sample.path)
      end
    end
  end

  if job.needs_layout then
    layout_samples()
    log("Re-layouting samples (missing/invalid coordinates)")
  else
    log("Using cached coordinates (no layout needed)")
  end

  rebuild_tag_index()
  rebuild_samples_path_index()
  refresh_scan_folder_availability()

  if job.stamp_schema or job.needs_tag_backfill then
    state.tag_schema_dirty = true
  end

  -- Rewrite fast Lua cache after JSON migration or schema stamp (handled in loop).
  if job.format == "json" or state.tag_schema_dirty then
    state._save_library_after_load = true
  end

  job.phase = "done"
  job.progress = 1
  job.message = string.format("Loaded %d samples", #state.samples)
  state.library_ready = true
  state.library_load = nil
  log(string.format(
    "Library loaded (%s): %d samples in %.0fms",
    job.format or "?",
    #state.samples,
    (r.time_precise() - job.started) * 1000
  ))
end

local function process_library_load_slice(max_ms)
  local job = state.library_load
  if not job or job.phase == "done" or job.phase == "miss" then
    return false
  end
  max_ms = max_ms or LIBRARY_LOAD_SLICE_MS
  local deadline = r.time_precise() + (max_ms / 1000.0)

  while r.time_precise() < deadline do
    if job.phase == "init" then
      local lua_file = io.open(DATA_LUA_PATH, "r")
      if lua_file then
        lua_file:close()
        job.format = "lua"
        job.path = DATA_LUA_PATH
        job.message = "Reading Lua cache…"
      else
        local json_file = io.open(DATA_PATH, "r")
        if json_file then
          json_file:close()
          job.format = "json"
          job.path = DATA_PATH
          job.message = "Reading JSON cache…"
        else
          finish_library_miss("Cache file not found")
          return false
        end
      end
      job.phase = "read"

    elseif job.phase == "read" then
      if job.format == "lua" then
        -- loadfile avoids holding a second giant string copy in Lua
        job.message = "Decoding Lua cache…"
        job.phase = "decode"
        job.progress = 0.05
      else
        local file = io.open(job.path, "r")
        if not file then
          finish_library_miss("Cache file cannot be opened")
          return false
        end
        job.content = file:read("*all")
        file:close()
        if not job.content or job.content == "" then
          finish_library_miss("Cache file is empty")
          return false
        end
        log(string.format("Cache file size: %d bytes (json)", #job.content))
        job.message = "Decoding JSON cache…"
        job.phase = "decode"
        job.progress = 0.05
      end

    elseif job.phase == "decode" then
      local data
      if job.format == "lua" then
        local loader, err
        if loadfile then
          local ok_lf, a, b = pcall(loadfile, job.path)
          if ok_lf then
            loader, err = a, b
          end
        end
        if not loader then
          local file = io.open(job.path, "r")
          if file then
            local content = file:read("*all")
            file:close()
            if load then
              local ok_l, a, b = pcall(load, content, "@SampleMapData.cache.lua")
              if ok_l then
                loader, err = a, b
              else
                err = a
              end
            end
          end
        end
        if not loader then
          log("Failed to load Lua cache: " .. tostring(err))
          pcall(os.remove, DATA_LUA_PATH)
          job.format = "json"
          job.path = DATA_PATH
          job.phase = "read"
          job.message = "Lua cache invalid; reading JSON…"
        else
          local ok, result = pcall(loader)
          if not ok or type(result) ~= "table" then
            log("Failed to execute Lua cache: " .. tostring(result))
            pcall(os.remove, DATA_LUA_PATH)
            job.format = "json"
            job.path = DATA_PATH
            job.phase = "read"
            job.message = "Lua cache invalid; reading JSON…"
          else
            data = result
          end
        end
      else
        local ok, result = pcall(json_decode_sample_cache, job.content)
        job.content = nil
        if not ok or type(result) ~= "table" then
          log("Fast JSON decode failed (" .. tostring(result) .. "); trying full decoder")
          local file = io.open(DATA_PATH, "r")
          if not file then
            finish_library_miss("Failed to decode JSON cache")
            return false
          end
          local content = file:read("*all")
          file:close()
          ok, result = pcall(json_decode, content)
          if not ok or type(result) ~= "table" then
            finish_library_miss("Failed to decode JSON: " .. tostring(result))
            return false
          end
        end
        data = result
      end

      if not data then
        -- Waiting for fallback read path
      elseif data.folders and not folders_match(state.folders, data.folders) then
        log("Cached samples ignored: folder list changed")
        finish_library_miss("Folder list changed; rescanning")
        return false
      else
        local streaming = data._samples_content ~= nil and data._samples_pos ~= nil
        local count = 0
        if streaming then
          -- Estimate from newlines (one sample per line in our writer).
          count = select(2, data._samples_content:gsub("\n", "\n"))
          if count < 1 then count = 0 end
        elseif data.samples and type(data.samples) == "table" then
          count = #data.samples
        end
        if not streaming and count == 0 then
          finish_library_miss("Cache has no samples")
          return false
        end
        job.data = data
        job.raw_samples = (not streaming) and data.samples or nil
        job.json_content = data._samples_content
        job.json_pos = data._samples_pos
        data._samples_content = nil
        data._samples_pos = nil
        job.total = count
        job.index = 1
        job.cleaned = {}
        job.needs_tag_backfill, job.stamp_schema = tag_schema_needs_backfill(data)
        job.needs_layout = false
        job.stream_json = streaming
        job.phase = "process"
        if job.needs_tag_backfill then
          job.message = streaming and "Refreshing genre tags…" or string.format("Refreshing genre tags (0/%d)…", job.total)
        else
          job.message = streaming and "Preparing samples…" or string.format("Preparing samples (0/%d)…", job.total)
        end
        job.progress = 0.1
        log(string.format(
          "Decoded cache meta (stream=%s, estimate=%d, tag_backfill=%s)",
          tostring(streaming),
          job.total,
          tostring(job.needs_tag_backfill)
        ))
      end

    elseif job.phase == "process" then
      if job.stream_json then
        while r.time_precise() < deadline do
          local obj
          obj, job.json_pos = next_json_sample(job.json_content, job.json_pos)
          if not obj then
            job.json_content = nil
            job.stream_json = false
            job.total = #job.cleaned
            job.phase = "finalize"
            job.message = "Finalizing library…"
            job.progress = 0.96
            break
          end
          local s = prepare_cached_sample(obj, job.needs_tag_backfill)
          if s then
            job.cleaned[#job.cleaned + 1] = s
            if not job.needs_layout then
              if not s.x or not s.y or s.x < 0 or s.x > 1 or s.y < 0 or s.y > 1 then
                job.needs_layout = true
              end
            end
          end
          local done = #job.cleaned
          if done % 256 == 0 then
            local total = math.max(job.total, done)
            job.progress = 0.1 + 0.85 * (done / total)
            local label = job.needs_tag_backfill and "Refreshing genre tags" or "Preparing samples"
            job.message = string.format("%s (%d/%d)…", label, done, total)
          end
        end
      else
        local raw = job.raw_samples
        local total = job.total
        while job.index <= total and r.time_precise() < deadline do
          local s = prepare_cached_sample(raw[job.index], job.needs_tag_backfill)
          if s then
            job.cleaned[#job.cleaned + 1] = s
            if not job.needs_layout then
              if not s.x or not s.y or s.x < 0 or s.x > 1 or s.y < 0 or s.y > 1 then
                job.needs_layout = true
              end
            end
          end
          job.index = job.index + 1
          if job.index % 256 == 0 then
            job.progress = 0.1 + 0.85 * ((job.index - 1) / math.max(total, 1))
            local label = job.needs_tag_backfill and "Refreshing genre tags" or "Preparing samples"
            job.message = string.format("%s (%d/%d)…", label, job.index - 1, total)
          end
        end
        if job.index > total then
          job.raw_samples = nil
          job.phase = "finalize"
          job.message = "Finalizing library…"
          job.progress = 0.96
        end
      end

    elseif job.phase == "finalize" then
      if #job.cleaned == 0 then
        finish_library_miss("No valid samples in cache")
        return false
      end
      finish_library_hit(job)
      return false
    else
      break
    end
  end

  return is_library_loading()
end


local function save_samples()
  local save_start = r.time_precise()

  local normalized_folders = {}
  for _, folder in ipairs(state.folders) do
    table.insert(normalized_folders, normalize_path(folder))
  end

  local function sanitize_sample(sample)
    local out = {}
    for k, v in pairs(sample) do
      if k ~= "samplerate" and k ~= "sample_rate" and k ~= "file_size" and k ~= "hot_color"
          and k ~= "_render_color" and k ~= "_folder_unavailable" then
        out[k] = v
      end
    end
    return out
  end

  local sanitized_samples = {}
  for _, s in ipairs(state.samples) do
    sanitized_samples[#sanitized_samples + 1] = sanitize_sample(s)
  end

  local payload = {
    tag_schema_version = TAG_SCHEMA_VERSION,
    folders = normalized_folders,
    map_seed = state.map_seed,
    samples = sanitized_samples,
    scan_queue = state.scan_queue,
    scan_total = state.scan_total,
    scan_started = state.scan_started,
    analyzer_queue = state.analyzer_queue,
    analyzer_pending = state.active_processes and #state.active_processes > 0,
    analyzer_results = state.analyzer_results,
    analyzer_mode = state.analyzer_mode,
  }

  -- Fast Lua cache (primary load path)
  local lua_str = encode_lua_cache(payload)
  local lua_file = io.open(DATA_LUA_PATH, "w")
  if lua_file then
    lua_file:write(lua_str)
    lua_file:close()
  else
    log("Failed to write Lua cache: " .. DATA_LUA_PATH)
  end

  -- Compact JSON for companion scripts (Quick Swap, etc.)
  local function encode_samples_lines(list)
    local out = {"["}
    for i, s in ipairs(list) do
      out[#out + 1] = json_encode(s)
      if i < #list then
        out[#out + 1] = ",\n"
      end
    end
    out[#out + 1] = "]"
    return table.concat(out)
  end

  local json_str = table.concat({
    "{",
    "\"tag_schema_version\":", json_encode(payload.tag_schema_version), ",",
    "\"folders\":", json_encode(payload.folders), ",",
    "\"map_seed\":", json_encode(payload.map_seed), ",",
    "\"samples\":", encode_samples_lines(payload.samples), ",",
    "\"scan_queue\":", json_encode(payload.scan_queue), ",",
    "\"scan_total\":", json_encode(payload.scan_total), ",",
    "\"scan_started\":", json_encode(payload.scan_started), ",",
    "\"analyzer_queue\":", json_encode(payload.analyzer_queue), ",",
    "\"analyzer_pending\":", json_encode(payload.analyzer_pending), ",",
    "\"analyzer_results\":", json_encode(payload.analyzer_results), ",",
    "\"analyzer_mode\":", json_encode(payload.analyzer_mode),
    "}"
  })

  local file = io.open(DATA_PATH, "w")
  if file then
    file:write(json_str)
    file:close()
  end

  state.last_save_time = r.time_precise()
  log(string.format("Saved sample cache in %.0fms (%d samples)", (state.last_save_time - save_start) * 1000, #sanitized_samples))
end


local function clear_sample_cache()
  os.remove(DATA_PATH)
  os.remove(DATA_LUA_PATH)
end

local function filter_samples_by_folders()
  if #state.folders == 0 then
    -- If no folders, clear all samples
    state.samples = {}
    state.active_tags = {}
    state.tag_list = {}
    state.tag_counts = {}
    return
  end

  local filtered_samples = {}
  local removed_count = 0

  for _, sample in ipairs(state.samples) do
    if sample.path then
      local normalized_sample_path = normalize_path(sample.path)
      local keep_sample = false

      -- Check if sample belongs to any of the current folders
      for _, folder in ipairs(state.folders) do
        local normalized_folder = normalize_path(folder)
        if normalized_sample_path:sub(1, #normalized_folder) == normalized_folder then
          keep_sample = true
          break
        end
      end

      if keep_sample then
        table.insert(filtered_samples, sample)
      else
        removed_count = removed_count + 1
      end
    else
      -- Keep samples without path (shouldn't happen but safety check)
      table.insert(filtered_samples, sample)
    end
  end

  state.samples = filtered_samples
  rebuild_samples_path_index()

  -- Rebuild tag data since samples changed
  state.active_tags = {}
  state.tag_list = {}
  state.tag_counts = {}

  if removed_count > 0 then
    log("Removed " .. removed_count .. " samples from removed folder(s)")
  end
end


-- --- Scanning and analysis ---------------------------------------------------
local function sample_analysis_incomplete(sample)
  if not sample or not sample.path then
    return false
  end
  -- Full analyzer pass fills freq, rms, audible length, and loop/one-shot together.
  if sample.dominant_freq == nil or sample.rms_energy == nil then
    return true
  end
  if type(sample.effective_duration) ~= "number" or sample.effective_duration <= 0 then
    return true
  end
  if sample.playback_type == nil then
    return true
  end
  return false
end

local function sample_effective_range_incomplete(sample)
  if not sample or not sample.path then
    return false
  end
  return type(sample.effective_duration) ~= "number" or sample.effective_duration <= 0
end

-- Drum one-shots only (not loops, FX, or melodic instruments).
-- Global: main chunk is near Lua's 200-local limit (see header comment).
DRUM_TRANSIENT_TAGS = {
  kick = true, snare = true, clap = true, snap = true, rim = true,
  hat = true, tom = true, ride = true, crash = true, perc = true,
  drum = true, ["808"] = true,
}

function sample_is_drum_oneshot(sample)
  if not sample then
    return false
  end
  local tags = sample.tags or {}
  local has_drum = sample.sample_type == "Drum"
  local has_loop = false
  for _, tag in ipairs(tags) do
    local lower = string.lower(tostring(tag))
    if lower == "loop" then
      has_loop = true
    end
    if DRUM_TRANSIENT_TAGS[lower] then
      has_drum = true
    end
  end
  if has_loop then
    return false
  end
  local loopish = detect_loop_or_oneshot(sample.path or "", sample.folder or "", sample.playback_type)
  if loopish == "loop" then
    return false
  end
  return has_drum
end

function sample_playback_type_incomplete(sample)
  if not sample or not sample.path then
    return false
  end
  return sample.playback_type == nil
end

function sample_transient_incomplete(sample)
  if not sample_is_drum_oneshot(sample) then
    return false
  end
  return type(sample.transient_end) ~= "number" or sample.transient_end <= 0
end

local function enqueue_analyzer_paths(predicate, empty_msg, queued_log)
  state.external_disabled = false
  state.analyzer_warned = false
  state.analyzer_path_mode = state.analyzer_path_mode or {}

  local already = {}
  for _, path in ipairs(state.analyzer_queue) do
    already[path] = true
  end
  for _, proc in ipairs(state.active_processes) do
    if proc.path then
      already[proc.path] = true
    end
  end

  local added = 0
  for _, sample in ipairs(state.samples) do
    if predicate(sample) then
      local path = normalize_path(sample.path)
      if path ~= "" and not already[path] and not sample_scan_folder_unavailable(sample) then
        table.insert(state.analyzer_queue, path)
        already[path] = true
        if state.analyzer_path_mode then
          state.analyzer_path_mode[path] = state.analyzer_mode
        end
        added = added + 1
      end
    end
  end

  local pending = #state.analyzer_queue + #state.active_processes
  if pending == 0 then
    log(empty_msg)
    add_scan_log(queued_log .. ": nothing to analyze")
    return 0
  end

  state.incomplete_analysis_total = pending
  if state.scan_started <= 0 then
    state.scan_started = r.time_precise()
  end
  state._pending_layout = true

  log(string.format("Queued %d sample(s) for analysis (%d total pending)", added, pending))
  add_scan_log(string.format("%s: queued %d sample(s)", queued_log, added))
  return added
end

local function enqueue_incomplete_analysis()
  state.analyzer_job_label = "Analyzing incomplete"
  state.external_disabled = false
  state.analyzer_warned = false
  state.analyzer_path_mode = state.analyzer_path_mode or {}
  state.analyzer_mode = nil

  local already = {}
  for _, path in ipairs(state.analyzer_queue) do
    already[path] = true
  end
  for _, proc in ipairs(state.active_processes) do
    if proc.path then
      already[proc.path] = true
    end
  end

  local added = 0
  for _, sample in ipairs(state.samples) do
    if sample.path and not sample_scan_folder_unavailable(sample) then
      local path = normalize_path(sample.path)
      if path ~= "" and not already[path] then
        local mode = nil
        local need = false
        if sample_analysis_incomplete(sample) then
          need = true
          mode = nil
        elseif sample_transient_incomplete(sample) then
          need = true
          mode = "transient"
        end
        if need then
          table.insert(state.analyzer_queue, path)
          already[path] = true
          state.analyzer_path_mode[path] = mode
          added = added + 1
        end
      end
    end
  end

  local pending = #state.analyzer_queue + #state.active_processes
  if pending == 0 then
    log("No incomplete samples found")
    add_scan_log("Incomplete scan: nothing to analyze")
    return 0
  end

  state.incomplete_analysis_total = pending
  if state.scan_started <= 0 then
    state.scan_started = r.time_precise()
  end
  state._pending_layout = true
  log(string.format("Queued %d sample(s) for analysis (%d total pending)", added, pending))
  add_scan_log(string.format("Incomplete scan: queued %d sample(s)", added))
  return added
end

local function enqueue_effective_range_analysis()
  state.analyzer_job_label = "Scanning effective range"
  state.analyzer_mode = nil
  return enqueue_analyzer_paths(
    sample_effective_range_incomplete,
    "No samples missing effective range (all have effective_duration)",
    "Effective range scan"
  )
end

function enqueue_transient_sustain_analysis()
  state.analyzer_job_label = "Scanning transient/sustain"
  state.analyzer_mode = "transient"
  return enqueue_analyzer_paths(
    sample_transient_incomplete,
    "No drum one-shots missing transient/sustain (or none tagged as drums)",
    "Transient/sustain scan"
  )
end

function enqueue_playback_type_analysis()
  state.analyzer_job_label = "Classifying loop / one-shot"
  state.analyzer_mode = nil
  return enqueue_analyzer_paths(
    sample_playback_type_incomplete,
    "No samples missing loop/one-shot classification",
    "Loop/one-shot scan"
  )
end

local function enqueue_scan(folder_only)
  state.debug_count = 0  -- Reset debug counter for new scan
  state.external_disabled = false
  state.analyzer_warned = false
  
  -- Build set of already-scanned paths for quick lookup (normalize paths to ensure matching)
  local scanned_set = {}
  for _, sample in ipairs(state.samples) do
    if sample.path then
      local normalized_path = normalize_path(sample.path)
      scanned_set[normalized_path] = true
      -- Also store original path mapping in case it's needed
      if normalized_path ~= sample.path then
        scanned_set[sample.path] = true
      end
    end
  end
  
  local paths = {}
  local skipped_count = 0
  local folders_to_scan = state.folders
  if folder_only and folder_only ~= "" then
    folders_to_scan = { normalize_path(folder_only) }
  end
  
  for _, folder in ipairs(folders_to_scan) do
    -- Normalize folder path
    folder = normalize_path(folder)
    local files_found = 0
    
    local function scan_dir(dir)
      -- Ensure dir path is normalized
      dir = normalize_path(dir)
      
      -- Scan all files in current directory
      local i = 0
      local file = r.EnumerateFiles(dir, i)
      while file do
        local ext = file:match("%.(.+)$")
        if ext then
          ext = "." .. ext:lower()
          if AUDIO_EXTS[ext] then
            -- Use forward slash for macOS
            local full_path = dir .. "/" .. file
            -- Normalize path before checking against scanned_set
            local normalized_full_path = normalize_path(full_path)
            -- Only add if not already scanned
            if not scanned_set[normalized_full_path] and not scanned_set[full_path] then
              table.insert(paths, normalized_full_path)
              files_found = files_found + 1
            else
              skipped_count = skipped_count + 1
            end
          end
        end
        i = i + 1
        file = r.EnumerateFiles(dir, i)
      end
      
      -- Recursively scan all subdirectories
      i = 0
      local subdir = r.EnumerateSubdirectories(dir, i)
      while subdir do
        -- Use forward slash for macOS
        scan_dir(dir .. "/" .. subdir)
        i = i + 1
        subdir = r.EnumerateSubdirectories(dir, i)
      end
    end
    
    -- Try to scan the folder
    local success, err = pcall(scan_dir, folder)
    if not success then
      -- Error scanning folder - silent during scan, errors visible in scan logs
    end
  end
  
  -- If we have existing samples, keep them; otherwise start fresh
  if #state.samples == 0 then
    state.samples = {}
  end
  
  state.scan_queue = paths
  state.scan_total = #paths + skipped_count  -- Total includes already-scanned
  state.scan_started = r.time_precise()
  state.last_save_time = r.time_precise()  -- Initialize save time for time-based saving
  state.active_tags = {}
  state.tag_list = {}
  state.tag_counts = {}
  
  -- Clear analyzer queues for new scan
  state.analyzer_queue = {}
  state.analyzer_results = {}
  state.active_processes = {}
  state.incomplete_analysis_total = 0
  state.analyzer_job_label = nil
  state.analyzer_mode = nil
  state.analyzer_path_mode = {}
  
  if folder_only and folder_only ~= "" then
    add_scan_log(string.format("Folder rescan: %s (%d new file(s))", folder_only, #paths))
    log(string.format("Rescanning folder (%d new file(s)): %s", #paths, folder_only))
  end
end


local function analyze_file(path)
  local file_start_time = r.time_precise()
  local timings = {}
  
  -- PCM_Source creation
  local t0 = r.time_precise()
  local src = r.PCM_Source_CreateFromFile(path)
  if not src then
    return nil
  end
  timings.pcm_create = (r.time_precise() - t0) * 1000  -- Convert to ms
  
  -- Get metadata from PCM_Source
  local t1 = r.time_precise()
  local length_ret = {r.GetMediaSourceLength(src)}
  local duration = pick_number(length_ret, 0.0)
  
  local sr_ret = {r.GetMediaSourceSampleRate(src)}
  local sr = pick_number(sr_ret, 44100.0)
  
  local ch_ret = {r.GetMediaSourceNumChannels(src)}
  local ch = math.floor(pick_number(ch_ret, 2))
  timings.pcm_metadata = (r.time_precise() - t1) * 1000

  -- Get file size from PCM_Source if possible (faster than opening file again)
  local t2 = r.time_precise()
  local size = 0
  local size_ret = {r.GetMediaSourceLength(src)}
  local length_in_samples = pick_number(size_ret, 0.0)
  if length_in_samples > 0 and sr > 0 then
    -- Estimate file size: samples * channels * bytes_per_sample
    -- Use average bitrate estimation
    local estimated_bytes = length_in_samples * ch * 2  -- Assume 16-bit (2 bytes)
    -- Try to get actual file size, but fall back to estimate
    local file = io.open(path, "rb")
    if file then
      file:seek("end")
      size = file:seek()
      file:close()
    else
      size = estimated_bytes
    end
  else
    -- Fallback: open file to get size
    local file = io.open(path, "rb")
    if file then
      file:seek("end")
      size = file:seek()
      file:close()
    end
  end
  timings.file_size = (r.time_precise() - t2) * 1000
  
  -- Queue analyzer request instead of blocking (analyzer data will be merged later)
  -- Normalize path before queuing
  local normalized_path = normalize_path(path)
  if not state.external_disabled then
    -- Add to analyzer queue for parallel processing
    table.insert(state.analyzer_queue, normalized_path)
    add_scan_log(string.format("Queued analyzer for: %s", path:match("([^/]+)$") or path))
  else
    add_scan_log(string.format("Analyzer disabled, skipping: %s", path:match("([^/]+)$") or path))
  end
  
  local t4 = r.time_precise()
  r.PCM_Source_Destroy(src)
  timings.pcm_destroy = (r.time_precise() - t4) * 1000
  
  local avg_bps = size / math.max(duration, 0.01)
  -- Normalize path to use forward slashes
  path = normalize_path(path)
  
  -- Get tags from path first
  local t5 = r.time_precise()
  local tags = infer_tags_from_path(path, path:match("(.+)/[^/]+$") or "")
  timings.tags = (r.time_precise() - t5) * 1000
  
  -- File timing logs removed - happens during scanning
  
  -- Note: Analyzer tags (Drum/Swell) will be added later when analyzer data is merged
  
  -- Detect Loop or One shot from filename/path (audio classification merged later)
  local sample_folder = path:match("(.+)/[^/]+$") or ""
  local tags_sample = { tags = tags }
  apply_loop_oneshot_tag(tags_sample, detect_loop_or_oneshot(path, sample_folder, nil))
  tags = tags_sample.tags

  -- Detect genre words from path/folder names in the user's library
  tags = append_unique_tags(tags, infer_genre_tags_from_path(path, sample_folder))
  
  -- Return sample without analyzer data initially (will be merged later)
  return {
    path = normalized_path,
    name = normalized_path:match("([^/]+)$"),  -- macOS uses forward slashes only
    folder = normalized_path:match("(.+)/[^/]+$") or "",
    duration = duration,
    samplerate = sr,
    channels = ch,
    bps = avg_bps,
    file_size = size,  -- Store file size for Y axis fallback
    dominant_freq = nil,  -- Will be set when analyzer completes
    rms_energy = nil,     -- Will be set when analyzer completes
    sample_type = nil,    -- Will be set when analyzer completes
    snap_offset = nil,    -- Will be set when analyzer completes
    effective_duration = nil, -- Audible end (trailing silence cropped); set by analyzer
    onset = nil,          -- First audible time; set by transient scan
    transient_end = nil,  -- Attack/click end, sustain start; set by transient scan
    playback_type = nil,  -- "oneshot"|"loop"|"unknown"; set by analyzer
    tags = tags
  }
end


local function process_scan_slice(max_ms)
  max_ms = max_ms or 12.0

  local analyzer_complete = (#state.analyzer_queue == 0 and #state.active_processes == 0)

  -- Idle: no active scan session and nothing queued — skip all finalize/merge work.
  if state.scan_started <= 0 and #state.scan_queue == 0 and analyzer_complete
      and not next(state.analyzer_results) then
    return
  end

  -- Manage analyzer process pool (start new processes, check for completed ones)
  process_analyzer_queue()
  analyzer_complete = (#state.analyzer_queue == 0 and #state.active_processes == 0)

  -- Merge completed analyzer results into samples (O(1) path lookup)
  local merged_count = 0
  for path, result in pairs(state.analyzer_results) do
    local sample = samples_by_path[path]
    if not sample then
      sample = samples_by_path[normalize_path(path)]
    end
    if sample and result.data then
      -- Only write fields the analyzer actually produced (don't clobber with nil)
      local data = result.data
      local wrote = false
      if data.dominant_freq ~= nil then
        sample.dominant_freq = data.dominant_freq
        wrote = true
      end
      if data.rms_energy ~= nil then
        sample.rms_energy = data.rms_energy
        wrote = true
      end
      if data.sample_type ~= nil then
        sample.sample_type = data.sample_type
        wrote = true
      end
      if data.snap_offset ~= nil then
        sample.snap_offset = data.snap_offset
        wrote = true
      end
      if data.effective_duration ~= nil then
        sample.effective_duration = data.effective_duration
        wrote = true
      end
      if data.onset ~= nil then
        sample.onset = data.onset
        wrote = true
      end
      if data.transient_end ~= nil then
        sample.transient_end = data.transient_end
        wrote = true
      end
      if data.playback_type ~= nil then
        sample.playback_type = data.playback_type
        apply_loop_oneshot_tag(sample, detect_loop_or_oneshot(sample.path, sample.folder or "", data.playback_type))
        wrote = true
      end
      -- Full analysis just landed: if this is a drum one-shot, queue transient/sustain next.
      if (data.playback_type ~= nil or data.dominant_freq ~= nil or data.effective_duration ~= nil)
          and sample_transient_incomplete(sample) then
        local npath = normalize_path(sample.path)
        local queued = false
        for _, p in ipairs(state.analyzer_queue) do
          if p == npath then
            queued = true
            break
          end
        end
        if not queued then
          for _, proc in ipairs(state.active_processes) do
            if proc.path == npath then
              queued = true
              break
            end
          end
        end
        if not queued and npath ~= "" then
          table.insert(state.analyzer_queue, npath)
          state.analyzer_path_mode = state.analyzer_path_mode or {}
          state.analyzer_path_mode[npath] = "transient"
        end
      end
      if data.sample_type and (data.sample_type == "Drum" or data.sample_type == "Swell") then
        local has_tag = false
        for _, tag in ipairs(sample.tags or {}) do
          if tag == data.sample_type then
            has_tag = true
            break
          end
        end
        if not has_tag then
          sample.tags = sample.tags or {}
          table.insert(sample.tags, data.sample_type)
          wrote = true
        end
      end
      if wrote then
        merged_count = merged_count + 1
      end
    end
    state.analyzer_results[path] = nil
  end

  if merged_count > 0 then
    -- Defer full layout until scan/analyzers settle — per-result layout is too expensive
    state._pending_layout = true
  end

  if state._pending_layout and analyzer_complete and #state.scan_queue == 0 then
    layout_samples()
    state._pending_layout = nil
    if state.scan_started <= 0 then
      rebuild_tag_index()
    end
  end

  -- Finalize only once when an active scan session is done (files + analyzers).
  local function try_finalize_scan()
    if state.scan_started <= 0 then
      return false
    end
    if #state.scan_queue > 0 or not analyzer_complete then
      return false
    end
    if state._pending_layout then
      layout_samples()
      state._pending_layout = nil
    else
      layout_samples()
    end
    rebuild_tag_index()
    rebuild_samples_path_index()
    save_samples()
    state.last_save_time = r.time_precise()
    state.scan_started = 0
    state.incomplete_analysis_total = 0
    state.analyzer_job_label = nil
    state.analyzer_mode = nil
    state.analyzer_path_mode = {}
    local still_incomplete = 0
    for _, s in ipairs(state.samples) do
      if sample_analysis_incomplete(s) then
        still_incomplete = still_incomplete + 1
      end
    end
    if still_incomplete > 0 then
      add_scan_log(string.format(
        "Scan finished with %d sample(s) still missing analyzer fields — click Scan for incomplete again",
        still_incomplete
      ))
      log(string.format("%d samples still incomplete after analysis", still_incomplete))
    else
      add_scan_log("Scan finished: all samples have analyzer fields")
    end
    return true
  end

  if #state.scan_queue == 0 and not analyzer_complete then
    return
  end

  local deadline = r.time_precise() + (max_ms / 1000.0)
  math.randomseed(state.map_seed)

  while #state.scan_queue > 0 and r.time_precise() < deadline do
    local path = table.remove(state.scan_queue)
    local sample = analyze_file(path)
    if sample then
      table.insert(state.samples, sample)
      if sample.path then
        samples_by_path[sample.path] = sample
      end
    end
  end

  try_finalize_scan()
end


-- --- Frequency analysis for spectral waveform ----------------------------------
-- Estimate dominant frequency using autocorrelation with zero-crossing fallback
local function estimate_dominant_frequency(samples, sample_rate)
  if not samples or #samples < 16 then
    return nil  -- Need at least 16 samples for meaningful analysis
  end

  local n = #samples

  -- For large sample sets, downsample to improve performance while maintaining frequency resolution
  local analysis_samples = samples
  local analysis_sr = sample_rate
  if n > 512 then
    -- Downsample to ~512 samples to balance performance and accuracy
    local downsample_factor = math.floor(n / 512)
    analysis_samples = {}
    analysis_sr = sample_rate / downsample_factor

    for i = 1, n, downsample_factor do
      table.insert(analysis_samples, samples[i])
    end
    n = #analysis_samples
  end

  -- Normalize samples (center around zero and normalize amplitude)
  local sum = 0.0
  local max_amp = 0.0
  for i = 1, n do
    sum = sum + analysis_samples[i]
    max_amp = math.max(max_amp, math.abs(analysis_samples[i]))
  end

  if max_amp < 1e-6 then
    return nil  -- Silence
  end

  -- Remove DC offset and normalize
  local mean = sum / n
  local normalized = {}
  for i = 1, n do
    normalized[i] = (analysis_samples[i] - mean) / max_amp
  end

  -- Try autocorrelation first (more accurate for periodic signals)
  -- Focus on musical frequency range: 80Hz to 8000Hz (covers most instruments)
  local max_freq = 8000  -- Look for frequencies up to 8kHz
  local min_freq = 80    -- Minimum frequency to detect (below this, likely noise or rumble)
  local min_lag = math.floor(analysis_sr / max_freq)
  local max_lag = math.floor(analysis_sr / min_freq)

  min_lag = math.max(2, min_lag)
  max_lag = math.min(max_lag, math.floor(n / 2))

  if max_lag >= min_lag then
    -- Calculate autocorrelation at lag 0 for normalization
    local autocorr_0 = 0.0
    for i = 1, n do
      autocorr_0 = autocorr_0 + normalized[i] * normalized[i]
    end
    autocorr_0 = autocorr_0 / n

    if autocorr_0 > 1e-10 then
      -- Autocorrelation - look for the strongest peak in the musical range
      local max_corr = -math.huge
      local best_lag = nil

      for lag = min_lag, max_lag do
        local corr = 0.0
        local count = 0

        for i = 1, n - lag do
          corr = corr + normalized[i] * normalized[i + lag]
          count = count + 1
        end

        if count > 0 then
          -- Normalize autocorrelation
          corr = corr / count
          corr = corr / autocorr_0  -- Normalize by autocorrelation at lag 0

          if corr > max_corr then
            max_corr = corr
            best_lag = lag
          end
        end
      end

      -- Require a minimum correlation threshold to avoid noise
      if best_lag and best_lag > 0 and max_corr > 0.3 then  -- Higher threshold for better accuracy
        local freq = analysis_sr / best_lag
        -- Clamp to audible range (20Hz to 20kHz)
        freq = math.max(20, math.min(20000, freq))
        return freq
      end
    end
  end

  -- Fallback: Zero-crossing rate estimation (simpler but less accurate)
  -- Count zero crossings to estimate frequency
  local zero_crossings = 0
  for i = 2, n do
    if (normalized[i-1] >= 0 and normalized[i] < 0) or (normalized[i-1] < 0 and normalized[i] >= 0) then
      zero_crossings = zero_crossings + 1
    end
  end

  if zero_crossings > 2 then
    -- Each zero crossing represents half a cycle
    local cycles = zero_crossings / 2
    local duration = n / analysis_sr
    local freq = cycles / duration
    -- Clamp to audible range
    freq = math.max(20, math.min(20000, freq))
    return freq
  end

  return nil
end

-- Convert frequency to color (spectral mapping: low=red, mid=yellow/green, high=blue)
local function frequency_to_color(freq)
  if not freq then
    return UI_THEME.text_dim  -- Gray for no frequency data
  end
  
  -- Map frequency to hue (0-360 degrees)
  -- 20Hz = red (0°), 2000Hz = yellow (60°), 20000Hz = blue (240°)
  local hue
  if freq < 2000 then
    -- Low to mid: red to yellow (0° to 60°)
    local t = (freq - 20) / (2000 - 20)
    hue = t * 60
  elseif freq < 8000 then
    -- Mid to high-mid: yellow to cyan (60° to 180°)
    local t = (freq - 2000) / (8000 - 2000)
    hue = 60 + t * 120
  else
    -- High: cyan to blue (180° to 240°)
    local t = (freq - 8000) / (20000 - 8000)
    hue = 180 + t * 60
  end
  
  -- Convert HSV to RGB
  local c = 1.0  -- Chroma
  local x = c * (1 - math.abs((hue / 60) % 2 - 1))
  local m = 0.3  -- Lightness adjustment (make it darker for visibility)
  
  local r, g, b = 0, 0, 0
  if hue < 60 then
    r, g, b = c, x, 0
  elseif hue < 120 then
    r, g, b = x, c, 0
  elseif hue < 180 then
    r, g, b = 0, c, x
  elseif hue < 240 then
    r, g, b = 0, x, c
  else
    r, g, b = x, 0, c
  end
  
  -- Convert to 0-255 and apply lightness
  r = math.floor((r + m) * 255)
  g = math.floor((g + m) * 255)
  b = math.floor((b + m) * 255)
  
  -- Clamp values
  r = math.max(0, math.min(255, r))
  g = math.max(0, math.min(255, g))
  b = math.max(0, math.min(255, b))
  
  -- Return as ARGB (0xAARRGGBB format)
  return (0xFF << 24) | (r << 16) | (g << 8) | b
end

-- --- Waveform generation -----------------------------------------------------
local function generate_waveform(sample, width)
  width = width or waveform_width
  if not sample or not sample.path then
    return nil
  end
  
  -- Create a temporary track and item to access audio samples via AudioAccessor
  local temp_track = r.GetTrack(0, 0)  -- Try to use first track
  if not temp_track then
    temp_track = r.InsertTrackAtIndex(0, true)
  end
  
  if not temp_track then
    log("Failed to create/get track for waveform generation")
    return nil
  end
  
  -- Insert media item
  local item = r.AddMediaItemToTrack(temp_track)
  if not item then
    log("Failed to create media item for waveform")
    return nil
  end
  
  -- Set item position
  r.SetMediaItemPosition(item, 0, false)
  local src = r.PCM_Source_CreateFromFile(sample.path)
  if not src then
    r.DeleteTrackMediaItem(temp_track, item)
    log("Failed to create PCM source for waveform")
    return nil
  end
  
  local length_ret = {r.GetMediaSourceLength(src)}
  local duration = pick_number(length_ret, 0.0)
  if duration <= 0 then
    r.PCM_Source_Destroy(src)
    r.DeleteTrackMediaItem(temp_track, item)
    return nil
  end
  
  r.SetMediaItemLength(item, duration, false)
  
  -- Add take
  local take = r.AddTakeToMediaItem(item)
  if not take then
    r.PCM_Source_Destroy(src)
    r.DeleteTrackMediaItem(temp_track, item)
    log("Failed to create take for waveform")
    return nil
  end
  
  r.SetMediaItemTake_Source(take, src)
  r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", 0.0)
  
  -- Note: After SetMediaItemTake_Source, REAPER owns the src, so don't destroy it manually
  
  -- We create/destroy a fresh accessor per pixel below.
  -- Only check API availability here.
  if not r.APIExists("GetAudioAccessorSamples") then
    log("GetAudioAccessorSamples API not available in this REAPER version")
    -- Note: Don't destroy src here - it's owned by the take/item
    r.DeleteTrackMediaItem(temp_track, item)
    return nil
  end
  
  local sr_ret = {r.GetMediaSourceSampleRate(src)}
  local sr = pick_number(sr_ret, 44100.0)
  
  local ch_ret = {r.GetMediaSourceNumChannels(src)}
  local channels = math.max(1, math.floor(pick_number(ch_ret, 2)))  -- Ensure at least 1 channel
  
  -- Calculate samples to read per pixel
  -- Ensure we read at least 128 samples per pixel for better frequency analysis
  local samples_per_pixel = math.max(128, math.floor((duration * sr) / width))
  
  -- Store waveform data per channel (for stereo: separate left/right)
  local waveform_channels = {}
  local frequency_channels = {}  -- Store frequency data per channel per pixel
  for c = 0, channels - 1 do
    waveform_channels[c] = {}
    frequency_channels[c] = {}
  end
  local max_val_per_channel = {}
  for c = 0, channels - 1 do
    max_val_per_channel[c] = 0.0
  end
  
  -- Read samples for each pixel
  local pixel_idx = 0
  
  while pixel_idx < width do
    
    -- Read samples (REAPER's PCM_Source API)
    -- Note: REAPER doesn't have a direct ReadSamples API in Lua
    -- We'll use a workaround: create a temporary take and read from it
    -- For now, let's use a simpler approach: sample at regular intervals
    
    -- Calculate RMS for this pixel's worth of samples
    -- Since we can't easily read raw samples, we'll use a simplified approach
    -- by sampling at regular time intervals
    local time_per_pixel = duration / width
    local time_at_pixel = pixel_idx * time_per_pixel
    
    -- Use REAPER's ability to get peak info at a specific time
    -- This is a simplified waveform - we'll use duration-based estimation
    -- For a more accurate waveform, we'd need to read actual samples
    
    -- For now, create a placeholder waveform based on file properties
    -- In a full implementation, you'd read actual sample data
    -- Calculate RMS for this pixel using AudioAccessor
    local time_start = (pixel_idx) * (duration / width)
    local time_end = (pixel_idx + 1) * (duration / width)
    local time_center = (time_start + time_end) * 0.5
    
    -- For frequency analysis, we need a longer time window to capture low frequencies
    -- Use a wider window: current pixel plus some surrounding context
    local analysis_window_start = math.max(0, time_start - 0.01)  -- 10ms before
    local analysis_window_end = math.min(duration, time_end + 0.01)  -- 10ms after
    local analysis_window_duration = analysis_window_end - analysis_window_start

    -- Read enough samples for frequency analysis (aim for 256-1024 samples for good analysis)
    local target_samples = math.max(256, math.floor(analysis_window_duration * sr))
    target_samples = math.min(target_samples, 1024)  -- Cap at 1024 to avoid excessive processing
    local max_samples_for_window = math.floor(analysis_window_duration * sr)
    local read_samples = math.min(target_samples, max_samples_for_window)
    read_samples = math.max(64, read_samples)  -- Minimum 64 samples for frequency analysis

    -- For very short windows, try to read more samples by extending the window
    if read_samples < 256 and analysis_window_start > 0.02 then
      -- Extend backward if possible
      analysis_window_start = math.max(0, analysis_window_start - 0.02)
      analysis_window_duration = analysis_window_end - analysis_window_start
      read_samples = math.min(1024, math.floor(analysis_window_duration * sr))
      read_samples = math.max(64, read_samples)
    elseif read_samples < 256 and analysis_window_end < duration - 0.02 then
      -- Extend forward if possible
      analysis_window_end = math.min(duration, analysis_window_end + 0.02)
      analysis_window_duration = analysis_window_end - analysis_window_start
      read_samples = math.min(1024, math.floor(analysis_window_duration * sr))
      read_samples = math.max(64, read_samples)
    end

    local buf_size = read_samples * channels
    local buf = r.new_array(buf_size)

    -- Debug logging for analysis window setup
    if pixel_idx < 3 then
      log(string.format("Pixel %d: analysis_window=%.3fs-%.3fs (%.1fms), target_samples=%d, read_samples=%d",
          pixel_idx + 1, analysis_window_start, analysis_window_end, analysis_window_duration * 1000, target_samples, read_samples))
    end
    
    -- Create a fresh accessor for each pixel to avoid positioning issues
    local pixel_accessor = r.CreateTakeAudioAccessor(take)
    if not pixel_accessor then
      log("Failed to create accessor for pixel " .. (pixel_idx + 1))
      if buf and buf.clear then
        buf.clear(buf)
      end
      for c = 0, channels - 1 do
        waveform_channels[c][pixel_idx + 1] = 0.1
        frequency_channels[c][pixel_idx + 1] = nil
      end
      pixel_idx = pixel_idx + 1
    elseif not r.GetAudioAccessorSamples then
      log("ERROR: GetAudioAccessorSamples not available - waveform generation will fail")
      r.DestroyAudioAccessor(pixel_accessor)
      if buf and buf.clear then
        buf.clear(buf)
      end
      for c = 0, channels - 1 do
        waveform_channels[c][pixel_idx + 1] = 0.1
        frequency_channels[c][pixel_idx + 1] = nil
      end
      pixel_idx = pixel_idx + 1
    else
      -- Read from analysis window to get samples for frequency analysis
      local samples_read = r.GetAudioAccessorSamples(pixel_accessor, sr, channels, analysis_window_start, read_samples, buf)

      -- Clean up the pixel accessor
      r.DestroyAudioAccessor(pixel_accessor)

      -- Debug logging for first few pixels
      if pixel_idx < 3 then
        log(string.format("Pixel %d: samples_read=%s, read_samples=%d, buf_size=%d, channels=%d, sr=%.0f, analysis_start=%.3f, analysis_end=%.3f", 
            pixel_idx + 1, tostring(samples_read), read_samples, buf_size, channels, sr, analysis_window_start, analysis_window_end))
      end
      
      if samples_read and samples_read > 0 and buf then
        -- GetAudioAccessorSamples returns the number of sample frames read (not total samples)
        -- Each frame contains one sample per channel
        local actual_frames = samples_read

        if pixel_idx < 3 then
          log(string.format("Pixel %d: Got %d sample frames (%d total samples across %d channels)",
              pixel_idx + 1, actual_frames, actual_frames * channels, channels))
        end
        
        -- Calculate RMS per channel for this pixel
        local sum_sq_per_channel = {}
        local count_per_channel = {}
        for c = 0, channels - 1 do
          sum_sq_per_channel[c] = 0.0
          count_per_channel[c] = 0
        end
        
        -- Debug: check first few buffer values for first pixel
        if pixel_idx < 1 and channels >= 2 then
          local debug_vals = {}
          -- REAPER arrays are 1-indexed, so we need to add 1 to the index
          for i = 0, math.min(5, buf_size - 1) do
            local buf_idx = i + 1  -- Convert to 1-based index
            local ok, val = pcall(function() return buf[buf_idx] end)
            if ok then
              debug_vals[i] = val
            else
              debug_vals[i] = "ERROR"
            end
          end
          -- Use %s to avoid errors if values are non-numeric
          log(string.format("Pixel %d buffer first 6 values: [0]=%s [1]=%s [2]=%s [3]=%s [4]=%s [5]=%s", 
              pixel_idx + 1, tostring(debug_vals[0] or 0), tostring(debug_vals[1] or 0), tostring(debug_vals[2] or 0), 
              tostring(debug_vals[3] or 0), tostring(debug_vals[4] or 0), tostring(debug_vals[5] or 0)))
        end
        
        -- Extract samples per channel for frequency analysis
        local channel_samples = {}
        for c = 0, channels - 1 do
          channel_samples[c] = {}
        end
        
        for j = 0, actual_frames - 1 do
          for c = 0, channels - 1 do
            -- REAPER arrays are 1-indexed, interleaved: [sample0_ch0, sample0_ch1, sample1_ch0, sample1_ch1, ...]
            -- Calculate 0-based index, then add 1 for 1-based array access
            local idx_0based = j * channels + c
            local buf_idx = idx_0based + 1  -- Convert to 1-based index for REAPER arrays
            if idx_0based >= 0 and idx_0based < buf_size then
              local ok, sample_val = pcall(function() return buf[buf_idx] end)
              if ok and sample_val ~= nil then
                sum_sq_per_channel[c] = sum_sq_per_channel[c] + (sample_val * sample_val)
                count_per_channel[c] = count_per_channel[c] + 1
                table.insert(channel_samples[c], sample_val)
              else
                if pixel_idx < 3 then
                  log(string.format("WARNING: Pixel %d, frame %d, ch %d: failed to read buf[%d] (1-based)", pixel_idx + 1, j, c, buf_idx))
                end
              end
            else
              if pixel_idx < 3 and c == 0 then
                log(string.format("WARNING: Pixel %d, frame %d, ch %d: idx %d out of bounds (buf_size=%d)", 
                    pixel_idx + 1, j, c, idx_0based, buf_size))
              end
            end
          end
        end
        
        -- Calculate RMS and frequency for each channel
        for c = 0, channels - 1 do
          if count_per_channel[c] > 0 then
            local rms = math.sqrt(sum_sq_per_channel[c] / count_per_channel[c])
            waveform_channels[c][pixel_idx + 1] = rms
            max_val_per_channel[c] = math.max(max_val_per_channel[c], rms)
            
            -- Estimate dominant frequency for this pixel/channel
            local freq = estimate_dominant_frequency(channel_samples[c], sr)
            frequency_channels[c][pixel_idx + 1] = freq
            
            -- Debug first few pixels for all channels
            if pixel_idx < 3 then
              local sample_count = channel_samples[c] and #channel_samples[c] or 0
              local first_sample = (channel_samples[c] and channel_samples[c][1]) or 0
              log(string.format("Pixel %d: time=%.3f, ch%d_rms=%.6f, ch%d_freq=%sHz, sample_count=%d, first_sample=%.6f", 
                  pixel_idx + 1, time_center, c, rms, c, freq and string.format("%.1f", freq) or "nil", sample_count, first_sample))
            end
          else
            waveform_channels[c][pixel_idx + 1] = 0.0
            frequency_channels[c][pixel_idx + 1] = nil
            if pixel_idx < 3 then
              log(string.format("WARNING: Pixel %d ch%d got 0 samples (buf_size=%d, read_samples=%d, actual_frames=%d, channels=%d)", 
                  pixel_idx + 1, c, buf_size, read_samples, actual_frames, channels))
            end
          end
        end
      else
        for c = 0, channels - 1 do
          waveform_channels[c][pixel_idx + 1] = 0.0
        end
        if pixel_idx < 3 then
          log(string.format("WARNING: GetAudioAccessorSamples failed for pixel %d: samples_read=%s, buf=%s", 
              pixel_idx + 1, tostring(samples_read), tostring(buf ~= nil)))
        end
      end
      
      if buf and buf.clear then
        buf.clear(buf)
      end
    end
    
    pixel_idx = pixel_idx + 1
  end
  
  -- Cleanup (accessors are destroyed per pixel now)
  -- Note: Don't destroy src - it's owned by the take/item, will be cleaned up when item is deleted
  r.DeleteTrackMediaItem(temp_track, item)
  
  -- Normalize waveforms per channel
  for c = 0, channels - 1 do
    local max_val = max_val_per_channel[c]
    log(string.format("Channel %d max_val before normalization: %.6f", c, max_val))
    if max_val > 0.001 then
      for i = 1, #waveform_channels[c] do
        waveform_channels[c][i] = waveform_channels[c][i] / max_val
      end
      log(string.format("Channel %d waveform normalized successfully", c))
    else
      -- If all values are very small, log warning and use a small value
      log("WARNING: Channel " .. c .. " max_val is very small (" .. string.format("%.6f", max_val) .. "), using placeholder")
      for i = 1, #waveform_channels[c] do
        waveform_channels[c][i] = 0.1
      end
    end
  end
  
  -- Log first few values for debugging (all channels)
  for c = 0, channels - 1 do
    if #waveform_channels[c] > 0 then
      local debug_str = string.format("First 5 waveform values (ch%d): ", c)
      for i = 1, math.min(5, #waveform_channels[c]) do
        debug_str = debug_str .. string.format("%.6f ", waveform_channels[c][i])
      end
      log(debug_str)
      
      -- Count non-zero values
      local non_zero_count = 0
      for i = 1, #waveform_channels[c] do
        if waveform_channels[c][i] and waveform_channels[c][i] > 0.0001 then
          non_zero_count = non_zero_count + 1
        end
      end
      log(string.format("Channel %d: %d total pixels, %d non-zero values", c, #waveform_channels[c], non_zero_count))
    else
      log(string.format("WARNING: Channel %d has no waveform data!", c))
    end
  end
  
  -- Return channel data: for mono, return single array; for stereo+, return table with channel arrays
  local waveform_data = {}
  local frequency_data = {}
  if channels == 1 then
    -- Mono: return single array for backward compatibility
    waveform_data.data = waveform_channels[0]
    frequency_data.data = frequency_channels[0]
    log("Returning mono waveform data")
  else
    -- Multi-channel: return table with channel arrays
    waveform_data.channel_data = {}
    frequency_data.channel_data = {}
    for c = 0, channels - 1 do
      waveform_data.channel_data[c] = waveform_channels[c]
      frequency_data.channel_data[c] = frequency_channels[c]
      log(string.format("Channel %d: %d pixels in channel_data", c, #waveform_channels[c]))
    end
    -- Also provide 'data' for backward compatibility (use first channel)
    waveform_data.data = waveform_channels[0]
    frequency_data.data = frequency_channels[0]
    local ch_data_count = 0
    if waveform_data.channel_data then
      for k, v in pairs(waveform_data.channel_data) do
        ch_data_count = ch_data_count + 1
      end
    end
    log(string.format("Multi-channel waveform: %d channels, channel_data has %d entries", 
        channels, ch_data_count))
  end
  
  local result = {
    data = waveform_data.data,  -- For backward compatibility
    channel_data = waveform_data.channel_data,  -- Per-channel data (nil for mono)
    frequency_data = frequency_data.data,  -- Frequency data for mono (backward compatibility)
    frequency_channel_data = frequency_data.channel_data,  -- Per-channel frequency data (nil for mono)
    duration = duration,
    sample_rate = sr,
    channels = channels
  }
  
  log(string.format("Waveform generation complete: channels=%d, data points=%d, channel_data=%s", 
      channels, result.data and #result.data or 0, result.channel_data and "present" or "nil"))
  
  return result
end


local waveform_gen_job = nil

local function make_placeholder_waveform(sample)
  local channels = sample.channels or 2
  local data = {
    data = {},
    duration = sample.duration or 1.0,
    sample_rate = sample.samplerate or 44100,
    channels = channels,
    sample_path = sample.path,
    frequency_data = {},
    frequency_channel_data = nil,
    _placeholder = true,
  }
  if channels > 1 then
    data.channel_data = {}
    data.frequency_channel_data = {}
    for c = 0, channels - 1 do
      data.channel_data[c] = {}
      data.frequency_channel_data[c] = {}
      for i = 1, waveform_width do
        data.channel_data[c][i] = 0.1
        data.frequency_channel_data[c][i] = nil
      end
    end
    data.data = data.channel_data[0]
    data.frequency_data = data.frequency_channel_data[0]
  else
    for i = 1, waveform_width do
      data.data[i] = 0.1
      data.frequency_data[i] = nil
    end
  end
  return data
end

local function cancel_waveform_generation()
  local job = waveform_gen_job
  if not job then
    return
  end
  if job.accessor then
    pcall(function() r.DestroyAudioAccessor(job.accessor) end)
  end
  if job.item and job.track then
    pcall(function() r.DeleteTrackMediaItem(job.track, job.item) end)
  end
  waveform_gen_job = nil
end

local function finalize_waveform_job(job)
  local channels = job.channels
  for c = 0, channels - 1 do
    local max_val = job.max_val_per_channel[c] or 0.0
    if max_val > 0.001 then
      for i = 1, #job.waveform_channels[c] do
        job.waveform_channels[c][i] = job.waveform_channels[c][i] / max_val
      end
    else
      for i = 1, #job.waveform_channels[c] do
        job.waveform_channels[c][i] = 0.1
      end
    end
  end

  local result
  if channels == 1 then
    result = {
      data = job.waveform_channels[0],
      channel_data = nil,
      frequency_data = job.frequency_channels[0],
      frequency_channel_data = nil,
      duration = job.duration,
      sample_rate = job.sr,
      channels = channels,
      sample_path = job.path,
    }
  else
    result = {
      data = job.waveform_channels[0],
      channel_data = {},
      frequency_data = job.frequency_channels[0],
      frequency_channel_data = {},
      duration = job.duration,
      sample_rate = job.sr,
      channels = channels,
      sample_path = job.path,
    }
    for c = 0, channels - 1 do
      result.channel_data[c] = job.waveform_channels[c]
      result.frequency_channel_data[c] = job.frequency_channels[c]
    end
  end
  return result
end

local function setup_waveform_job(job)
  local sample = job.sample
  local temp_track = r.GetTrack(0, 0)
  if not temp_track then
    temp_track = r.InsertTrackAtIndex(0, true)
  end
  if not temp_track then
    return false
  end

  r.PreventUIRefresh(1)
  local item = r.AddMediaItemToTrack(temp_track)
  if not item then
    r.PreventUIRefresh(-1)
    return false
  end

  r.SetMediaItemPosition(item, 0, false)
  local src = r.PCM_Source_CreateFromFile(sample.path)
  if not src then
    r.DeleteTrackMediaItem(temp_track, item)
    r.PreventUIRefresh(-1)
    return false
  end

  local duration = pick_number({ r.GetMediaSourceLength(src) }, 0.0)
  if duration <= 0 then
    r.DeleteTrackMediaItem(temp_track, item)
    r.PreventUIRefresh(-1)
    return false
  end

  r.SetMediaItemLength(item, duration, false)
  local take = r.AddTakeToMediaItem(item)
  if not take then
    r.DeleteTrackMediaItem(temp_track, item)
    r.PreventUIRefresh(-1)
    return false
  end

  r.SetMediaItemTake_Source(take, src)
  r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", 0.0)

  if not r.APIExists("GetAudioAccessorSamples") then
    r.DeleteTrackMediaItem(temp_track, item)
    r.PreventUIRefresh(-1)
    return false
  end

  local accessor = r.CreateTakeAudioAccessor(take)
  r.PreventUIRefresh(-1)
  if not accessor then
    r.DeleteTrackMediaItem(temp_track, item)
    return false
  end

  local sr = pick_number({ r.GetMediaSourceSampleRate(src) }, 44100.0)
  local channels = math.max(1, math.floor(pick_number({ r.GetMediaSourceNumChannels(src) }, 2)))

  job.track = temp_track
  job.item = item
  job.accessor = accessor
  job.sr = sr
  job.channels = channels
  job.duration = duration
  job.width = waveform_width
  job.waveform_channels = {}
  job.frequency_channels = {}
  job.max_val_per_channel = {}
  for c = 0, channels - 1 do
    job.waveform_channels[c] = {}
    job.frequency_channels[c] = {}
    job.max_val_per_channel[c] = 0.0
  end
  job.pixel_idx = 0
  job.setup_done = true
  return true
end

local function begin_waveform_generation(sample)
  if not sample or not sample.path then
    return
  end
  cancel_waveform_generation()
  waveform_gen_job = {
    sample = sample,
    path = sample.path,
    setup_done = false,
  }
end

local function waveform_is_ready(sample)
  return waveform_data
    and sample
    and waveform_data.sample_path == sample.path
    and not waveform_data._placeholder
end

local function ensure_waveform_for_sample(sample)
  if not sample or not sample.path then
    return
  end
  if waveform_is_ready(sample) then
    return
  end
  if waveform_gen_job and waveform_gen_job.path == sample.path then
    return
  end
  waveform_data = make_placeholder_waveform(sample)
  begin_waveform_generation(sample)
end

local function process_waveform_pixel(job)
  local pixel_idx = job.pixel_idx
  local width = job.width
  local duration = job.duration
  local sr = job.sr
  local channels = job.channels
  local accessor = job.accessor

  local time_start = pixel_idx * (duration / width)
  -- Cap read size for speed — RMS only needs a short window, not full pixel duration
  local read_samples = math.min(256, math.max(64, math.floor((duration / width) * sr)))
  local buf_size = read_samples * channels
  local buf = r.new_array(buf_size)

  local samples_read = r.GetAudioAccessorSamples(accessor, sr, channels, time_start, read_samples, buf)
  if samples_read and samples_read > 0 and buf then
    local actual_frames = samples_read
    for c = 0, channels - 1 do
      local sum_sq = 0.0
      local count = 0
      for j = 0, actual_frames - 1 do
        local buf_idx = j * channels + c + 1
        local sample_val = buf[buf_idx]
        if sample_val then
          sum_sq = sum_sq + (sample_val * sample_val)
          count = count + 1
        end
      end
      if count > 0 then
        local rms = math.sqrt(sum_sq / count)
        job.waveform_channels[c][pixel_idx + 1] = rms
        job.max_val_per_channel[c] = math.max(job.max_val_per_channel[c], rms)
      else
        job.waveform_channels[c][pixel_idx + 1] = 0.0
      end
      job.frequency_channels[c][pixel_idx + 1] = nil
    end
  else
    for c = 0, channels - 1 do
      job.waveform_channels[c][pixel_idx + 1] = 0.0
      job.frequency_channels[c][pixel_idx + 1] = nil
    end
  end

  if buf and buf.clear then
    buf.clear(buf)
  end
  job.pixel_idx = pixel_idx + 1
end

local function process_waveform_slice(max_ms)
  local job = waveform_gen_job
  if not job then
    return
  end
  max_ms = max_ms or 6.0

  if not job.setup_done then
    if not setup_waveform_job(job) then
      cancel_waveform_generation()
      return
    end
    if waveform_data and waveform_data.sample_path == job.path then
      waveform_data.duration = job.duration
      waveform_data.sample_rate = job.sr
      waveform_data.channels = job.channels
    end
  end

  local deadline = r.time_precise() + (max_ms / 1000.0)
  while job.pixel_idx < job.width and r.time_precise() < deadline do
    process_waveform_pixel(job)
  end

  if job.pixel_idx >= job.width then
    waveform_data = finalize_waveform_job(job)
    cancel_waveform_generation()
  end
end


-- --- Preview handling --------------------------------------------------------
local function release_preview_source()
  if not preview_source then
    preview_source_engine_owned = false
    return
  end

  if preview_source_engine_owned then
    preview_source = nil
    preview_source_engine_owned = false
    return
  end

  if r.PCM_Source_Destroy then
    local can_destroy = false

    if r.GetMediaSourceLength then
      local ok = pcall(function() return r.GetMediaSourceLength(preview_source) end)
      if ok then
        can_destroy = true
      end
    end

    if not can_destroy and r.ValidatePtr2 then
      local ok, valid = pcall(function() return r.ValidatePtr2(0, preview_source, "PCM_source*") end)
      if ok and valid then
        can_destroy = true
      end
    end

    if not can_destroy and r.ValidatePtr then
      local ok, valid = pcall(function() return r.ValidatePtr(preview_source, "PCM_source*") end)
      if ok and valid then
        can_destroy = true
      end
    end

    if can_destroy then
      pcall(function() r.PCM_Source_Destroy(preview_source) end)
    end
  end

  preview_source = nil
  preview_source_engine_owned = false
end

local function stop_preview()
  -- Stop CF_Preview instances first (uses objects, not IDs)
  if cf_preview_obj then
    if r.CF_Preview_StopAll then
      r.CF_Preview_StopAll()
    elseif r.CF_Preview_Stop then
      r.CF_Preview_Stop(cf_preview_obj)
    end
    cf_preview_obj = nil
  elseif r.CF_Preview_StopAll then
    -- Stop all CF_Preview instances even if we don't have a handle
    r.CF_Preview_StopAll()
  end

  -- Stop preview using Xen_StopSourcePreview if we have an integer preview ID
  if preview_proc and type(preview_proc) == "number" and r.Xen_StopSourcePreview then
    r.Xen_StopSourcePreview(preview_proc)
    preview_proc = nil
  elseif preview_proc and type(preview_proc) == "number" and r.StopSourcePreview then
    r.StopSourcePreview(preview_proc)
    preview_proc = nil
  elseif preview_source then
    -- Stop track preview style APIs
    if r.StopTrackPreview2 and preview_track then
      r.StopTrackPreview2(preview_source, preview_track)
    elseif r.StopTrackPreview then
      r.StopTrackPreview(preview_source)
    end
    preview_proc = nil
  end

  release_preview_source()

  cancel_waveform_generation()

  preview_start_time = 0.0
  preview_proc = nil
end

-- Stop sample preview when REAPER transport starts (space, arrange play, etc).
function stop_preview_if_transport_started()
  local playing = false
  if r.GetPlayState then
    playing = (r.GetPlayState() & 1) == 1
  end
  if playing and not state.seq_last_reaper_playing and preview_proc then
    stop_preview()
    state.preview_paused = false
  end
  state.seq_last_reaper_playing = playing
end


local function start_preview_audio(sample, start_time)
  start_time = math.max(0.0, start_time or 0.0)
  if preview_source then
    release_preview_source()
  end

  preview_source = r.PCM_Source_CreateFromFile(sample.path)
  preview_source_engine_owned = false
  if not preview_source then
    return false
  end

  if r.CF_CreatePreview and r.CF_Preview_SetValue and r.CF_Preview_Play then
    cf_preview_obj = r.CF_CreatePreview(preview_source)
    if cf_preview_obj then
      r.CF_Preview_SetValue(cf_preview_obj, "D_VOLUME", state.preview_volume or 1.0)
      if start_time > 0 then
        r.CF_Preview_SetValue(cf_preview_obj, "D_POSITION", start_time)
      end
      if r.CF_Preview_Play(cf_preview_obj) then
        preview_proc = true
        preview_start_time = r.time_precise() - start_time
        state.pop_start_time = r.time_precise()
        return true
      end
      cf_preview_obj = nil
    end
  elseif r.PlayTrackPreview2 then
    local track = ensure_preview_track()
    if track then
      local preview = {
        src = preview_source,
        startpos = start_time,
        volume = state.preview_volume or 1.0,
        pan = 0.0,
        loop = false,
        length = -1.0,
        fadein = 0.0,
        fadeout = 0.0,
        pitch = 0.0,
        mode = 0,
      }
      if r.PlayTrackPreview2(0, preview, track) then
        preview_proc = true
        preview_start_time = r.time_precise() - start_time
        state.pop_start_time = r.time_precise()
        return true
      end
    end
  elseif r.Xen_StartSourcePreview then
    local preview_id = r.Xen_StartSourcePreview(preview_source, state.preview_volume or 1.0, false)
    if preview_id and preview_id ~= 0 then
      preview_proc = preview_id
      preview_source_engine_owned = true
      preview_start_time = r.time_precise() - start_time
      state.pop_start_time = r.time_precise()
      return true
    end
  end

  release_preview_source()
  return false
end


-- --- History navigation --------------------------------------------------------
local function preview_sample_from_history(sample)
  local start_time = get_sample_start_offset(sample)

  if not sample or not sample.path then
    return
  end

  if sample_scan_folder_unavailable(sample) then
    return
  end

  stop_preview()

  preview_sample_obj = sample
  preview_start_time = r.time_precise() - start_time
  state.preview_position = start_time
  state.preview_paused = false
  state.breathing_start_time = r.time_precise()

  -- Play immediately; waveform builds across subsequent frames
  start_preview_audio(sample, start_time)
  ensure_waveform_for_sample(sample)
end


local function navigate_history(direction)
  -- direction: -1 for back (up arrow), 1 for forward (down arrow)
  -- history_index: 0 = current sample, 1+ = index in played_history array
  
  local new_index = state.history_index + direction
  
  -- Clamp to valid range
  if new_index < 0 then
    return  -- Can't go back further than current
  elseif new_index > #state.played_history then
    return  -- Can't go forward past oldest
  end
  
  -- If going back from current (index 0) to history, need at least one item
  if new_index > 0 and #state.played_history == 0 then
    return
  end
  
  state.history_index = new_index
  
  local sample = nil
  if new_index == 0 then
    -- Back to current sample
    sample = preview_sample_obj
  else
    -- Navigate to history entry
    sample = state.played_history[new_index]  -- Lua arrays are 1-indexed
  end
  
  if sample and sample.path then
    preview_sample_from_history(sample)
  end
end


local function preview_sample(sample, start_time)
  if start_time == nil then
    start_time = get_sample_start_offset(sample)
  end
  start_time = math.max(0.0, start_time or 0.0)

  if not sample or not sample.path then
    return
  end

  if sample_scan_folder_unavailable(sample) then
    return
  end

  if preview_sample_obj and preview_sample_obj.path and preview_sample_obj.path ~= sample.path then
    table.insert(state.played_history, 1, preview_sample_obj)
    if #state.played_history > 100 then
      table.remove(state.played_history, #state.played_history)
    end
  end

  state.history_index = 0

  stop_preview()

  preview_sample_obj = sample
  preview_start_time = r.time_precise() - start_time
  state.preview_position = start_time
  state.preview_paused = false
  state.breathing_start_time = r.time_precise()

  -- Start audio first so click feels instant; waveform fills in over the next frames
  start_preview_audio(sample, start_time)
  ensure_waveform_for_sample(sample)
end


local function get_preview_position()
  if preview_proc and preview_sample_obj then
    local pos = nil

    if cf_preview_obj and r.CF_Preview_GetValue then
      local ret, cf_pos = r.CF_Preview_GetValue(cf_preview_obj, "D_POSITION")
      if ret and cf_pos then
        pos = cf_pos
      end
    end

    if not pos then
      local elapsed = r.time_precise() - preview_start_time
      local duration = preview_sample_obj.duration or 0.0
      pos = math.min(elapsed, duration)
      if elapsed >= duration then
        stop_preview()
        state.preview_paused = false
        state.preview_position = duration
        return duration
      end
    end

    state.preview_position = pos
    return pos
  end

  if preview_sample_obj then
    return state.preview_position or 0.0
  end

  return nil
end

function seek_preview(time)
  if not preview_sample_obj then
    return
  end
  local duration = preview_sample_obj.duration or 0.0
  time = tonumber(time) or 0.0
  if duration > 0 then
    time = math.max(0.0, math.min(duration, time))
  else
    time = math.max(0.0, time)
  end
  if preview_proc and cf_preview_obj and r.CF_Preview_SetValue then
    r.CF_Preview_SetValue(cf_preview_obj, "D_POSITION", time)
    preview_start_time = r.time_precise() - time
    state.preview_position = time
    state.preview_paused = false
    return
  end
  preview_sample(preview_sample_obj, time)
end

local function apply_preview_volume(vol)
  vol = math.max(0.0, math.min(1.0, vol))
  state.preview_volume = vol
  save_config()

  if cf_preview_obj and r.CF_Preview_SetValue then
    r.CF_Preview_SetValue(cf_preview_obj, "D_VOLUME", vol)
    return
  end

  if preview_proc and preview_sample_obj then
    local resume_pos = state.preview_position or 0.0
    local sample = preview_sample_obj
    stop_preview()
    preview_sample(sample, resume_pos)
  end
end

local function draw_preview_volume_knob(knob_size)
  local vol = state.preview_volume or 1.0
  local radius = knob_size * 0.5

  r.ImGui_InvisibleButton(ctx, "##preview_vol_knob", knob_size, knob_size)
  local active = r.ImGui_IsItemActive(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)

  if active then
    local _, dy = r.ImGui_GetMouseDelta(ctx)
    if dy ~= 0.0 then
      local step = 1.0 / 200.0
      vol = vol + (-dy) * step
      apply_preview_volume(vol)
      vol = state.preview_volume or vol
    end
  end

  if r.ImGui_IsItemClicked(ctx, 0) and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
    apply_preview_volume(1.0)
    vol = state.preview_volume or 1.0
  end

  if hovered or active then
    r.ImGui_SetTooltip(ctx, string.format("Volume: %.0f%% (double-click reset)", vol * 100))
  end

  local dl = r.ImGui_GetWindowDrawList(ctx)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local cx = x0 + radius
  local cy = y0 + radius
  local ANGLE_MIN = math.pi * 0.75
  local ANGLE_MAX = math.pi * 2.25
  local angle = ANGLE_MIN + (ANGLE_MAX - ANGLE_MIN) * vol
  local accent = active and UI_THEME.accent_hvr or (hovered and UI_THEME.accent or 0x148A3AFF)
  local fill = active and UI_THEME.accent_fill_h or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)

  r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, radius - 0.5, fill, 22)
  r.ImGui_DrawList_AddCircle(dl, cx, cy, radius - 0.5, accent, 22, hovered and 1.8 or 1.3)
  if hovered or active then
    r.ImGui_DrawList_AddCircle(dl, cx, cy, radius + 1.5, 0x1EFF5E33, 22, 1.0)
  end
  local arc_r = radius - 3.0
  local n = 18
  local prev_x, prev_y
  for i = 0, n do
    local t = i / n
    local a = ANGLE_MIN + (angle - ANGLE_MIN) * t
    local ax = cx + math.cos(a) * arc_r
    local ay = cy + math.sin(a) * arc_r
    if prev_x then
      r.ImGui_DrawList_AddLine(dl, prev_x, prev_y, ax, ay, accent, 2.0)
    end
    prev_x, prev_y = ax, ay
  end
  local lx = cx + math.cos(angle) * (radius - 5.0)
  local ly = cy + math.sin(angle) * (radius - 5.0)
  r.ImGui_DrawList_AddLine(dl, cx, cy, lx, ly, 0xFFFFFFFF, 1.8)
  r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, 2.0, 0xFFFFFFFF, 10)
end


-- Helper function to change color alpha (set alpha value 0.0-1.0)
local function change_color_alpha(color, alpha_value)
  if not color then return color end
  local r, g, b = extract_rgb_rrgbbaa(color)
  local new_alpha = math.max(0, math.min(255, math.floor(alpha_value * 255)))
  return build_color_rrgbbaa(r, g, b, new_alpha)
end

-- Helper function to blend two colors
local function blend_colors(color1, color2, t)
  t = math.max(0.0, math.min(1.0, t))
  local r1, g1, b1 = extract_rgb_rrgbbaa(color1)
  local r2, g2, b2 = extract_rgb_rrgbbaa(color2)
  local r = math.floor(r1 * (1.0 - t) + r2 * t)
  local g = math.floor(g1 * (1.0 - t) + g2 * t)
  local b = math.floor(b1 * (1.0 - t) + b2 * t)
  local a1 = color1 % 256
  local a2 = color2 % 256
  local a = math.floor(a1 * (1.0 - t) + a2 * t)
  return build_color_rrgbbaa(r, g, b, a)
end

-- Helper function to brighten a color while preserving hue
-- brightness_factor: 0.0 = no change, 1.0 = maximum brightness (toward white but preserving hue)
local function brighten_color_preserve_hue(color, brightness_factor)
  brightness_factor = math.max(0.0, math.min(1.0, brightness_factor))
  local r, g, b = extract_rgb_rrgbbaa(color)
  
  -- Find the maximum component to determine the current brightness
  local max_component = math.max(r, g, b)
  if max_component == 0 then
    -- Black color - return a gray based on brightness
    local gray = math.floor(brightness_factor * 255)
    return build_color_rrgbbaa(gray, gray, gray, 255)
  end
  
  -- Calculate how much to scale each component toward 255 while preserving ratios
  -- This preserves hue while increasing brightness
  local scale_factor = 1.0 + brightness_factor * (255.0 / max_component - 1.0)
  
  local new_r = math.min(255, math.floor(r * scale_factor))
  local new_g = math.min(255, math.floor(g * scale_factor))
  local new_b = math.min(255, math.floor(b * scale_factor))
  
  return build_color_rrgbbaa(new_r, new_g, new_b, 255)
end

-- Draw glowing circle effect (adapted from provided pattern)
local function draw_glowing_circle(dl, x, y, glow_in, glow_out, solid_rad, clr, center_clr)
  -- Draw solid center circle if specified
  if solid_rad then
    local center_color = center_clr or clr
    r.ImGui_DrawList_AddCircleFilled(dl, x, y, solid_rad, center_color, 32)
  end
  
  -- Draw concentric circles for glow effect
  -- Use step size based on radius to balance quality and performance
  local step = math.max(1.5, (glow_out - glow_in) / 8.0)  -- ~8 rings (cheap glow)
  for i = glow_in, glow_out, step do
    local range = glow_out - glow_in
    if range > 0 then
      -- Calculate normalized position (1.0 at glow_in, 0.0 at glow_out)
      local n = (glow_out - i) / range
      
      -- Opacity decreases as we go outward
      local opacity = n
      
      -- Blend colors if center color is provided
      local circle_color = clr
      if center_clr then
        circle_color = blend_colors(clr, center_clr, n)
      end
      
      -- Apply opacity
      local final_color = change_color_alpha(circle_color, opacity)
      
      -- Draw circle outline (not filled for glow effect)
      r.ImGui_DrawList_AddCircle(dl, x, y, i, final_color, 32, 1.0)
    end
  end
end

-- --- UI helpers --------------------------------------------------------------
local function sample_passes_filters(sample)
  if not sample then return false end

  if state.filter ~= "" then
    local name = string.lower(sample.name or "")
    if not string.find(name, string.lower(state.filter), 1, true) then
      return false
    end
  end

  if state.active_tags and next(state.active_tags) ~= nil then
    local matched = false
    if sample.tags then
      for _, tag in ipairs(sample.tags) do
        if state.active_tags[tag] then
          matched = true
          break
        end
      end
    end
    if not matched then
      return false
    end
  end

  -- Check folder path filter
  if state.folder_filter_path and state.folder_filter_path ~= "" then
    local sample_path = normalize_path(sample.path or "")
    local filter_path = normalize_path(state.folder_filter_path)
    -- Check if sample path starts with filter path
    if not (sample_path:sub(1, #filter_path) == filter_path) then
      return false
    end
  end

  return true
end

-- Samples currently assigned to sequencer tracks (and layering verts).
function seq_assigned_sample_info()
  local info = {}
  local selected_slot = nil
  if state.selected_seq_track then
    selected_slot = state.seq_tracks[state.selected_seq_track]
  end
  local function mark(path, name, is_selected)
    if not path or path == "" then
      return
    end
    local entry = info[path]
    if not entry then
      entry = { names = {}, selected = false }
      info[path] = entry
    end
    entry.names[#entry.names + 1] = name or "Track"
    if is_selected then
      entry.selected = true
    end
  end
  for _, slot in ipairs(state.seq_tracks or {}) do
    local is_selected = selected_slot ~= nil and slot.id == selected_slot.id
    mark(slot.sample_path, slot.name, is_selected)
    local layers = slot.layers
    if type(layers) == "table" then
      for _, side_key in ipairs({ "transient", "sustain" }) do
        local verts = layers[side_key] and layers[side_key].verts
        if type(verts) == "table" then
          for i = 1, #verts do
            local vert = verts[i]
            if vert and vert.path then
              mark(vert.path, (slot.name or "Track") .. " (" .. side_key .. ")", is_selected)
            end
          end
        end
      end
    end
  end
  return info
end

function seq_assigned_view_fingerprint()
  local bits = {}
  for _, slot in ipairs(state.seq_tracks or {}) do
    bits[#bits + 1] = tostring(slot.sample_path or "")
    local layers = slot.layers
    if type(layers) == "table" then
      for _, side_key in ipairs({ "transient", "sustain" }) do
        local verts = layers[side_key] and layers[side_key].verts
        if type(verts) == "table" then
          for i = 1, #verts do
            local vert = verts[i]
            if vert and vert.path then
              bits[#bits + 1] = vert.path
            end
          end
        end
      end
    end
  end
  bits[#bits + 1] = tostring(state.selected_seq_track or 0)
  return table.concat(bits, "\n")
end

local function get_sample_dot_color(sample)
  if not sample then
    return build_color_rrgbbaa(96, 96, 96, 255)
  end

  local color = build_color_rrgbbaa(extract_rgb(state.dot_color or 0x44AA55))
  if sample.tags and type(sample.tags) == "table" and #sample.tags > 0 then
    local best_tag = nil
    local best_weight = 0
    for _, tag_name in ipairs(sample.tags) do
      for _, keyword_entry in ipairs(TAG_KEYWORDS) do
        if keyword_entry.tag == tag_name and keyword_entry.weight > best_weight then
          best_weight = keyword_entry.weight
          best_tag = tag_name
        end
      end
    end
    if best_tag and state.tag_colors[best_tag] then
      local tr, tg, tb = extract_rgb(state.tag_colors[best_tag])
      color = build_color_rrgbbaa(tr, tg, tb, 255)
    end
  end

  if sample.channels == 1 then
    local base_r, base_g, base_b = extract_rgb_rrgbbaa(color)
    color = build_color_rrgbbaa(
      math.min(255, math.floor(base_r * 1.5)),
      math.min(255, math.floor(base_g * 1.5)),
      math.min(255, math.floor(base_b * 1.5)),
      255
    )
  end

  return color
end


-- --- Map spatial index + cached draw lists -----------------------------------
local map_cache = {
  filter_key = nil,
  spatial = nil,
  filtered = nil,
  filtered_count = 0,
  view_key = nil,
  draw_list = nil,
  hover_list = nil,
  visible_total = 0,
  draw_count = 0,
  dots_capped = false,
}

local function compute_map_filter_key()
  local tags = {}
  for tag, active in pairs(state.active_tags or {}) do
    if active then
      tags[#tags + 1] = tag
    end
  end
  table.sort(tags)
  return string.format(
    "%s|%s|%s|%d|%d|%d",
    state.filter or "",
    table.concat(tags, ","),
    state.folder_filter_path or "",
    #state.samples,
    state.map_layout_version or 0,
    state.map_availability_epoch or 0
  )
end

local function compute_map_view_key(padded_x0, padded_y0, padded_width, padded_height)
  local playing_path = preview_sample_obj and preview_sample_obj.path or ""
  -- Fine zoom quantization keeps LOD updates smooth while scrolling the wheel
  return string.format(
    "%.3f|%d|%d|%d|%d|%d|%d|%s|%s",
    state.zoom or 1.0,
    math.floor((state.pan_x or 0.0) + 0.5),
    math.floor((state.pan_y or 0.0) + 0.5),
    math.floor(padded_width or 0),
    math.floor(padded_height or 0),
    math.floor(padded_x0 or 0),
    math.floor(padded_y0 or 0),
    playing_path,
    seq_assigned_view_fingerprint()
  )
end

local function map_spatial_cell_key(cell_x, cell_y)
  return cell_y * MAP_GRID_RES + cell_x
end

local function rebuild_map_filtered_cache()
  local filtered = {}
  local duration_min, duration_max = nil, nil
  for _, s in ipairs(state.samples) do
    if type(s) == "table" and s.x and sample_passes_filters(s) then
      s._render_color = get_sample_dot_color(s)
      s._folder_unavailable = sample_scan_folder_unavailable(s)
      filtered[#filtered + 1] = s
      local map_dur = sample_map_duration(s)
      if map_dur > 0 then
        if not duration_min then
          duration_min = map_dur
          duration_max = map_dur
        else
          duration_min = math.min(duration_min, map_dur)
          duration_max = math.max(duration_max, map_dur)
        end
      end
    end
  end

  local spatial = {}
  for _, s in ipairs(filtered) do
    local cell_x = math.max(0, math.min(MAP_GRID_RES - 1, math.floor((s.x or 0.5) * MAP_GRID_RES)))
    local cell_y = math.max(0, math.min(MAP_GRID_RES - 1, math.floor((s.y or 0.5) * MAP_GRID_RES)))
    local key = map_spatial_cell_key(cell_x, cell_y)
    local bucket = spatial[key]
    if not bucket then
      bucket = {}
      spatial[key] = bucket
    end
    bucket[#bucket + 1] = s
  end

  map_cache.filtered = filtered
  map_cache.filtered_count = #filtered
  map_cache.spatial = spatial
  map_cache.duration_min = duration_min
  map_cache.duration_max = duration_max
  map_cache.filter_key = compute_map_filter_key()
  map_cache.view_key = nil
end

local function get_viewport_norm_bounds(padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y, margin)
  local zoom = state.zoom or 1.0
  local inv_x = 1.0 / math.max(padded_width * zoom, 1e-6)
  local inv_y = 1.0 / math.max(padded_height * zoom, 1e-6)
  local x_min = ((padded_x0 - margin - padded_center_x) * inv_x) + 0.5
  local x_max = ((padded_x0 + padded_width + margin - padded_center_x) * inv_x) + 0.5
  local y_min = ((padded_y0 - margin - padded_center_y) * inv_y) + 0.5
  local y_max = ((padded_y0 + padded_height + margin - padded_center_y) * inv_y) + 0.5
  return x_min, x_max, y_min, y_max
end

local function collect_viewport_samples(spatial, x_min, x_max, y_min, y_max)
  local seen = {}
  local out = {}
  local cx0 = math.max(0, math.floor(x_min * MAP_GRID_RES) - 1)
  local cx1 = math.min(MAP_GRID_RES - 1, math.floor(x_max * MAP_GRID_RES) + 1)
  local cy0 = math.max(0, math.floor(y_min * MAP_GRID_RES) - 1)
  local cy1 = math.min(MAP_GRID_RES - 1, math.floor(y_max * MAP_GRID_RES) + 1)

  for cy = cy0, cy1 do
    for cx = cx0, cx1 do
      local bucket = spatial[map_spatial_cell_key(cx, cy)]
      if bucket then
        for _, s in ipairs(bucket) do
          local path = s.path
          local sx, sy = s.x or 0.5, s.y or 0.5
          if path and not seen[path] and sx >= x_min and sx <= x_max and sy >= y_min and sy <= y_max then
            seen[path] = true
            out[#out + 1] = s
          end
        end
      end
    end
  end

  return out
end

local function apply_map_dot_cap(candidates, max_dots, playing_path, x_min, x_max, y_min, y_max)
  if #candidates <= max_dots then
    return candidates, #candidates, false
  end

  -- Viewport-relative grid: always ~sqrt(budget)² cells across the *visible* area so
  -- on-screen density stays ~constant at every zoom (not denser when zoomed in).
  local vw = math.max(1e-6, (x_max or 1) - (x_min or 0))
  local vh = math.max(1e-6, (y_max or 1) - (y_min or 0))
  local subgrid = math.max(8, math.floor(math.sqrt(max_dots) + 0.5))
  local x0 = x_min or 0
  local y0 = y_min or 0
  local cells = {}
  local playing = nil

  for _, s in ipairs(candidates) do
    if playing_path and s.path == playing_path then
      playing = s
    else
      local gx = math.max(0, math.min(subgrid - 1, math.floor(((s.x or 0.5) - x0) / vw * subgrid)))
      local gy = math.max(0, math.min(subgrid - 1, math.floor(((s.y or 0.5) - y0) / vh * subgrid)))
      local key = gy * subgrid + gx
      if not cells[key] then
        cells[key] = s
      end
    end
  end

  local draw_list = {}
  if playing then
    draw_list[#draw_list + 1] = playing
  end
  for _, s in pairs(cells) do
    draw_list[#draw_list + 1] = s
  end

  if #draw_list > max_dots then
    -- Deterministic stride trim (no sort) — evenly thins the set
    local trimmed = {}
    if playing then
      trimmed[#trimmed + 1] = playing
    end
    local stride = math.max(1, math.ceil(#draw_list / max_dots))
    for i = 1, #draw_list, stride do
      local s = draw_list[i]
      if not playing or s.path ~= playing.path then
        trimmed[#trimmed + 1] = s
      end
      if #trimmed >= max_dots then
        break
      end
    end
    draw_list = trimmed
  end

  return draw_list, #candidates, true
end

local function ensure_map_render_cache(padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y, margin)
  margin = margin or 24.0

  local filter_key = compute_map_filter_key()
  if map_cache.filter_key ~= filter_key or not map_cache.spatial then
    rebuild_map_filtered_cache()
  end

  local view_key = compute_map_view_key(padded_x0, padded_y0, padded_width, padded_height)
  if map_cache.view_key == view_key and map_cache.draw_list then
    return map_cache.draw_list, map_cache.hover_list, map_cache
  end

  local x_min, x_max, y_min, y_max = get_viewport_norm_bounds(
    padded_x0, padded_y0, padded_width, padded_height,
    padded_center_x, padded_center_y, margin
  )

  local hover_list = collect_viewport_samples(map_cache.spatial, x_min, x_max, y_min, y_max)
  local playing_path = preview_sample_obj and preview_sample_obj.path or nil
  local zoom = state.zoom or 1.0
  local max_dots = MAP_DOT_BUDGET

  local draw_list, visible_total, capped = apply_map_dot_cap(
    hover_list, max_dots, playing_path, x_min, x_max, y_min, y_max
  )

  if playing_path then
    local playing_in_draw = false
    for i = 1, #draw_list do
      if draw_list[i].path == playing_path then
        playing_in_draw = true
        break
      end
    end
    if not playing_in_draw then
      local playing = samples_by_path[playing_path]
      if playing and playing.x then
        draw_list[#draw_list + 1] = playing
      end
    end
  end

  local assigned_info = seq_assigned_sample_info()
  for path, _ in pairs(assigned_info) do
    local already = false
    for i = 1, #draw_list do
      if draw_list[i].path == path then
        already = true
        break
      end
    end
    if not already then
      local sample = samples_by_path[path]
      if sample and sample.x
          and sample.x >= x_min and sample.x <= x_max
          and sample.y >= y_min and sample.y <= y_max then
        draw_list[#draw_list + 1] = sample
      end
    end
  end

  -- Precompute screen positions + colors once per view (avoids redo in draw + hover)
  local zoom_f = zoom
  local half_w = padded_width * 0.5
  local half_h = padded_height * 0.5
  local entries = {}
  for i = 1, #draw_list do
    local s = draw_list[i]
    local px = padded_center_x + ((s.x or 0.5) * padded_width - half_w) * zoom_f
    local py = padded_center_y + ((s.y or 0.5) * padded_height - half_h) * zoom_f
    entries[i] = {
      s = s,
      px = px,
      py = py,
      color = s._folder_unavailable and build_color_rrgbbaa(136, 136, 136, 90) or (s._render_color or 0x44AA55FF),
      unavailable = s._folder_unavailable and true or false,
    }
  end

  map_cache.view_key = view_key
  map_cache.hover_list = hover_list
  map_cache.draw_list = draw_list
  map_cache.draw_entries = entries
  map_cache.visible_total = visible_total
  map_cache.draw_count = #draw_list
  map_cache.dots_capped = capped
  map_cache.lod_budget = max_dots

  return draw_list, hover_list, map_cache
end


-- --- UI kit: modern minimal custom-drawn controls ---------------------------
-- Palette keyed to accent #1EFF5E (hue ~137°). Neutrals are charcoal with a
-- faint forest cast so the UI never reads as blue-gray.
UI_THEME = {
  bg            = 0x101410FF,
  bg_panel      = 0x141A16FF,
  surface       = 0x1A211DFF,
  surface_hvr   = 0x242E28FF,
  surface_act   = 0x151A17FF,
  elevated      = 0x1F2722FF,
  border        = 0x2A342EFF,
  border_hvr    = 0x3D5446FF,
  text          = 0xE8EEEAFF,
  text_dim      = 0x8B968EFF,
  text_mute     = 0x5C655FFF,
  popup_bg      = 0x161C18F5,
  title_bg      = 0x0C0F0DFF,
  title_bg_act  = 0x121614FF,
  accent        = 0x1EFF5EFF,
  accent_hvr    = 0x62FF8AFF,
  accent_fill   = 0x0E2A18FF,
  accent_fill_h = 0x174A24FF,
  danger        = 0xE07070FF,
  danger_fill   = 0x3A1E1EFF,
  danger_hvr    = 0x4A2828FF,
  success       = 0x5EDC8AFF,
  success_fill  = 0x1A3224FF,
  success_hvr   = 0x244830FF,
}

function ui_push_theme()
  local n_col, n_var = 0, 0
  local function col(getter, value)
    if getter then
      r.ImGui_PushStyleColor(ctx, getter(), value)
      n_col = n_col + 1
    end
  end
  local function var1(getter, value)
    if getter then
      r.ImGui_PushStyleVar(ctx, getter(), value)
      n_var = n_var + 1
    end
  end
  local function var2(getter, a, b)
    if getter then
      r.ImGui_PushStyleVar(ctx, getter(), a, b)
      n_var = n_var + 1
    end
  end

  local T = UI_THEME
  col(r.ImGui_Col_WindowBg, T.bg)
  col(r.ImGui_Col_ChildBg, 0x00000000)
  col(r.ImGui_Col_PopupBg, T.popup_bg)
  col(r.ImGui_Col_Border, T.border)
  col(r.ImGui_Col_BorderShadow, 0x00000000)
  col(r.ImGui_Col_Text, T.text)
  col(r.ImGui_Col_TextDisabled, T.text_mute)
  col(r.ImGui_Col_TitleBg, T.title_bg)
  col(r.ImGui_Col_TitleBgActive, T.title_bg_act)
  col(r.ImGui_Col_TitleBgCollapsed, T.title_bg)
  col(r.ImGui_Col_MenuBarBg, T.title_bg_act)
  col(r.ImGui_Col_FrameBg, T.surface)
  col(r.ImGui_Col_FrameBgHovered, T.surface_hvr)
  col(r.ImGui_Col_FrameBgActive, T.accent_fill)
  col(r.ImGui_Col_Button, T.surface)
  col(r.ImGui_Col_ButtonHovered, T.surface_hvr)
  col(r.ImGui_Col_ButtonActive, T.surface_act)
  col(r.ImGui_Col_Header, T.accent_fill)
  col(r.ImGui_Col_HeaderHovered, T.accent_fill_h)
  col(r.ImGui_Col_HeaderActive, 0x1A5A2CFF)
  col(r.ImGui_Col_Separator, T.border)
  col(r.ImGui_Col_SeparatorHovered, T.border_hvr)
  col(r.ImGui_Col_SeparatorActive, T.accent)
  col(r.ImGui_Col_CheckMark, T.accent)
  col(r.ImGui_Col_SliderGrab, T.accent)
  col(r.ImGui_Col_SliderGrabActive, T.accent_hvr)
  col(r.ImGui_Col_ResizeGrip, 0x1EFF5E33)
  col(r.ImGui_Col_ResizeGripHovered, 0x1EFF5E77)
  col(r.ImGui_Col_ResizeGripActive, T.accent)
  col(r.ImGui_Col_ScrollbarBg, 0x0C0F0D00)
  col(r.ImGui_Col_ScrollbarGrab, 0x3A4A4088)
  col(r.ImGui_Col_ScrollbarGrabHovered, 0x5A6A60AA)
  col(r.ImGui_Col_ScrollbarGrabActive, T.accent)
  col(r.ImGui_Col_Tab, T.surface)
  col(r.ImGui_Col_TabHovered, T.surface_hvr)
  col(r.ImGui_Col_TabActive, T.accent_fill)
  col(r.ImGui_Col_PlotHistogram, T.accent)
  col(r.ImGui_Col_NavHighlight, 0x00000000)

  var1(r.ImGui_StyleVar_WindowRounding, 10)
  var1(r.ImGui_StyleVar_ChildRounding, 8)
  var1(r.ImGui_StyleVar_PopupRounding, 8)
  var1(r.ImGui_StyleVar_FrameRounding, 6)
  var1(r.ImGui_StyleVar_GrabRounding, 4)
  var1(r.ImGui_StyleVar_TabRounding, 6)
  var1(r.ImGui_StyleVar_ScrollbarRounding, 8)
  var1(r.ImGui_StyleVar_WindowBorderSize, 1)
  var1(r.ImGui_StyleVar_ChildBorderSize, 0)
  var1(r.ImGui_StyleVar_PopupBorderSize, 1)
  var1(r.ImGui_StyleVar_FrameBorderSize, 0)
  var2(r.ImGui_StyleVar_WindowPadding, 10, 8)
  var2(r.ImGui_StyleVar_FramePadding, 8, 4)
  var2(r.ImGui_StyleVar_ItemSpacing, 6, 5)
  var2(r.ImGui_StyleVar_ItemInnerSpacing, 6, 4)
  var1(r.ImGui_StyleVar_GrabMinSize, 10)
  var1(r.ImGui_StyleVar_ScrollbarSize, 10)

  state._ui_theme_cols = n_col
  state._ui_theme_vars = n_var
end

function ui_pop_theme()
  local cols = state._ui_theme_cols or 0
  local vars = state._ui_theme_vars or 0
  state._ui_theme_cols = 0
  state._ui_theme_vars = 0
  if cols <= 0 and vars <= 0 then
    return
  end
  -- Docker float/dock can invalidate the context mid-frame. Never let a
  -- style-stack unwind take the script down with it.
  if not (ctx and r.ImGui_ValidatePtr(ctx, "ImGui_Context*")) then
    return
  end
  if cols > 0 then
    pcall(r.ImGui_PopStyleColor, ctx, cols)
  end
  if vars > 0 then
    pcall(r.ImGui_PopStyleVar, ctx, vars)
  end
end

function ui_draw_panel(dl, x0, y0, x1, y1, rounding, bg, border, hovered, active)
  rounding = rounding or 7.0
  if hovered and not active then
    r.ImGui_DrawList_AddRectFilled(dl, x0 - 0.5, y0 - 0.5, x1 + 0.5, y1 + 0.5, 0xFFFFFF10, rounding + 0.5)
  end
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x1, y1, bg, rounding)
  if not active then
    r.ImGui_DrawList_AddLine(dl, x0 + rounding, y0 + 1.0, x1 - rounding, y0 + 1.0, 0xFFFFFF16, 1.0)
  end
  if border and border ~= 0 then
    r.ImGui_DrawList_AddRect(dl, x0 + 0.5, y0 + 0.5, x1 - 0.5, y1 - 0.5, border, rounding, 0, 1.0)
  end
end

function ui_button_colors_from_accent(accent, hovered, pressed)
  local cr, cg, cb = extract_rgb_rrgbbaa(accent or UI_THEME.accent)
  local function tone(t, a)
    return build_color_rrgbbaa(
      math.max(0, math.min(255, math.floor(cr * t))),
      math.max(0, math.min(255, math.floor(cg * t))),
      math.max(0, math.min(255, math.floor(cb * t))),
      a or 255
    )
  end
  if pressed then
    return tone(0.18), 0x00000000, 0xFFFFFFFF, tone(1.0), 1.2
  end
  if hovered then
    return tone(0.40), tone(1.0, 0x33), 0xFFFFFFFF, tone(1.0), 1.2
  end
  return tone(0.26), 0x00000000, 0xFFFFFFFF, tone(0.90), 1.0
end

function ui_button_colors(style, hovered, active, selected)
  local T = UI_THEME
  if style == "danger" then
    if active then return T.danger_fill, 0x00000000, 0xFFFFFFFF, T.danger, 1.0 end
    if hovered then return T.danger_hvr, 0xE0707028, 0xFFFFFFFF, 0xE0707055, 1.0 end
    return 0x2C1818FF, 0x00000000, 0xF0C4C4FF, 0xE0707033, 1.0
  elseif style == "ghost_arrow" then
    if active then return 0x00000000, 0x00000000, 0xB6FFD0FF, 0x1EFF5E33, 0.0 end
    if hovered then return 0x00000000, 0x00000000, 0xFFFFFFFF, 0x1EFF5E28, 0.0 end
    return 0x00000000, 0x00000000, 0x8AA898FF, 0x00000000, 0.0
  elseif style == "success" then
    if active then return T.success_fill, 0x00000000, 0xFFFFFFFF, T.success, 1.0 end
    if hovered then return T.success_hvr, 0x5EDC8A28, 0xFFFFFFFF, 0x5EDC8A55, 1.0 end
    return 0x173022FF, 0x00000000, 0xD4F5E0FF, 0x5EDC8A33, 1.0
  elseif style == "primary" or selected then
    if active then return 0x0A2212FF, 0x00000000, 0xFFFFFFFF, T.accent, 1.2 end
    if hovered then return T.accent_fill_h, 0x1EFF5E28, 0xFFFFFFFF, T.accent_hvr, 1.2 end
    return T.accent_fill, 0x00000000, 0xE8F8EEFF, 0x1EFF5E66, 1.0
  elseif style == "accent" then
    if active then return 0x0F3018FF, 0x00000000, 0xFFFFFFFF, T.accent_hvr, 1.2 end
    if hovered then return 0x1A5A2CFF, 0x1EFF5E33, 0xFFFFFFFF, T.accent_hvr, 1.2 end
    return 0x145028FF, 0x00000000, 0xF0FFF4FF, T.accent, 1.0
  end
  if active then return T.surface_act, 0x00000000, 0xFFFFFFFF, T.border_hvr, 1.0 end
  if hovered then return T.surface_hvr, 0xFFFFFF10, 0xFFFFFFFF, T.border_hvr, 1.0 end
  return T.surface, 0x00000000, T.text_dim, T.border, 1.0
end

function ui_button_draw_icon(dl, icon, cx, cy, size, color)
  local arm = size * 0.32
  local stroke = math.max(1.4, size * 0.08)
  if icon == "plus" then
    r.ImGui_DrawList_AddLine(dl, cx - arm, cy, cx + arm, cy, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx, cy - arm, cx, cy + arm, color, stroke)
  elseif icon == "minus" then
    r.ImGui_DrawList_AddLine(dl, cx - arm, cy, cx + arm, cy, color, stroke)
  elseif icon == "close" then
    r.ImGui_DrawList_AddLine(dl, cx - arm, cy - arm, cx + arm, cy + arm, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx + arm, cy - arm, cx - arm, cy + arm, color, stroke)
  elseif icon == "check" then
    r.ImGui_DrawList_AddLine(dl, cx - arm * 0.85, cy + arm * 0.05, cx - arm * 0.12, cy + arm * 0.78, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx - arm * 0.12, cy + arm * 0.78, cx + arm * 0.95, cy - arm * 0.70, color, stroke)
  elseif icon == "chev_left" then
    r.ImGui_DrawList_AddLine(dl, cx + arm * 0.28, cy - arm * 0.72, cx - arm * 0.38, cy, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx - arm * 0.38, cy, cx + arm * 0.28, cy + arm * 0.72, color, stroke)
  elseif icon == "chev_right" then
    r.ImGui_DrawList_AddLine(dl, cx - arm * 0.28, cy - arm * 0.72, cx + arm * 0.38, cy, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx + arm * 0.38, cy, cx - arm * 0.28, cy + arm * 0.72, color, stroke)
  elseif icon == "chev_down" then
    r.ImGui_DrawList_AddLine(dl, cx - arm * 0.72, cy - arm * 0.22, cx, cy + arm * 0.42, color, stroke)
    r.ImGui_DrawList_AddLine(dl, cx, cy + arm * 0.42, cx + arm * 0.72, cy - arm * 0.22, color, stroke)
  elseif icon == "chev_right_small" then
    r.ImGui_DrawList_AddTriangleFilled(dl, cx + arm * 0.28, cy, cx - arm * 0.42, cy - arm * 0.62, cx - arm * 0.42, cy + arm * 0.62, color)
  elseif icon == "play" then
    local h = size * 0.30
    r.ImGui_DrawList_AddTriangleFilled(dl, cx - h * 0.38, cy - h, cx - h * 0.38, cy + h, cx + h * 0.82, cy, color)
  elseif icon == "pause" then
    local h = size * 0.28
    local bar_w = size * 0.10
    local gap = size * 0.08
    r.ImGui_DrawList_AddRectFilled(dl, cx - gap - bar_w, cy - h, cx - gap, cy + h, color, 1.6)
    r.ImGui_DrawList_AddRectFilled(dl, cx + gap, cy - h, cx + gap + bar_w, cy + h, color, 1.6)
  elseif icon == "stop" then
    local s = size * 0.24
    r.ImGui_DrawList_AddRectFilled(dl, cx - s, cy - s, cx + s, cy + s, color, 2.2)
  elseif icon == "list" then
    local lw = size * 0.28
    local dot = math.max(1.0, size * 0.05)
    for i = -1, 1 do
      local ly = cy + i * (size * 0.20)
      r.ImGui_DrawList_AddCircleFilled(dl, cx - lw - dot * 1.4, ly, dot, color, 8)
      r.ImGui_DrawList_AddLine(dl, cx - lw, ly, cx + lw, ly, color, 1.6)
    end
  elseif icon == "midi" then
    local rad = size * 0.36
    r.ImGui_DrawList_AddCircle(dl, cx, cy, rad, color, 18, stroke)
    local pr = math.max(1.05, size * 0.055)
    local s = size * 0.22
    r.ImGui_DrawList_AddCircleFilled(dl, cx - s * 0.55, cy - s * 0.42, pr, color, 8)
    r.ImGui_DrawList_AddCircleFilled(dl, cx + s * 0.55, cy - s * 0.42, pr, color, 8)
    r.ImGui_DrawList_AddCircleFilled(dl, cx - s * 0.88, cy + s * 0.22, pr, color, 8)
    r.ImGui_DrawList_AddCircleFilled(dl, cx + s * 0.88, cy + s * 0.22, pr, color, 8)
    r.ImGui_DrawList_AddCircleFilled(dl, cx, cy + s * 0.72, pr, color, 8)
  elseif type(icon) == "string" and icon:match("^dice[1-6]$") then
    local count = tonumber(icon:match("(%d)$")) or 1
    local half = size * 0.26
    r.ImGui_DrawList_AddRect(dl, cx - half, cy - half, cx + half, cy + half, color, 3.0, 0, 1.4)
    local p = half * 0.48
    local pip_r = math.max(1.2, size * 0.045)
    local function pip(dx, dy)
      r.ImGui_DrawList_AddCircleFilled(dl, cx + dx, cy + dy, pip_r, color, 10)
    end
    if count == 1 or count == 3 or count == 5 then pip(0, 0) end
    if count >= 2 then pip(-p, -p) pip(p, p) end
    if count >= 4 then pip(p, -p) pip(-p, p) end
    if count == 6 then pip(-p, 0) pip(p, 0) end
  end
end

function draw_ui_button(id, label, w, h, opts)
  opts = opts or {}
  local style = opts.style or "default"
  local icon = opts.icon
  local trailing = opts.trailing_icon
  local display = label or ""
  if icon and not trailing then
    display = ""
  end
  local frame_padding = { r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding()) }
  local frame_pad_x = frame_padding[1]
  local frame_pad_y = frame_padding[2]
  if opts.compact then
    frame_pad_x = frame_pad_x * 0.65
    frame_pad_y = frame_pad_y * 0.65
  end

  local text_size = { r.ImGui_CalcTextSize(ctx, (display ~= "" and display) or "Ay") }
  local trail_w = trailing and 14 or 0
  if not w or w == 0 then
    if opts.full_width then
      w = r.ImGui_GetContentRegionAvail(ctx)
    elseif display ~= "" then
      w = text_size[1] + frame_pad_x * 2 + trail_w
    else
      w = h or 26
    end
  end
  if not h or h == 0 then
    if display ~= "" then
      h = text_size[2] + frame_pad_y * 2
    else
      h = 26
    end
  end

  r.ImGui_InvisibleButton(ctx, "##ui_" .. tostring(id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local press = active and 1.0 or 0.0
  local cx = (x0 + x1) * 0.5
  local cy = (y0 + y1) * 0.5 + press
  local rounding = opts.pill and (h * 0.5) or (opts.compact and 6.0 or 7.0)
  local tint = opts.color
  local bg, glow, text_col, border, border_w
  if tint and opts.selected then
    bg, glow, text_col, border, border_w = ui_button_colors_from_accent(tint, hovered, active)
  else
    bg, glow, text_col, border, border_w = ui_button_colors(style, hovered, active, opts.selected)
  end
  local is_ghost_arrow = style == "ghost_arrow"

  if is_ghost_arrow then
    if hovered or active then
      r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, active and math.min(w, h) * 0.40 or math.min(w, h) * 0.34, border, 22)
    end
  else
    if glow ~= 0 and hovered then
      r.ImGui_DrawList_AddRectFilled(dl, x0 - 1, y0 - 1, x1 + 1, y1 + 1, glow, rounding + 1)
    end
    ui_draw_panel(dl, x0, y0, x1, y1, rounding, bg, border, hovered, active)
    if opts.selected then
      r.ImGui_DrawList_AddRectFilled(dl, x0 + 6, y1 - 3, x1 - 6, y1 - 1.5, tint or UI_THEME.accent, 1.5)
    end
  end

  if icon and not trailing then
    local icon_size = math.min(w, h)
    local icon_color = (hovered or active) and 0xFFFFFFFF or text_col
    if is_ghost_arrow then
      if active then
        icon_size = icon_size * 1.12
        icon_color = 0xB6FFD0FF
      elseif hovered then
        icon_size = icon_size * 1.08
        icon_color = 0xFFFFFFFF
      end
    end
    ui_button_draw_icon(dl, icon, cx, cy, icon_size, icon_color)
  elseif display ~= "" then
    local text_x = x0 + (w - text_size[1] - trail_w) * 0.5
    local text_y = y0 + (h - text_size[2]) * 0.5 + press
    r.ImGui_DrawList_AddText(dl, text_x, text_y, text_col, display)
    if trailing then
      ui_button_draw_icon(dl, trailing, x1 - 10, cy, 14, text_col)
    end
  end

  return clicked
end

local function draw_tag_button(ctx, label, active, tag, id_prefix)
  id_prefix = id_prefix or ""
  local text_size = {r.ImGui_CalcTextSize(ctx, label)}
  local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
  local button_width = text_size[1] + frame_padding[1] * 2
  local button_height = text_size[2] + frame_padding[2] * 2
  local tag_color = state.tag_colors[tag] or 0x336699
  local base_r, base_g, base_b = extract_rgb(tag_color)

  local clicked = r.ImGui_InvisibleButton(ctx, "##" .. id_prefix .. "tag_" .. label, button_width, button_height)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  if hovered then
    state.hovered_tag = tag
  end

  local factor, alpha, text_color
  if active then
    factor = hovered and 0.82 or 0.70
    alpha = 255
    text_color = 0xFFFFFFFF
  elseif hovered then
    factor = 0.55
    alpha = 220
    text_color = 0xF4F4F4FF
  else
    factor = 0.38
    alpha = 160
    text_color = 0xD0D0D0FF
  end
  if pressed then
    factor = factor * 0.88
  end

  local bg = build_color_rrgbbaa(
    math.floor(base_r * factor),
    math.floor(base_g * factor),
    math.floor(base_b * factor),
    alpha
  )
  local border = build_color_rrgbbaa(
    math.min(255, math.floor(base_r * (active and 0.95 or 0.70))),
    math.min(255, math.floor(base_g * (active and 0.95 or 0.70))),
    math.min(255, math.floor(base_b * (active and 0.95 or 0.70))),
    hovered and 220 or 140
  )
  local rounding = button_height * 0.5
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local press = pressed and 1.0 or 0.0
  ui_draw_panel(dl, x0, y0, x1, y1, rounding, bg, border, hovered, pressed)
  local text_x = x0 + frame_padding[1]
  local text_y = y0 + frame_padding[2] + press
  r.ImGui_DrawList_AddText(dl, text_x, text_y, text_color, label)
  if active then
    r.ImGui_DrawList_AddText(dl, text_x + 0.4, text_y, text_color, label)
  end
  return clicked
end

function draw_ui_checkbox(id, label, checked)
  local box = 15.0
  local gap = 8.0
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  local h = math.max(box, th + 2)
  local w = box + gap + tw
  r.ImGui_InvisibleButton(ctx, "##chk_" .. tostring(id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local bx0 = x0
  local by0 = y0 + (h - box) * 0.5 + (active and 1.0 or 0.0)
  local bx1, by1 = bx0 + box, by0 + box
  local bg = checked and UI_THEME.accent_fill or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local border = checked and UI_THEME.accent or (hovered and UI_THEME.border_hvr or UI_THEME.border)
  ui_draw_panel(dl, bx0, by0, bx1, by1, 4.0, bg, border, hovered, active)
  if checked then
    ui_button_draw_icon(dl, "check", bx0 + box * 0.5, by0 + box * 0.5, box, 0xFFFFFFFF)
  end
  r.ImGui_DrawList_AddText(dl, x0 + box + gap, y0 + (h - th) * 0.5, UI_THEME.text, label)
  if clicked then
    return true, not checked
  end
  return false, checked
end

function draw_ui_radio(id, label, selected)
  local rad = 7.5
  local gap = 8.0
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  local h = math.max(rad * 2 + 2, th + 2)
  local w = rad * 2 + gap + tw
  r.ImGui_InvisibleButton(ctx, "##rad_" .. tostring(id), w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local cx = x0 + rad
  local cy = y0 + h * 0.5 + (active and 1.0 or 0.0)
  local ring = selected and UI_THEME.accent or (hovered and UI_THEME.border_hvr or UI_THEME.border)
  local fill = hovered and UI_THEME.surface_hvr or UI_THEME.surface
  r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, rad, fill, 20)
  r.ImGui_DrawList_AddCircle(dl, cx, cy, rad, ring, 20, selected and 1.6 or 1.2)
  if selected then
    r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, rad * 0.42, UI_THEME.accent, 16)
  elseif hovered then
    r.ImGui_DrawList_AddCircleFilled(dl, cx, cy, rad * 0.22, 0x1EFF5E66, 12)
  end
  r.ImGui_DrawList_AddText(dl, x0 + rad * 2 + gap, y0 + (h - th) * 0.5, UI_THEME.text, label)
  return clicked
end

function draw_ui_combo(id, label, preview, choices, current, stringify)
  stringify = stringify or tostring
  local btn_w = 150
  if draw_ui_button(id, preview, btn_w, 24, { compact = true, trailing_icon = "chev_down" }) then
    r.ImGui_OpenPopup(ctx, "##combo_" .. tostring(id))
  end
  r.ImGui_SameLine(ctx)
  r.ImGui_AlignTextToFramePadding(ctx)
  r.ImGui_Text(ctx, label)

  local changed = false
  local value = current
  if r.ImGui_BeginPopup(ctx, "##combo_" .. tostring(id)) then
    for _, choice in ipairs(choices) do
      local choice_label = stringify(choice)
      local is_sel = (choice == current)
      if draw_ui_button(id .. "_opt_" .. tostring(choice), choice_label, 180, 22, {
        compact = true,
        style = is_sel and "accent" or "default",
        selected = is_sel,
      }) then
        changed = true
        value = choice
        r.ImGui_CloseCurrentPopup(ctx)
      end
    end
    r.ImGui_EndPopup(ctx)
  end
  return changed, value
end

function draw_ui_number(id, label, value, step, step_fast, format, min_v, max_v)
  step = step or 0.1
  step_fast = step_fast or (step * 10)
  format = format or "%.1f"
  local h = 24
  local changed = false
  local coarse = is_shift_down and is_shift_down()
  local delta = coarse and step_fast or step
  if draw_ui_button(id .. "_minus", nil, h, h, { icon = "minus", compact = true }) then
    value = value - delta
    changed = true
  end
  r.ImGui_SameLine(ctx, 0, 4)
  r.ImGui_SetNextItemWidth(ctx, 88)
  local ret, v = r.ImGui_InputDouble(ctx, "##num_" .. tostring(id), value, 0, 0, format)
  if ret then
    value = v
    changed = true
  end
  r.ImGui_SameLine(ctx, 0, 4)
  if draw_ui_button(id .. "_plus", nil, h, h, { icon = "plus", compact = true }) then
    value = value + delta
    changed = true
  end
  if changed then
    if min_v then value = math.max(min_v, value) end
    if max_v then value = math.min(max_v, value) end
  end
  r.ImGui_SameLine(ctx, 0, 8)
  r.ImGui_AlignTextToFramePadding(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, label)
  return changed, value
end

function draw_ui_color(id, label, rgb24, inline)
  local cr, cg, cb = extract_rgb(rgb24 or 0x336699)
  local fill = build_color_rrgbbaa(cr, cg, cb, 255)
  local size = 18
  r.ImGui_InvisibleButton(ctx, "##swatch_" .. tostring(id), size, size)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  ui_draw_panel(dl, x0, y0, x1, y1, 5.0, fill, hovered and 0xFFFFFFFF or UI_THEME.border, hovered, active)
  if clicked and not inline then
    r.ImGui_OpenPopup(ctx, "##color_" .. tostring(id))
  end
  r.ImGui_SameLine(ctx, 0, 8)
  r.ImGui_AlignTextToFramePadding(ctx)
  r.ImGui_Text(ctx, label)

  local changed = false
  local new_color = rgb24
  local function run_picker()
    local picker = r.ImGui_ColorPicker3 or r.ImGui_ColorEdit3
    if picker then
      local ok, result = picker(ctx, "##picker_" .. tostring(id), (rgb24 or 0) | 0xFF000000, 0)
      if ok then
        changed = true
        new_color = result & 0xFFFFFF
      end
    end
  end
  if inline then
    run_picker()
  elseif r.ImGui_BeginPopup(ctx, "##color_" .. tostring(id)) then
    run_picker()
    r.ImGui_EndPopup(ctx)
  end
  return changed, new_color
end


-- Function to save tag colors to current preset
local function save_tag_color_to_preset(tag, color)
  -- Load current presets
  local tag_presets = {}
  local function load_tag_presets()
    local preset_file = io.open(CONFIG_DIR .. "/tag_presets.lua", "r")
    if preset_file then
      local content = preset_file:read("*all")
      preset_file:close()
      local success, presets = pcall(load, content)
      if success and type(presets) == "function" then
        tag_presets = presets() or {}
      end
    end
  end
  load_tag_presets()
  
  -- Ensure current preset exists
  if not tag_presets[state.current_preset_name] then
    tag_presets[state.current_preset_name] = {}
  end
  
  -- Update the tag color in the preset
  tag_presets[state.current_preset_name][tag] = color
  
  -- Save presets back to file
  local preset_content = "return " .. serialize_table(tag_presets)
  local preset_file = io.open(CONFIG_DIR .. "/tag_presets.lua", "w")
  if preset_file then
    preset_file:write(preset_content)
    preset_file:close()
  end
end

-- Helper function to categorize tags
function categorize_tags(tag)
  -- Normalize tag to lowercase for comparison (but preserve original for display)
  local tag_lower = string.lower(tag)
  
  -- Drum category tags (case-insensitive)
  local drum_tags = {
    kick = true, snare = true, clap = true, snap = true, rim = true, hat = true,
    tom = true, ride = true, crash = true, perc = true, fx = true,
    bass = true, ["808"] = true, drum = true
  }
  
  -- Melodic category tags (case-insensitive)
  local melodic_tags = {
    vocal = true, pluck = true, lead = true, pad = true,
    keys = true, guitar = true, swell = true  -- Swell is melodic
  }
  
  -- Loop/oneshot category tags (case-insensitive, handle both "One shot" and "oneshot")
  local loop_tags = {
    loop = true, ["one shot"] = true, oneshot = true
  }
  
  if drum_tags[tag_lower] then
    return "drum"
  elseif melodic_tags[tag_lower] then
    return "melodic"
  elseif GENRE_TAG_SET[tag_lower] then
    return "genre"
  elseif loop_tags[tag_lower] then
    return "loop"
  end
  
  return nil
end

function is_loop_oneshot_filter_tag(tag)
  local lower = string.lower(tostring(tag or ""))
  return lower == "loop" or lower == "one shot" or lower == "oneshot"
end

function clear_loop_oneshot_filters(except_tag)
  local except_lower = except_tag and string.lower(tostring(except_tag)) or nil
  for tag, active in pairs(state.active_tags or {}) do
    if active and is_loop_oneshot_filter_tag(tag) then
      if not except_lower or string.lower(tostring(tag)) ~= except_lower then
        state.active_tags[tag] = nil
      end
    end
  end
end

function toggle_sample_map_tag_filter(tag)
  if not tag then
    return
  end
  state.active_tags = state.active_tags or {}
  local active = state.active_tags[tag]
  if is_loop_oneshot_filter_tag(tag) then
    if active then
      state.active_tags[tag] = nil
    else
      clear_loop_oneshot_filters(tag)
      state.active_tags[tag] = true
    end
    return
  end
  if active then
    state.active_tags[tag] = nil
  else
    state.active_tags[tag] = true
  end
end

-- Helper function to draw a larger category tag
local function draw_category_tag(ctx, label, id_prefix, active)
  id_prefix = id_prefix or ""
  local text_size = {r.ImGui_CalcTextSize(ctx, label)}
  local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
  local button_width = text_size[1] + frame_padding[1] * 2
  local button_height = text_size[2] + frame_padding[2] * 2

  local clicked = r.ImGui_InvisibleButton(ctx, "##" .. id_prefix .. "cat_" .. label, button_width, button_height)
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local pressed = r.ImGui_IsItemActive(ctx)
  local bg, border, text
  if active then
    bg = hovered and UI_THEME.accent_fill_h or UI_THEME.accent_fill
    border = UI_THEME.accent
    text = 0xFFFFFFFF
  elseif hovered then
    bg = UI_THEME.surface_hvr
    border = UI_THEME.border_hvr
    text = UI_THEME.text
  else
    bg = UI_THEME.surface
    border = UI_THEME.border
    text = UI_THEME.text_dim
  end
  local dl = r.ImGui_GetWindowDrawList(ctx)
  ui_draw_panel(dl, x0, y0, x1, y1, button_height * 0.5, bg, border, hovered, pressed)
  local text_x = x0 + (button_width - text_size[1]) * 0.5
  local text_y = y0 + (button_height - text_size[2]) * 0.5 + (pressed and 1.0 or 0.0)
  r.ImGui_DrawList_AddText(dl, text_x, text_y, text, label)
  return clicked
end

function imgui_window_right_x()
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_WindowPadding())
  local win_x = r.ImGui_GetWindowPos(ctx)
  local win_w = select(1, r.ImGui_GetWindowSize(ctx))
  return win_x + win_w - (pad_x or 8)
end

function imgui_same_line_if_fits(needed_w, gap)
  gap = gap or select(1, r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing()))
  local last_x2 = r.ImGui_GetItemRectMax(ctx)
  if last_x2 + gap + needed_w <= imgui_window_right_x() then
    r.ImGui_SameLine(ctx, 0, gap)
    return true
  end
  return false
end

function calc_tag_chip_width(label)
  local text_w = r.ImGui_CalcTextSize(ctx, label)
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  return text_w + pad_x * 2
end

function calc_compact_chip_width(label)
  local text_w = r.ImGui_CalcTextSize(ctx, label)
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  return text_w + pad_x * 0.65 * 2
end

function calc_seq_note_edit_mode_btn_width()
  local max_text_w = r.ImGui_CalcTextSize(ctx, "Notes")
  for _, def in ipairs(seq_note_edit_mode_defs()) do
    local text_w = r.ImGui_CalcTextSize(ctx, def.label)
    if text_w > max_text_w then
      max_text_w = text_w
    end
  end
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  return max_text_w + pad_x * 0.65 * 2
end

function measure_tag_group_width(cat_label, entries)
  local spacing = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing())
  local w = 0
  if cat_label and cat_label ~= "" then
    w = calc_tag_chip_width(cat_label) + spacing + r.ImGui_CalcTextSize(ctx, ":")
  end
  for _, entry in ipairs(entries or {}) do
    w = w + spacing + calc_tag_chip_width(entry.tag)
  end
  return w
end

function tag_group_all_active(entries)
  if not entries or #entries == 0 then
    return false
  end
  for _, entry in ipairs(entries) do
    if not state.active_tags[entry.tag] then
      return false
    end
  end
  return true
end

function toggle_tag_group(entries)
  local all_active = tag_group_all_active(entries)
  for _, entry in ipairs(entries) do
    if all_active then
      state.active_tags[entry.tag] = nil
    else
      state.active_tags[entry.tag] = true
    end
  end
end

function parent_category_fully_active(cat)
  if cat ~= "drum" and cat ~= "melodic" and cat ~= "genre" then
    return false
  end
  local found = false
  for _, entry in ipairs(state.tag_list or {}) do
    if categorize_tags(entry.tag) == cat then
      found = true
      if not state.active_tags[entry.tag] then
        return false
      end
    end
  end
  return found
end

function should_hide_active_tag_in_search_bar(tag)
  local cat = categorize_tags(tag)
  if cat ~= "drum" and cat ~= "melodic" and cat ~= "genre" then
    return false
  end
  if collapse_children_tags_active() and is_tag_parent_selected(cat) then
    return true
  end
  return parent_category_fully_active(cat)
end

function tag_group_has_active(entries)
  for _, entry in ipairs(entries or {}) do
    if state.active_tags[entry.tag] then
      return true
    end
  end
  return false
end

function collapse_children_tags_active()
  local mode = state.collapse_children_tags or "off"
  if mode == "on" then
    return true
  end
  if mode ~= "dynamic" then
    return false
  end
  local win_w = state.main_window_rect and state.main_window_rect.w
  if not win_w and r.ImGui_GetWindowSize then
    win_w = select(1, r.ImGui_GetWindowSize(ctx))
  end
  local threshold = state.collapse_children_tags_width or 1100
  return (win_w or 0) <= threshold
end

function set_collapse_children_tags_mode(mode)
  if mode ~= "on" and mode ~= "off" and mode ~= "dynamic" then
    return
  end
  if state.collapse_children_tags ~= mode then
    state.collapse_children_tags = mode
    save_config()
  end
end

function is_tag_parent_selected(key)
  return state.selected_tag_parents and state.selected_tag_parents[key] == true
end

function toggle_tag_parent_selected(key)
  state.selected_tag_parents = state.selected_tag_parents or {}
  if state.selected_tag_parents[key] then
    state.selected_tag_parents[key] = nil
  else
    state.selected_tag_parents[key] = true
  end
end

function render_collapsed_parent_chip(label, key, entries)
  if not entries or #entries == 0 then
    return
  end
  imgui_same_line_if_fits(calc_tag_chip_width(label), 8)
  local selected = is_tag_parent_selected(key) or tag_group_all_active(entries)
  if draw_category_tag(ctx, label, "collapse_cat_", selected) then
    local turning_off = tag_group_all_active(entries)
    toggle_tag_group(entries)
    state.selected_tag_parents = state.selected_tag_parents or {}
    if turning_off then
      state.selected_tag_parents[key] = nil
    else
      state.selected_tag_parents[key] = true
    end
  end
end

-- In collapsed mode, child tags sit to the right of the parent chips on the
-- first line when they fit, then wrap onto the next line.
function collapsed_child_group_entries(tag)
  local cat = categorize_tags(tag)
  if cat ~= "drum" and cat ~= "melodic" and cat ~= "genre" then
    return nil
  end
  local entries = {}
  for _, entry in ipairs(state.tag_list or {}) do
    if categorize_tags(entry.tag) == cat then
      entries[#entries + 1] = entry
    end
  end
  return entries
end

function child_tag_is_solo_in_group(tag, group)
  if not state.active_tags[tag] then
    return false
  end
  for _, entry in ipairs(group or {}) do
    if entry.tag ~= tag and state.active_tags[entry.tag] then
      return false
    end
  end
  return true
end

-- In collapsed mode, a child click isolates that tag within its parent group.
-- Clicking the already-soloed child restores the full parent filter.
function solo_collapsed_child_tag(tag)
  local group = collapsed_child_group_entries(tag)
  if not group or #group == 0 then
    toggle_sample_map_tag_filter(tag)
    return
  end
  state.active_tags = state.active_tags or {}
  if child_tag_is_solo_in_group(tag, group) then
    for _, entry in ipairs(group) do
      state.active_tags[entry.tag] = true
    end
    return
  end
  for _, entry in ipairs(group) do
    if entry.tag == tag then
      state.active_tags[entry.tag] = true
    else
      state.active_tags[entry.tag] = nil
    end
  end
end

function render_collapsed_child_tags(entries)
  if not entries or #entries == 0 then
    return
  end

  local spacing = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing())
  for idx, entry in ipairs(entries) do
    local tag = entry.tag
    imgui_same_line_if_fits(calc_tag_chip_width(tag), idx == 1 and 12 or spacing)
    if draw_tag_button(ctx, tag, state.active_tags[tag], tag) then
      solo_collapsed_child_tag(tag)
    end
  end
end

function render_wrapping_tag_entries(entries)
  local item_spacing_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing())
  local window_visible_x2 = imgui_window_right_x()

  for idx, entry in ipairs(entries) do
    local tag = entry.tag
    local tag_w = calc_tag_chip_width(tag)
    if idx == 1 then
      r.ImGui_SameLine(ctx)
    else
      local last_button_x2 = r.ImGui_GetItemRectMax(ctx)
      if last_button_x2 + item_spacing_x + tag_w < window_visible_x2 then
        r.ImGui_SameLine(ctx)
      end
    end

    local active = state.active_tags[tag]
    if draw_tag_button(ctx, tag, active, tag) then
      toggle_sample_map_tag_filter(tag)
    end
  end
end

function render_tag_category(label, entries, opts)
  opts = opts or {}
  if not entries or #entries == 0 then
    return
  end
  if opts.same_line then
    r.ImGui_SameLine(ctx, 0, opts.gap or 12)
  end
  if draw_category_tag(ctx, label, "cat_", tag_group_has_active(entries)) then
    toggle_tag_group(entries)
  end
  r.ImGui_SameLine(ctx)
  if r.ImGui_AlignTextToFramePadding then
    r.ImGui_AlignTextToFramePadding(ctx)
  end
  r.ImGui_Text(ctx, ":")
  render_wrapping_tag_entries(entries)
end

function render_tag_filters()
  if not state.tag_list or #state.tag_list == 0 then
    return
  end

  -- Reset hovered tag at start of frame
  state.hovered_tag = nil

  -- Categorize tags
  local drum_tags = {}
  local melodic_tags = {}
  local genre_tags = {}
  local loop_tags = {}

  for _, entry in ipairs(state.tag_list) do
    local tag = entry.tag
    local category = categorize_tags(tag)
    if category == "drum" then
      table.insert(drum_tags, entry)
    elseif category == "melodic" then
      table.insert(melodic_tags, entry)
    elseif category == "genre" then
      table.insert(genre_tags, entry)
    elseif category == "loop" then
      table.insert(loop_tags, entry)
    end
  end

  -- Loop / one-shot sit on the search row when there is room.
  if #loop_tags > 0 then
    for idx, entry in ipairs(loop_tags) do
      local tag_w = calc_tag_chip_width(entry.tag)
      if idx == 1 then
        imgui_same_line_if_fits(tag_w, 8)
      else
        imgui_same_line_if_fits(tag_w, 4)
      end
      local tag = entry.tag
      local active = state.active_tags[tag]
      if draw_tag_button(ctx, tag, active, tag) then
        toggle_sample_map_tag_filter(tag)
      end
    end
  end

  if collapse_children_tags_active() then
    render_collapsed_parent_chip("Drum", "drum", drum_tags)
    render_collapsed_parent_chip("Melodic", "melodic", melodic_tags)
    render_collapsed_parent_chip("Genre", "genre", genre_tags)

    local children = {}
    if is_tag_parent_selected("drum") then
      for _, entry in ipairs(drum_tags) do
        children[#children + 1] = entry
      end
    end
    if is_tag_parent_selected("melodic") then
      for _, entry in ipairs(melodic_tags) do
        children[#children + 1] = entry
      end
    end
    if is_tag_parent_selected("genre") then
      for _, entry in ipairs(genre_tags) do
        children[#children + 1] = entry
      end
    end
    render_collapsed_child_tags(children)
  else
    local combine_drum_melodic = false
    if #drum_tags > 0 and #melodic_tags > 0 then
      local cursor_x = r.ImGui_GetCursorScreenPos(ctx)
      local avail_w = imgui_window_right_x() - cursor_x
      local combined_w = measure_tag_group_width("Drum", drum_tags)
        + 12
        + measure_tag_group_width("Melodic", melodic_tags)
      combine_drum_melodic = combined_w <= avail_w
    end

    render_tag_category("Drum", drum_tags)
    render_tag_category("Melodic", melodic_tags, { same_line = combine_drum_melodic, gap = 12 })
    render_tag_category("Genre", genre_tags)
  end

  -- Check for C key press when hovering over a tag
  if state.hovered_tag and r.ImGui_IsKeyPressed and r.ImGui_Key_C then
    local c_pressed = r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_C(), false)
    if c_pressed then
      state.tag_color_picker_tag = state.hovered_tag
      r.ImGui_OpenPopup(ctx, "tag_color_picker")
    end
  end

  -- Color picker popup
  if r.ImGui_BeginPopup(ctx, "tag_color_picker") then
    if state.tag_color_picker_tag then
      r.ImGui_Text(ctx, "Edit color")
      r.ImGui_SameLine(ctx)
      r.ImGui_TextColored(ctx, UI_THEME.accent_hvr, state.tag_color_picker_tag)
      local tag_color = state.tag_colors[state.tag_color_picker_tag] or 0x336699
      local color_changed, new_color = draw_ui_color("tag_picker", "Color", tag_color, true)
      if color_changed then
        local rgb_color = new_color & 0xFFFFFF  -- Extract RGB part only
        state.tag_colors[state.tag_color_picker_tag] = rgb_color
        save_tag_color_to_preset(state.tag_color_picker_tag, rgb_color)
        save_config()  -- Also save to main config
      end
      
      r.ImGui_Spacing(ctx)
      if draw_ui_button("tag_picker_done", "Done") then
        r.ImGui_CloseCurrentPopup(ctx)
        state.tag_color_picker_tag = nil
      end
      
      -- Close popup if clicked outside (ImGui handles this automatically, but we can also check for escape)
      if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape then
        local escape_pressed = r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false)
        if escape_pressed then
          r.ImGui_CloseCurrentPopup(ctx)
          state.tag_color_picker_tag = nil
        end
      end
    else
      -- Tag was cleared, close popup
      r.ImGui_CloseCurrentPopup(ctx)
    end
    r.ImGui_EndPopup(ctx)
  end

  r.ImGui_Separator(ctx)
end


local function begin_window()
  r.ImGui_SetNextWindowSize(ctx, 1024, 720, r.ImGui_Cond_FirstUseEver())
  if r.ImGui_SetConfigVar and r.ImGui_ConfigVar_WindowsMoveFromTitleBarOnly then
    r.ImGui_SetConfigVar(ctx, r.ImGui_ConfigVar_WindowsMoveFromTitleBarOnly(), 1)
  end
  local flags = r.ImGui_WindowFlags_NoCollapse() |
                r.ImGui_WindowFlags_NoScrollbar() |
                r.ImGui_WindowFlags_NoScrollWithMouse() |
                r.ImGui_WindowFlags_NoNav() |
                r.ImGui_WindowFlags_MenuBar()
  -- ReaImGui docker attach/detach can fail Begin for a frame without
  -- pushing a window. Treat that as "not visible, still open".
  local ok, visible, open = pcall(r.ImGui_Begin, ctx, SCRIPT_NAME, true, flags)
  if not ok then
    return false, true, false
  end
  if open == nil then
    open = true
  end
  return visible and true or false, open, true
end

local function end_window(visible, began)
  -- ReaImGui docker attach/detach can return not-visible without pushing a
  -- window. Calling End() in that state asserts and poisons the context.
  if not began or not visible then
    return
  end
  if not (ctx and r.ImGui_ValidatePtr(ctx, "ImGui_Context*")) then
    return
  end
  pcall(r.ImGui_End, ctx)
end

-- Build peaks for a specific item while preserving user selection
local function rebuild_peaks_for_item(item)
  if not item then return end

  -- Save current selection
  local selected = {}
  local sel_count = r.CountSelectedMediaItems(0)
  for i = 0, sel_count - 1 do
    selected[#selected + 1] = r.GetSelectedMediaItem(0, i)
  end

  -- Select only the target item
  r.SelectAllMediaItems(0, false)
  r.SetMediaItemSelected(item, true)

  -- Rebuild peaks for selected items
  r.Main_OnCommand(40047, 0) -- Peaks: Rebuild peaks for selected items

  -- Restore previous selection
  r.SelectAllMediaItems(0, false)
  for _, it in ipairs(selected) do
    if r.ValidatePtr(it, "MediaItem*") then
      r.SetMediaItemSelected(it, true)
    end
  end
end

-- Insert a sample at the current cursor position in the arrange window
local function insert_sample_at_cursor(sample)
  if not sample or not sample.path then
    log("No sample to insert")
    return false
  end

  -- Check if file exists
  if not r.file_exists(sample.path) then
    log("Sample file does not exist: " .. sample.path)
    return false
  end

  -- Prevent UI refresh during operations
  r.PreventUIRefresh(1)

  -- Get cursor position
  local cursor_pos = r.GetCursorPosition()
  log("Cursor position: " .. string.format("%.3f", cursor_pos))

  -- Get selected track (or first track if none selected)
  local num_tracks = r.CountTracks(0)
  log("Total tracks in project: " .. num_tracks)

  local track = r.GetSelectedTrack(0, 0)
  if not track then
    log("No selected track, trying first track...")
    if num_tracks > 0 then
      track = r.GetTrack(0, 0)  -- Get first track (0-indexed)
    end
  end

  if not track then
    log("No track available for inserting sample (project has " .. num_tracks .. " tracks)")
    r.PreventUIRefresh(-1)
    return false
  end

  -- Get track info for debugging
  local _, track_name = r.GetTrackName(track)
  log("Using track: " .. (track_name or "unnamed"))

  -- Create media item
  local item = r.AddMediaItemToTrack(track)
  if not item then
    log("Failed to create media item")
    r.PreventUIRefresh(-1)
    return false
  end

  -- Set item position and length
  r.SetMediaItemPosition(item, cursor_pos, false)
  local startoffs = get_sample_start_offset(sample)
  local duration = math.max(0.001, (sample.duration or 1.0) - startoffs)
  r.SetMediaItemLength(item, duration, false)
  log("Set item position to " .. string.format("%.3f", cursor_pos) .. " and length to " .. string.format("%.3f", duration))

  -- Create take and set source
  local take = r.AddTakeToMediaItem(item)
  if take then
    local src = r.PCM_Source_CreateFromFile(sample.path)
    if src then
      local retval = r.SetMediaItemTake_Source(take, src)
      log("SetMediaItemTake_Source result: " .. tostring(retval))

      -- Verify the source was set
      local take_src = r.GetMediaItemTake_Source(take)
      if take_src then
        log("Take source successfully set")
      else
        log("WARNING: Take source not set properly")
      end

      -- Name the item after the filename (with debug)
      set_item_name(item, take, sample.path)
      if startoffs > 0 then
        r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", startoffs)
      end

      log("Inserted sample '" .. sample.name .. "' at position " .. string.format("%.3f", cursor_pos))

      -- Build peaks for the newly created item
      rebuild_peaks_for_item(item)

      -- Update arrange view and allow UI refresh
      r.UpdateArrange()
      r.PreventUIRefresh(-1)

      return true
    else
      log("Failed to create PCM source for: " .. sample.path)
      r.PreventUIRefresh(-1)
      return false
    end
  else
    log("Failed to create take for media item")
    r.PreventUIRefresh(-1)
    return false
  end
end

-- Get the drop position from mouse cursor context (using SWS extension)
local function get_drop_position()
  if not r.BR_GetMouseCursorContext then
    log("SWS functions not available; cannot get mouse position")
    return nil, nil
  end

  -- Refresh mouse context; returns window/segment/details strings
  local window, segment, details = r.BR_GetMouseCursorContext()

  -- Only proceed when mouse is over arrange view (window == "arrange")
  if window == "arrange" then
    local time_pos = r.BR_GetMouseCursorContext_Position()
    local track = r.BR_GetMouseCursorContext_Track()
    if time_pos then
      return time_pos, track
    end
  end

  -- No position available (mouse not over arrange)
  return nil, nil
end

-- Insert sample at specific position and track
local function insert_sample_at_position(sample, time_pos, target_track)
  if not sample or not sample.path then
    log("No sample to insert")
    return false
  end

  -- Check if file exists
  if not r.file_exists(sample.path) then
    log("Sample file does not exist: " .. sample.path)
    return false
  end

  -- Prevent UI refresh during operations
  r.PreventUIRefresh(1)

  -- Use target track if provided, otherwise fallback to selected/first track
  local track = target_track
  if not track then
    track = r.GetSelectedTrack(0, 0)
    if not track then
      local num_tracks = r.CountTracks(0)
      if num_tracks > 0 then
        track = r.GetTrack(0, 0)
      end
    end
  end

  if not track then
    log("No track available for inserting sample")
    r.PreventUIRefresh(-1)
    return false
  end

  -- Get track info for debugging
  local _, track_name = r.GetTrackName(track)
  log("Using track: " .. (track_name or "unnamed"))

  -- Create media item
  local item = r.AddMediaItemToTrack(track)
  if not item then
    log("Failed to create media item")
    r.PreventUIRefresh(-1)
    return false
  end

  -- Set item position and length
  r.SetMediaItemPosition(item, time_pos, false)
  local startoffs = get_sample_start_offset(sample)
  local duration = math.max(0.001, (sample.duration or 1.0) - startoffs)
  r.SetMediaItemLength(item, duration, false)
  log("Set item position to " .. string.format("%.3f", time_pos) .. " and length to " .. string.format("%.3f", duration))

  -- Create take and set source
  local take = r.AddTakeToMediaItem(item)
  if take then
    local src = r.PCM_Source_CreateFromFile(sample.path)
    if src then
      local retval = r.SetMediaItemTake_Source(take, src)
      log("SetMediaItemTake_Source result: " .. tostring(retval))

      -- Verify the source was set
      local take_src = r.GetMediaItemTake_Source(take)
      if take_src then
        log("Take source successfully set")
      else
        log("WARNING: Take source not set properly")
      end

      -- Name the item after the filename (with debug)
      set_item_name(item, take, sample.path)
      if startoffs > 0 then
        r.SetMediaItemTakeInfo_Value(take, "D_STARTOFFS", startoffs)
      end

      log("Inserted sample '" .. sample.name .. "' at position " .. string.format("%.3f", time_pos))

      -- Build peaks for the newly created item
      rebuild_peaks_for_item(item)

      -- Update arrange view and allow UI refresh
      r.UpdateArrange()
      r.PreventUIRefresh(-1)

      return true
    else
      log("Failed to create PCM source for: " .. sample.path)
      r.PreventUIRefresh(-1)
      return false
    end
  else
    log("Failed to create take for media item")
    r.PreventUIRefresh(-1)
    return false
  end
end

-- Wrap a single committed insert in one undo point (prefer the project-scoped API).
-- NOTE: declared as globals (not locals) to avoid exceeding Lua's 200 local-per-chunk limit.
function arrange_undo_begin()
  if r.Undo_BeginBlock2 then
    r.Undo_BeginBlock2(0)
  elseif r.Undo_BeginBlock then
    r.Undo_BeginBlock()
  end
end

function arrange_undo_end(label)
  label = label or "Insert sample"
  if r.Undo_EndBlock2 then
    r.Undo_EndBlock2(0, label, -1)
  elseif r.Undo_EndBlock then
    r.Undo_EndBlock(label, -1)
  end
end

-- Snap to grid only when REAPER snapping is enabled, mirroring native drag behavior.
function maybe_snap_drop_time(t)
  if not t then
    return t
  end
  if r.GetToggleCommandState and r.SnapToGrid and r.GetToggleCommandState(1157) == 1 then
    local snapped = r.SnapToGrid(0, t)
    if snapped and snapped == snapped then
      return snapped
    end
  end
  return t
end

-- Remove the live "provisional" preview item without touching the undo history.
function remove_provisional_drop()
  local p = state.provisional_drop
  state.provisional_drop = nil
  if not p or not p.item then
    return
  end
  if not r.ValidatePtr(p.item, "MediaItem*") then
    return
  end
  local track = p.track
  if not (track and r.ValidatePtr(track, "MediaTrack*")) then
    track = r.GetMediaItemTrack(p.item)
  end
  if not track then
    return
  end
  r.PreventUIRefresh(1)
  r.DeleteTrackMediaItem(track, p.item)
  r.UpdateArrange()
  r.PreventUIRefresh(-1)
end

-- Create/move a real media item under the cursor while dragging over the arrange,
-- so the user gets REAPER's own drop preview. Created outside any undo block; the
-- final commit (or cancel) is what manages the undo history.
function update_provisional_drop(sample)
  if not sample or not sample.path then
    remove_provisional_drop()
    return
  end

  -- In-window drop targets (sequencer track row / timeline) are not arrange inserts.
  if state.seq_drop_target_idx or state.seq_timeline_drop_track_idx then
    remove_provisional_drop()
    return
  end

  local drop_time, drop_track = get_drop_position()
  if not drop_time or not drop_track then
    -- Cursor is not over an arrange track; hide the preview but keep dragging.
    remove_provisional_drop()
    return
  end

  drop_time = maybe_snap_drop_time(drop_time)
  state.last_mouse_time_pos = drop_time
  state.last_mouse_track = drop_track

  local p = state.provisional_drop
  local valid = p and p.item and r.ValidatePtr(p.item, "MediaItem*") and p.sample_path == sample.path
  if not valid then
    remove_provisional_drop()
    if not r.file_exists(sample.path) then
      return
    end
    r.PreventUIRefresh(1)
    local item = r.AddMediaItemToTrack(drop_track)
    if item then
      local take = r.AddTakeToMediaItem(item)
      local src = take and r.PCM_Source_CreateFromFile(sample.path)
      if src then
        r.SetMediaItemTake_Source(take, src)
        set_item_name(item, take, sample.path)
      end
      r.SetMediaItemLength(item, sample.duration or 1.0, false)
      r.SetMediaItemPosition(item, drop_time, false)
      -- Tint the preview so it reads as provisional, not a committed item.
      if r.ColorToNative then
        r.SetMediaItemInfo_Value(item, "I_CUSTOMCOLOR", r.ColorToNative(120, 170, 255) | 0x1000000)
      end
      r.SetMediaItemInfo_Value(item, "B_UISEL", 0)
      -- Peaks build lazily for the visible preview; the committed item rebuilds them.
      state.provisional_drop = { item = item, track = drop_track, time = drop_time, sample_path = sample.path }
    end
    r.UpdateArrange()
    r.PreventUIRefresh(-1)
    return
  end

  -- Reposition the existing preview (cheap: no source/peak rebuild).
  r.PreventUIRefresh(1)
  if drop_track ~= p.track and r.ValidatePtr(drop_track, "MediaTrack*") then
    r.MoveMediaItemToTrack(p.item, drop_track)
    p.track = drop_track
  end
  r.SetMediaItemPosition(p.item, drop_time, false)
  p.time = drop_time
  r.UpdateArrange()
  r.PreventUIRefresh(-1)
end

-- Hide REAPER's floating drag tooltip window if it is currently shown.
function clear_drag_tooltip()
  if state.drag_tooltip_active and r.TrackCtl_SetToolTip then
    r.TrackCtl_SetToolTip("", 0, 0, true)
  end
  state.drag_tooltip_active = false
end

local function is_alt_down()
  if r.JS_Mouse_GetState then
    local cap = r.JS_Mouse_GetState(0)
    if cap & 16 == 16 then
      return true
    end
  end
  if r.ImGui_GetIO then
    local io = r.ImGui_GetIO(ctx)
    if io and io.KeyAlt then
      return io.KeyAlt
    end
  end
  if r.ImGui_IsKeyDown and r.ImGui_Key_LeftAlt and r.ImGui_Key_RightAlt then
    return r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftAlt()) or r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightAlt())
  end
  return false
end

local function is_cmd_down()
  if not r.ImGui_IsKeyDown then
    return false
  end
  if r.ImGui_Key_LeftSuper and r.ImGui_Key_RightSuper then
    return r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftSuper()) or r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightSuper())
  end
  return false
end

local function is_shift_down()
  if not r.ImGui_IsKeyDown then
    return false
  end
  if r.ImGui_Key_LeftShift and r.ImGui_Key_RightShift then
    return r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftShift()) or r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightShift())
  end
  return false
end

function is_ctrl_down()
  if r.JS_Mouse_GetState then
    local cap = r.JS_Mouse_GetState(0)
    if cap & 4 == 4 then
      return true
    end
  end
  if r.ImGui_GetIO then
    local io = r.ImGui_GetIO(ctx)
    if io and io.KeyCtrl then
      return io.KeyCtrl
    end
  end
  if r.ImGui_IsKeyDown and r.ImGui_Key_LeftCtrl and r.ImGui_Key_RightCtrl then
    return r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftCtrl()) or r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightCtrl())
  end
  return false
end

function is_r_down()
  if not r.ImGui_IsKeyDown or not r.ImGui_Key_R then
    return false
  end
  return r.ImGui_IsKeyDown(ctx, r.ImGui_Key_R())
end

-- Customizable mouse-modifier support for sequencer gestures.
-- These are declared as globals (not locals) to avoid the per-chunk local limit,
-- matching the existing pattern used by is_ctrl_down().
MOUSE_MOD_DEFAULTS = {
  lane_zoom = "shift",
  time_zoom = "cmd",
  velocity_ramp = "shift",
  unify = "alt",
}

-- Ordered list used by the settings editor (id, label, hint).
MOUSE_MOD_ACTIONS = {
  { id = "time_zoom",     label = "Timeline zoom",   hint = "Wheel over the sequencer zooms the timeline horizontally. Shift+horizontal scroll also zooms." },
  { id = "lane_zoom",     label = "Lane height zoom", hint = "Wheel over the sequencer zooms note/parameter lane height." },
  { id = "velocity_ramp", label = "Value ramp",      hint = "Drag in a parameter lane ramps values across cells." },
  { id = "unify",         label = "Unify values",    hint = "Drag in a parameter lane sets every cell to the same value." },
}

MOUSE_MOD_CHOICES = { "none", "shift", "alt", "ctrl", "cmd" }

function modifier_is_down(mod)
  if mod == "shift" then return is_shift_down() end
  if mod == "alt" then return is_alt_down() end
  if mod == "ctrl" then return is_ctrl_down() end
  if mod == "cmd" then return is_cmd_down() end
  if mod == "none" then return true end
  return false
end

-- Returns true if the modifier currently configured for `action` is held.
function mod_active(action)
  local mods = state.mouse_mods or MOUSE_MOD_DEFAULTS
  local mod = mods[action] or MOUSE_MOD_DEFAULTS[action] or "none"
  return modifier_is_down(mod)
end

function mouse_mod_label(mod)
  if mod == "shift" then return "Shift" end
  if mod == "alt" then return "Alt/Option" end
  if mod == "ctrl" then return "Ctrl" end
  if mod == "cmd" then return "Cmd/Win" end
  return "None"
end

local function update_pending_drop_tracking()
  if not state.pending_waveform_drop then
    return
  end
  local time_pos, track = get_drop_position()
  if time_pos then
    state.last_mouse_time_pos = time_pos
    state.last_mouse_track = track
  end
end

local function render_playback_controls_compact(column_w)
  local is_playing = preview_proc ~= nil and preview_sample_obj ~= nil
  local current_pos = get_preview_position()
  local btn = 20
  local knob = 24

  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 2, 2)
  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 1, 1)

  if is_playing then
    if draw_ui_button("playback_pause", nil, btn, btn, { icon = "pause", style = "primary", compact = true }) then
      state.preview_position = current_pos or state.preview_position or 0.0
      stop_preview()
      state.preview_paused = true
    end
  else
    if draw_ui_button("playback_play", nil, btn, btn, { icon = "play", style = "primary", compact = true }) then
      if preview_sample_obj then
        local start_time = state.preview_paused and (state.preview_position or 0.0) or 0.0
        preview_sample(preview_sample_obj, start_time)
        state.preview_paused = false
      end
    end
  end

  r.ImGui_SameLine(ctx)
  if draw_ui_button("playback_stop", nil, btn, btn, { icon = "stop", compact = true }) then
    stop_preview()
    state.preview_paused = false
    state.preview_position = 0.0
  end

  local knob_offset = math.max(0, (column_w - knob) * 0.5)
  if knob_offset > 0 then
    r.ImGui_Dummy(ctx, knob_offset, 0)
    r.ImGui_SameLine(ctx, 0, 0)
  end
  draw_preview_volume_knob(knob)

  if preview_sample_obj then
    local duration = preview_sample_obj.duration or 0.0
    local pos = current_pos or state.preview_position or 0.0
    if pos > duration then pos = duration end
    r.ImGui_Text(ctx, string.format("%.1f/%.1fs", pos, duration))
  end

  r.ImGui_PopStyleVar(ctx, 2)
end

local function clamp_effective_duration(sample, seconds)
  local file_dur = (sample and type(sample.duration) == "number" and sample.duration > 0) and sample.duration or nil
  seconds = tonumber(seconds) or 0
  if file_dur then
    return math.max(0.001, math.min(file_dur, seconds))
  end
  return math.max(0.001, seconds)
end

local function render_waveform_overlay_tags(x0, y0, layout_x, layout_y)
  if preview_sample_obj and preview_sample_obj.tags and type(preview_sample_obj.tags) == "table" and #preview_sample_obj.tags > 0 then
    r.ImGui_SetCursorScreenPos(ctx, x0 + 4, y0 + 4)
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 3, 2)
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 3, 1)
    for idx, tag in ipairs(preview_sample_obj.tags) do
      if idx > 1 then
        r.ImGui_SameLine(ctx)
      end

      local active = state.active_tags[tag] or false
      if draw_tag_button(ctx, tag, active, tag, "waveform_") then
        local alt_pressed = false
        if r.ImGui_IsKeyDown and r.ImGui_Key_LeftAlt and r.ImGui_Key_RightAlt then
          alt_pressed = r.ImGui_IsKeyDown(ctx, r.ImGui_Key_LeftAlt()) or r.ImGui_IsKeyDown(ctx, r.ImGui_Key_RightAlt())
        end

        if alt_pressed then
          log("Deleting tag '" .. tag .. "' from sample: " .. preview_sample_obj.name)
          local new_tags = {}
          for _, t in ipairs(preview_sample_obj.tags) do
            if t ~= tag then
              table.insert(new_tags, t)
            end
          end
          preview_sample_obj.tags = new_tags
          for _, s in ipairs(state.samples) do
            if s.path == preview_sample_obj.path then
              s.tags = new_tags
              break
            end
          end
          rebuild_tag_index()
          save_samples()
          log("Tag deleted. Remaining tags: " .. table.concat(new_tags, ", "))
        elseif active then
          state.active_tags[tag] = nil
        else
          toggle_sample_map_tag_filter(tag)
        end
      end
    end
    r.ImGui_PopStyleVar(ctx, 2)
  end

  r.ImGui_SetCursorPos(ctx, layout_x, layout_y)
end

local function render_waveform()
  -- Always show waveform area if a sample is selected/previewing
  if not preview_sample_obj then
    -- Show placeholder message when no sample is selected
    r.ImGui_Text(ctx, "(No sample selected)")
    r.ImGui_Separator(ctx)
    return
  end

  -- Defer heavy waveform work across frames (placeholder shows immediately)
  if not waveform_data or waveform_data.sample_path ~= preview_sample_obj.path then
    ensure_waveform_for_sample(preview_sample_obj)
  end

  if not waveform_data then
    return
  end
  
  local height = 80
  local width = r.ImGui_GetContentRegionAvail(ctx)
  
  -- Render path as clickable folder buttons
  
  local full_path = preview_sample_obj.path or ""
  if full_path ~= "" then
    -- Find which scanned folder contains this sample
    local normalized_path = normalize_path(full_path)
    local scanned_root = nil
    
    -- Find the longest matching scanned folder (most specific match)
    for _, scanned_folder in ipairs(state.folders) do
      local norm_scanned = normalize_path(scanned_folder)
      -- Check if the sample path starts with this scanned folder
      if normalized_path:sub(1, #norm_scanned) == norm_scanned then
        if not scanned_root or #norm_scanned > #scanned_root then
          scanned_root = norm_scanned
        end
      end
    end
    
    -- Extract directory path (remove filename)
    local dir_path = normalized_path:match("(.+)/[^/]+$") or ""
    
    -- If we found a scanned root, only show path segments from that root onward
    local path_segments = {}
    if scanned_root and dir_path ~= "" then
      -- Always add the scanned root as the first segment
      local root_name = scanned_root:match("([^/]+)/?$") or scanned_root
      table.insert(path_segments, {name = root_name, path = scanned_root})
      
      -- Remove the scanned root from the path to get relative path
      local relative_path = dir_path
      if dir_path:sub(1, #scanned_root) == scanned_root then
        relative_path = dir_path:sub(#scanned_root + 1)
        -- Remove leading slash if present
        if relative_path:sub(1, 1) == "/" then
          relative_path = relative_path:sub(2)
        end
      end
      
      -- Build path segments for subfolders
      if relative_path ~= "" then
        local current_path = scanned_root
        for segment in relative_path:gmatch("([^/]+)") do
          current_path = current_path .. "/" .. segment
          table.insert(path_segments, {name = segment, path = current_path})
        end
      end
    elseif dir_path ~= "" then
      -- Fallback: show full path if no scanned root found (shouldn't happen normally)
      local is_absolute = dir_path:sub(1, 1) == "/"
      local current_path = is_absolute and "/" or ""
      for segment in dir_path:gmatch("([^/]+)") do
        if is_absolute then
          current_path = current_path .. segment
        else
          current_path = current_path .. (current_path == "" and "" or "/") .. segment
        end
        table.insert(path_segments, {name = segment, path = current_path})
        if is_absolute then
          current_path = current_path .. "/"
        end
      end
    end
    
    -- Render each segment as a button with improved styling
    for i, seg in ipairs(path_segments) do
      if i > 1 then
        r.ImGui_SameLine(ctx, 0, 2)
        local cx, cy = r.ImGui_GetCursorScreenPos(ctx)
        local sep_h = 18
        r.ImGui_Dummy(ctx, 10, sep_h)
        ui_button_draw_icon(r.ImGui_GetWindowDrawList(ctx), "chev_right", cx + 5, cy + sep_h * 0.5, 12, UI_THEME.text_mute)
        r.ImGui_SameLine(ctx, 0, 2)
      end
      
      local is_filtered = state.folder_filter_path and normalize_path(state.folder_filter_path) == normalize_path(seg.path)
      local text_size = {r.ImGui_CalcTextSize(ctx, seg.name)}
      local frame_padding = 6.0
      local button_width = text_size[1] + frame_padding * 2
      local button_height = text_size[2] + 6.0

      local clicked = r.ImGui_InvisibleButton(ctx, "##path_btn_" .. seg.name, button_width, button_height)
      local hovered = r.ImGui_IsItemHovered(ctx)
      local pressed = r.ImGui_IsItemActive(ctx)
      local x0, y0 = r.ImGui_GetItemRectMin(ctx)
      local x1, y1 = r.ImGui_GetItemRectMax(ctx)
      local bg, border, text_col
      if is_filtered then
        bg = hovered and UI_THEME.accent_fill_h or UI_THEME.accent_fill
        border = UI_THEME.accent
        text_col = 0xFFFFFFFF
      elseif hovered then
        bg = UI_THEME.surface_hvr
        border = UI_THEME.border_hvr
        text_col = UI_THEME.text
      else
        bg = UI_THEME.surface
        border = UI_THEME.border
        text_col = UI_THEME.text_dim
      end
      local dl = r.ImGui_GetWindowDrawList(ctx)
      ui_draw_panel(dl, x0, y0, x1, y1, button_height * 0.5, bg, border, hovered, pressed)
      local text_x = x0 + frame_padding
      local text_y = y0 + (button_height - text_size[2]) * 0.5 + (pressed and 1.0 or 0.0)
      r.ImGui_DrawList_AddText(dl, text_x, text_y, text_col, seg.name)

      if clicked then
        -- Toggle filter: if already filtered, clear it; otherwise set it
        if is_filtered then
          state.folder_filter_path = nil
        else
          state.folder_filter_path = seg.path
        end
      end
    end
    
    -- Show filename (not clickable)
    if #path_segments > 0 then
      r.ImGui_SameLine(ctx)
      r.ImGui_Text(ctx, " / ")
      r.ImGui_SameLine(ctx)
    end
    r.ImGui_TextColored(ctx, 0xFFCCCCCC, preview_sample_obj.name or "Unknown")
    
    -- Add a clear filter button if filter is active
    if state.folder_filter_path and state.folder_filter_path ~= "" then
      r.ImGui_SameLine(ctx)
      if draw_ui_button("clear_folder_filter", "Clear folder", nil, nil, { compact = true, style = "danger" }) then
        state.folder_filter_path = nil
      end
    end
  else
    r.ImGui_Text(ctx, preview_sample_obj.name or "Unknown")
  end
  
  r.ImGui_Separator(ctx)

  local transport_w = 52
  local no_scroll_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()
  if r.ImGui_BeginChild(ctx, "waveform_transport", transport_w, height, 0, no_scroll_flags) then
    render_playback_controls_compact(transport_w)
    r.ImGui_EndChild(ctx)
  end
  r.ImGui_SameLine(ctx)

  width = r.ImGui_GetContentRegionAvail(ctx)
  local pos_x, pos_y = r.ImGui_GetCursorScreenPos(ctx)
  local x0, y0 = pos_x, pos_y
  
  -- Create invisible button for click detection
  r.ImGui_InvisibleButton(ctx, "waveform_area", width, height)
  local layout_x, layout_y = r.ImGui_GetCursorPos(ctx)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local clicked = r.ImGui_IsItemClicked(ctx, 0)
  local dl = r.ImGui_GetWindowDrawList(ctx)

  -- Track Alt+drag drops from the sample map (not waveform click-to-insert)
  if state.pending_waveform_drop then
    if hovered then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
    update_pending_drop_tracking()
  end
  
  -- Draw waveform background
  ui_draw_panel(dl, x0, y0, x0 + width, y0 + height, 6.0, UI_THEME.bg_panel, UI_THEME.border, false, false)
  
  -- Draw waveform
  local waveform = waveform_data.data
  if not waveform or #waveform == 0 then
    -- Show message if no waveform data
    r.ImGui_DrawList_AddText(dl, x0 + width * 0.5 - 50, y0 + height * 0.5, 0xFFFFFFFF, "No waveform data")
    render_waveform_overlay_tags(x0, y0, layout_x, layout_y)
    r.ImGui_Separator(ctx)
    return
  end
  
  if waveform and #waveform > 0 then
    local channels = waveform_data.channels or 1
    local channel_data = waveform_data.channel_data
    local frequency_data = waveform_data.frequency_data
    local frequency_channel_data = waveform_data.frequency_channel_data
    
    -- For mono: draw centered waveform (backward compatible)
    -- For stereo+: draw separate waveforms per channel
    if channels == 1 or not channel_data then
      -- Mono waveform: centered display
      local center_y = y0 + height * 0.5
      local half_height = height * 0.4
      
      -- Draw center line
      r.ImGui_DrawList_AddLine(dl, x0, center_y, x0 + width, center_y, 0x444444FF, 1.0)
      
      -- Draw waveform
      local step = width / #waveform
      local prev_x = x0
      local prev_y_top = center_y
      local prev_y_bot = center_y
      local prev_color = nil
      
      for i = 1, #waveform do
        local x = x0 + (i - 1) * step
        local value = waveform[i] or 0.0
        local y_top = center_y - value * half_height
        local y_bot = center_y + value * half_height
        
        -- Get frequency-based color for this pixel
        local freq = frequency_data and frequency_data[i]
        local color = frequency_to_color(freq)
        
        -- Draw vertical line for this sample
        r.ImGui_DrawList_AddLine(dl, x, y_top, x, y_bot, color, 1.5)
        
        -- Draw connecting line to previous sample (use average color for smooth transition)
        if i > 1 then
          local prev_freq = frequency_data and frequency_data[i - 1]
          local prev_color_val = frequency_to_color(prev_freq)
          -- Blend colors for smooth transition
          local avg_color = color
          if prev_color_val ~= color then
            -- Simple average of RGB components
            local r1 = (color >> 16) & 0xFF
            local g1 = (color >> 8) & 0xFF
            local b1 = color & 0xFF
            local r2 = (prev_color_val >> 16) & 0xFF
            local g2 = (prev_color_val >> 8) & 0xFF
            local b2 = prev_color_val & 0xFF
            local r_avg = math.floor((r1 + r2) / 2)
            local g_avg = math.floor((g1 + g2) / 2)
            local b_avg = math.floor((b1 + b2) / 2)
            avg_color = (0xFF << 24) | (r_avg << 16) | (g_avg << 8) | b_avg
          end
          r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_top, x, y_top, avg_color, 1.0)
          r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_bot, x, y_bot, avg_color, 1.0)
        end
        
        prev_x = x
        prev_y_top = y_top
        prev_y_bot = y_bot
        prev_color = color
      end
    else
      -- Multi-channel waveform: draw separate waveforms per channel
      -- For stereo: left channel on top half, right channel on bottom half
      local channel_height = height / channels
      
      for ch = 0, channels - 1 do
        local ch_data = channel_data[ch]
        local ch_freq_data = frequency_channel_data and frequency_channel_data[ch]
        if ch_data and #ch_data > 0 then
          -- Calculate channel-specific parameters
          local ch_y0 = y0 + ch * channel_height
          local ch_y1 = y0 + (ch + 1) * channel_height
          local ch_center_y = (ch_y0 + ch_y1) * 0.5
          local ch_half_height = channel_height * 0.4
          
          -- Draw center line for this channel
          r.ImGui_DrawList_AddLine(dl, x0, ch_center_y, x0 + width, ch_center_y, 0x444444FF, 1.0)
          
          -- Draw waveform for this channel
          local step = width / #ch_data
          local prev_x = x0
          local prev_y_top = ch_center_y
          local prev_y_bot = ch_center_y
          
          for i = 1, #ch_data do
            local x = x0 + (i - 1) * step
            local value = ch_data[i] or 0.0
            local y_top = ch_center_y - value * ch_half_height
            local y_bot = ch_center_y + value * ch_half_height
            
            -- Get frequency-based color for this pixel/channel
            local freq = ch_freq_data and ch_freq_data[i]
            local color = frequency_to_color(freq)
            
            -- Draw vertical line for this sample
            r.ImGui_DrawList_AddLine(dl, x, y_top, x, y_bot, color, 1.5)
            
            -- Draw connecting line to previous sample (use average color for smooth transition)
            if i > 1 then
              local prev_freq = ch_freq_data and ch_freq_data[i - 1]
              local prev_color_val = frequency_to_color(prev_freq)
              -- Blend colors for smooth transition
              local avg_color = color
              if prev_color_val ~= color then
                -- Simple average of RGB components
                local r1 = (color >> 16) & 0xFF
                local g1 = (color >> 8) & 0xFF
                local b1 = color & 0xFF
                local r2 = (prev_color_val >> 16) & 0xFF
                local g2 = (prev_color_val >> 8) & 0xFF
                local b2 = prev_color_val & 0xFF
                local r_avg = math.floor((r1 + r2) / 2)
                local g_avg = math.floor((g1 + g2) / 2)
                local b_avg = math.floor((b1 + b2) / 2)
                avg_color = (0xFF << 24) | (r_avg << 16) | (g_avg << 8) | b_avg
              end
              r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_top, x, y_top, avg_color, 1.0)
              r.ImGui_DrawList_AddLine(dl, prev_x, prev_y_bot, x, y_bot, avg_color, 1.0)
            end
            
            prev_x = x
            prev_y_top = y_top
            prev_y_bot = y_bot
          end
          
          -- Draw separator line between channels (except after last channel)
          if ch < channels - 1 then
            r.ImGui_DrawList_AddLine(dl, x0, ch_y1, x0 + width, ch_y1, 0x333333FF, 1.0)
          end
        end
      end
    end
    
    -- Effective length marker (draggable) + dim cropped tail
    local file_dur = waveform_data.duration or preview_sample_obj.duration or 0.0
    if preview_sample_obj and file_dur > 0 and width > 1 then
      if state.waveform_eff_drag and state.waveform_eff_drag_path
          and state.waveform_eff_drag_path ~= preview_sample_obj.path then
        state.waveform_eff_drag = false
        state.waveform_eff_drag_path = nil
      end

      local eff = sample_map_duration(preview_sample_obj)
      if eff <= 0 then
        eff = file_dur
      end
      local eff_x = x0 + (eff / file_dur) * width
      eff_x = math.max(x0, math.min(x0 + width, eff_x))

      if eff < file_dur - 0.0005 then
        r.ImGui_DrawList_AddRectFilled(dl, eff_x, y0, x0 + width, y0 + height, 0x00000099, 0)
      end

      local handle_color = 0xFF9A3CFF  -- Orange (RRGGBBAA)
      local handle_hover = 0xFFC070FF
      local mx, my = r.ImGui_GetMousePos(ctx)
      local handle_hit = 8.0
      local near_handle = math.abs(mx - eff_x) <= handle_hit and my >= y0 - 4 and my <= y0 + height + 4
      local color = (near_handle or state.waveform_eff_drag) and handle_hover or handle_color

      r.ImGui_DrawList_AddLine(dl, eff_x, y0, eff_x, y0 + height, color, 2.0)
      local tri = 7.0
      r.ImGui_DrawList_AddTriangleFilled(dl,
        eff_x, y0 + 1,
        eff_x - tri, y0 + tri + 1,
        eff_x + tri, y0 + tri + 1,
        color)
      r.ImGui_DrawList_AddTriangleFilled(dl,
        eff_x, y0 + height - 1,
        eff_x - tri, y0 + height - tri - 1,
        eff_x + tri, y0 + height - tri - 1,
        color)

      local label = string.format("%.2fs", eff)
      local label_w = select(1, r.ImGui_CalcTextSize(ctx, label)) or 36
      local label_x = math.min(eff_x + 6, x0 + width - label_w - 4)
      if label_x < x0 + 4 then
        label_x = x0 + 4
      end
      r.ImGui_DrawList_AddText(dl, label_x + 1, y0 + 8, 0x000000AA, label)
      r.ImGui_DrawList_AddText(dl, label_x, y0 + 7, color, label)

      if (hovered and near_handle) or state.waveform_eff_drag then
        if r.ImGui_MouseCursor_ResizeEW then
          r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
        else
          r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
        end
      end

      if hovered and near_handle and not state.waveform_eff_drag then
        r.ImGui_BeginTooltip(ctx)
        r.ImGui_Text(ctx, "Effective length")
        r.ImGui_Text(ctx, "Drag to crop trailing silence")
        r.ImGui_TextColored(ctx, 0xAAAAAAFF, "Double-click to reset to full file")
        r.ImGui_EndTooltip(ctx)
      end

      if hovered and near_handle and r.ImGui_IsMouseDoubleClicked(ctx, 0) then
        preview_sample_obj.effective_duration = file_dur
        state.waveform_eff_drag = false
        state.waveform_eff_drag_path = nil
        save_samples()
        layout_samples()
        clicked = false
      elseif (clicked and near_handle) or state.waveform_eff_drag then
        if r.ImGui_IsMouseDown(ctx, 0) then
          state.waveform_eff_drag = true
          state.waveform_eff_drag_path = preview_sample_obj.path
          local rel = math.max(0.0, math.min(1.0, (mx - x0) / width))
          preview_sample_obj.effective_duration = clamp_effective_duration(preview_sample_obj, rel * file_dur)
          clicked = false
        elseif state.waveform_eff_drag then
          state.waveform_eff_drag = false
          state.waveform_eff_drag_path = nil
          save_samples()
          layout_samples()
          clicked = false
        end
      end
    end

    -- Transient / sustain split (drum one-shots)
    if preview_sample_obj and type(preview_sample_obj.transient_end) == "number"
        and preview_sample_obj.transient_end > 0 and width > 1 then
      local ts_dur = waveform_data.duration or preview_sample_obj.duration or 0.0
      if ts_dur > 0 then
        local function time_to_x(t)
          local x = x0 + (math.max(0.0, math.min(ts_dur, t or 0.0)) / ts_dur) * width
          return math.max(x0, math.min(x0 + width, x))
        end
        local onset_t = preview_sample_obj.onset
        if type(onset_t) ~= "number" or onset_t < 0 then
          onset_t = 0.0
        end
        local trans_t = preview_sample_obj.transient_end
        local sustain_t = sample_map_duration(preview_sample_obj)
        if sustain_t <= 0 then
          sustain_t = ts_dur
        end
        local onset_x = time_to_x(onset_t)
        local trans_x = time_to_x(trans_t)
        local sustain_x = time_to_x(sustain_t)

        if trans_x > onset_x + 0.5 then
          r.ImGui_DrawList_AddRectFilled(dl, onset_x, y0, trans_x, y0 + height, 0xFF6B3C33, 0)
        end
        if sustain_x > trans_x + 0.5 then
          r.ImGui_DrawList_AddRectFilled(dl, trans_x, y0, sustain_x, y0 + height, 0x4A9CFF28, 0)
        end

        local ts_color = 0x7CFF4AFF  -- Lime (RRGGBBAA)
        r.ImGui_DrawList_AddLine(dl, trans_x, y0, trans_x, y0 + height, ts_color, 2.0)
        local tri = 5.5
        r.ImGui_DrawList_AddTriangleFilled(dl,
          trans_x, y0,
          trans_x - tri, y0 + tri,
          trans_x + tri, y0 + tri,
          ts_color)
        r.ImGui_DrawList_AddTriangleFilled(dl,
          trans_x, y0 + height,
          trans_x - tri, y0 + height - tri,
          trans_x + tri, y0 + height - tri,
          ts_color)
        if (trans_x - onset_x) >= 10.0 then
          r.ImGui_DrawList_AddText(dl, onset_x + 3, y0 + 2, ts_color, "T")
        end
        if (sustain_x - trans_x) >= 10.0 then
          r.ImGui_DrawList_AddText(dl, trans_x + 4, y0 + 2, 0xA8D4FFFF, "S")
        end
      end
    end

    -- Draw snap offset marker if available
    if preview_sample_obj and preview_sample_obj.snap_offset then
      local snap_time = preview_sample_obj.snap_offset
      local duration = waveform_data.duration or preview_sample_obj.duration or 1.0
      if duration > 0 and snap_time >= 0 and snap_time <= duration then
        local snap_x = x0 + (snap_time / duration) * width
        snap_x = math.max(x0, math.min(x0 + width, snap_x))
        
        -- Draw snap offset line (bright yellow/green, distinct from playhead)
        local snap_color = 0x00FFFFFF  -- Cyan (RRGGBBAA format)
        local snap_thickness = 2.5
        r.ImGui_DrawList_AddLine(dl, snap_x, y0, snap_x, y0 + height, snap_color, snap_thickness)
        
        -- Draw snap offset indicators at top and bottom (triangles pointing down/up)
        local triangle_size = 6.0
        -- Top triangle (pointing down)
        r.ImGui_DrawList_AddTriangleFilled(dl, 
          snap_x, y0, 
          snap_x - triangle_size, y0 + triangle_size, 
          snap_x + triangle_size, y0 + triangle_size, 
          snap_color)
        -- Bottom triangle (pointing up)
        r.ImGui_DrawList_AddTriangleFilled(dl, 
          snap_x, y0 + height, 
          snap_x - triangle_size, y0 + height - triangle_size, 
          snap_x + triangle_size, y0 + height - triangle_size, 
          snap_color)
      end
    end
    
    -- Draw playhead when playing or paused
    local current_pos = get_preview_position()
    local duration = waveform_data.duration or 1.0
    if (preview_proc ~= nil or state.preview_paused) and current_pos ~= nil and duration > 0 then
      local playhead_x = x0 + (current_pos / duration) * width
      playhead_x = math.max(x0, math.min(x0 + width, playhead_x))
      
      -- Draw playhead line (bright yellow, thicker for visibility)
      local playhead_color = 0xFFFF88FF  -- Yellow (RRGGBBAA format)
      local playhead_thickness = 2.0
      r.ImGui_DrawList_AddLine(dl, playhead_x, y0, playhead_x, y0 + height, playhead_color, playhead_thickness)
      
      -- Draw playhead indicators at top and bottom (filled circles for better visibility)
      local indicator_radius = 5.0
      r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y0, indicator_radius, playhead_color, 16)
    end
  end
  
  -- Handle click to seek (ignored while dragging the effective-length marker)
  if clicked and not state.waveform_eff_drag then
    local mx, my = r.ImGui_GetMousePos(ctx)
    local rel_x = mx - x0
    local normalized_pos = math.max(0.0, math.min(1.0, rel_x / width))
    local duration = waveform_data.duration or preview_sample_obj.duration or 0.0
    local seek_time = normalized_pos * duration
    
    log(string.format("Waveform click: mx=%.1f, x0=%.1f, rel_x=%.1f, width=%.1f, normalized=%.3f, duration=%.2f, seek_time=%.2fs", 
        mx, x0, rel_x, width, normalized_pos, duration, seek_time))
    preview_sample(preview_sample_obj, seek_time)
  end

  render_waveform_overlay_tags(x0, y0, layout_x, layout_y)
  r.ImGui_Separator(ctx)
end


-- --- Sequencer track helpers -------------------------------------------------
local function get_track_by_guid(track_guid)
  if not track_guid or track_guid == "" then
    return nil
  end
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    if r.GetTrackGUID(tr) == track_guid then
      return tr
    end
  end
  return nil
end

local function get_project_tracks_list()
  local tracks = {}
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    local _, name = r.GetTrackName(tr)
    tracks[#tracks + 1] = {
      track = tr,
      guid = r.GetTrackGUID(tr),
      name = name ~= "" and name or ("Track " .. (i + 1)),
    }
  end
  return tracks
end

local function get_reaper_track_display_name(track_guid)
  if not track_guid then
    return nil
  end
  local tr = get_track_by_guid(track_guid)
  if not tr then
    return "(missing track)"
  end
  local _, name = r.GetTrackName(tr)
  if name and name ~= "" then
    return name
  end
  return "(unnamed track)"
end

local function find_sample_by_path(path)
  if not path then
    return nil
  end
  local hit = samples_by_path[path]
  if hit then
    return hit
  end
  -- Fallback once if index is stale (then rebuild)
  for _, s in ipairs(state.samples) do
    if s.path == path then
      samples_by_path[path] = s
      return s
    end
  end
  return nil
end

function sample_drag_active()
  return state.pending_waveform_drop ~= nil
    or (state.is_left_dragging and state.last_dragged_sample_path ~= nil)
end

function get_active_dragged_sample()
  if state.pending_waveform_drop then
    return state.pending_waveform_drop
  end
  if state.last_dragged_sample_path then
    return find_sample_by_path(state.last_dragged_sample_path)
  end
  return nil
end

local function seq_track_has_guid(guid)
  if not guid then
    return false
  end
  for _, slot in ipairs(state.seq_tracks) do
    if slot.reaper_track_guid == guid then
      return true
    end
  end
  return false
end

local function clamp_selected_seq_track()
  if state.selected_seq_track and state.selected_seq_track > #state.seq_tracks then
    state.selected_seq_track = #state.seq_tracks > 0 and #state.seq_tracks or nil
  end
  if state.selected_seq_track and state.selected_seq_track < 1 then
    state.selected_seq_track = nil
  end
  if state.seq_swap_track_idx and state.seq_swap_track_idx > #state.seq_tracks then
    state.seq_swap_track_idx = nil
  end
end

local function add_seq_track_from_reaper_track(tr)
  if not tr then
    return nil
  end
  local guid = r.GetTrackGUID(tr)
  if seq_track_has_guid(guid) then
    return nil
  end
  local _, name = r.GetTrackName(tr)
  local slot = {
    id = state.seq_track_next_id,
    name = name ~= "" and name or ("Track " .. (#state.seq_tracks + 1)),
    reaper_track_guid = guid,
    sample_path = nil,
    sample_name = nil,
  }
  seq_normalize_slot_mix(slot)
  state.seq_track_next_id = state.seq_track_next_id + 1
  table.insert(state.seq_tracks, slot)
  state.selected_seq_track = #state.seq_tracks
  return slot
end

local function add_empty_seq_track()
  local slot = {
    id = state.seq_track_next_id,
    name = "Track " .. (#state.seq_tracks + 1),
    reaper_track_guid = nil,
    sample_path = nil,
    sample_name = nil,
  }
  seq_normalize_slot_mix(slot)
  state.seq_track_next_id = state.seq_track_next_id + 1
  table.insert(state.seq_tracks, slot)
  state.selected_seq_track = #state.seq_tracks
  return slot
end

local function remove_selected_seq_track()
  if not state.selected_seq_track then
    return
  end
  local own = seq_undo_own_begin("Remove sequencer track")
  local removed_idx = state.selected_seq_track
  local removed_slot = state.seq_tracks[removed_idx]
  local removed_id = removed_slot and removed_slot.id
  table.remove(state.seq_tracks, removed_idx)
  if state.seq_swap_track_id and removed_id and state.seq_swap_track_id == removed_id then
    clear_seq_swap_mode_state()
  elseif state.seq_swap_track_idx and state.seq_swap_track_idx > removed_idx then
    state.seq_swap_track_idx = state.seq_swap_track_idx - 1
  end
  if #state.seq_tracks == 0 then
    state.selected_seq_track = nil
  elseif state.selected_seq_track > #state.seq_tracks then
    state.selected_seq_track = #state.seq_tracks
  end
  save_config()
  if own then
    end_seq_undo("Remove sequencer track")
  end
end

local function assign_sample_to_seq_track(slot, sample, persist)
  if not slot or not sample or not sample.path then
    return false
  end
  local path_changed = slot.sample_path ~= sample.path
  slot.sample_path = sample.path
  slot.sample_name = sample.name or basename(sample.path)
  local should_persist = persist == nil or persist
  if path_changed and update_seq_track_sample_assignments then
    -- update_seq_track_sample_assignments persists when asked, so skip a second save_config.
    update_seq_track_sample_assignments(slot, sample.path, slot.sample_name, should_persist)
    return true
  end
  if should_persist then
    save_config()
  end
  return true
end

local function seq_slot_in_swap_mode(slot)
  if not state.seq_swap_track_id or not slot then
    return false
  end
  return slot.id == state.seq_swap_track_id
end

local function find_seq_track_by_id(track_id)
  if not track_id then
    return nil, nil
  end
  for idx, slot in ipairs(state.seq_tracks) do
    if slot.id == track_id then
      return slot, idx
    end
  end
  return nil, nil
end

local function clone_active_tags(tags)
  local copy = {}
  if type(tags) ~= "table" then
    return copy
  end
  for tag, active in pairs(tags) do
    if active then
      copy[tag] = true
    end
  end
  return copy
end

local function find_library_tag(tag)
  local needle = seq_trim_text(tag)
  if needle == "" or not state.tag_list then
    return nil
  end
  needle = needle:lower()
  for _, entry in ipairs(state.tag_list) do
    local lib_tag = tostring(entry.tag or "")
    if lib_tag:lower() == needle then
      return lib_tag
    end
  end
  return nil
end

local function resolve_seq_swap_filter_tag(slot)
  if not slot then
    return nil
  end
  local tag = slot.sample_tag and seq_trim_text(slot.sample_tag) or ""
  if tag ~= "" then
    return tag
  end
  local role = infer_seq_track_role(slot)
  if role and role ~= "other" and SEQ_ROLE_TAG_CANDIDATES[role] then
    return SEQ_ROLE_TAG_CANDIDATES[role][1]
  end
  return nil
end

local function restore_seq_swap_map_filter()
  if state.seq_swap_saved_active_tags ~= nil then
    state.active_tags = clone_active_tags(state.seq_swap_saved_active_tags)
    state.seq_swap_saved_active_tags = nil
  end
end

local function apply_seq_swap_map_filter(slot)
  local tag = find_library_tag(resolve_seq_swap_filter_tag(slot))
  if not tag then
    restore_seq_swap_map_filter()
    return
  end
  if state.seq_swap_saved_active_tags == nil then
    state.seq_swap_saved_active_tags = clone_active_tags(state.active_tags)
  end
  state.active_tags = { [tag] = true }
end

local function clear_seq_swap_mode_state()
  restore_seq_swap_map_filter()
  state.seq_swap_track_idx = nil
  state.seq_swap_track_id = nil
  state.seq_swap_backup_path = nil
  state.seq_swap_backup_name = nil
end

local function begin_seq_swap_mode(idx)
  local slot = state.seq_tracks[idx]
  if not slot then
    return
  end
  if state.seq_swap_track_id == slot.id then
    state.seq_swap_track_idx = idx
    return
  end
  if state.seq_swap_track_id and state.seq_swap_track_id ~= slot.id then
    local prev_slot = find_seq_track_by_id(state.seq_swap_track_id)
    if prev_slot then
      if state.seq_swap_backup_path then
        assign_sample_to_seq_track(prev_slot, {
          path = state.seq_swap_backup_path,
          name = state.seq_swap_backup_name or basename(state.seq_swap_backup_path),
        }, true)
      else
        prev_slot.sample_path = nil
        prev_slot.sample_name = nil
        save_config()
      end
    end
    state.seq_swap_track_idx = nil
    state.seq_swap_track_id = nil
    state.seq_swap_backup_path = nil
    state.seq_swap_backup_name = nil
    if seq_undo_is_open() then
      end_seq_undo("Swap sequencer sample")
    end
  end
  begin_seq_undo("Swap sequencer sample")
  state.seq_swap_track_idx = idx
  state.seq_swap_track_id = slot.id
  state.selected_seq_track = idx
  state.seq_swap_backup_path = slot.sample_path
  state.seq_swap_backup_name = slot.sample_name
  apply_seq_swap_map_filter(slot)
  state.active_view = "sample_map"
  save_config()
end

local function end_seq_swap_mode(confirmed)
  local slot, idx = find_seq_track_by_id(state.seq_swap_track_id)
  if not slot then
    clear_seq_swap_mode_state()
    return
  end
  state.seq_swap_track_idx = idx
  if confirmed then
    -- Arrange items were already retargeted while browsing candidates.
    save_config()
  else
    if state.seq_swap_backup_path then
      assign_sample_to_seq_track(slot, {
        path = state.seq_swap_backup_path,
        name = state.seq_swap_backup_name or basename(state.seq_swap_backup_path),
      }, true)
    else
      slot.sample_path = nil
      slot.sample_name = nil
      save_config()
    end
    if slot.sample_path then
      local restored = find_sample_by_path(slot.sample_path)
      if restored then
        preview_sample(restored)
      end
    end
  end
  if seq_undo_is_open() then
    end_seq_undo("Swap sequencer sample")
  end
  clear_seq_swap_mode_state()
end

local function get_active_swap_slot()
  local slot, idx = find_seq_track_by_id(state.seq_swap_track_id)
  if not slot then
    return nil, nil
  end
  state.seq_swap_track_idx = idx
  return slot, idx
end

local function complete_pending_sample_drop()
  local sample = get_active_dragged_sample()
  local mouse_down = r.ImGui_IsMouseDown(ctx, 0)

  if mouse_down then
    if state.pending_waveform_drop then
      -- Escape during the drag cancels everything (no insert, no undo point).
      if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
          and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
        remove_provisional_drop()
        clear_drag_tooltip()
        state.pending_waveform_drop = nil
        state.last_mouse_time_pos = nil
        state.last_mouse_track = nil
        state.seq_drop_target_idx = nil
        state.seq_timeline_drop_track_idx = nil
        state.seq_timeline_drop_time = nil
        state.is_left_dragging = false
        state.last_dragged_sample_path = nil
        state.map_press_x = nil
        state.map_press_y = nil
        state.map_press_pending = false
        state.map_audition_rearm = false
        log("Drag cancelled via Escape")
        return
      end
      update_provisional_drop(sample)
    end
    return
  end

  if not sample and not state.pending_waveform_drop and not state.is_left_dragging then
    return
  end

  if sample then
    log("Mouse released globally, completing drag operation")

    if state.seq_layering_drop_vert and state.seq_layering_slot_id then
      local layer_slot = find_seq_track_by_id(state.seq_layering_slot_id)
      if layer_slot then
        seq_layering_set_vert(layer_slot, state.seq_layering_drop_vert.side, state.seq_layering_drop_vert.idx, sample)
        preview_sample(sample)
        save_config()
        if save_seq_project_state then save_seq_project_state() end
        seq_layering_sync_arrange(layer_slot)
      end
      state.seq_layering_drop_vert = nil
      state.pending_waveform_drop = nil
      state.seq_drop_target_idx = nil
      state.seq_timeline_drop_track_idx = nil
      state.seq_timeline_drop_time = nil
      state.is_left_dragging = false
      state.last_dragged_sample_path = nil
      state.map_press_x = nil
      state.map_press_y = nil
      state.map_press_pending = false
      state.map_audition_rearm = false
      remove_provisional_drop()
      clear_drag_tooltip()
      return
    end

    if state.seq_drop_target_idx then
      remove_provisional_drop()
      local slot = state.seq_tracks[state.seq_drop_target_idx]
      if slot and sample.path then
        local in_swap = state.seq_swap_track_id and slot.id == state.seq_swap_track_id
        local own = (not in_swap) and seq_undo_own_begin("Assign sequencer sample")
        assign_sample_to_seq_track(slot, sample, not in_swap)
        if own then
          end_seq_undo("Assign sequencer sample")
        end
        state.selected_seq_track = state.seq_drop_target_idx
        preview_sample(sample)
        log("Swapped '" .. (sample.name or sample.path) .. "' onto " .. slot.name)
      end
    elseif state.pending_waveform_drop then
      local sample_label = sample.name or basename(sample.path or "") or "sample"
      if state.seq_timeline_drop_track_idx and state.seq_timeline_drop_time then
        remove_provisional_drop()
        local slot = state.seq_tracks[state.seq_timeline_drop_track_idx]
        local target_track = nil
        if slot and slot.reaper_track_guid then
          local n = r.CountTracks(0)
          for i = 0, n - 1 do
            local tr = r.GetTrack(0, i)
            if r.GetTrackGUID(tr) == slot.reaper_track_guid then
              target_track = tr
              break
            end
          end
        end
        arrange_undo_begin()
        local success = insert_sample_at_position(sample, state.seq_timeline_drop_time, target_track)
        arrange_undo_end("Insert sample: " .. sample_label)
        if success then
          state.selected_seq_track = state.seq_timeline_drop_track_idx
          log("Inserted '" .. sample_label .. "' via sequencer timeline")
        else
          log("Failed sequencer timeline insertion")
        end
      else
        -- Arrange drop: commit the provisional preview position as one undo point.
        local commit_time, commit_track
        local p = state.provisional_drop
        if p and p.item and r.ValidatePtr(p.item, "MediaItem*") then
          commit_time = p.time or state.last_mouse_time_pos
          if p.track and r.ValidatePtr(p.track, "MediaTrack*") then
            commit_track = p.track
          end
        end
        if not commit_time then
          local dt, dtr = get_drop_position()
          if dt then
            commit_time = maybe_snap_drop_time(dt)
            commit_track = commit_track or dtr
          end
        end
        if not commit_time and state.last_mouse_time_pos then
          commit_time = state.last_mouse_time_pos
          commit_track = commit_track or state.last_mouse_track
        end

        -- Clear the preview before committing so the undo block captures exactly
        -- one media item creation (project returns to clean state first).
        remove_provisional_drop()

        if commit_time then
          arrange_undo_begin()
          local success = insert_sample_at_position(sample, commit_time, commit_track)
          arrange_undo_end("Insert sample: " .. sample_label)
          if success then
            log(string.format("Committed arrange insert at %.3f", commit_time))
          else
            log("Failed to commit arrange insert")
          end
        else
          log("Drag released away from the arrange; insert cancelled")
        end
      end
    end
  end

  remove_provisional_drop()
  clear_drag_tooltip()
  state.pending_waveform_drop = nil
  state.last_mouse_time_pos = nil
  state.last_mouse_track = nil
  state.seq_drop_target_idx = nil
  state.seq_timeline_drop_track_idx = nil
  state.seq_timeline_drop_time = nil
  state.is_left_dragging = false
  state.last_dragged_sample_path = nil
  state.map_press_x = nil
  state.map_press_y = nil
  state.map_press_pending = false
  state.map_audition_rearm = false
end

local function clear_seq_track_sample(slot)
  if not slot then
    return
  end
  slot.sample_path = nil
  slot.sample_name = nil
  save_config()
end

local function add_seq_tracks_from_selection()
  local own = seq_undo_own_begin("Add sequencer track")
  local count = r.CountSelectedTracks(0)
  if count == 0 then
    add_empty_seq_track()
    save_config()
    if own then
      end_seq_undo("Add sequencer track")
    end
    return
  end
  local added = 0
  for i = 0, count - 1 do
    local tr = r.GetSelectedTrack(0, i)
    if add_seq_track_from_reaper_track(tr) then
      added = added + 1
    end
  end
  if added == 0 then
    log("Selected project tracks are already in the sequencer track list")
  else
    save_config()
  end
  if own then
    end_seq_undo("Add sequencer track")
  end
end

function seq_trim_text(value)
  local text = tostring(value or "")
  text = text:gsub("^%s+", "")
  text = text:gsub("%s+$", "")
  return text
end

function find_sample_for_tag(tag_name)
  local needle = seq_trim_text(tag_name):lower()
  if needle == "" then
    return nil
  end
  for _, sample in ipairs(state.samples) do
    if sample_has_tag(sample, needle) and not sample_scan_folder_unavailable(sample) then
      return sample
    end
  end
  return nil
end

function sample_has_tag(sample, tag_name)
  if not sample or not sample.tags or type(sample.tags) ~= "table" then
    return false
  end
  local needle = seq_trim_text(tag_name):lower()
  if needle == "" then
    return false
  end
  for _, sample_tag in ipairs(sample.tags) do
    if tostring(sample_tag):lower() == needle then
      return true
    end
  end
  return false
end

function seq_get_media_track_index(tr)
  if not tr then
    return nil
  end
  local num = r.GetMediaTrackInfo_Value(tr, "IP_TRACKNUMBER")
  if num and num > 0 then
    return math.floor(num + 0.5) - 1
  end
  return nil
end

function find_seq_parent_folder_track()
  if state.seq_folder_guid and state.seq_folder_guid ~= "" then
    local tr = get_track_by_guid(state.seq_folder_guid)
    if tr then
      return tr
    end
    state.seq_folder_guid = nil
  end
  local n = r.CountTracks(0)
  for i = 0, n - 1 do
    local tr = r.GetTrack(0, i)
    local _, name = r.GetTrackName(tr)
    if name == SEQ_TRACK_FOLDER_NAME then
      local depth = r.GetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH") or 0
      if depth >= 1 then
        state.seq_folder_guid = r.GetTrackGUID(tr)
        return tr
      end
    end
  end
  return nil
end

function create_seq_parent_folder_track()
  local insert_idx = r.CountTracks(0)
  r.InsertTrackAtIndex(insert_idx, true)
  local tr = r.GetTrack(0, insert_idx)
  if not tr then
    return nil
  end
  r.GetSetMediaTrackInfo_String(tr, "P_NAME", SEQ_TRACK_FOLDER_NAME, true)
  r.SetMediaTrackInfo_Value(tr, "I_FOLDERDEPTH", 0)
  state.seq_folder_guid = r.GetTrackGUID(tr)
  return tr
end

function seq_folder_last_child_index(folder_tr)
  local folder_idx = seq_get_media_track_index(folder_tr)
  if not folder_idx then
    return nil, false
  end
  local folder_depth = r.GetMediaTrackInfo_Value(folder_tr, "I_FOLDERDEPTH") or 0
  if folder_depth < 1 then
    return folder_idx, false
  end
  local depth = 1
  local last_idx = folder_idx
  local n = r.CountTracks(0)
  for i = folder_idx + 1, n - 1 do
    last_idx = i
    depth = depth + (r.GetMediaTrackInfo_Value(r.GetTrack(0, i), "I_FOLDERDEPTH") or 0)
    if depth <= 0 then
      return last_idx, true
    end
  end
  return last_idx, last_idx > folder_idx
end

function insert_reaper_track_in_seq_folder()
  local folder = find_seq_parent_folder_track() or create_seq_parent_folder_track()
  if not folder then
    local idx = r.CountTracks(0)
    r.InsertTrackAtIndex(idx, true)
    return r.GetTrack(0, idx)
  end

  local last_idx, has_children = seq_folder_last_child_index(folder)
  if not last_idx then
    local idx = r.CountTracks(0)
    r.InsertTrackAtIndex(idx, true)
    return r.GetTrack(0, idx)
  end

  local insert_idx = last_idx + 1
  r.InsertTrackAtIndex(insert_idx, true)
  local new_tr = r.GetTrack(0, insert_idx)
  if not new_tr then
    return nil
  end

  if not has_children then
    r.SetMediaTrackInfo_Value(folder, "I_FOLDERDEPTH", 1)
    r.SetMediaTrackInfo_Value(new_tr, "I_FOLDERDEPTH", -1)
  else
    local prev = r.GetTrack(0, last_idx)
    local prev_d = r.GetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH") or 0
    if prev_d < 0 then
      r.SetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH", prev_d + 1)
    else
      r.SetMediaTrackInfo_Value(prev, "I_FOLDERDEPTH", 0)
    end
    r.SetMediaTrackInfo_Value(new_tr, "I_FOLDERDEPTH", -1)
  end
  return new_tr
end

function create_seq_track_with_name(track_name)
  local final_name = seq_trim_text(track_name)
  if final_name == "" then
    final_name = "Track " .. tostring(#state.seq_tracks + 1)
  end

  local tr
  if state.group_seq_tracks_in_folder ~= false then
    tr = insert_reaper_track_in_seq_folder()
  else
    local insert_idx = r.CountTracks(0)
    r.InsertTrackAtIndex(insert_idx, true)
    tr = r.GetTrack(0, insert_idx)
  end
  if not tr then
    return nil
  end

  r.GetSetMediaTrackInfo_String(tr, "P_NAME", final_name, true)
  local slot = add_seq_track_from_reaper_track(tr)
  if not slot then
    return nil
  end

  slot.name = final_name
  return slot
end

function create_seq_track_from_popup(track_name, tag_name)
  local own = seq_undo_own_begin("Add sequencer track")
  local slot = create_seq_track_with_name(track_name)
  if not slot then
    if own then
      end_seq_undo("Add sequencer track")
    end
    return false
  end

  local chosen_tag = seq_trim_text(tag_name)
  if chosen_tag ~= "" then
    slot.sample_tag = chosen_tag
    local sample = find_sample_for_tag(chosen_tag)
    if sample then
      assign_sample_to_seq_track(slot, sample, false)
    else
      log("No sample found for tag '" .. chosen_tag .. "'")
    end
  end

  save_config()
  if r.TrackList_AdjustWindows then
    r.TrackList_AdjustWindows(false)
  end
  r.UpdateArrange()
  if own then
    end_seq_undo("Add sequencer track")
  end
  return true
end

function seq_add_popup_tag_width(tag_label)
  local text_w = r.ImGui_CalcTextSize(ctx, tag_label)
  local pad_x = r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())
  return text_w + pad_x * 2
end

function seq_add_popup_count_rows(query_lower, content_w)
  content_w = math.max(120.0, content_w or 480.0)
  local rows = 0
  local row_w = 0.0
  local gap = 6.0
  for _, entry in ipairs(state.tag_list or {}) do
    local tag = tostring(entry.tag or "")
    if query_lower == "" or tag:lower():find(query_lower, 1, true) then
      local tw = seq_add_popup_tag_width(tag)
      if rows == 0 then
        rows = 1
        row_w = tw
      elseif row_w + gap + tw > content_w then
        rows = rows + 1
        row_w = tw
      else
        row_w = row_w + gap + tw
      end
    end
  end
  return math.max(1, rows)
end

function seq_add_popup_window_height(trimmed_query)
  local popup_w = 520.0
  local content_w = popup_w - 32.0
  local query_lower = seq_trim_text(trimmed_query):lower()
  local rows = seq_add_popup_count_rows(query_lower, content_w)
  local tag_row_h = 28.0
  return math.max(220.0, 118.0 + rows * tag_row_h + 12.0)
end

function open_seq_add_track_popup()
  state.seq_new_track_query = ""
  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end
  if r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Appearing and r.ImGui_Cond_Appearing() or 0
    r.ImGui_SetNextWindowSize(ctx, 520, seq_add_popup_window_height(""), cond)
  end
  r.ImGui_OpenPopup(ctx, "seq_add_track_popup")
end

function render_seq_add_track_full_width_button(button_id, button_h)
  if draw_ui_button(tostring(button_id or "seq_add_track_popup_open"), nil, nil, button_h or 28, { icon = "plus", full_width = true, style = "primary" }) then
    open_seq_add_track_popup()
  end
end

function render_seq_add_popup_tag_list(trimmed_query)
  local wrap_w = r.ImGui_GetContentRegionAvail(ctx)
  local query_lower = seq_trim_text(trimmed_query):lower()
  local row_w = 0.0
  local gap = 6.0
  local shown_tags = 0
  local first_tag = true

  for idx, entry in ipairs(state.tag_list or {}) do
    local tag = tostring(entry.tag or "")
    if query_lower == "" or tag:lower():find(query_lower, 1, true) then
      local tw = seq_add_popup_tag_width(tag)
      if not first_tag then
        if row_w + gap + tw > wrap_w then
          row_w = 0.0
        else
          r.ImGui_SameLine(ctx, 0, gap)
          row_w = row_w + gap
        end
      end
      first_tag = false
      shown_tags = shown_tags + 1
      if draw_tag_button(ctx, tag, false, tag, "seq_add_popup_" .. tostring(idx) .. "_") then
        if create_seq_track_from_popup(tag, tag) then
          state.seq_new_track_query = ""
          r.ImGui_CloseCurrentPopup(ctx)
        end
      end
      row_w = row_w + tw
    end
  end

  if shown_tags == 0 then
    r.ImGui_TextColored(ctx, 0xFF888888, "No tags match filter")
  end
  return shown_tags
end

function render_seq_add_track_popup()
  local trimmed_query = seq_trim_text(state.seq_new_track_query)
  if r.ImGui_IsPopupOpen and r.ImGui_IsPopupOpen(ctx, "seq_add_track_popup") and r.ImGui_SetNextWindowSize then
    local cond = r.ImGui_Cond_Always and r.ImGui_Cond_Always() or 0
    r.ImGui_SetNextWindowSize(ctx, 520, seq_add_popup_window_height(trimmed_query), cond)
  end

  if not r.ImGui_BeginPopup(ctx, "seq_add_track_popup") then
    return
  end

  if (not state.tag_list or #state.tag_list == 0) and #state.samples > 0 then
    rebuild_tag_index()
  end

  r.ImGui_Text(ctx, "Track Name / Tag Search")
  local changed, query = r.ImGui_InputText(ctx, "##seq_new_track_query", state.seq_new_track_query or "", 128)
  if changed then
    state.seq_new_track_query = query
    trimmed_query = seq_trim_text(query)
  end

  local create_label = (trimmed_query ~= "") and ('Create "' .. trimmed_query .. '"') or "Create Track"
  if draw_ui_button("seq_create_custom", create_label, nil, nil, { full_width = true, style = "primary" }) then
    if create_seq_track_from_popup(trimmed_query, nil) then
      state.seq_new_track_query = ""
      r.ImGui_CloseCurrentPopup(ctx)
    end
  end

  r.ImGui_Separator(ctx)
  r.ImGui_Text(ctx, "Available Tags")
  r.ImGui_Dummy(ctx, 0, 4)
  render_seq_add_popup_tag_list(trimmed_query)
  r.ImGui_EndPopup(ctx)
end

local function get_selected_seq_track()
  clamp_selected_seq_track()
  if not state.selected_seq_track then
    return nil
  end
  return state.seq_tracks[state.selected_seq_track]
end

local function preview_seq_track_sample(slot)
  if not slot or not slot.sample_path then
    return false
  end
  local sample = find_sample_by_path(slot.sample_path)
  if not sample then
    return false
  end
  preview_sample(sample)
  state.seq_track_play_anims = state.seq_track_play_anims or {}
  state.seq_track_play_anims[tostring(slot.id)] = {
    start_time = r.time_precise(),
    duration = 0.35,
  }
  return true
end

function seq_resolve_hover_note(active, hovered_qn, start_qn, col, step_qn)
  if not active then
    return nil
  end
  if seq_active_cell_is_playable
      and not seq_active_cell_is_playable(active, start_qn, col, step_qn) then
    return nil
  end
  if seq_pick_packed_note then
    return seq_pick_packed_note(active, hovered_qn, start_qn, col, step_qn)
  end
  return active
end

function seq_set_grid_hover(slot, col, active_cells, start_qn, step_qn, hovered_qn)
  if not slot then
    state.seq_grid_hover = nil
    return
  end
  local active = active_cells and col and active_cells[slot.id] and active_cells[slot.id][col]
  local picked = hovered_qn and seq_resolve_hover_note(active, hovered_qn, start_qn, col, step_qn) or nil
  state.seq_grid_hover = {
    slot_id = slot.id,
    step_key = picked and picked.key or nil,
    region_id = picked and picked.region_id or nil,
    note = picked and picked.note or nil,
    hovered_qn = hovered_qn,
    step_qn = step_qn,
  }
end

local function select_seq_track(idx, opts)
  opts = opts or {}
  if not idx or idx < 1 or idx > #state.seq_tracks then
    return false
  end
  state.selected_seq_track = idx
  save_config()
  if opts.preview ~= false then
    preview_seq_track_sample(state.seq_tracks[idx])
  end
  return true
end

