  { key = "sample_vary", label = "Vary", mode_name = "Variation", hotkey = "V", min = 0.0, max = 1.0, default = 0.0, fmt = "%.2f" },
  { key = "stutter", label = "Stut", mode_name = "Stutter", hotkey = "S", min = 1.0, max = 16.0, default = 1.0, fmt = "%.0f" },
  { key = "pan", label = "Pan", mode_name = "Pan", hotkey = "P", min = -1.0, max = 1.0, default = 0.0, fmt = "%.2f" },
  { key = "pitch", label = "Pitch", mode_name = "Pitch", hotkey = "T", min = -24.0, max = 24.0, default = 0.0, fmt = "%.1f" },
  { key = "decay", label = "Dec", mode_name = "Decay", hotkey = "D", min = 0.0, max = 8.0, default = 0.0, fmt = "%.3f" },
  { key = "length_qn", label = "Len", min = 0.03125, max = 8.0, default = 0.25, fmt = "%.3f" },
  { key = "stretch", label = "Stretch", mode_name = "Stretch", hotkey = "R", min = 0.25, max = 4.0, default = 1.0, fmt = "%.2fx" },
  { key = "start", label = "Start", mode_name = "Start", hotkey = "A", min = 0.0, max = 0.99, default = 0.0, fmt = "%.0f%%" },
  { key = "locked", label = "Lock", mode_name = "Lock", hotkey = "L", min = 0.0, max = 1.0, default = 0.0, fmt = "%.0f", boolean = true },
}

function get_seq_row_lane_style(row)
  if row.type == "note" then
    return {
      bg = UI_THEME.bg_panel,
      label_bg = UI_THEME.bg,
      timeline_bg = UI_THEME.surface,
      edge = UI_THEME.border,
      accent = UI_THEME.accent,
    }
  end
  if row.type == "param" and row.param then
    local styles = {
      volume = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFD166FF },
      sample_vary = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x8FD98FFF },
      stutter = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xC9A8FFFF },
      pan = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x6EC8FFFF },
      pitch = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFB84DFF },
      length_qn = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x88DDAAFF },
      decay = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xFFD166FF },
      stretch = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0x7ED0C8FF },
      start = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xA8E0C0FF },
      locked = { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = 0xE8C070FF },
    }
    return styles[row.param.key] or { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = UI_THEME.text_dim }
  end
  return { bg = UI_THEME.bg_panel, label_bg = UI_THEME.bg, timeline_bg = UI_THEME.surface, edge = UI_THEME.border, accent = UI_THEME.text_mute }
end

function seq_lane_color_with_alpha(color, alpha)
  local cr, cg, cb = extract_rgb_rrgbbaa(color or 0xFFFFFFFF)
  return build_color_rrgbbaa(cr, cg, cb, alpha or 255)
end

function seq_lane_param_fill_colors(accent, bipolar, value)
  local ar, ag, ab = extract_rgb_rrgbbaa(accent or 0xFFD166FF)
  local fill = build_color_rrgbbaa(ar, ag, ab, 205)
  local cap = build_color_rrgbbaa(math.min(255, ar + 45), math.min(255, ag + 45), math.min(255, ab + 45), 255)
  local fill_neg = build_color_rrgbbaa(math.max(0, ar - 70), math.max(0, ag - 35), math.min(255, ab + 40), 205)
  if bipolar and value ~= nil and value < 0 then
    return fill_neg, cap
  end
  return fill, cap
end

function get_param_lane_def(param_key)
  for _, def in ipairs(SEQ_PARAM_LANES) do
    if def.key == param_key then
      return def
    end
  end
  return nil
end

function seq_note_edit_mode_defs()
  local defs = {}
  for _, def in ipairs(SEQ_PARAM_LANES) do
    if def.hotkey then
      defs[#defs + 1] = def
    end
  end
  return defs
end

function get_seq_note_edit_mode_def()
  return get_param_lane_def(state.seq_note_edit_mode)
end

function seq_set_note_edit_mode(param_key)
  if param_key and get_param_lane_def(param_key) then
    state.seq_note_edit_mode = param_key
  else
    state.seq_note_edit_mode = nil
  end
end

function seq_toggle_note_edit_mode(param_key)
  if state.seq_note_edit_mode == param_key then
    seq_set_note_edit_mode(nil)
  else
    seq_set_note_edit_mode(param_key)
  end
end

function seq_plain_letter_pressed(letter)
  if not letter or not r.ImGui_IsKeyPressed then
    return false
  end
  if is_ctrl_down() or is_cmd_down() or is_alt_down() or is_shift_down() then
    return false
  end
  local fn = r["ImGui_Key_" .. string.upper(letter)]
  if not fn then
    return false
  end
  return r.ImGui_IsKeyPressed(ctx, fn(), false)
end

function seq_plain_digit_pressed(digit)
  if digit == nil or not r.ImGui_IsKeyPressed then
    return false
  end
  if is_ctrl_down() or is_cmd_down() or is_alt_down() or is_shift_down() then
    return false
  end
  local fn = r["ImGui_Key_" .. tostring(digit)]
  if not fn then
    return false
  end
  return r.ImGui_IsKeyPressed(ctx, fn(), false)
end

function seq_capture_shortcut_key()
  if r.ImGui_SetNextFrameWantCaptureKeyboard then
    r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
  end
end

function seq_start_transport_playback()
  local play_state = r.GetPlayState and r.GetPlayState() or 0
  if (play_state & 1) == 0 then
    r.Main_OnCommand(1007, 0)
  end
end

function seq_hover_play_qn()
  local hover = state.seq_grid_hover
  if not hover or type(hover.hovered_qn) ~= "number" then
    return nil
  end
  local step_qn = hover.step_qn or state.seq_grid_qn or 0.25
  if step_qn <= 0 then
    step_qn = 0.25
  end
  -- Start of the hovered grid cell (measure/beat on the current grid).
  return math.max(0.0, math.floor((hover.hovered_qn / step_qn) + 1e-9) * step_qn)
end

function seq_play_from_hover_grid()
  local qn = seq_hover_play_qn()
  if qn then
    seq_set_playhead_qn(qn)
  end
  seq_start_transport_playback()
  return qn ~= nil
end

function seq_set_exclusive_slot_solo(slot)
  local changed = false
  for _, s in ipairs(state.seq_tracks or {}) do
    local want = (slot ~= nil and s.id == slot.id)
    if s.solo ~= want then
      s.solo = want
      changed = true
    end
  end
  if changed then
    seq_apply_all_slot_mix_to_reaper()
    save_config()
  end
  return changed
end

function seq_clear_all_slot_solos()
  local changed = false
  for _, s in ipairs(state.seq_tracks or {}) do
    if s.solo then
      s.solo = false
      changed = true
    end
  end
  if changed then
    seq_apply_all_slot_mix_to_reaper()
    save_config()
  end
  return changed
end

function seq_hover_slot()
  local hover = state.seq_grid_hover
  if not hover or not hover.slot_id then
    return nil
  end
  return seq_find_slot_by_id(hover.slot_id)
end

function seq_set_note_body_length(note, length_qn, step_qn)
  if type(note) ~= "table" then
    return
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  length_qn = math.max(step_qn * 0.05, tonumber(length_qn) or step_qn)
  if seq_stutter_count(note) > 1 then
    note.length_qn = length_qn
  else
    note.decay_qn = length_qn
  end
  seq_clamp_note_fades(note, length_qn)
end

function seq_find_note_covering_abs_qn(region, slot, abs_qn, step_qn)
  if not region or not slot or type(abs_qn) ~= "number" then
    return nil, nil
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local pattern = get_seq_pattern(region.pattern_id, false)
  local notes = get_track_note_table(pattern, slot.id, false)
  if not notes then
    return nil, nil
  end
  local best_key, best_note, best_start = nil, nil, -math.huge
  for key, note in pairs(notes) do
    if type(note) == "table" and note.enabled ~= false then
      local start_qn = seq_note_visual_abs_qn(region, note, key, step_qn)
      local length_qn = seq_note_current_decay_length_qn(region, slot, note, key, step_qn) or 0.0
      local end_qn = start_qn + math.max(0.0, length_qn)
      if abs_qn >= start_qn - 1e-9 and abs_qn < end_qn - 1e-9 and start_qn >= best_start then
        best_key, best_note, best_start = tostring(key), note, start_qn
      end
    end
  end
  return best_key, best_note
end

function seq_split_note_at_qn(region, slot, step_key, note, split_qn, step_qn, snap)
  if not region or not slot or not note or type(split_qn) ~= "number" then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  if snap then
    split_qn = seq_snap_qn(split_qn, step_qn)
  else
    split_qn = seq_quantize_free_qn(split_qn)
  end
  local start_qn = seq_note_visual_abs_qn(region, note, step_key, step_qn)
  local length_qn = seq_note_current_decay_length_qn(region, slot, note, step_key, step_qn) or 0.0
  local end_qn = start_qn + math.max(0.0, length_qn)
  local min_qn = snap and 1e-4 or (1.0 / 192.0)
  if split_qn <= start_qn + min_qn or split_qn >= end_qn - min_qn then
    return false
  end
  local left_len = split_qn - start_qn
  local right_len = end_qn - split_qn
  if left_len < min_qn or right_len < min_qn then
    return false
  end

  local own = seq_undo_own_begin("Split sequencer note")
  local right = clone_table_deep(note)
  seq_set_note_body_length(note, left_len, step_qn)
  seq_note_clear_fade_side(note, "out")
  seq_clamp_note_fades(note, left_len)

  right.qn_offset = split_qn - (region.start_qn or 0.0)
  right.step = math.floor((right.qn_offset / step_qn) + 1e-9)
  right.offset_qn = 0.0
  seq_set_note_body_length(right, right_len, step_qn)
  seq_note_clear_fade_side(right, "in")
  seq_clamp_note_fades(right, right_len)

  local new_key = seq_alloc_note_key(region, slot.id, right.qn_offset)
  set_seq_note(region, slot.id, new_key, right)
  register_seq_note_anim(region.id, slot.id, new_key, right, "add")
  state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = new_key }
  sync_seq_pattern_note(region.pattern_id, slot, step_key)
  sync_seq_pattern_note(region.pattern_id, slot, new_key, { skip_neighbor = true })
  r.UpdateArrange()
  save_config()
  if own then
    end_seq_undo("Split sequencer note")
  end
  return true
end

function handle_seq_playback_and_split_keys()
  if state.active_view ~= "sequencer" then
    return
  end
  if imgui_any_popup_open() or seq_ingest_busy() then
    return
  end
  if seq_plain_digit_pressed(2) then
    local slot = seq_hover_slot()
    if slot then
      seq_capture_shortcut_key()
      seq_set_exclusive_slot_solo(slot)
      seq_play_from_hover_grid()
    end
    return
  end
  if seq_plain_digit_pressed(3) then
    seq_capture_shortcut_key()
    seq_clear_all_slot_solos()
    seq_play_from_hover_grid()
    return
  end
  local snap_split = seq_plain_digit_pressed(4)
  local free_split = seq_plain_digit_pressed(5)
  if snap_split or free_split then
    local hover = state.seq_grid_hover
    if not hover or not hover.slot_id or type(hover.hovered_qn) ~= "number" then
      return
    end
    local slot = seq_find_slot_by_id(hover.slot_id)
    local region = seq_region_at_qn(hover.hovered_qn)
      or (hover.region_id and get_seq_region_by_id(hover.region_id))
    if not slot or not region then
      return
    end
    local step_qn = hover.step_qn or state.seq_grid_qn or 0.25
    local step_key, note = seq_find_note_covering_abs_qn(region, slot, hover.hovered_qn, step_qn)
    if not step_key or not note then
      return
    end
    seq_capture_shortcut_key()
    seq_split_note_at_qn(region, slot, step_key, note, hover.hovered_qn, step_qn, snap_split)
  end
end

function handle_seq_note_edit_mode_keys()
  if state.active_view ~= "sequencer" then
    return
  end
  if imgui_any_popup_open() then
    return
  end
  if seq_plain_letter_pressed("Z") then
    local now = r.time_precise()
    local is_double = (now - (state.seq_z_preview_last_t or 0)) < 0.45
    state.seq_z_preview_last_t = now
    if is_double and preview_proc then
      stop_preview()
      state.preview_paused = false
      state.preview_position = 0.0
      return
    end
    preview_seq_hovered_grid()
    return
  end
  if handle_seq_razor_keys() then
    return
  end
  if seq_ingest_busy() then
    return
  end
  if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
    if state.seq_note_edit_mode then
      seq_set_note_edit_mode(nil)
      return
    end
  end
  for _, def in ipairs(seq_note_edit_mode_defs()) do
    if seq_plain_letter_pressed(def.hotkey) then
      seq_toggle_note_edit_mode(def.key)
      return
    end
  end
end

SEQ_RAZOR_FILL = 0x3DCEFF55
SEQ_RAZOR_EDGE = 0x3DCEFFFF
SEQ_RAZOR_PREVIEW_FILL = 0x3DCEFF88
SEQ_RAZOR_PREVIEW_EDGE = 0x9AEEFFFF
SEQ_RAZOR_HOVER_FILL = 0x3DCEFF99
SEQ_RAZOR_HOVER_EDGE = 0xB8F0FFFF

function seq_razor_right_down()
  if not ctx or not r.ImGui_IsMouseDown then
    return false
  end
  return r.ImGui_IsMouseDown(ctx, 1)
end

function seq_razor_right_clicked()
  if not ctx or not r.ImGui_IsMouseClicked then
    return false
  end
  return r.ImGui_IsMouseClicked(ctx, 1)
end

-- Alt + right-drag draws a razor. Alt+Ctrl/Cmd + right-drag adds another.
function seq_razor_gesture_active()
  if state.seq_razor_drag then
    return state.seq_razor_drag.mode ~= "move"
  end
  if not is_alt_down() then
    return false
  end
  return seq_razor_right_down() or seq_razor_right_clicked()
end

function seq_razor_copy_modifier()
  return is_ctrl_down() or is_cmd_down()
end

function seq_note_copy_modifier()
  return is_ctrl_down() or is_cmd_down()
end

function seq_note_slip_modifier()
  return is_shift_down()
end

function seq_razor_additive_gesture()
  return is_alt_down() and (is_ctrl_down() or is_cmd_down())
end

function seq_has_razors()
  return state.seq_razors and #state.seq_razors > 0
end

function seq_razor_blocks_grid_edit()
  return state.seq_razor_drag ~= nil or seq_razor_gesture_active()
end

function seq_clear_razors()
  local drag = state.seq_razor_drag
  if drag and drag.mode == "move" then
    if drag.patterns_backup then
      state.seq_patterns = clone_table_deep(drag.patterns_backup)
    end
    if drag.undo_open then
      end_seq_undo(drag.undo_label or (drag.copy and "Copy razor notes" or "Move razor notes"))
    end
  end
  local had = seq_has_razors() or state.seq_razor_drag ~= nil
  state.seq_razors = {}
  state.seq_razor_drag = nil
  return had
end

function seq_razor_has_track(razor, track_id)
  if not razor or not razor.track_ids then
    return false
  end
  for _, id in ipairs(razor.track_ids) do
    if id == track_id then
      return true
    end
  end
  return false
end

function seq_cell_in_any_razor(track_id, qn)
  if not seq_has_razors() then
    return false
  end
  for _, razor in ipairs(state.seq_razors) do
    if qn >= (razor.start_qn or 0) and qn < (razor.end_qn or 0) and seq_razor_has_track(razor, track_id) then
      return true
    end
  end
  return false
end

function seq_razor_hovered_at(track_id, qn)
  if not track_id or type(qn) ~= "number" or not seq_has_razors() then
    return false
  end
  for _, razor in ipairs(state.seq_razors) do
    if qn >= (razor.start_qn or 0) and qn < (razor.end_qn or 0) and seq_razor_has_track(razor, track_id) then
      return true
    end
  end
  return false
end

function seq_compute_razor_hover(mx, my, visual_rows, body_y0, body_y1, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not seq_has_razors() or mx < timeline_x0 or mx > timeline_x0 + timeline_w
      or my < body_y0 or my > body_y1 then
    return false, nil, nil
  end
  local track_id = nil
  local cursor_y = body_y0
  for _, row in ipairs(visual_rows) do
    local row_y0 = cursor_y
    local row_y1 = row_y0 + row.h
    if my >= row_y0 and my <= row_y1 and row.slot then
      track_id = row.slot.id
      break
    end
    cursor_y = row_y1
  end
  if not track_id then
    return false, nil, nil
  end
  local qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_razor_hovered_at(track_id, qn) then
    return true, track_id, qn
  end
  return false, nil, nil
end

function seq_track_id_at_y(row_positions, my)
  if not row_positions or #row_positions == 0 then
    return nil
  end
  for _, row_pos in ipairs(row_positions) do
    if my >= row_pos.y0 and my <= row_pos.y1 and row_pos.row and row_pos.row.slot then
      return row_pos.row.slot.id
    end
  end
  local first = row_positions[1]
  if my < first.y0 and first.row and first.row.slot then
    return first.row.slot.id
  end
  for i = #row_positions, 1, -1 do
    local row_pos = row_positions[i]
    if row_pos.row and row_pos.row.slot then
      return row_pos.row.slot.id
    end
  end
  return nil
end

function seq_normalize_razor_area(start_qn, end_qn, track_id_a, track_id_b, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  if type(start_qn) ~= "number" or type(end_qn) ~= "number" then
    return nil
  end
  local q0 = math.min(start_qn, end_qn)
  local q1 = math.max(start_qn, end_qn)
  q0 = math.max(0.0, math.floor(q0 / step_qn + 1e-9) * step_qn)
  q1 = math.ceil(q1 / step_qn - 1e-9) * step_qn
  if q1 <= q0 then
    q1 = q0 + step_qn
  end
  local _, ia = find_seq_track_by_id(track_id_a)
  local _, ib = find_seq_track_by_id(track_id_b)
  if not ia or not ib then
    return nil
  end
  if ia > ib then
    ia, ib = ib, ia
  end
  local track_ids = {}
  for i = ia, ib do
    local slot = state.seq_tracks[i]
    if slot then
      track_ids[#track_ids + 1] = slot.id
    end
  end
  if #track_ids == 0 then
    return nil
  end
  return { start_qn = q0, end_qn = q1, track_ids = track_ids }
end

function seq_begin_razor_drag(track_id, qn, additive)
  if not track_id or type(qn) ~= "number" then
    return
  end
  if not additive then
    state.seq_razors = {}
  end
  state.seq_razor_drag = {
    mode = "draw",
    additive = additive and true or false,
    start_qn = qn,
    start_track_id = track_id,
    current_qn = qn,
    current_track_id = track_id,
  }
end

function seq_razor_collect_notes(step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local items = {}
  local seen = {}
  for _, razor in ipairs(state.seq_razors or {}) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      for _, region in ipairs(state.seq_regions) do
        local reg_start = region.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(region)
        if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
          local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), track_id, false)
          if notes then
            for step_key, note in pairs(notes) do
              if type(note) == "table" then
                local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    local uniq = tostring(region.id) .. ":" .. tostring(track_id) .. ":" .. tostring(step_key)
                    if not seen[uniq] then
                      seen[uniq] = true
                      local slot = seq_find_slot_by_id(track_id)
                      items[#items + 1] = {
                        region_id = region.id,
                        track_id = track_id,
                        step_key = tostring(step_key),
                        step_idx = tonumber(step_key) or tonumber(note.step) or 0,
                        abs_qn = abs_qn,
                        note = clone_table_deep(note),
                        length_qn = seq_note_length_qn_for_copy(region, slot, note, step_key, step_qn),
                      }
                    end
                end
              end
            end
          end
        end
      end
    end
  end
  return items
end

function seq_razor_track_index_bounds(track_ids)
  local min_idx, max_idx = nil, nil
  for _, track_id in ipairs(track_ids or {}) do
    local _, idx = find_seq_track_by_id(track_id)
    if idx then
      min_idx = min_idx and math.min(min_idx, idx) or idx
      max_idx = max_idx and math.max(max_idx, idx) or idx
    end
  end
  return min_idx, max_idx
end

function seq_shift_track_ids(track_ids, delta_tracks)
  if not track_ids or delta_tracks == 0 then
    return track_ids
  end
  local shifted = {}
  for _, track_id in ipairs(track_ids) do
    local _, idx = find_seq_track_by_id(track_id)
    local slot = idx and state.seq_tracks[idx + delta_tracks]
    if not slot then
      return nil
    end
    shifted[#shifted + 1] = slot.id
  end
  return shifted
end

function seq_razor_clear_notes_in_areas(razors, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  for _, razor in ipairs(razors or {}) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      for _, region in ipairs(state.seq_regions) do
        local reg_start = region.start_qn or 0.0
        local reg_end = reg_start + get_seq_region_length_qn(region)
        if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
          local notes = get_track_note_table(get_seq_pattern(region.pattern_id, false), track_id, false)
          if notes then
            local to_delete = {}
            for step_key, note in pairs(notes) do
              if type(note) == "table" then
                local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    to_delete[#to_delete + 1] = step_key
                end
              end
            end
            for _, step_key in ipairs(to_delete) do
              delete_seq_note(region, track_id, step_key)
            end
          end
        end
      end
    end
  end
end

function seq_begin_razor_move(track_id, qn, step_qn, copy)
  if not seq_has_razors() or not track_id or type(qn) ~= "number" then
    return
  end
  copy = copy and true or false
  local label = begin_seq_undo(copy and "Copy razor notes" or "Move razor notes")
  state.seq_razor_drag = {
    mode = "move",
    copy = copy,
    start_qn = qn,
    start_track_id = track_id,
    current_qn = qn,
    current_track_id = track_id,
    payload = seq_razor_collect_notes(step_qn),
    patterns_backup = clone_table_deep(state.seq_patterns),
    razors_orig = clone_table_deep(state.seq_razors),
    applied_delta_qn = 0,
    applied_delta_tracks = 0,
    undo_label = label,
    undo_open = true,
    dirty = false,
  }
end

function seq_razor_clamped_move_delta(drag, step_qn)
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local raw_qn = (drag.current_qn or drag.start_qn) - (drag.start_qn or 0)
  local delta_qn = math.floor((raw_qn / step_qn) + 0.5) * step_qn
  local _, start_idx = find_seq_track_by_id(drag.start_track_id)
  local _, cur_idx = find_seq_track_by_id(drag.current_track_id)
  local delta_tracks = 0
  if start_idx and cur_idx then
    delta_tracks = cur_idx - start_idx
  end

  local min_qn = nil
  local min_idx, max_idx = nil, nil
  for _, razor in ipairs(drag.razors_orig or {}) do
    min_qn = min_qn and math.min(min_qn, razor.start_qn or 0) or (razor.start_qn or 0)
    local rmin, rmax = seq_razor_track_index_bounds(razor.track_ids)
    if rmin then
      min_idx = min_idx and math.min(min_idx, rmin) or rmin
      max_idx = max_idx and math.max(max_idx, rmax) or rmax
    end
  end
  for _, item in ipairs(drag.payload or {}) do
    min_qn = min_qn and math.min(min_qn, item.abs_qn) or item.abs_qn
    local _, idx = find_seq_track_by_id(item.track_id)
    if idx then
      min_idx = min_idx and math.min(min_idx, idx) or idx
      max_idx = max_idx and math.max(max_idx, idx) or idx
    end
  end
  if min_qn then
    delta_qn = math.max(delta_qn, -min_qn)
  end
  local track_count = #(state.seq_tracks or {})
  if min_idx and max_idx and track_count > 0 then
    delta_tracks = math.max(1 - min_idx, math.min(track_count - max_idx, delta_tracks))
  else
    delta_tracks = 0
  end
  return delta_qn, delta_tracks
end

function seq_razor_apply_move(drag, step_qn)
  if not drag or drag.mode ~= "move" then
    return
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local delta_qn, delta_tracks = seq_razor_clamped_move_delta(drag, step_qn)
  if drag.applied_delta_qn == delta_qn and drag.applied_delta_tracks == delta_tracks then
    return
  end

  state.seq_patterns = clone_table_deep(drag.patterns_backup)
  if delta_qn ~= 0 or delta_tracks ~= 0 then
    local dest_razors = {}
    for _, orig in ipairs(drag.razors_orig or {}) do
      dest_razors[#dest_razors + 1] = {
        start_qn = (orig.start_qn or 0) + delta_qn,
        end_qn = (orig.end_qn or 0) + delta_qn,
        track_ids = seq_shift_track_ids(orig.track_ids, delta_tracks) or orig.track_ids,
      }
    end
    if not drag.copy then
      for _, item in ipairs(drag.payload or {}) do
        local region = get_seq_region_by_id(item.region_id)
        delete_seq_note(region, item.track_id, item.step_key)
      end
    end
    seq_razor_clear_notes_in_areas(dest_razors, step_qn)
    for _, item in ipairs(drag.payload or {}) do
      local _, orig_idx = find_seq_track_by_id(item.track_id)
      local dest_slot = orig_idx and state.seq_tracks[orig_idx + delta_tracks]
      local dest_qn = item.abs_qn + delta_qn
      local dest_region = seq_region_at_qn(dest_qn)
      if dest_slot and dest_region and dest_qn >= 0 then
        local rel = dest_qn - (dest_region.start_qn or 0.0)
        if rel >= -1e-9 and rel < get_seq_region_length_qn(dest_region) - 1e-9 then
          local note = clone_table_deep(item.note)
          note.qn_offset = rel
          note.step = math.floor((rel / step_qn) + 1e-9)
          seq_keep_copied_note_over_region(note, item.length_qn, dest_region, rel)
          local key = seq_alloc_note_key(dest_region, dest_slot.id, rel)
          set_seq_note(dest_region, dest_slot.id, key, note)
        end
      end
    end
  end

  local moved_razors = {}
  for _, orig in ipairs(drag.razors_orig or {}) do
    local track_ids = seq_shift_track_ids(orig.track_ids, delta_tracks) or orig.track_ids
    moved_razors[#moved_razors + 1] = {
      start_qn = (orig.start_qn or 0) + delta_qn,
      end_qn = (orig.end_qn or 0) + delta_qn,
      track_ids = track_ids,
    }
  end
  state.seq_razors = moved_razors
  drag.applied_delta_qn = delta_qn
  drag.applied_delta_tracks = delta_tracks
  drag.dirty = (delta_qn ~= 0 or delta_tracks ~= 0)
end

function seq_razor_mark_pattern_ids_for_razors(razors, pattern_ids)
  for _, razor in ipairs(razors or {}) do
    for _, region in ipairs(state.seq_regions) do
      local rs = region.start_qn or 0.0
      local re = rs + get_seq_region_length_qn(region)
      if re > (razor.start_qn or 0) and rs < (razor.end_qn or 0) and region.pattern_id then
        pattern_ids[region.pattern_id] = true
      end
    end
  end
end

function seq_razor_sync_moved_items(drag, step_qn)
  local track_ids = {}
  local pattern_ids = {}

  local function mark_track(id)
    if id then
      track_ids[id] = true
    end
  end

  for _, item in ipairs(drag.payload or {}) do
    mark_track(item.track_id)
    local src_region = get_seq_region_by_id(item.region_id)
    if src_region and src_region.pattern_id then
      pattern_ids[src_region.pattern_id] = true
    end
    local _, orig_idx = find_seq_track_by_id(item.track_id)
    local dest_slot = orig_idx and state.seq_tracks[orig_idx + (drag.applied_delta_tracks or 0)]
    if dest_slot then
      mark_track(dest_slot.id)
    end
    local dest_qn = (item.abs_qn or 0) + (drag.applied_delta_qn or 0)
    local dest_region = seq_region_at_qn(dest_qn)
    if dest_region and dest_region.pattern_id then
      pattern_ids[dest_region.pattern_id] = true
    end
  end
  for _, razor in ipairs(drag.razors_orig or {}) do
    for _, tid in ipairs(razor.track_ids or {}) do
      mark_track(tid)
    end
  end
  for _, razor in ipairs(state.seq_razors or {}) do
    for _, tid in ipairs(razor.track_ids or {}) do
      mark_track(tid)
    end
  end
  seq_razor_mark_pattern_ids_for_razors(drag.razors_orig, pattern_ids)
  seq_razor_mark_pattern_ids_for_razors(state.seq_razors, pattern_ids)

  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, region in ipairs(state.seq_regions) do
    if pattern_ids[region.pattern_id] then
      for _, slot in ipairs(state.seq_tracks) do
        if track_ids[slot.id] then
          sync_seq_region_track(region, slot, { skip_arrange = true })
        end
      end
    end
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  r.UpdateArrange()
end

function seq_update_razor_drag(track_id, qn, row_positions, my)
  local drag = state.seq_razor_drag
  if not drag then
    return
  end
  if type(qn) == "number" then
    drag.current_qn = qn
  end
  if track_id then
    drag.current_track_id = track_id
  elseif row_positions and my then
    local id = seq_track_id_at_y(row_positions, my)
    if id then
      drag.current_track_id = id
    end
  end
end

function seq_commit_razor_drag(step_qn)
  local drag = state.seq_razor_drag
  state.seq_razor_drag = nil
  if not drag then
    return
  end
  if drag.mode == "move" then
    if drag.dirty then
      seq_razor_sync_moved_items(drag, step_qn)
      save_config()
    end
    if drag.undo_open then
      end_seq_undo(drag.undo_label or (drag.copy and "Copy razor notes" or "Move razor notes"))
    end
    return
  end
  local area = seq_normalize_razor_area(
    drag.start_qn, drag.current_qn, drag.start_track_id, drag.current_track_id, step_qn
  )
  if not area then
    return
  end
  state.seq_razors = state.seq_razors or {}
  if not drag.additive then
    state.seq_razors = {}
  end
  state.seq_razors[#state.seq_razors + 1] = area
end

function seq_razor_y_bounds(razor, row_positions)
  if not razor or not row_positions then
    return nil, nil
  end
  local y0, y1 = nil, nil
  for _, row_pos in ipairs(row_positions) do
    local slot = row_pos.row and row_pos.row.slot
    if slot and seq_razor_has_track(razor, slot.id) then
      y0 = y0 and math.min(y0, row_pos.y0) or row_pos.y0
      y1 = y1 and math.max(y1, row_pos.y1) or row_pos.y1
    end
  end
  return y0, y1
end

function draw_seq_razor_area(dl, razor, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, preview, hovered)
  if not razor or not dl then
    return
  end
  local y0, y1 = seq_razor_y_bounds(razor, row_positions)
  if not y0 or not y1 or y1 <= y0 then
    return
  end
  local timeline_w = math.max(1.0, timeline_x1 - timeline_x0)
  local function qn_to_x(qn)
    return timeline_x0 + ((qn - view_start_qn) / math.max(0.0001, qn_span)) * timeline_w
  end
  local rx0 = math.max(timeline_x0, qn_to_x(razor.start_qn or 0))
  local rx1 = math.min(timeline_x1, qn_to_x(razor.end_qn or 0))
  if rx1 <= rx0 then
    return
  end
  local fill = preview and SEQ_RAZOR_PREVIEW_FILL or (hovered and SEQ_RAZOR_HOVER_FILL or SEQ_RAZOR_FILL)
  local edge = preview and SEQ_RAZOR_PREVIEW_EDGE or (hovered and SEQ_RAZOR_HOVER_EDGE or SEQ_RAZOR_EDGE)
  local thickness = preview and 2.0 or (hovered and 2.4 or 1.6)
  r.ImGui_DrawList_AddRectFilled(dl, rx0, y0, rx1, y1, fill, 0)
  r.ImGui_DrawList_AddRect(dl, rx0, y0, rx1, y1, edge, 0, 0, thickness)
end

function draw_seq_razors(dl, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, step_qn, hover_track_id, hover_qn)
  for _, razor in ipairs(state.seq_razors or {}) do
    local hovered = hover_track_id and hover_qn
      and seq_razor_has_track(razor, hover_track_id)
      and hover_qn >= (razor.start_qn or 0) and hover_qn < (razor.end_qn or 0)
    draw_seq_razor_area(dl, razor, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, false, hovered)
  end
  local drag = state.seq_razor_drag
  if drag and drag.mode ~= "move" then
    local preview = seq_normalize_razor_area(
      drag.start_qn, drag.current_qn, drag.start_track_id, drag.current_track_id, step_qn
    )
    if preview then
      draw_seq_razor_area(dl, preview, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, true)
    end
  end
end

function seq_delete_notes_in_razors()
  if not seq_has_razors() then
    return false
  end
  local step_qn = state.seq_grid_qn or 0.25
  local label = begin_seq_undo("Delete razor notes")
  local changed = false
  local synced = {}
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  for _, razor in ipairs(state.seq_razors) do
    for _, track_id in ipairs(razor.track_ids or {}) do
      local slot = find_seq_track_by_id(track_id)
      if slot then
        for _, region in ipairs(state.seq_regions) do
          local reg_start = region.start_qn or 0.0
          local reg_end = reg_start + get_seq_region_length_qn(region)
          if reg_end > (razor.start_qn or 0) and reg_start < (razor.end_qn or 0) then
            local pattern = get_seq_pattern(region.pattern_id, false)
            local notes = get_track_note_table(pattern, track_id, false)
            if notes then
              local to_delete = {}
              for step_key, note in pairs(notes) do
                if type(note) == "table" then
                  local abs_qn = seq_note_abs_qn(region, note, step_key, step_qn)
                  if abs_qn >= (razor.start_qn or 0) and abs_qn < (razor.end_qn or 0) then
                    to_delete[#to_delete + 1] = { key = step_key, qn = seq_note_qn_offset(note, step_key, step_qn) }
                  end
                end
              end
              for _, rec in ipairs(to_delete) do
                if toggle_seq_note(region, slot, rec.key, rec.qn, "erase", {
                  defer_save = true,
                  defer_arrange = true,
                }) then
                  changed = true
                  synced[region.pattern_id] = true
                end
              end
            end
          end
        end
      end
    end
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  if changed then
    for pattern_id in pairs(synced) do
      sync_seq_pattern_regions(pattern_id)
    end
    r.UpdateArrange()
    save_config()
  end
  end_seq_undo(label)
  return changed
end

function handle_seq_razor_keys()
  if r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
      and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false) then
    if seq_clear_razors() then
      return true
    end
  end
  if seq_ingest_busy() then
    return false
  end
  local delete_pressed = r.ImGui_IsKeyPressed and r.ImGui_Key_Delete
    and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Delete(), false)
  local backspace_pressed = r.ImGui_IsKeyPressed and r.ImGui_Key_Backspace
    and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Backspace(), false)
  if (delete_pressed or backspace_pressed) and seq_has_razors() then
    if r.ImGui_SetNextFrameWantCaptureKeyboard then
      r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
    end
    seq_delete_notes_in_razors()
    return true
  end
  return false
end

function find_seq_note_lane_bounds(row_positions, track_id)
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot and row.slot.id == track_id then
      return row_pos.y0 + 2, row_pos.y1 - 2, row_pos
    end
  end
  return nil, nil, nil
end

function seq_param_drag_button_down(drag, left_down, right_down)
  if not drag then
    return false
  end
  if drag.button == 1 then
    return right_down
  end
  return left_down
end

function apply_seq_param_reset_drag(drag, def, mx, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells)
  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.col, drag.end_col)
  local col_max = math.max(drag.col, drag.end_col)
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_is_lock_def(def) then
    if drag.lock_click_span then
      if drag.end_col == drag.col then
        return false, 0.0, col_min, col_max, drag.end_col
      end
      drag.lock_click_span = false
    end
    local region = get_seq_region_by_id(drag.region_id)
    local changed = seq_apply_lock_range(region, drag.track_id, col_min, col_max, start_qn, step_qn, false, active_cells)
    return changed, 0.0, col_min, col_max, drag.end_col
  end
  local changed = false
  for col = col_min, col_max do
    local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
    if active then
      local qn0 = start_qn + col * step_qn
      local qn1 = qn0 + step_qn
      seq_for_each_active_note(active, function(entry)
        if seq_apply_param_to_note(
          entry.note, entry.abs_qn, def, def.default, mouse_qn, step_qn, true, true, qn0, qn1
        ) then
          changed = true
        end
      end)
    end
  end
  return changed, def.default, col_min, col_max, drag.end_col
end

function seq_note_item_x_range(note, slot, region, pattern, step_idx, cell_qn, step_qn, qn_to_x, cell_x1)
  if not note or not qn_to_x then
    return nil, nil
  end
  local _, resolved_sample = resolve_seq_note_sample(note, slot)
  local note_qn = cell_qn
  if region then
    note_qn = seq_note_abs_qn(region, note, step_idx, step_qn)
  end
  local note_len = seq_note_draw_length_qn(
    region, pattern, slot, slot and slot.id, step_idx, note, resolved_sample, step_qn
  ) or step_qn
  local note_off = note.offset_qn or 0.0
  local draw_x0 = qn_to_x(note_qn + note_off) + 2
  local draw_x1 = math.max(draw_x0 + 6.0, qn_to_x(note_qn + note_off + note_len) - 2)
  local trigger_x1 = draw_x1
  if seq_stutter_count(note) <= 1 then
    local head_x1 = seq_note_head_end_x(qn_to_x, note_qn, note, step_qn)
    if head_x1 and draw_x1 > head_x1 + 1.0 then
      trigger_x1 = math.max(draw_x0 + 6.0, head_x1)
    end
  end
  return draw_x0, trigger_x1
end

function draw_seq_param_value_bar(dl, x0, x1, lane_top, lane_bot, def, value, step_qn, accent, selected)
  if not def then
    return
  end
  if value == nil then
    value = def.default
  end
  value = seq_param_value_for_drag(def, value, step_qn)
  local bipolar = def.min < 0
  local py = seq_param_y_from_value(def, value, lane_top, lane_bot, step_qn)
  local base_y = lane_bot
  if bipolar then
    base_y = seq_param_y_from_value(def, 0.0, lane_top, lane_bot, step_qn)
  end
  local fill_x0 = x0
  local fill_x1 = x1
  if fill_x1 <= fill_x0 then
    fill_x1 = fill_x0 + 1
  end
  local top_y = math.min(py, base_y)
  local bot_y = math.max(py, base_y)
  if math.abs(bot_y - top_y) < 2 then
    top_y = math.min(top_y, bot_y - 2)
  end
  local fill_col, cap_col = seq_lane_param_fill_colors(accent, bipolar, value)
  if not selected then
    fill_col = seq_dim_color_rrgbbaa(fill_col, true)
    cap_col = seq_dim_color_rrgbbaa(cap_col, true)
  end
  r.ImGui_DrawList_AddRectFilled(dl, fill_x0, top_y, fill_x1, bot_y, fill_col, 2.0)
  local cap_y = (py <= base_y) and top_y or bot_y
  r.ImGui_DrawList_AddRectFilled(dl, fill_x0, cap_y - 1, fill_x1, cap_y + 1, cap_col, 1.0)
end

function seq_draw_stutter_param_slices(dl, note, note_qn, def, step_qn, qn_to_x, lane_top, lane_bot, accent, selected, hover_qn)
  local count = seq_stutter_count(note)
  if count <= 1 or not seq_stutter_hit_param_key(def.key) then
    return false
  end
  local span = seq_stutter_span_qn(note, step_qn) or step_qn
  local note_off = (note and note.offset_qn) or 0.0
  local slice = span / count
  local hover_idx = hover_qn and seq_stutter_hit_index_at_qn(note, note_qn, hover_qn, step_qn) or nil
  for hi = 1, count do
    local s0 = note_qn + note_off + (hi - 1) * slice
    local s1 = s0 + slice
    local sx0 = qn_to_x(s0) + 1.0
    local sx1 = qn_to_x(s1) - 1.0
    if sx1 <= sx0 then
      sx1 = sx0 + 1.0
    end
    local value = seq_note_param_value(note, def.key, hi)
    if value == nil then
      value = def.default
    end
    draw_seq_param_value_bar(dl, sx0, sx1, lane_top, lane_bot, def, value, step_qn, accent, selected)
    if hover_idx == hi then
      r.ImGui_DrawList_AddRect(dl, sx0, lane_top, sx1, lane_bot, seq_lane_color_with_alpha(accent, 220), 1.0, 0, 1.2)
    end
    if hi > 1 then
      local dx = qn_to_x(s0)
      r.ImGui_DrawList_AddLine(dl, dx, lane_top, dx, lane_bot, 0xFFFFFF55, 1.0)
    end
  end
  return true
end

function seq_draw_param_lane_packed_notes(dl, ctx, slot, active, def, selected_region_id, start_qn, col, step_qn, qn_to_x, cx0, cx1, lane_top, lane_bot, base_y, bipolar, is_stutter_lane, lane_style, region)
  local pack = seq_active_cell_notes(active)
  if not pack then
    return
  end
  seq_pack_sort_later_on_top(pack)
  for pi = 1, #pack do
    local entry = pack[pi]
    local note = entry.note
    if type(note) == "table" then
      local cell_selected = entry.region_id == selected_region_id
      local value = note[def.key]
      if value == nil then value = def.default end
      if def.key == "length_qn" then
        value = snap_seq_length_qn(value, step_qn)
      elseif def.key == "stutter" then
        value = seq_param_value_for_drag(def, value, step_qn)
      end
      local note_qn = entry.abs_qn or (start_qn + col * step_qn)
      local cell_qn = start_qn + col * step_qn
      if note_qn < cell_qn - 1e-9 then
        -- Occupancy-only cell for a spanning stutter; draw from the start cell.
      else
      local cell_reg = get_seq_region_by_id(entry.region_id) or seq_region_at_qn(note_qn) or region
      local pattern = get_seq_pattern(cell_reg and cell_reg.pattern_id, false)
      local item_x0, item_x1 = seq_note_item_x_range(
        note, slot, cell_reg, pattern, entry.key, note_qn, step_qn, qn_to_x, qn_to_x(note_qn + step_qn)
      )
      if not item_x0 then
        item_x0, item_x1 = cx0 + 2, cx1 - 2
      end
      if item_x1 <= item_x0 then
        item_x1 = item_x0 + 1
      end
      if is_stutter_lane then
        local accent = cell_selected and lane_style.accent or seq_lane_color_with_alpha(lane_style.accent, 100)
        draw_seq_stutter_lane_cell(dl, ctx, item_x0, item_x1, lane_top, lane_bot, value, accent)
      else
        local accent = cell_selected and lane_style.accent or seq_lane_color_with_alpha(lane_style.accent, 100)
        if not seq_draw_stutter_param_slices(
          dl, note, note_qn, def, step_qn, qn_to_x, lane_top, lane_bot, accent, cell_selected, nil
        ) then
          draw_seq_param_value_bar(dl, item_x0, item_x1, lane_top, lane_bot, def, value, step_qn, accent, cell_selected)
        end
      end
      local note_fx = get_seq_note_anim(entry.region_id, slot.id, entry.key, r.time_precise())
      if note_fx and note_fx.kind == "sync" then
        draw_seq_note_sync_flash(dl, item_x0, lane_top, item_x1, lane_bot, note_fx.t)
      end
      end
    end
  end
end

function seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells)
  if not slot then
    return false
  end
  local active = active_cells and active_cells[slot.id] and active_cells[slot.id][col]
  if active then
    local locked = false
    seq_for_each_active_note(active, function(entry)
      if seq_note_is_locked(entry.note) then
        locked = true
      end
    end)
    if locked then
      return true
    end
  end
  local cell_qn = start_qn + col * step_qn
  local lock_reg = seq_region_at_qn(cell_qn)
  if not lock_reg then
    return false
  end
  return seq_cell_is_locked(
    get_seq_pattern(lock_reg.pattern_id, false),
    slot.id,
    seq_region_step_key(lock_reg, cell_qn, step_qn)
  )
end

function seq_lock_span_cols(slot, col, start_qn, step_qn, step_count, active_cells)
  col = math.max(0, math.min((step_count or 1) - 1, col or 0))
  if not seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells) then
    return col, col
  end
  local lo, hi = col, col
  while lo > 0 and seq_visible_cell_is_locked(slot, lo - 1, start_qn, step_qn, active_cells) do
    lo = lo - 1
  end
  while hi < step_count - 1 and seq_visible_cell_is_locked(slot, hi + 1, start_qn, step_qn, active_cells) do
    hi = hi + 1
  end
  return lo, hi
end

function draw_seq_lock_icon(dl, cx, cy, size)
  size = math.max(12.0, size or 18.0)
  local half = size * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, cx - half, cy - half, cx + half, cy + half, 0x10141CF5, 4.0)
  r.ImGui_DrawList_AddRect(dl, cx - half, cy - half, cx + half, cy + half, 0xF7FBFFFF, 4.0, 0, 1.5)
  local body_w = size * 0.44
  local body_h = size * 0.34
  local body_y = cy + size * 0.02
  r.ImGui_DrawList_AddRectFilled(dl, cx - body_w * 0.5, body_y, cx + body_w * 0.5, body_y + body_h, 0xFFFFFFFF, 1.8)
  local shackle_r = size * 0.16
  r.ImGui_DrawList_AddCircle(dl, cx, body_y, shackle_r, 0xFFFFFFFF, 14, 2.0)
end

function draw_seq_lock_span(dl, x0, y0, x1, y1, edit_mode, hovered)
  local pad = 3.0
  local sx0 = x0 + 1.0
  local sx1 = x1 - 1.0
  local sy0 = y0 + pad
  local sy1 = y1 - pad
  if sx1 <= sx0 + 2.0 then
    return
  end
  local fill = edit_mode and 0x0B1220B8 or 0x0B122096
  local wash = 0xF4F8FF28
  local outline = 0xF7FBFFFF
  local outline_w = 1.7
  if hovered then
    fill = 0x1A2438E0
    wash = 0xFFFFFF58
    outline = 0xFFFFFFFF
    outline_w = 2.3
  end
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, fill, 5.0)
  r.ImGui_DrawList_AddRectFilled(dl, sx0, sy0, sx1, sy1, wash, 5.0)
  if hovered then
    r.ImGui_DrawList_AddRect(dl, sx0 - 1.0, sy0 - 1.0, sx1 + 1.0, sy1 + 1.0, 0xFFFFFFF0, 5.0, 0, 1.6)
  end
  r.ImGui_DrawList_AddRect(dl, sx0, sy0, sx1, sy1, outline, 5.0, 0, outline_w)
  local w = sx1 - sx0
  local h = sy1 - sy0
  local icon = math.min(28.0, math.max(16.0, h * 0.64))
  if w < icon + 6.0 then
    icon = math.max(12.0, w - 6.0)
  end
  draw_seq_lock_icon(dl, (sx0 + sx1) * 0.5, (sy0 + sy1) * 0.5, icon)
end

function draw_seq_lock_spans(dl, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, active_cells, edit_mode, hover_col)
  local run_start = nil
  local function flush(run_end)
    if not run_start then
      return
    end
    local x0 = math.max(timeline_x0, col_x0(run_start))
    local x1 = math.min(timeline_x1, col_x1(run_end))
    if x1 > x0 + 1.0 then
      local hovered = hover_col ~= nil and hover_col >= run_start and hover_col <= run_end
      draw_seq_lock_span(dl, x0, row_y0, x1, row_y1, edit_mode, hovered)
    end
    run_start = nil
  end
  for col = 0, step_count - 1 do
    if seq_visible_cell_is_locked(slot, col, start_qn, step_qn, active_cells) then
      if not run_start then
        run_start = col
      end
    else
      flush(col - 1)
    end
  end
  flush(step_count - 1)
end

function draw_seq_note_param_mode_overlay(dl, ctx, def, value, cx0, cx1, y0, y1, step_qn, accent, selected)
  if not def then
    return
  end
  local lane_top = y0 + 2
  local lane_bot = y1 - 2
  if seq_is_lock_def(def) then
    return
  end
  if def.key == "stutter" then
    if value == nil then
      value = def.default
    end
    draw_seq_stutter_lane_cell(dl, ctx, cx0, cx1, lane_top, lane_bot, value, accent)
    return
  end
  draw_seq_param_value_bar(dl, cx0, cx1, lane_top, lane_bot, def, value, step_qn, accent, selected)
end

function seq_edit_mode_accent(param_key)
  if not param_key then
    return UI_THEME.accent
  end
  local style = get_seq_row_lane_style({ type = "param", param = { key = param_key } })
  return (style and style.accent) or UI_THEME.accent
end

function render_seq_note_edit_mode_bar(btn_h)
  btn_h = btn_h or 26
  local btn_w = calc_seq_note_edit_mode_btn_width()
  local active_def = get_seq_note_edit_mode_def()
  local notes_on = not active_def
  if draw_ui_button("seq_edit_mode_notes", "Notes", btn_w, btn_h, {
    style = "default",
    selected = notes_on,
    compact = true,
    color = seq_edit_mode_accent(nil),
  }) then
    seq_set_note_edit_mode(nil)
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Paint and erase notes (Esc)\nAlt+LMB drag = stutter (horizontal = length, vertical = count)\nCtrl/Cmd+LMB drag on a note = copy (keeps sample, including region variation)\nShift+empty grid = place off-grid (click inserts at the pointer)\nShift+LMB drag on a note = move off-grid\nAlt+RMB drag = razor edit\nAlt+Ctrl+RMB drag = add razor area\nLMB drag on razor = move notes\nCtrl/Cmd+LMB drag on razor = copy notes")
  end
  for _, def in ipairs(seq_note_edit_mode_defs()) do
    local selected = active_def and active_def.key == def.key
    imgui_same_line_if_fits(btn_w, 3)
    if draw_ui_button("seq_edit_mode_" .. def.key, def.label, btn_w, btn_h, {
      style = "default",
      selected = selected,
      compact = true,
      color = seq_edit_mode_accent(def.key),
    }) then
      seq_toggle_note_edit_mode(def.key)
    end
    if r.ImGui_IsItemHovered(ctx) then
      if seq_is_decay_def(def) then
        r.ImGui_SetTooltip(ctx, "Decay mode (D)\nDrag the last grid / end line to set note length (Shift = unsnap)\nDrag start/end circles for fade length (vertical = fade type)\nDrag the fade curve to change native curvature\nDragging a fade past the other fade pushes it out of the way\nRMB on a handle = reset")
      elseif seq_is_lock_def(def) then
        r.ImGui_SetTooltip(ctx, "Lock mode (L)\nClick a note or empty cell to lock it\nDrag to lock a range of notes and empty grids\nRMB click a lock = unlock the whole area\nRMB drag = unlock only the cells you sweep")
      else
        r.ImGui_SetTooltip(ctx, string.format(
          "%s mode (%s)\nLMB drag on notes = set value\nRMB drag on notes = reset to default\nOn stutter notes, each slice can be edited separately",
          def.mode_name or def.label, def.hotkey
        ))
      end
    end
  end
  if seq_has_razors() or state.seq_razor_drag then
    local count = state.seq_razors and #state.seq_razors or 0
    if state.seq_razor_drag and state.seq_razor_drag.mode ~= "move" then
      count = count + 1
    end
    local razor_label = string.format("Razor ×%d", count)
    imgui_same_line_if_fits(calc_compact_chip_width(razor_label), 8)
    r.ImGui_TextColored(ctx, SEQ_RAZOR_EDGE, razor_label)
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "LMB move  ·  Ctrl/Cmd+LMB copy  ·  Del erase  ·  Esc clear")
    end
  end
end

function render_seq_top_toolbar()
  local btn_h = 26
  local grids = {
    { "1/4", 1.0, "seq_grid_4" },
    { "1/8", 0.5, "seq_grid_8" },
    { "1/16", 0.25, "seq_grid_16" },
    { "1/32", 0.125, "seq_grid_32" },
    { "1/8T", 1.0 / 3.0, "seq_grid_8t" },
    { "1/16T", 1.0 / 6.0, "seq_grid_16t" },
  }

  local function toolbar_button(id, label, opts, tooltip)
    opts = opts or {}
    opts.compact = true
    local clicked = draw_ui_button(id, label, nil, btn_h, opts)
    if tooltip and r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, tooltip)
    end
    return clicked
  end

  local function toolbar_divider()
    if not imgui_same_line_if_fits(7, 8) then
      return
    end
    local x, y0 = r.ImGui_GetCursorScreenPos(ctx)
    r.ImGui_Dummy(ctx, 1, btn_h)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    r.ImGui_DrawList_AddLine(dl, x, y0 + 5, x, y0 + btn_h - 5, UI_THEME.border, 1.0)
  end

  for i, grid in ipairs(grids) do
    if i > 1 then
      imgui_same_line_if_fits(calc_compact_chip_width(grid[1]), 3)
    end
    local active = math.abs((state.seq_grid_qn or 0.25) - grid[2]) < 0.0001
    if toolbar_button(grid[3], grid[1], { style = active and "accent" or "default", selected = active }, "Grid " .. grid[1]) then
      state.seq_grid_qn = grid[2]
      save_config()
    end
  end

  toolbar_divider()
  local focus_region = get_selected_seq_region()
  if state.seq_region_rename and focus_region and state.seq_region_rename.region_id ~= focus_region.id then
    seq_commit_region_rename()
  end
  local renaming = state.seq_region_rename
    and focus_region
    and state.seq_region_rename.region_id == focus_region.id
  local region_name = get_seq_region_display_name(focus_region)
  local region_chip = seq_truncate_text_to_width(region_name, 96)
  state.seq_gen_style = normalize_seq_gen_style(state.seq_gen_style)
  local pattern_label = get_seq_region_pattern_label(focus_region)
  local groove_key = get_seq_region_groove(focus_region)
  local groove_active = groove_key ~= "off"
  local groove_label = get_seq_groove_chip_label(groove_key)
  local inner_h = btn_h - 6
  local inner_gap = 3
  local pocket_pad = 4
  local name_w = calc_compact_chip_width(region_chip) + 6
  if renaming then
    local typed = state.seq_region_rename.text or ""
    local measure = typed ~= "" and typed or "Intro 1"
    local tw = select(1, r.ImGui_CalcTextSize(ctx, measure)) or 0
    name_w = math.max(150, tw + 28)
  end
  local pat_w = calc_compact_chip_width(pattern_label)
  local grv_w = calc_compact_chip_width(groove_label)
  local pocket_w = pocket_pad + pat_w + inner_gap + grv_w + pocket_pad
  local group_w = name_w + pocket_w
  imgui_same_line_if_fits(group_w, 8)
  do
    local gx, gy = r.ImGui_GetCursorScreenPos(ctx)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local pool = seq_region_pool_color(focus_region and focus_region.pool_id, 255)
    local cr, cg, cb = extract_rgb_rrgbbaa(pool)
    local function tone(t, a)
      return build_color_rrgbbaa(
        math.max(0, math.min(255, math.floor(cr * t))),
        math.max(0, math.min(255, math.floor(cg * t))),
        math.max(0, math.min(255, math.floor(cb * t))),
        a or 255
      )
    end
    local rounding = 8.0
    r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + group_w, gy + btn_h, tone(0.16), rounding)
    r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + name_w + rounding, gy + btn_h, tone(0.38), rounding)
    r.ImGui_DrawList_AddRectFilled(dl, gx + name_w, gy, gx + name_w + rounding, gy + btn_h, tone(0.16), 0)
    r.ImGui_DrawList_AddRect(dl, gx + 0.5, gy + 0.5, gx + group_w - 0.5, gy + btn_h - 0.5, tone(0.95), rounding, 0, 1.6)
    r.ImGui_DrawList_AddLine(dl, gx + name_w, gy + 4, gx + name_w, gy + btn_h - 4, tone(0.75, 180), 1.0)

    if renaming then
      if r.ImGui_SetNextFrameWantCaptureKeyboard then
        r.ImGui_SetNextFrameWantCaptureKeyboard(ctx, true)
      end
      r.ImGui_SetCursorScreenPos(ctx, gx + 4, gy + 2)
      r.ImGui_SetNextItemWidth(ctx, name_w - 8)
      local first_focus = state.seq_region_rename.focus
      if first_focus then
        if r.ImGui_SetKeyboardFocusHere then
          r.ImGui_SetKeyboardFocusHere(ctx)
        end
        state.seq_region_rename.focus = false
      end
      local input_flags = 0
      if first_focus and r.ImGui_InputTextFlags_AutoSelectAll then
        input_flags = input_flags | r.ImGui_InputTextFlags_AutoSelectAll()
      end
      local input_value = state.seq_region_rename.typed_prefix
      if input_value == nil then
        input_value = state.seq_region_rename.text or ""
      end
      local completing = state.seq_region_rename.completed == true
      local style_cols, style_vars = 0, 0
      if r.ImGui_Col_FrameBg then
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x00000066)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x00000088)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x00000099)
        r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Text(), completing and 0xFFFFFF00 or 0xFFFFFFFF)
        style_cols = 4
      end
      if r.ImGui_StyleVar_FramePadding then
        r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 4, 2)
        style_vars = style_vars + 1
      end
      local _, txt = r.ImGui_InputText(ctx, "##seq_region_rename", input_value, input_flags)
      local edit_x, edit_y = r.ImGui_GetItemRectMin(ctx)
      local edit_x1, edit_y1 = r.ImGui_GetItemRectMax(ctx)
      local edit_hovered = r.ImGui_IsItemHovered(ctx)
      if style_vars > 0 then
        r.ImGui_PopStyleVar(ctx, style_vars)
      end
      if style_cols > 0 then
        r.ImGui_PopStyleColor(ctx, style_cols)
      end
      local arrow_down = r.ImGui_IsKeyPressed and r.ImGui_Key_DownArrow
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_DownArrow(), false)
      local arrow_up = r.ImGui_IsKeyPressed and r.ImGui_Key_UpArrow
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_UpArrow(), false)
      if arrow_down or arrow_up then
        seq_region_rename_move_candidate(state.seq_region_rename, focus_region, arrow_down and 1 or -1)
      elseif type(txt) == "string" then
        if first_focus and txt == (state.seq_region_rename.orig or "") then
          state.seq_region_rename.text = txt
        else
          seq_apply_region_rename_autocomplete(state.seq_region_rename, txt, focus_region)
        end
      end
      if state.seq_region_rename and state.seq_region_rename.completed then
        seq_draw_region_rename_completion(state.seq_region_rename, edit_x, edit_y, edit_x1, edit_y1)
        if r.ImGui_IsKeyPressed and r.ImGui_Key_Tab
            and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Tab(), false) then
          state.seq_region_rename.typed_prefix = state.seq_region_rename.text
          state.seq_region_rename.completed = false
          state.seq_region_rename.select_from = 0
        end
      end
      local edit_w = (edit_x1 or (gx + name_w)) - (edit_x or gx)
      local enter = r.ImGui_IsKeyPressed and r.ImGui_Key_Enter
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Enter(), false)
      local escape = r.ImGui_IsKeyPressed and r.ImGui_Key_Escape
        and r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_Escape(), false)
      local click_outside = r.ImGui_IsMouseClicked and r.ImGui_IsMouseClicked(ctx, 0)
        and not edit_hovered
        and not (state.seq_region_rename and state.seq_region_rename.over_suggest)
      if escape then
        seq_cancel_region_rename()
      elseif enter then
        seq_commit_region_rename()
      elseif click_outside then
        seq_commit_region_rename()
      end
      if state.seq_region_rename then
        render_seq_region_name_suggest_popup(edit_x or gx, edit_y or gy, edit_w)
      end
    else
      r.ImGui_InvisibleButton(ctx, "##ui_seq_focus_region_chip", name_w, btn_h)
      local cap_hovered = r.ImGui_IsItemHovered(ctx)
      local cap_clicked = r.ImGui_IsItemClicked(ctx, 0)
      local cap_dbl = cap_hovered and r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)
      if cap_hovered then
        r.ImGui_DrawList_AddRectFilled(dl, gx, gy, gx + name_w + rounding, gy + btn_h, tone(0.50, 70), rounding)
        r.ImGui_SetTooltip(ctx, "Focused region — pattern and groove apply here only.\nClick to zoom. Double-click to rename.")
      end
      local tw, th = r.ImGui_CalcTextSize(ctx, region_chip)
      r.ImGui_DrawList_AddText(dl, gx + (name_w - tw) * 0.5, gy + (btn_h - th) * 0.5, 0xFFFFFFFF, region_chip)
      if cap_dbl then
        seq_begin_region_rename(focus_region)
      elseif cap_clicked then
        seq_zoom_to_region(focus_region)
      end
    end

    local inner_y = gy + (btn_h - inner_h) * 0.5
    r.ImGui_SetCursorScreenPos(ctx, gx + name_w + pocket_pad, inner_y)
    if draw_ui_button("seq_pattern_popup_open", pattern_label, nil, inner_h, {
      compact = true,
      style = "primary",
      selected = state.seq_pattern_window_open,
    }) then
      open_seq_pattern_popup()
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Pattern for " .. region_name)
    end
    r.ImGui_SameLine(ctx, 0, inner_gap)
    if draw_ui_button("seq_groove_popup_open", groove_label, nil, inner_h, {
      compact = true,
      style = "primary",
      selected = groove_active,
    }) then
      r.ImGui_OpenPopup(ctx, "seq_groove_popup")
    end
    if r.ImGui_IsItemHovered(ctx) then
      r.ImGui_SetTooltip(ctx, "Groove for " .. region_name .. " — this region only")
    end

    r.ImGui_SetCursorScreenPos(ctx, gx + group_w, gy)
    r.ImGui_Dummy(ctx, 1, btn_h)
  end
  render_seq_groove_popup()

  toolbar_divider()
  imgui_same_line_if_fits(calc_compact_chip_width("Kit"), 4)
  if toolbar_button("seq_kit_random_popup_open", "Kit", { style = "primary" }, "Randomize Kit") then
    open_seq_kit_random_popup()
  end
  render_seq_kit_random_popup()

  imgui_same_line_if_fits(calc_compact_chip_width("Sync"), 4)
  local sync_on = state.seq_follow_arrange == true
  if toolbar_button("seq_sync", "Sync", { style = sync_on and "accent" or "default", selected = sync_on }, "Sync to Arrange") then
    state.seq_follow_arrange = not sync_on
    seq_timeline_scroll_stop()
    if state.seq_follow_arrange then
      local arrange_start, arrange_end = get_arrange_view_range()
      local arrange_start_qn = time_to_qn(arrange_start) or 0.0
      local arrange_end_qn = time_to_qn(arrange_end) or (arrange_start_qn + (state.seq_grid_qn or 0.25) * 16.0)
      state.seq_view_start_qn = arrange_start_qn
      state.seq_view_span_qn = math.max(state.seq_grid_qn or 0.25, arrange_end_qn - arrange_start_qn)
    end
    save_config()
  end

  imgui_same_line_if_fits(calc_compact_chip_width("Peek"), 4)
  local peek_on = state.seq_follow_hovered_item == true
  if toolbar_button("seq_peek_item", "Peek", { style = peek_on and "accent" or "default", selected = peek_on }, "Follow hovered notes in the arrange") then
    state.seq_follow_hovered_item = not peek_on
    save_config()
  end

  toolbar_divider()
  imgui_same_line_if_fits(calc_seq_note_edit_mode_btn_width(), 6)
  render_seq_note_edit_mode_bar(btn_h)
end

function seq_param_value_from_y(def, y, y0, y1, step_qn)
  if def.boolean or seq_is_lock_def(def) then
    return def.max or 1.0
  end
  local t = 1.0 - ((y - y0) / math.max(1.0, y1 - y0))
  t = math.max(0.0, math.min(1.0, t))
  local min_v = def.min
  local max_v = def.max
  if def.key == "length_qn" then
    min_v = math.min(step_qn or state.seq_grid_qn or 0.25, def.min)
    max_v = math.max(step_qn or state.seq_grid_qn or 0.25, def.max)
  elseif def.key == "stretch" then
    -- Log scale so 1.0x sits in the middle (0.25x .. 4.0x).
    return SEQ_STRETCH_MIN * ((SEQ_STRETCH_MAX / SEQ_STRETCH_MIN) ^ t)
  end
  return min_v + (max_v - min_v) * t
end

function seq_param_y_from_value(def, value, y0, y1, step_qn)
  local min_v = def.min
  local max_v = def.max
  if def.key == "length_qn" then
    min_v = math.min(step_qn or state.seq_grid_qn or 0.25, def.min)
    max_v = math.max(step_qn or state.seq_grid_qn or 0.25, def.max)
  elseif def.key == "stretch" then
    local v = tonumber(value) or 1.0
    if v < SEQ_STRETCH_MIN then v = SEQ_STRETCH_MIN end
    if v > SEQ_STRETCH_MAX then v = SEQ_STRETCH_MAX end
    local t = math.log(v / SEQ_STRETCH_MIN) / math.log(SEQ_STRETCH_MAX / SEQ_STRETCH_MIN)
    t = math.max(0.0, math.min(1.0, t))
    return y1 - t * (y1 - y0)
  end
  local t = ((value or def.default) - min_v) / math.max(0.000001, max_v - min_v)
  t = math.max(0.0, math.min(1.0, t))
  return y1 - t * (y1 - y0)
end

function seq_get_project_first_measure()
  -- Project Settings → "Project start measure". TimeMap measure 0 is always
  -- the first bar; the displayed number can be 1 (default), 0, -1, etc.
  if r.format_timestr_pos and r.TimeMap_GetMeasureInfo then
    local meas_time, qn_start = r.TimeMap_GetMeasureInfo(0, 0)
    if type(qn_start) == "number" then
      local nudged = qn_to_time(qn_start + 0.0001)
      if type(nudged) == "number" then
        meas_time = nudged
      end
    end
    if type(meas_time) == "number" then
      local formatted = r.format_timestr_pos(meas_time, "", 2)
      local n = tonumber((formatted or ""):match("^%s*(-?%d+)"))
      if n then
        return n
      end
    end
  end
  -- SWS: projmeasoffs is 0 when the first displayed measure is 1.
  if r.SNM_GetIntConfigVarEx then
    return (r.SNM_GetIntConfigVarEx(0, "projmeasoffs", 0) or 0) + 1
  end
  if r.SNM_GetIntConfigVar then
    return (r.SNM_GetIntConfigVar("projmeasoffs", 0) or 0) + 1
  end
  return 1
end

function collect_measure_guides_qn(start_qn, end_qn, max_guides)
  local guides = {}
  if not r.TimeMap_GetMeasureInfo or not r.TimeMap2_timeToBeats then
    return guides
  end

  local start_time = qn_to_time(start_qn)
  if not start_time then
    return guides
  end

  max_guides = max_guides or 1024
  local _, start_measure = r.TimeMap2_timeToBeats(0, start_time)
  if start_measure == nil then
    return guides
  end

  local first_measure = seq_get_project_first_measure()
  local measure = math.max(0, start_measure)
  local guard = 0
  while guard < max_guides do
    local meas_time, qn_start, qn_end, ts_num, ts_den = r.TimeMap_GetMeasureInfo(0, measure)
    if not meas_time or not qn_start then
      break
    end
    if qn_start > end_qn + 0.000001 then
      break
    end

    local out_num = (type(ts_num) == "number" and ts_num > 0) and ts_num or 4
    local out_den = (type(ts_den) == "number" and ts_den > 0) and ts_den or 4
    local out_qn_end = qn_end
    if type(out_qn_end) ~= "number" or out_qn_end <= qn_start then
      out_qn_end = qn_start + out_num * (4.0 / out_den)
    end

    if out_qn_end >= start_qn - 0.000001 then
      guides[#guides + 1] = {
        measure = measure,
        display_measure = measure + first_measure,
        qn_start = qn_start,
        qn_end = out_qn_end,
        time = meas_time,
        ts_num = out_num,
        ts_den = out_den,
      }
    end

    measure = measure + 1
    guard = guard + 1
  end

  return guides
end

function find_seq_param_lane_bounds(row_positions, track_id, param_key)
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "param" and row.slot and row.slot.id == track_id and row.param and row.param.key == param_key then
      return row_pos.y0 + 2, row_pos.y1 - 2, row_pos
    end
  end
  return nil, nil, nil
end

function format_seq_param_value(def, value)
  if value == nil then
    value = def.default
  end
  if def.boolean or seq_is_lock_def(def) then
    local on = value == true or (tonumber(value) or 0) >= 0.5
    return string.format("%s %s", def.label, on and "On" or "Off")
  end
  if def.key == "start" then
    return string.format("%s %.0f%%", def.label, (tonumber(value) or 0.0) * 100.0)
  end
  if def.key == "stretch" then
    return string.format("%s %.2fx", def.label, tonumber(value) or 1.0)
  end
  return string.format("%s %s", def.label, string.format(def.fmt, value))
end

function draw_seq_stutter_count_badge(dl, ctx, x0, y0, x1, y1, count, accent)
  count = math.max(1, math.floor((count or 1) + 0.5))
  local text = tostring(count)
  local text_size = { r.ImGui_CalcTextSize(ctx, text) }
  local text_w = text_size[1] or 0
  local text_h = text_size[2] or 0
  local tx = (x0 + x1) * 0.5 - text_w * 0.5
  local ty = (y0 + y1) * 0.5 - text_h * 0.5
  r.ImGui_DrawList_AddRectFilled(dl, tx - 3, ty - 1, tx + text_w + 3, ty + text_h + 1, 0x000000BB, 2.0)
  r.ImGui_DrawList_AddText(dl, tx + 1, ty + 1, 0x000000AA, text)
  r.ImGui_DrawList_AddText(dl, tx, ty, seq_lane_color_with_alpha(accent or 0xC9A8FFFF, 255), text)
end

function draw_seq_stutter_lane_cell(dl, ctx, cx0, cx1, lane_top, lane_bot, count, accent)
  count = math.max(1, math.min(SEQ_STUTTER_MAX, math.floor((count or 1) + 0.5)))
  local ar, ag, ab = extract_rgb_rrgbbaa(accent or 0xC9A8FFFF)
  local pad_x = 2.0
  local fill_x0 = cx0 + pad_x
  local fill_x1 = cx1 - pad_x
  if fill_x1 <= fill_x0 then
    fill_x1 = fill_x0 + 1.0
  end

  local lane_h = math.max(4.0, lane_bot - lane_top)
  local gap = 1.0
  local box_h = math.max(2.0, (lane_h - gap * (count - 1)) / count)
  local stack_h = count * box_h + math.max(0, count - 1) * gap
  local stack_y0 = lane_bot - stack_h

  for i = 1, count do
    local by1 = lane_bot - (i - 1) * (box_h + gap)
    local by0 = by1 - box_h
    if by0 < stack_y0 then
      by0 = stack_y0
    end
    local fade = 50 + math.floor((i / count) * 120)
    local edge_fade = math.min(255, fade + 40)
    local fill_col = build_color_rrgbbaa(ar, ag, ab, fade)
    local edge_col = build_color_rrgbbaa(ar, ag, ab, edge_fade)
    r.ImGui_DrawList_AddRectFilled(dl, fill_x0, by0, fill_x1, by1, fill_col, 1.0)
    r.ImGui_DrawList_AddRect(dl, fill_x0, by0, fill_x1, by1, edge_col, 1.0, 0, 1.0)
  end

  draw_seq_stutter_count_badge(dl, ctx, fill_x0, lane_top, fill_x1, lane_bot, count, accent)
end

function seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  return math.max(0, math.min(step_count - 1, math.floor((qn - start_qn) / step_qn + 1e-9)))
end

function seq_param_value_for_drag(def, value, step_qn)
  if def.key == "length_qn" then
    return snap_seq_length_qn(value, step_qn)
  end
  if def.key == "stutter" then
    return math.max(1, math.floor((value or 1) + 0.5))
  end
  if def.key == "stretch" then
    value = tonumber(value) or 1.0
    if value < SEQ_STRETCH_MIN then return SEQ_STRETCH_MIN end
    if value > SEQ_STRETCH_MAX then return SEQ_STRETCH_MAX end
    return value
  end
  if def.key == "start" then
    value = tonumber(value) or 0.0
    if value < 0.0 then return 0.0 end
    if value > SEQ_START_MAX then return SEQ_START_MAX end
    return value
  end
  return value
end

function apply_seq_note_lane_drag(drag, region, step_qn, start_qn, step_count, mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end

  local slot = nil
  for _, track_slot in ipairs(state.seq_tracks) do
    if track_slot.id == drag.track_id then
      slot = track_slot
      break
    end
  end
  if not slot then
    return false
  end

  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.start_col, drag.end_col)
  local col_max = math.max(drag.start_col, drag.end_col)
  local prev_min = drag.applied_min or drag.start_col
  local prev_max = drag.applied_max or drag.start_col
  if col_min >= prev_min and col_max <= prev_max then
    return false
  end

  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local changed = false

  local function apply_col(col)
    local qn = start_qn + col * step_qn
    if qn < region_start or qn >= region_end then
      return
    end
    if drag.mode == "erase" then
      if seq_erase_notes_starting_in_span(region, slot, qn, qn + step_qn, {
        defer_save = true,
        defer_arrange = true,
      }) then
        changed = true
      end
      return
    end
    local step_idx = math.floor(((qn - region_start) / step_qn) + 1e-9)
    local step_key = tostring(step_idx)
    if toggle_seq_note(region, slot, step_key, step_idx * step_qn, drag.mode, {
      defer_save = true,
      defer_arrange = true,
    }) then
      changed = true
    end
  end

  -- Highest step first so gap-to-next-hit lengths are correct on first insert.
  if r.PreventUIRefresh then r.PreventUIRefresh(1) end
  if col_min < prev_min then
    for col = prev_min - 1, col_min, -1 do
      apply_col(col)
    end
  end
  if col_max > prev_max then
    for col = col_max, prev_max + 1, -1 do
      apply_col(col)
    end
  end
  if r.PreventUIRefresh then r.PreventUIRefresh(-1) end
  if changed then
    r.UpdateArrange()
  end

  drag.applied_min = col_min
  drag.applied_max = col_max
  return changed
end

function apply_seq_note_copy_drag(drag, step_qn, start_qn, step_count, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions)
  if not drag or not drag.src_note then
    return false
  end
  if drag.mode ~= "copy" and drag.mode ~= "move" then
    return false
  end
  step_qn = step_qn or state.seq_grid_qn or 0.25
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  local dest_abs
  if drag.mode == "copy" and drag.snap ~= false then
    dest_abs = math.floor((mouse_qn / step_qn) + 1e-9) * step_qn
  else
    dest_abs = (drag.src_abs_qn or 0.0) + (mouse_qn - (drag.grab_qn or mouse_qn))
    dest_abs = seq_quantize_free_qn(dest_abs)
  end
  if dest_abs < 0 then
    dest_abs = 0
  end
  local dest_track_id = seq_track_id_at_y(row_positions, my) or drag.track_id
  local dest_region = seq_region_at_qn(dest_abs)
  local dest_slot = seq_find_slot_by_id(dest_track_id)

  local function restore()
    if drag.patterns_backup then
      state.seq_patterns = clone_table_deep(drag.patterns_backup)
    end
  end

  local origin_qn = (drag.mode == "copy") and (drag.src_snap_qn or drag.src_abs_qn or 0) or (drag.src_abs_qn or 0)
  local same = dest_region and dest_region.id == drag.region_id
    and dest_track_id == drag.track_id
    and math.abs(dest_abs - origin_qn) < 1e-6

  if not dest_region or not dest_slot or (same and not drag.place_new) then
    if drag.dirty then
      restore()
      drag.dirty = false
      drag.dest_track_id = nil
      drag.dest_region_id = nil
      drag.dest_step_key = nil
    end
    drag.last_dest_qn = dest_abs
    drag.last_dest_track = dest_track_id
    drag.last_dest_region = dest_region and dest_region.id or nil
    return false
  end

  if drag.last_dest_qn == dest_abs and drag.last_dest_track == dest_track_id
     and drag.last_dest_region == dest_region.id then
    return drag.dirty and true or false
  end

  restore()
  local rel = dest_abs - (dest_region.start_qn or 0.0)
  local region_len = get_seq_region_length_qn(dest_region)
  if rel < -1e-9 then
    rel = 0.0
    dest_abs = dest_region.start_qn or 0.0
  elseif rel >= region_len - 1e-9 then
    rel = math.max(0.0, seq_quantize_free_qn(region_len - (1.0 / 192.0)))
    dest_abs = (dest_region.start_qn or 0.0) + rel
  end

  if drag.mode == "move" and not drag.place_new then
    local src_region = get_seq_region_by_id(drag.region_id)
    delete_seq_note(src_region, drag.track_id, drag.src_step_key)
  end

  local note = clone_table_deep(drag.src_note)
  note.qn_offset = rel
  note.step = math.floor((rel / step_qn) + 1e-9)
  seq_keep_copied_note_over_region(note, drag.src_length_qn, dest_region, rel)
  local n_start, n_end = seq_note_qn_range(note, "0", step_qn)
  local span_end = (n_end and n_end > n_start + 1e-9) and n_end or (rel + step_qn)
  local keep_key = nil
  if drag.mode == "copy" and dest_region.id == drag.region_id and dest_track_id == drag.track_id then
    keep_key = drag.src_step_key
  end
  seq_delete_notes_overlapping_span(
    dest_region, dest_slot, rel, span_end, keep_key, step_qn, {
      defer_arrange = true,
      -- Keep later hits; item lengths crop to the next start instead of deleting.
      same_start = true,
    }
  )
  local key = seq_alloc_note_key(dest_region, dest_slot.id, rel)
  set_seq_note(dest_region, dest_slot.id, key, note)
  state.selected_seq_note = { region_id = dest_region.id, track_id = dest_slot.id, step_key = key }
  drag.dest_region_id = dest_region.id
  drag.dest_track_id = dest_slot.id
  drag.dest_step_key = key
  drag.last_dest_qn = dest_abs
  drag.last_dest_track = dest_track_id
  drag.last_dest_region = dest_region.id
  drag.dirty = true
  return true
end

function apply_seq_stutter_lane_drag(drag, region, step_qn, start_qn, step_count, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end
  local slot = seq_find_slot_by_id(drag.track_id)
  if not slot then
    return false
  end

  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local col_min = math.min(drag.start_col, drag.end_col)
  local col_max = math.max(drag.start_col, drag.end_col)
  local region_start = region.start_qn or 0.0
  local region_end = region_start + get_seq_region_length_qn(region)
  local abs_start = start_qn + col_min * step_qn
  local abs_end = start_qn + (col_max + 1) * step_qn
  if abs_start < region_start then abs_start = region_start end
  if abs_end > region_end then abs_end = region_end end
  if abs_end - abs_start < step_qn * 0.5 then
    abs_end = math.min(region_end, abs_start + step_qn)
    if abs_end - abs_start < step_qn * 0.5 then
      abs_start = math.max(region_start, abs_end - step_qn)
    end
  end
  local length_qn = snap_seq_length_qn(abs_end - abs_start, step_qn)
  if length_qn <= 0 then
    return false
  end
  local qn_offset = abs_start - region_start
  if qn_offset < -1e-9 or qn_offset >= (region_end - region_start) - 1e-9 then
    return false
  end
  local count = seq_stutter_count_from_drag_dy(drag.origin_y, my)

  if not drag.step_key then
    local existing_key, existing = seq_find_note_key_at_qn(region, slot.id, qn_offset)
    if existing then
      drag.step_key = existing_key
    else
      local key = seq_alloc_note_key(region, slot.id, qn_offset)
      local note = make_default_seq_note(slot, key, qn_offset)
      if not note then
        log("Sequencer slot has no assigned sample")
        return false
      end
      set_seq_note(region, slot.id, key, note)
      register_seq_note_anim(region.id, slot.id, key, note, "add")
      drag.step_key = key
    end
  end

  local note = get_seq_note(region, slot.id, drag.step_key)
  if not note then
    return false
  end

  local changed = not drag.initialized
  if math.abs((note.qn_offset or 0.0) - qn_offset) > 1e-9 then
    note.qn_offset = qn_offset
    note.step = math.floor((qn_offset / step_qn) + 1e-9)
    changed = true
  end
  if math.abs((note.length_qn or 0.0) - length_qn) > 1e-9 then
    note.length_qn = length_qn
    changed = true
  end
  if note.stutter ~= count then
    note.stutter = count
    seq_prune_stutter_hits(note)
    changed = true
  end

  drag.length_qn = length_qn
  drag.stutter = count
  drag.qn_offset = qn_offset

  if changed then
    seq_delete_notes_overlapping_span(
      region, slot, qn_offset, qn_offset + length_qn, drag.step_key, step_qn, { defer_arrange = true }
    )
    state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = drag.step_key }
    drag.initialized = true
    drag.dirty = true
    return true
  end
  return false
end

function seq_note_decay_max_qn(region, slot, note, step_key, step_qn)
  local resolved_path, resolved_sample = resolve_seq_note_sample(note, slot)
  local cap = seq_sample_length_qn(resolved_path, resolved_sample)
  if cap and cap > 0 then
    return cap
  end
  local region_len = region and get_seq_region_length_qn(region) or 8.0
  return math.max(step_qn or 0.25, region_len)
end

function seq_note_current_decay_length_qn(region, slot, note, step_key, step_qn)
  if seq_stutter_count(note) > 1 then
    return seq_stutter_span_qn(note, step_qn) or step_qn
  end
  local _, resolved_sample = resolve_seq_note_sample(note, slot)
  local pattern = region and get_seq_pattern(region.pattern_id, false) or nil
  return seq_note_draw_length_qn(region, pattern, slot, slot and slot.id, step_key, note, resolved_sample, step_qn)
end

function apply_seq_decay_drag(drag, region, step_qn, mx, my, timeline_x0, timeline_w, view_start_qn, qn_span)
  if not drag or not region then
    return false
  end
  local slot = seq_find_slot_by_id(drag.track_id)
  local note = get_seq_note(region, drag.track_id, drag.step_key)
  if not slot or not note then
    return false
  end
  local note_start_qn = drag.note_start_qn
  if not note_start_qn then
    note_start_qn = seq_note_abs_qn(region, note, drag.step_key, step_qn) + (note.offset_qn or 0.0)
    drag.note_start_qn = note_start_qn
  end
  local min_qn = (step_qn or 0.25) * 0.25
  local max_qn = drag.max_length_qn or seq_note_decay_max_qn(region, slot, note, drag.step_key, step_qn)
  drag.max_length_qn = max_qn
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  local changed = false
  local dx = mx - (drag.origin_x or mx)
  local dy = (drag.origin_y or my) - my

  if drag.handle == "end" then
    local length_qn = mouse_qn - note_start_qn
    if not is_shift_down() then
      length_qn = snap_seq_length_qn(length_qn, step_qn)
    else
      length_qn = math.max(min_qn, length_qn)
    end
    if length_qn < min_qn then length_qn = min_qn end
    if length_qn > max_qn then length_qn = max_qn end
    if seq_stutter_count(note) > 1 then
      if math.abs((note.length_qn or 0.0) - length_qn) > 1e-9 then
        note.length_qn = length_qn
        changed = true
        local qn_offset = seq_note_qn_offset(note, drag.step_key, step_qn)
        seq_delete_notes_overlapping_span(
          region, slot, qn_offset, qn_offset + length_qn, drag.step_key, step_qn, { defer_arrange = true }
        )
      end
    else
      if math.abs((tonumber(note.decay_qn) or 0.0) - length_qn) > 1e-9 then
        note.decay_qn = length_qn
        changed = true
      end
    end
    seq_clamp_note_fades(note, length_qn)
    drag.length_qn = length_qn
  elseif drag.handle == "curve_in" or drag.handle == "curve_out" then
    local which = (drag.handle == "curve_in") and "in" or "out"
    local base_curve = drag.origin_curve or 0.0
    local curve = seq_fade_curve_clamp(base_curve + dy / SEQ_FADE_CURVE_PX)
    if seq_note_set_fade_curve(note, which, curve) then
      changed = true
    end
    drag.fade_curve = seq_note_fade_curve(note, which)
    drag.fade_qn = seq_note_fade_qn(note, which)
    drag.fade_shape = seq_note_fade_shape(note, which)
  elseif drag.handle == "fade_out" or drag.handle == "fade_in" then
    local length_qn = seq_note_current_decay_length_qn(region, slot, note, drag.step_key, step_qn)
    local which = (drag.handle == "fade_in") and "in" or "out"
    if not drag.axis then
      if math.abs(dx) >= SEQ_FADE_AXIS_PX or math.abs(dy) >= SEQ_FADE_AXIS_PX then
        drag.axis = (math.abs(dy) > math.abs(dx)) and "type" or "length"
      end
    end
    if drag.axis == "type" and (drag.origin_fade_qn or 0) < 1e-6 then
      drag.axis = "length"
    end
    if drag.axis ~= "type" then
      local fade_qn
      if which == "in" then
        fade_qn = mouse_qn - note_start_qn
      else
        fade_qn = (note_start_qn + length_qn) - mouse_qn
      end
      if fade_qn < 0 then fade_qn = 0 end
      fade_qn = math.min(fade_qn, math.max(0.0, length_qn - min_qn * 0.1))
      if seq_note_set_fade(note, which, fade_qn, drag.origin_shape) then
        changed = true
      end
      seq_push_note_fades(note, length_qn, which)
    end
    if drag.axis == "type" then
      local base_shape = drag.origin_shape
      if base_shape == nil then
        base_shape = 1
      end
      local shape = seq_fade_shape_clamp(base_shape + math.floor(dy / SEQ_FADE_SHAPE_PX + 0.5))
      local fade_qn = seq_note_fade_qn(note, which)
      if fade_qn < 1e-6 then
        fade_qn = drag.origin_fade_qn or 0.0
      end
      if fade_qn > 1e-6 and seq_note_set_fade(note, which, fade_qn, shape) then
        changed = true
      end
    end
    drag.fade_qn = seq_note_fade_qn(note, which)
    drag.fade_shape = seq_note_fade_shape(note, which)
    drag.fade_curve = seq_note_fade_curve(note, which)
    drag.length_qn = length_qn
  end

  if changed then
    state.selected_seq_note = { region_id = region.id, track_id = slot.id, step_key = drag.step_key }
    drag.dirty = true
  end
  return changed
end

function apply_seq_param_lane_drag(drag, def, lane_y0, lane_y1, mx, my, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells)
  drag.end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
  local mouse_col = drag.end_col
  local current_value = seq_param_value_for_drag(def, seq_param_value_from_y(def, my, lane_y0, lane_y1, step_qn), step_qn)
  local col_min = math.min(drag.col, drag.end_col)
  local col_max = math.max(drag.col, drag.end_col)
  local mouse_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
  if seq_is_lock_def(def) then
    local region = get_seq_region_by_id(drag.region_id)
    local changed = seq_apply_lock_range(region, drag.track_id, col_min, col_max, start_qn, step_qn, true, active_cells)
    return changed, 1.0, col_min, col_max, mouse_col
  end
  local changed = false

  local function apply_entry(entry, value, qn, all_hits, qn0, qn1)
    if seq_apply_param_to_note(entry.note, entry.abs_qn, def, value, qn, step_qn, false, all_hits, qn0, qn1) then
      changed = true
    end
  end

  if drag.ramp and drag.end_col ~= drag.col then
    local start_val = drag.start_value
    if start_val == nil then
      start_val = def.default
    end
    for col = col_min, col_max do
      local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
      if active then
        local t = (col - drag.col) / (drag.end_col - drag.col)
        local value = seq_param_value_for_drag(def, start_val + (current_value - start_val) * t, step_qn)
        local qn0 = start_qn + col * step_qn
        local qn1 = qn0 + step_qn
        seq_for_each_active_note(active, function(entry)
          apply_entry(entry, value, qn0 + step_qn * 0.5, true, qn0, qn1)
        end)
      end
    end
  elseif drag.unify then
    for col = col_min, col_max do
      local active = active_cells[drag.track_id] and active_cells[drag.track_id][col]
      if active then
        local qn0 = start_qn + col * step_qn
        local qn1 = qn0 + step_qn
        seq_for_each_active_note(active, function(entry)
          apply_entry(entry, current_value, qn0 + step_qn * 0.5, true, qn0, qn1)
        end)
      end
    end
  else
    local active = active_cells[drag.track_id] and active_cells[drag.track_id][mouse_col]
    if active then
      seq_for_each_active_note(active, function(entry)
        apply_entry(entry, current_value, mouse_qn, false)
      end)
      changed = true
      state.selected_seq_note = {
        region_id = drag.region_id,
        track_id = drag.track_id,
        step_key = active.key,
      }
      drag.hit_idx = seq_stutter_hit_index_at_qn(active.note, active.abs_qn, mouse_qn, step_qn)
    end
  end

  local highlight_col_min = mouse_col
  local highlight_col_max = mouse_col
  if drag.ramp or drag.unify then
    highlight_col_min = col_min
    highlight_col_max = col_max
  end

  return changed, current_value, highlight_col_min, highlight_col_max, mouse_col
end

function sample_start_path_key(sample)
  if not sample or not sample.path or sample.path == "" then
    return nil
  end
  return normalize_path(sample.path)
end

function get_sample_start_offset(sample)
  if not sample then
    return 0.0
  end
  local path = sample_start_path_key(sample)
  local session = path and state.seq_sample_start_session and state.seq_sample_start_session[path]
  local t = nil
  if type(session) == "number" then
    t = session
  else
    t = tonumber(sample.start_pos)
  end
  t = tonumber(t) or 0.0
  if t < 0 then
    t = 0
  end
  local dur = tonumber(sample.duration) or 0.0
  if dur > 0.002 and t > dur - 0.001 then
    t = dur - 0.001
  end
  return t
end

function sample_start_has_session(sample)
  local path = sample_start_path_key(sample)
  return path and state.seq_sample_start_session and type(state.seq_sample_start_session[path]) == "number"
end

function sample_start_is_saved(sample)
  return sample ~= nil and sample.start_pos ~= nil
end

function set_sample_start_offset_session(sample, t)
  local path = sample_start_path_key(sample)
  if not path then
    return 0.0
  end
  state.seq_sample_start_session = state.seq_sample_start_session or {}
  t = tonumber(t) or 0.0
  if t < 0 then
    t = 0
  end
  local dur = tonumber(sample.duration) or 0.0
  if dur > 0.002 and t > dur - 0.001 then
    t = dur - 0.001
  end
  state.seq_sample_start_session[path] = t
  return t
end

function seq_rebuild_after_sample_start_change(sample)
  if not sample then
    return
  end
  local path = sample_start_path_key(sample)
  if not path then
    return
  end
  if seq_mark_self_arrange_write then
    seq_mark_self_arrange_write()
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(1)
  end
  for _, slot in ipairs(state.seq_tracks or {}) do
    local match = slot.sample_path and normalize_path(slot.sample_path) == path
    if not match and slot.layers then
      local sides = { slot.layers.transient, slot.layers.sustain }
      for s = 1, #sides do
        local side = sides[s]
        local verts = side and side.verts
        if verts then
          for i = 1, #verts do
            local v = verts[i]
            if v and v.path and normalize_path(v.path) == path then
              match = true
              break
            end
          end
        end
        if match then
          break
        end
      end
    end
    if match then
      sync_seq_slot_all_regions(slot, { skip_arrange = true, force_rebuild = true })
    end
  end
  if r.PreventUIRefresh then
    r.PreventUIRefresh(-1)
  end
  if r.UpdateArrange then
    r.UpdateArrange()
  end
end

function save_sample_start_offset(sample)
  if not sample then
    return
  end
  sample.start_pos = get_sample_start_offset(sample)
  save_samples()
  seq_rebuild_after_sample_start_change(sample)
end

function clear_sample_start_offset_session(sample)
  local path = sample_start_path_key(sample)
  if path and state.seq_sample_start_session then
    state.seq_sample_start_session[path] = nil
  end
  seq_rebuild_after_sample_start_change(sample)
end

function clear_sample_start_offset_saved(sample)
  if not sample then
    return
  end
  sample.start_pos = nil
  save_samples()
  seq_rebuild_after_sample_start_change(sample)
end

function seq_reveal_sample_in_explorer(sample)
  local path = sample and sample.path
  if not path or path == "" then
    return
  end
  if r.CF_LocateInExplorer then
    r.CF_LocateInExplorer(path)
  elseif r.CF_ShellExecute then
    r.CF_ShellExecute(path)
  else
    os.execute("open -R " .. shell_escape(path))
  end
end

function draw_seq_header_sample_menu(sample)
  if not r.ImGui_BeginPopup or not r.ImGui_BeginPopup(ctx, "##seq_header_sample_menu") then
    return
  end
  local menu_sample = state.seq_header_menu_sample or sample
  if not menu_sample then
    r.ImGui_EndPopup(ctx)
    return
  end
  local start_t = get_sample_start_offset(menu_sample)
  local saved = sample_start_is_saved(menu_sample)
  local session = sample_start_has_session(menu_sample)
  local status = string.format("Start  %.3fs", start_t)
  if session then
    status = status .. "  (this project)"
  elseif saved then
    status = status .. "  (saved)"
  end
  if r.ImGui_TextDisabled then
    r.ImGui_TextDisabled(ctx, status)
  else
    r.ImGui_Text(ctx, status)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Save start to sample") then
    save_sample_start_offset(menu_sample)
  end
  if r.ImGui_MenuItem(ctx, "Reset start (this project)", nil, false, session) then
    clear_sample_start_offset_session(menu_sample)
  end
  if r.ImGui_MenuItem(ctx, "Clear saved start", nil, false, saved) then
    clear_sample_start_offset_saved(menu_sample)
  end
  local can_playhead = preview_sample_obj and preview_sample_obj.path == menu_sample.path
  if r.ImGui_MenuItem(ctx, "Set start to playhead", nil, false, can_playhead) then
    local pos = get_preview_position() or state.preview_position or 0.0
    set_sample_start_offset_session(menu_sample, pos)
    seq_rebuild_after_sample_start_change(menu_sample)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Preview from start") then
    preview_sample(menu_sample)
  end
  if r.ImGui_MenuItem(ctx, "Insert at cursor") then
    insert_sample_at_cursor(menu_sample)
  end
  r.ImGui_Separator(ctx)
  if r.ImGui_MenuItem(ctx, "Copy path") then
    if r.ImGui_SetClipboardText then
      r.ImGui_SetClipboardText(ctx, menu_sample.path or "")
    end
  end
  if r.ImGui_MenuItem(ctx, "Show in Finder") then
    seq_reveal_sample_in_explorer(menu_sample)
  end
  r.ImGui_EndPopup(ctx)
end

-- Mini preview waveform in the sequencer's "Track / Mix / Env" header corner.
-- Stays on the last hovered/previewed sample until a new note is hovered.
-- Drag the start marker to set a project-only start; "..." saves it globally.
function draw_seq_header_preview_waveform(dl, x, y, w, h, mx, my, left_down, left_clicked)
  local playing = preview_proc ~= nil and preview_sample_obj ~= nil
  local hover_sample = resolve_seq_hovered_grid_sample()
  if hover_sample then
    state.seq_header_wave_sample = hover_sample
  elseif playing or (state.preview_paused and preview_sample_obj) then
    state.seq_header_wave_sample = preview_sample_obj
  end
  local sample = hover_sample or state.seq_header_wave_sample or preview_sample_obj
  if not sample or w < 16 or h < 10 then
    r.ImGui_DrawList_AddText(dl, x + 4, y + math.max(0, (h - 14) * 0.5), 0xE8E8E8FF, "Track / Mix / Env")
    state.seq_preview_wave_scrub = nil
    state.seq_header_start_drag = nil
    return false
  end

  local is_live = playing and preview_sample_obj and preview_sample_obj.path == sample.path
  local hovered = mx >= x and mx <= x + w and my >= y and my <= y + h
  local bg = hovered and UI_THEME.surface_hvr or UI_THEME.bg_panel
  local edge = hovered and UI_THEME.border_hvr or UI_THEME.border
  r.ImGui_DrawList_AddRectFilled(dl, x, y, x + w, y + h, bg, 4.0)
  r.ImGui_DrawList_AddRect(dl, x, y, x + w, y + h, edge, 4.0, 0, 1.0)

  local inner_x = x + 3
  local inner_y = y + 2
  local inner_w = w - 6
  local inner_h = h - 4
  local peaks, duration = nil, nil
  if waveform_data and waveform_data.sample_path == sample.path
      and waveform_data.data and #waveform_data.data > 0 then
    peaks = seq_env_downsample_peaks(waveform_data.data, math.max(48, math.floor(inner_w)))
    duration = tonumber(waveform_data.duration) or tonumber(sample.duration)
  else
    peaks, duration = seq_env_get_wave_peaks(sample, math.floor(inner_w))
  end
  duration = duration or sample.duration or 0.0
  if peaks then
    seq_draw_env_waveform(dl, inner_x, inner_y, inner_w, inner_h, peaks, nil, nil, duration)
  end

  local start_t = get_sample_start_offset(sample)
  local start_x = inner_x
  if duration > 0 and inner_w > 0 then
    start_x = inner_x + (math.max(0.0, math.min(duration, start_t)) / duration) * inner_w
  end
  if start_t > 0.0005 and start_x > inner_x then
    r.ImGui_DrawList_AddRectFilled(dl, inner_x, inner_y, start_x, inner_y + inner_h, 0x00000099)
  end

  local start_col = sample_start_has_session(sample) and 0x5CE1FFFF
      or (sample_start_is_saved(sample) and 0x7CFFB0FF or 0x8EC8E8CC)
  r.ImGui_DrawList_AddLine(dl, start_x, y + 1, start_x, y + h - 1, start_col, 1.6)
  r.ImGui_DrawList_AddTriangleFilled(dl,
    start_x, y + h - 2,
    start_x - 5, y + h - 9,
    start_x + 5, y + h - 9,
    start_col)
  if start_t > 0.0005 then
    r.ImGui_DrawList_AddText(dl, math.min(start_x + 4, x + w - 48), y + h - 16, start_col,
      string.format("%.2fs", start_t))
  end

  if is_live then
    local pos = get_preview_position() or state.preview_position or 0.0
    if duration > 0 then
      local playhead_x = inner_x + (math.max(0.0, math.min(duration, pos)) / duration) * inner_w
      r.ImGui_DrawList_AddLine(dl, playhead_x, y + 1, playhead_x, y + h - 1, 0xFFFF88FF, 1.6)
      r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y + 3, 3.0, 0xFFFF88FF, 10)
    end
  end

  local btn_r = 7.5
  local btn_cx = x + w - 11
  local btn_cy = y + 11
  local over_btn = (mx - btn_cx) * (mx - btn_cx) + (my - btn_cy) * (my - btn_cy) <= (btn_r + 2) * (btn_r + 2)
  r.ImGui_DrawList_AddCircleFilled(dl, btn_cx, btn_cy, btn_r, over_btn and 0x4A5A74FF or 0x2C384CFF, 16)
  r.ImGui_DrawList_AddCircle(dl, btn_cx, btn_cy, btn_r, over_btn and 0xC8D4E8FF or 0x8090A8FF, 16, 1.2)
  local dots = "..."
  local dots_w, dots_h = 10, 12
  if r.ImGui_CalcTextSize then
    dots_w, dots_h = r.ImGui_CalcTextSize(ctx, dots)
  end
  r.ImGui_DrawList_AddText(dl, btn_cx - dots_w * 0.5, btn_cy - dots_h * 0.5 - 1, 0xF4F7FCFF, dots)

  local restore_x, restore_y = r.ImGui_GetCursorScreenPos(ctx)
  r.ImGui_SetCursorScreenPos(ctx, btn_cx - btn_r, btn_cy - btn_r)
  r.ImGui_InvisibleButton(ctx, "##seq_header_dots", btn_r * 2 + 2, btn_r * 2 + 2)
  if r.ImGui_IsItemHovered(ctx) then
    over_btn = true
  end
  local dots_clicked = r.ImGui_IsItemClicked and r.ImGui_IsItemClicked(ctx, 0)
  r.ImGui_SetCursorScreenPos(ctx, restore_x, restore_y)

  local name = sample.name or ""
  if name ~= "" then
    if r.ImGui_DrawList_PushClipRect then
      r.ImGui_DrawList_PushClipRect(dl, x + 4, y + 1, btn_cx - btn_r - 3, y + h - 1, true)
    end
    r.ImGui_DrawList_AddText(dl, x + 7, y + 4, 0x000000CC, name)
    r.ImGui_DrawList_AddText(dl, x + 6, y + 3, 0xF4F7FCFF, name)
    if r.ImGui_DrawList_PopClipRect then
      r.ImGui_DrawList_PopClipRect(dl)
    end
  end

  local start_slop = 8.0
  local over_start = hovered and math.abs(mx - start_x) <= start_slop
  if start_t <= 0.0005 then
    over_start = over_start or (hovered and mx <= inner_x + 12)
  end

  if (over_btn and left_clicked) or dots_clicked then
    state.seq_header_menu_sample = sample
    if r.ImGui_OpenPopup then
      r.ImGui_OpenPopup(ctx, "##seq_header_sample_menu")
    end
  end
  draw_seq_header_sample_menu(sample)

  if state.seq_header_start_drag and not left_down then
    state.seq_header_start_drag = nil
    seq_rebuild_after_sample_start_change(sample)
  end

  local consumed = over_btn or over_start or state.seq_header_start_drag or state.seq_preview_wave_scrub
  if over_btn then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif over_start or state.seq_header_start_drag then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    end
    if r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, string.format("Start  %.3fs", start_t))
    end
  elseif hovered then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    end
    if name ~= "" and r.ImGui_SetTooltip then
      r.ImGui_SetTooltip(ctx, name)
    end
  end

  local seek_t = 0.0
  if duration > 0 and inner_w > 0 then
    seek_t = (mx - inner_x) / inner_w
    if seek_t < 0 then seek_t = 0 elseif seek_t > 1 then seek_t = 1 end
    seek_t = seek_t * duration
  end

  if duration > 0 and not over_btn and ((left_clicked and over_start) or (state.seq_header_start_drag and left_down)) then
    state.seq_header_start_drag = true
    state.seq_preview_wave_scrub = nil
    start_t = set_sample_start_offset_session(sample, seek_t)
    if is_live then
      seek_preview(start_t)
    else
      preview_sample(sample, start_t)
    end
  elseif duration > 0 and not over_btn and not over_start and not state.seq_header_start_drag
      and ((left_clicked and hovered) or (state.seq_preview_wave_scrub and left_down)) then
    state.seq_preview_wave_scrub = true
    if is_live then
      seek_preview(seek_t)
    else
      preview_sample(sample, seek_t)
    end
  else
    state.seq_preview_wave_scrub = nil
  end

  return hovered or consumed
end

function render_sequencer_map()
  seq_sec_per_qn = nil
  seq_decay_clear_hits()
  local region = get_selected_seq_region()
  local avail_x, avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local width = math.max(720.0, avail_x)
  local lane_zoom = math.max(0.5, math.min(3.0, state.seq_lane_zoom or 1.0))
  state.seq_lane_zoom = lane_zoom
  local note_lane_h = 48.0 * lane_zoom
  local param_lane_h = 22.0 * lane_zoom
  local region_lane_h = 22.0
  local ruler_lane_h = 30.0
  local header_h = region_lane_h + ruler_lane_h
  local visual_rows = {}
  for _, slot in ipairs(state.seq_tracks) do
    seq_normalize_slot_mix(slot)
    visual_rows[#visual_rows + 1] = { type = "note", slot = slot, h = note_lane_h }
    if state.seq_expanded_tracks[tostring(slot.id)] then
      for _, def in ipairs(SEQ_PARAM_LANES) do
        if def.key ~= "length_qn" and def.key ~= "decay" and def.key ~= "locked" then
          visual_rows[#visual_rows + 1] = { type = "param", slot = slot, param = def, h = param_lane_h }
        end
      end
    end
  end
  if #visual_rows == 0 then
    visual_rows[#visual_rows + 1] = { type = "empty", h = note_lane_h }
  end
  local rows_h = 0.0
  for _, row in ipairs(visual_rows) do
    rows_h = rows_h + row.h
  end
  local add_track_row_h = 28.0
  local map_body_h = rows_h + add_track_row_h

  local child_flags = 0
  if r.ImGui_ChildFlags_Border then child_flags = r.ImGui_ChildFlags_Border end
  local no_scroll_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()
  if not r.ImGui_BeginChild(ctx, "sequencer_map_area", 0, math.max(0, avail_y), child_flags, no_scroll_flags) then
    r.ImGui_EndChild(ctx)
    return
  end

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)
  local header_y1 = y0 + header_h
  -- Pin region lane + ruler at the top (outside the scrollable track list).
  -- Move the cursor without a Dummy so the header stays click-through for
  -- extras flyouts that draw into the ruler.
  r.ImGui_SetCursorScreenPos(ctx, x0, header_y1)

  local _, tracks_avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local body_viewport_y1 = header_y1 + math.max(0, tracks_avail_y)

  -- Popup clicks must not fall through into sequencer geometry hit-testing.
  local popup_blocks_input = imgui_any_popup_open()
  local left_clicked = (not popup_blocks_input) and r.ImGui_IsMouseClicked(ctx, 0)
  local right_clicked = (not popup_blocks_input) and r.ImGui_IsMouseClicked(ctx, 1)
  local left_down = (not popup_blocks_input) and r.ImGui_IsMouseDown(ctx, 0)
  local right_down = (not popup_blocks_input) and r.ImGui_IsMouseDown(ctx, 1)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)
  local header_hovered = (not popup_blocks_input) and mx >= x0 and mx <= x0 + width and my >= y0 and my <= header_y1
  local body_hovered = (not popup_blocks_input) and mx >= x0 and mx <= x0 + width and my >= header_y1 and my <= body_viewport_y1
  local over_random_flyout = seq_random_flyout_hit(mx, my) or (state.seq_random_knob_drag ~= nil)
  if over_random_flyout then
    header_hovered = false
    body_hovered = false
    right_clicked = false
  end
  local hovered = header_hovered or body_hovered
  local body_y0, body_y1

  local view_start, view_end = get_arrange_view_range()
  local arrange_start_qn = time_to_qn(view_start) or 0.0
  local arrange_end_qn = time_to_qn(view_end) or (arrange_start_qn + (state.seq_grid_qn or 0.25) * 16.0)
  local arrange_span_qn = math.max(state.seq_grid_qn or 0.25, arrange_end_qn - arrange_start_qn)
  if (state.seq_follow_arrange or not state.seq_view_start_qn) and not seq_view_is_driving_arrange() then
    state.seq_view_start_qn = arrange_start_qn
    state.seq_view_span_qn = arrange_span_qn
    seq_timeline_scroll_stop()
  elseif not state.seq_view_span_qn or state.seq_view_span_qn <= 0 then
    state.seq_view_span_qn = get_seq_region_length_qn(region)
  end

  local start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(
    state.seq_view_start_qn,
    state.seq_view_start_qn + (state.seq_view_span_qn or get_seq_region_length_qn(region))
  )
  -- Continuous view window (smooth scroll). Grid-aligned start_qn/end_qn are only
  -- used for cell indexing; rendering and hit-testing use the raw view coords.
  local view_start_qn = state.seq_view_start_qn or start_qn
  local view_span_qn = state.seq_view_span_qn or math.max(step_qn, end_qn - start_qn)
  local qn_span = view_span_qn
  local scroll_now = r.time_precise()
  local scroll_dt = math.min(0.05, math.max(0.001, scroll_now - (state.seq_scroll_last_t or scroll_now)))
  state.seq_scroll_last_t = scroll_now
  local label_w = math.min(340.0, math.max(268.0, width * 0.34))
  local timeline_x0 = x0 + label_w
  local timeline_w = math.max(120.0, width - label_w)
  state.seq_map_rect = {
    x = x0,
    y = y0,
    w = width,
    h = math.max(0.0, (body_viewport_y1 or y0) - y0),
    timeline_x = timeline_x0,
    timeline_w = timeline_w,
    header_y1 = header_y1,
  }

  -- Floating "keep pattern?" confirmation bar geometry. Computed up-front so we
  -- can suppress grid interactions underneath it (otherwise clicking the tick
  -- would also toggle a note in the cell below).
  local show_confirm = state.seq_pattern_confirm and state.seq_pattern_confirm.active
  local cb_x0, cb_y0, cb_x1, cb_y1
  if show_confirm then
    local cb_h = 34.0
    local cb_w = 240.0
    local confirm_region = region
    if state.seq_pattern_confirm.region_id then
      confirm_region = get_seq_region_by_id(state.seq_pattern_confirm.region_id) or region
    end
    if confirm_region then
      local reg_start = confirm_region.start_qn or 0.0
      local reg_end = reg_start + get_seq_region_length_qn(confirm_region)
      local rx0 = math.max(timeline_x0, timeline_x0 + ((reg_start - view_start_qn) / qn_span) * timeline_w)
      local rx1 = math.min(timeline_x0 + timeline_w, timeline_x0 + ((reg_end - view_start_qn) / qn_span) * timeline_w)
      if rx1 > rx0 + 48.0 then
        cb_w = math.min(cb_w, rx1 - rx0 - 8.0)
        cb_x0 = rx0 + math.max(0.0, (rx1 - rx0 - cb_w) * 0.5)
      else
        cb_x0 = timeline_x0 + math.max(0.0, (timeline_w - cb_w) * 0.5)
      end
    else
      cb_x0 = timeline_x0 + math.max(0.0, (timeline_w - cb_w) * 0.5)
    end
    -- Sit just above the region's note grid (below the ruler), centered on the region span.
    cb_y0 = header_y1 - cb_h - 6.0
    cb_x1 = cb_x0 + cb_w
    cb_y1 = cb_y0 + cb_h
    if mx >= cb_x0 and mx <= cb_x1 and my >= cb_y0 and my <= cb_y1 then
      hovered = false
    end
  end

  if hovered then
    -- ReaImGui returns vertical and horizontal wheel as two values from one call.
    local wheel, wheel_h = r.ImGui_GetMouseWheel(ctx)
    wheel_h = wheel_h or 0.0
    local natural_scroll = (state.seq_scroll_mode == "natural")
    -- In natural mode the vertical wheel is left for ImGui to scroll the track
    -- list vertically; the horizontal wheel (trackpad/Magic Mouse) pans the
    -- timeline. In legacy mode the vertical wheel pans the timeline.
    local pan_wheel = natural_scroll and wheel_h or wheel
    -- Zoom gestures keep using the vertical wheel together with their modifier.
    -- Shift + horizontal wheel/trackpad scroll zooms the timeline.
    local shift_hzoom = wheel_h ~= 0 and is_shift_down()
    if wheel ~= 0 and mod_active("lane_zoom") and (not shift_hzoom or math.abs(wheel) >= math.abs(wheel_h)) then
      local zoom = state.seq_lane_zoom or 1.0
      state.seq_lane_zoom = math.max(0.5, math.min(3.0, zoom * math.exp(wheel * 0.15)))
      save_config()
    elseif (wheel ~= 0 and mod_active("time_zoom")) or shift_hzoom then
      local zoom_delta = shift_hzoom and -wheel_h or wheel
      if seq_apply_time_zoom(zoom_delta, mx, timeline_x0, timeline_w, view_start_qn, qn_span, step_qn) then
        start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(state.seq_view_start_qn, state.seq_view_start_qn + state.seq_view_span_qn)
        view_start_qn = state.seq_view_start_qn
        view_span_qn = state.seq_view_span_qn
        qn_span = view_span_qn
      end
    elseif pan_wheel ~= 0 then
      if state.seq_follow_arrange then
        state.seq_drive_arrange = true
      end
      seq_timeline_scroll_impulse(pan_wheel, view_span_qn)
    end
  end

  if seq_timeline_scroll_apply_inertia(view_span_qn, scroll_dt) then
    start_qn, end_qn, step_qn, step_count = get_visible_qn_grid_range(
      state.seq_view_start_qn,
      state.seq_view_start_qn + (state.seq_view_span_qn or view_span_qn)
    )
    view_start_qn = state.seq_view_start_qn
  end

  if seq_view_is_driving_arrange() then
    seq_push_view_to_arrange()
    if not seq_timeline_scroll_is_active() then
      state.seq_drive_arrange = false
    end
  end

  local measure_guides = collect_measure_guides_qn(start_qn, end_qn, 1024)
  local active_cells = seq_build_visible_active_cells(start_qn, end_qn, step_qn, step_count)
  local selected_region_id = region.id
  local pattern = get_seq_pattern(region.pattern_id, true)
  local random_edit_region = state.seq_random_edit_region_id and get_seq_region_by_id(state.seq_random_edit_region_id) or nil
  local random_edit_pattern = random_edit_region and get_seq_pattern(random_edit_region.pattern_id, true) or nil
  local random_focus_prev = state.seq_random_active_key
  local random_focus_effective = random_focus_prev
  local random_focus_next = nil
  local random_overlay_text = nil
  local random_overlay_y = nil
  local random_overlay_x = nil
  if state.seq_random_edit_region_id and not random_edit_region then
    state.seq_random_edit_region_id = nil
    state.seq_random_active_key = nil
  end
  local now_t = r.time_precise()
  prune_seq_note_anims(now_t)
  prune_seq_track_play_anims(now_t)

  local function qn_to_x(qn) return timeline_x0 + ((qn - view_start_qn) / qn_span) * timeline_w end
  -- Cell edges must use the same continuous QN mapping as grid/region lines.
  -- Using col*cell_w drifts whenever view_start_qn is not grid-aligned.
  local function col_x0(col) return qn_to_x(start_qn + col * step_qn) end
  local function col_x1(col) return qn_to_x(start_qn + (col + 1) * step_qn) end
  local timeline_x1 = timeline_x0 + timeline_w
  local function push_timeline_clip(clip_y0, clip_y1)
    if r.ImGui_DrawList_PushClipRect then
      r.ImGui_DrawList_PushClipRect(dl, timeline_x0, clip_y0, timeline_x1, clip_y1, true)
      return true
    end
    return false
  end
  local function pop_timeline_clip(pushed)
    if pushed and r.ImGui_DrawList_PopClipRect then
      r.ImGui_DrawList_PopClipRect(dl)
    end
  end
  local function label_for_step(step)
    local denom = math.floor((4.0 / step) + 0.5)
    if denom > 0 and math.abs(step - (4.0 / denom)) < 0.0001 then return "1/" .. tostring(denom) end
    return string.format("%.3f QN", step)
  end

  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + width, header_y1, UI_THEME.bg, 6.0)
  r.ImGui_DrawList_AddRect(dl, x0, y0, x0 + width, header_y1, 0x40516AFF, 6.0, 0, 1.2)
  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + width, header_y1, UI_THEME.surface, 0)
  r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, y0, timeline_x0 + timeline_w, y0 + region_lane_h, UI_THEME.bg_panel, 0)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, y0 + region_lane_h, timeline_x0 + timeline_w, y0 + region_lane_h, 0x40516AFF, 1.0)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, y0, timeline_x0, header_y1, 0x70829CFF, 1.5)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, header_y1, timeline_x0 + timeline_w, header_y1, 0x607086FF, 2.0)
  draw_seq_header_preview_waveform(
    dl,
    x0 + 4,
    y0 + 3,
    math.max(16.0, timeline_x0 - x0 - 8),
    math.max(10.0, header_y1 - y0 - 6),
    mx, my, left_down, left_clicked
  )

  local measure_y0 = y0 + region_lane_h
  local measure_line_clr = 0x5A7A9840
  local measure_label_clr = 0x90A8C888
  local measure_header_clip = push_timeline_clip(measure_y0, header_y1)
  for i, guide in ipairs(measure_guides) do
    local px = qn_to_x(guide.qn_start)
    if px >= timeline_x0 and px <= timeline_x1 then
      local next_guide = measure_guides[i + 1]
      local measure_px = next_guide and math.abs(qn_to_x(next_guide.qn_start) - px) or (4.0 / qn_span) * timeline_w
      local show_every = 1
      if measure_px < 12 then
        show_every = 32
      elseif measure_px < 20 then
        show_every = 16
      elseif measure_px < 35 then
        show_every = 8
      elseif measure_px < 60 then
        show_every = 4
      elseif measure_px < 95 then
        show_every = 2
      end
      local measure_num = guide.display_measure or (guide.measure + 1)
      if (guide.measure % show_every) == 0 then
        r.ImGui_DrawList_AddLine(dl, px, measure_y0, px, header_y1, measure_line_clr, 1.0)
        r.ImGui_DrawList_AddText(dl, px + 4, measure_y0 + 7, measure_label_clr, tostring(measure_num))
      end
    end
  end
  pop_timeline_clip(measure_header_clip)

  -- Region blocks live above the ruler and align to the sequencer timeline.
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x0 + timeline_w, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local linked = seq_region_is_linked(reg)
      local fill = seq_region_pool_color(reg.pool_id, selected and 220 or 145)
      local edge = selected and 0xFFFFFFFF or seq_region_pool_color(reg.pool_id, 230)
      r.ImGui_DrawList_AddRectFilled(dl, rx0 + 1, y0 + 3, rx1 - 1, y0 + region_lane_h - 3, fill, 4.0)
      r.ImGui_DrawList_AddRect(dl, rx0 + 1, y0 + 3, rx1 - 1, y0 + region_lane_h - 3, edge, 4.0, 0, selected and 1.6 or 1.0)
      local link_fits = linked and (rx1 - rx0) >= (SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD * 2 + 8)
      local label_x = rx0 + 6
      if link_fits then
        label_x = rx0 + 6 + SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD
      end
      local _, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after = seq_collect_region_random_entries(reg)
      local chips_x0 = link_fits and (rx0 + SEQ_LINK_ICON_SIZE + SEQ_LINK_HIT_PAD + 8) or rx0
      local random_labels = seq_region_random_label_layout(chips_x0, rx1, y0, region_lane_h, has_prob, has_human, has_vel, has_vary, has_stut, has_ghost, has_grace, has_after)
      local name_right = rx1 - 6
      if #random_labels > 0 then
        name_right = random_labels[1].x0 - 4
      end
      local region_clipped = false
      if r.ImGui_DrawList_PushClipRect then
        r.ImGui_DrawList_PushClipRect(dl, rx0, y0, rx1, y0 + region_lane_h, true)
        region_clipped = true
      end
      if link_fits then
        local icon_x, icon_y = seq_region_link_icon_xy(rx0, y0)
        local lx0, ly0, lx1, ly1 = seq_region_link_hit_rect(rx0, y0)
        local link_hovered = mx >= lx0 and mx <= lx1 and my >= ly0 and my <= ly1
        seq_draw_link_icon(dl, icon_x, icon_y, 0xFFFFFFFF, link_hovered)
      end
      if name_right - label_x > 16 then
        local label = reg.name or ("Region " .. reg.id)
        r.ImGui_DrawList_AddText(dl, label_x, y0 + 5, 0xFFFFFFFF, label)
      end
      seq_draw_region_random_labels(dl, random_labels, mx, my)
      if region_clipped then
        r.ImGui_DrawList_PopClipRect(dl)
      end
      r.ImGui_DrawList_AddLine(dl, rx0, y0, rx0, header_y1, edge, selected and 2.5 or 1.5)
    end
  end

  if state.seq_region_drag and left_down then
    local drag = state.seq_region_drag
    local current_qn_raw = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
    local current_qn = seq_snap_qn_for_region_drag(current_qn_raw, step_qn)
    local function begin_region_drag_undo()
      if not drag.undo_started then
        begin_seq_undo(drag.undo_label or "Edit sequencer region")
        drag.undo_started = true
      end
    end
    if drag.mode == "move" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        local anchor_qn_raw = drag.anchor_qn_raw or drag.anchor_qn or current_qn_raw
        local desired = drag.orig_start_qn + (current_qn_raw - anchor_qn_raw)
        desired = seq_snap_qn_for_region_move(desired, step_qn)
        begin_region_drag_undo()
        if seq_move_region_to(reg, desired) then
          seq_select_region(reg)
          region = reg
        end
      end
    elseif drag.mode == "pool_copy" then
      drag.current_start_qn = seq_snap_qn_for_region_drag(current_qn_raw - (drag.anchor_offset_qn or 0.0), step_qn)
    elseif drag.mode == "resize_left" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        begin_region_drag_undo()
        if seq_resize_region_start(reg, current_qn, step_qn) then
          seq_select_region(reg)
          region = reg
        end
      end
    elseif drag.mode == "resize_right" then
      local reg = get_seq_region_by_id(drag.region_id)
      if reg then
        begin_region_drag_undo()
        if seq_resize_region_end(reg, current_qn, step_qn) then
          seq_select_region(reg)
          region = reg
        end
      end
    elseif drag.mode == "create" then
      drag.current_qn = current_qn
    end
  end

  if state.seq_region_drag then
    local drag = state.seq_region_drag
    if drag.mode == "pool_copy" and drag.current_start_qn then
      local src = get_seq_region_by_id(drag.source_region_id)
      if src then
        local ghost_start = drag.current_start_qn
        local ghost_end = ghost_start + get_seq_region_length_qn(src)
        local gx0 = math.max(timeline_x0, qn_to_x(ghost_start))
        local gx1 = math.min(timeline_x0 + timeline_w, qn_to_x(ghost_end))
        local ghost_fill = seq_region_pool_color(src.pool_id, 90)
        local ghost_edge = seq_region_pool_color(src.pool_id, 200)
        r.ImGui_DrawList_AddRectFilled(dl, gx0 + 1, y0 + 3, gx1 - 1, y0 + region_lane_h - 3, ghost_fill, 4.0)
        r.ImGui_DrawList_AddRect(dl, gx0 + 1, y0 + 3, gx1 - 1, y0 + region_lane_h - 3, ghost_edge, 4.0, 0, 1.2)
      end
    elseif drag.mode == "create" and drag.start_qn and drag.current_qn then
      local create_start = math.min(drag.start_qn, drag.current_qn)
      local create_end = math.max(drag.start_qn, drag.current_qn)
      if create_end - create_start < step_qn then
        create_end = create_start + (drag.default_length_qn or get_seq_region_length_qn({ start_qn = create_start, length_bars = 4 }))
      end
      local cx0 = math.max(timeline_x0, qn_to_x(create_start))
      local cx1 = math.min(timeline_x0 + timeline_w, qn_to_x(create_end))
      r.ImGui_DrawList_AddRectFilled(dl, cx0 + 1, y0 + 3, cx1 - 1, y0 + region_lane_h - 3, 0x4A8BD688, 3.0)
      r.ImGui_DrawList_AddRect(dl, cx0 + 1, y0 + 3, cx1 - 1, y0 + region_lane_h - 3, 0x4A8BD6FF, 3.0, 0, 1.2)
    end
  end

  if hovered and not state.seq_region_drag and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and my >= y0 and my <= y0 + region_lane_h then
    local hover_hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, view_start_qn, qn_span, qn_to_x)
    if hover_hit and hover_hit.part == "link" then
      if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
      end
      if r.ImGui_SetTooltip then
        r.ImGui_SetTooltip(ctx, "Linked region — click to unlink")
      end
    elseif hover_hit and (hover_hit.part == "rand_all" or hover_hit.part == "rand_prob" or hover_hit.part == "rand_human" or hover_hit.part == "rand_vel" or hover_hit.part == "rand_vary" or hover_hit.part == "rand_stut" or hover_hit.part == "rand_ghost" or hover_hit.part == "rand_grace" or hover_hit.part == "rand_after") then
      if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
        r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
      end
      if r.ImGui_SetTooltip then
        local tip = "Humanize — click to edit, double-click to reset"
        if hover_hit.part == "rand_all" then
          tip = "Randomization — click to edit, double-click to reset all"
        elseif hover_hit.part == "rand_prob" then
          tip = "Probability — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_vel" then
          tip = "Velocity humanize — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_vary" then
          tip = "Sample variation — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_stut" then
          tip = "Stutter probability — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_ghost" then
          tip = "Ghost notes — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_grace" then
          tip = "Grace notes — click to edit, double-click to reset"
        elseif hover_hit.part == "rand_after" then
          tip = "After notes — click to edit, double-click to reset"
        end
        r.ImGui_SetTooltip(ctx, tip)
      end
    elseif hover_hit and is_shift_down() and hover_hit.part ~= "left_edge" and hover_hit.part ~= "right_edge" and hover_hit.part ~= "link" then
      local hover_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
      local split_qn = seq_split_qn_for_region(hover_hit.region, hover_qn, step_qn)
      if split_qn then
        local sx = qn_to_x(split_qn)
        if sx >= timeline_x0 and sx <= timeline_x0 + timeline_w then
          r.ImGui_DrawList_AddLine(dl, sx, y0 + 2, sx, y0 + region_lane_h - 2, 0xFFE599FF, 2.0)
          r.ImGui_DrawList_AddLine(dl, sx, y0 + region_lane_h, sx, header_y1, 0xFFE599AA, 1.2)
        end
        if r.ImGui_SetTooltip then
          r.ImGui_SetTooltip(ctx, "Shift+click to split region")
        end
      end
    elseif not hover_hit then
      local hover_qn = seq_snap_qn_for_region_drag(seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span), step_qn)
      local preview_start_qn, preview_len_qn = seq_get_default_create_region_qn(hover_qn, step_qn)
      local px0 = math.max(timeline_x0, qn_to_x(preview_start_qn))
      local px1 = math.min(timeline_x0 + timeline_w, qn_to_x(preview_start_qn + preview_len_qn))
      r.ImGui_DrawList_AddRectFilled(dl, px0 + 1, y0 + 3, px1 - 1, y0 + region_lane_h - 3, 0x4A8BD655, 3.0)
      r.ImGui_DrawList_AddRect(dl, px0 + 1, y0 + 3, px1 - 1, y0 + region_lane_h - 3, 0x4A8BD6DD, 3.0, 0, 1.0)
    end
  end

  if left_clicked and not hovered then
    state.seq_random_popup_pending = nil
  end

  if hovered and left_clicked and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and not over_random_flyout then
    local clicked_qn_raw = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
    local clicked_qn = seq_snap_qn_for_region_drag(clicked_qn_raw, step_qn)
    if my >= y0 and my <= y0 + region_lane_h then
      local hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, view_start_qn, qn_span, qn_to_x)
      if hit and (hit.part == "rand_all" or hit.part == "rand_prob" or hit.part == "rand_human" or hit.part == "rand_vel" or hit.part == "rand_vary" or hit.part == "rand_stut" or hit.part == "rand_ghost" or hit.part == "rand_grace" or hit.part == "rand_after") then
        local kind = "human"
        if hit.part == "rand_all" then
          kind = "all"
        elseif hit.part == "rand_prob" then
          kind = "prob"
        elseif hit.part == "rand_vel" then
          kind = "vel"
        elseif hit.part == "rand_vary" then
          kind = "vary"
        elseif hit.part == "rand_stut" then
          kind = "stut"
        elseif hit.part == "rand_grace" then
          kind = "grace"
        elseif hit.part == "rand_after" then
          kind = "after"
        elseif hit.part == "rand_ghost" then
          kind = "ghost"
        end
        seq_handle_region_random_label_click(hit.region, kind)
        region = hit.region
      else
        state.seq_random_popup_pending = nil
        if hit then
          if hit.part == "link" then
          local label = begin_seq_undo("Unlink sequencer region")
          seq_unpool_region(hit.region)
          end_seq_undo(label)
        elseif hit.part == "body" and is_alt_down() then
          local label = begin_seq_undo("Delete sequencer region")
          seq_delete_region_by_id(hit.region.id)
          end_seq_undo(label)
          region = get_selected_seq_region()
          if region then
            selected_region_id = region.id
            pattern = get_seq_pattern(region.pattern_id, true)
          end
          active_cells = seq_build_visible_active_cells(start_qn, end_qn, step_qn, step_count)
        elseif hit.part == "body" and is_shift_down() then
          seq_select_region(hit.region)
          region = hit.region
          if seq_split_qn_for_region(hit.region, clicked_qn_raw, step_qn) then
            local label = begin_seq_undo("Split sequencer region")
            local right = seq_split_region(hit.region, clicked_qn_raw, step_qn)
            if right then
              seq_select_region(right)
              region = right
            end
            end_seq_undo(label)
          end
        elseif hit.part == "left_edge" then
          seq_select_region(hit.region)
          region = hit.region
          state.seq_region_drag = {
            mode = "resize_left",
            region_id = hit.region.id,
            undo_label = "Resize sequencer region",
            undo_started = false,
          }
        elseif hit.part == "right_edge" then
          seq_select_region(hit.region)
          region = hit.region
          state.seq_region_drag = {
            mode = "resize_right",
            region_id = hit.region.id,
            undo_label = "Resize sequencer region",
            undo_started = false,
          }
        elseif hit.part == "body" then
          if r.ImGui_IsMouseDoubleClicked(ctx, 0) then
            state.seq_region_drag = nil
            state.selected_seq_region_id = hit.region.id
            seq_zoom_to_region(hit.region)
            region = hit.region
          else
            seq_select_region(hit.region)
            region = hit.region
            if is_ctrl_down() then
              state.seq_region_drag = {
                mode = "pool_copy",
                source_region_id = hit.region.id,
                anchor_offset_qn = clicked_qn - (hit.region.start_qn or 0.0),
                current_start_qn = hit.region.start_qn,
                length_bars = hit.region.length_bars,
                undo_label = "Pool copy sequencer region",
                start_mx = mx,
                start_my = my,
              }
            else
              state.seq_region_drag = {
                mode = "move",
                region_id = hit.region.id,
                anchor_qn = clicked_qn,
                anchor_qn_raw = clicked_qn_raw,
                orig_start_qn = hit.region.start_qn or 0.0,
                undo_label = "Move sequencer region",
                undo_started = false,
              }
            end
          end
        end
      else
        local create_start_qn, create_length_qn = seq_get_default_create_region_qn(clicked_qn, step_qn)
        state.seq_region_drag = {
          mode = "create",
          start_qn = create_start_qn,
          current_qn = create_start_qn,
          default_length_qn = create_length_qn,
          undo_label = "Create sequencer region",
          start_mx = mx,
          start_my = my,
        }
      end
      end
    elseif my > y0 + region_lane_h and my <= header_y1 then
      state.seq_random_popup_pending = nil
      seq_set_playhead_qn(clicked_qn)
    end
  end

  if hovered and right_clicked and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w and my >= y0 and my <= y0 + region_lane_h and not over_random_flyout then
    state.seq_random_popup_pending = nil
    local right_hit = seq_hit_test_region_at(mx, my, y0, region_lane_h, timeline_x0, timeline_w, start_qn, qn_span, qn_to_x)
    if right_hit and right_hit.region then
      if state.seq_random_edit_region_id == right_hit.region.id then
        state.seq_random_edit_region_id = nil
      else
        seq_select_region(right_hit.region)
        region = right_hit.region
        state.seq_random_edit_region_id = right_hit.region.id
      end
    end
  end

  render_seq_region_random_popup()

  local playhead_time = seq_get_playhead_time()
  if playhead_time then
    local playhead_qn = time_to_qn(playhead_time)
    if playhead_qn and playhead_qn >= start_qn and playhead_qn <= end_qn then
      local playhead_x = qn_to_x(playhead_qn)
      if playhead_x >= timeline_x0 - 1 and playhead_x <= timeline_x0 + timeline_w + 1 then
        local playing = r.GetPlayState and (r.GetPlayState() & 1) == 1
        local playhead_color = playing and 0xFFFF88EE or 0xFFFF8866
        local playhead_thickness = playing and 2.0 or 1.5
        r.ImGui_DrawList_AddLine(dl, playhead_x, y0, playhead_x, header_y1, playhead_color, playhead_thickness)
        r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, y0 + region_lane_h + 6, 4.0, playhead_color, 12)
      end
    end
  end

  if show_confirm then
    render_seq_pattern_confirm_bar(dl, cb_x0, cb_y0, cb_x1, cb_y1)
  end

  if not r.ImGui_BeginChild(ctx, "sequencer_map_tracks", 0, math.max(0, tracks_avail_y), child_flags) then
    r.ImGui_EndChild(ctx)
    return
  end

  body_y0 = select(2, r.ImGui_GetCursorScreenPos(ctx))
  r.ImGui_Dummy(ctx, width, map_body_h)
  body_y1 = body_y0 + map_body_h

  local hover_on_razor, razor_hover_track_id, razor_hover_qn = seq_compute_razor_hover(
    mx, my, visual_rows, body_y0, body_y1, timeline_x0, timeline_w, view_start_qn, qn_span
  )

  r.ImGui_DrawList_AddRectFilled(dl, x0, body_y0, x0 + width, body_y1, UI_THEME.bg, 0)
  r.ImGui_DrawList_AddRect(dl, x0, body_y0, x0 + width, body_y1, 0x40516AFF, 0, 0, 1.2)
  r.ImGui_DrawList_AddLine(dl, timeline_x0, body_y0, timeline_x0, body_y1, 0x70829CFF, 1.5)

  for i, guide in ipairs(measure_guides) do
    local px = qn_to_x(guide.qn_start)
    if px >= timeline_x0 and px <= timeline_x1 then
      local next_guide = measure_guides[i + 1]
      local measure_px = next_guide and math.abs(qn_to_x(next_guide.qn_start) - px) or (4.0 / qn_span) * timeline_w
      local show_every = 1
      if measure_px < 12 then
        show_every = 32
      elseif measure_px < 20 then
        show_every = 16
      elseif measure_px < 35 then
        show_every = 8
      elseif measure_px < 60 then
        show_every = 4
      elseif measure_px < 95 then
        show_every = 2
      end
      if (guide.measure % show_every) == 0 then
        r.ImGui_DrawList_AddLine(dl, px, body_y0, px, body_y1, measure_line_clr, 1.0)
      end
    end
  end

  if playhead_time then
    local playhead_qn = time_to_qn(playhead_time)
    if playhead_qn and playhead_qn >= start_qn and playhead_qn <= end_qn then
      local playhead_x = qn_to_x(playhead_qn)
      if playhead_x >= timeline_x0 - 1 and playhead_x <= timeline_x0 + timeline_w + 1 then
        local playing = r.GetPlayState and (r.GetPlayState() & 1) == 1
        local playhead_color = playing and 0xFFFF88EE or 0xFFFF8866
        local playhead_thickness = playing and 2.0 or 1.5
        r.ImGui_DrawList_AddLine(dl, playhead_x, body_y0, playhead_x, body_y1, playhead_color, playhead_thickness)
        r.ImGui_DrawList_AddCircleFilled(dl, playhead_x, body_y1 - 6, 3.0, playhead_color, 10)
      end
    end
  end

  -- Region ownership cues in the sequencer grid.
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x0 + timeline_w, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local fill = seq_region_pool_color(reg.pool_id, selected and 42 or 22)
      local edge = seq_region_pool_color(reg.pool_id, selected and 255 or 150)
      r.ImGui_DrawList_AddRectFilled(dl, rx0, body_y0, rx1, body_y1, fill, 0)
      r.ImGui_DrawList_AddLine(dl, rx0, body_y0, rx0, body_y1, edge, selected and 2.5 or 1.5)
      r.ImGui_DrawList_AddLine(dl, rx1, body_y0, rx1, body_y1, edge, selected and 2.0 or 1.0)
    end
  end

  local edit_def = get_seq_note_edit_mode_def()
  local edit_style = edit_def and get_seq_row_lane_style({ type = "param", param = edit_def }) or nil
  local row_positions = {}
  local cursor_y = body_y0
  for row_idx, row in ipairs(visual_rows) do
    local row_y0 = cursor_y
    local row_y1 = row_y0 + row.h
    row_positions[row_idx] = { y0 = row_y0, y1 = row_y1, row = row }
    cursor_y = row_y1

    local lane_style = get_seq_row_lane_style(row)
    if row.type == "note" and edit_style then
      lane_style = {
        bg = lane_style.bg,
        label_bg = edit_style.label_bg,
        timeline_bg = edit_style.timeline_bg,
        edge = edit_style.edge,
        accent = edit_style.accent,
      }
    end
    local track_boundary = row.type == "note" and row_idx > 1

    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + width, row_y1, lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, row_y0, timeline_x0 + timeline_w, row_y1, lane_style.timeline_bg or lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, timeline_x0 - 1, row_y1, lane_style.label_bg or lane_style.bg, 0)
    r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + 4, row_y1, lane_style.accent or UI_THEME.accent, 0)
    if row.type == "note" and row.slot then
      if row.slot.mute then
        r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + width, row_y1, 0x00000055, 0)
      elseif row.slot.solo then
        r.ImGui_DrawList_AddRectFilled(dl, x0, row_y0, x0 + 4, row_y1, 0xE8A020FF, 0)
      end
    end
    r.ImGui_DrawList_AddLine(dl, x0, row_y0, x0 + width, row_y0, lane_style.edge, 1.0)
    r.ImGui_DrawList_AddLine(dl, timeline_x0, row_y0, timeline_x0 + timeline_w, row_y0, lane_style.edge, 1.0)
    r.ImGui_DrawList_AddLine(dl, x0, row_y1, x0 + width, row_y1, lane_style.edge, 1.5)
    r.ImGui_DrawList_AddLine(dl, timeline_x0, row_y1, timeline_x0 + timeline_w, row_y1, lane_style.edge, 1.5)
    if track_boundary then
      r.ImGui_DrawList_AddLine(dl, x0, row_y0, x0 + width, row_y0, 0x8090A8FF, 2.5)
    end
    if row.type == "note" then
      local next_row = visual_rows[row_idx + 1]
      if next_row and next_row.type == "param" then
        r.ImGui_DrawList_AddLine(dl, x0, row_y1, x0 + width, row_y1, 0x607088FF, 2.0)
      end
    end

    local slot = row.slot
    if row.type == "note" and slot then
      local expanded = state.seq_expanded_tracks[tostring(slot.id)] == true
      local play_anim = get_seq_track_play_anim(slot.id, now_t)
      if play_anim then
        local assigned_sample = slot.sample_path and find_sample_by_path(slot.sample_path) or nil
        draw_seq_track_play_row_fx(dl, x0, row_y0, timeline_x0 - 1, row_y1, play_anim.t, assigned_sample)
      end
      local name_alpha = play_anim and math.floor(180 + math.sin(play_anim.t * math.pi) * 75) or 255
      local ctrl = seq_get_track_control_layout(
        x0, row_y0, timeline_x0 - seq_track_nav_width(row.h) - 6.0, row_y1
      )
      row_positions[row_idx].ctrl = ctrl
      seq_draw_track_name_and_expand(
        dl, slot, ctrl, expanded, name_alpha,
        (edit_style and edit_style.accent) or 0xFFDFAAFF,
        "Track " .. row_idx
      )

      local note_clip = push_timeline_clip(row_y0, row_y1)
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        if cx1 > timeline_x0 and cx0 < timeline_x1 and col % 2 == 1 then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, row_y0, cx1, row_y1, seq_lane_color_with_alpha(lane_style.accent, 16), 0)
        end
      end
      -- Shift insert preview is drawn under notes so a later hit stays on top.
      if seq_note_slip_modifier() and not edit_def
          and hovered and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w
          and my >= row_y0 and my <= row_y1
          and not hover_on_razor and not seq_razor_gesture_active() and not state.seq_razor_drag
          and not (seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
            and state.seq_param_drag and state.seq_param_drag.region_id == region.id)
          and not seq_lane_random_controls_hit({ y0 = row_y0, y1 = row_y1, row = row }, mx, my, timeline_x0, header_y1, body_viewport_y1) then
        local slip_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
        local slip_col = math.max(0, math.min(step_count - 1, math.floor((slip_qn - start_qn) / step_qn + 1e-9)))
        local region_end_qn = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
        local slip_in_region = slip_qn >= (region.start_qn or 0.0) and slip_qn < region_end_qn
        local slip_on_note = seq_resolve_hover_note(
          active_cells[slot.id] and active_cells[slot.id][slip_col],
          slip_qn, start_qn, slip_col, step_qn
        )
        if slip_in_region and not slip_on_note
            and not seq_visible_cell_is_locked(slot, slip_col, start_qn, step_qn, active_cells) then
          local highlight_end = math.min(region_end_qn, slip_qn + step_qn, seq_next_note_vis_qn_after(region, slot.id, slip_qn, step_qn))
          local hx0 = math.max(timeline_x0, qn_to_x(slip_qn))
          local hx1 = math.min(timeline_x1, qn_to_x(highlight_end))
          if hx1 > hx0 then
            local hover_fill = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 51)) or 0xFFE59933
            local hover_edge = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 255)) or 0xFFE599FF
            r.ImGui_DrawList_AddRectFilled(dl, hx0, row_y0, hx1, row_y1, hover_fill, 0)
            r.ImGui_DrawList_AddRect(dl, hx0, row_y0, hx1, row_y1, hover_edge, 0, 0, 1.5)
          end
        end
      end
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        -- Skip cells fully outside the visible timeline (continuous scroll pads extras).
        if cx1 > timeline_x0 and cx0 < timeline_x1 then
        local active = active_cells[slot.id] and active_cells[slot.id][col]
        if active then
          seq_draw_lane_packed_notes(
            dl, slot, active, row_y0, row_y1, cx0, cx1,
            selected_region_id, now_t, step_qn, qn_to_x,
            edit_def, edit_style, mx, my, hover_on_razor,
            seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span),
            start_qn, col
          )
        end
        end
      end
      seq_draw_lane_delete_anims(
        dl, slot, row_y0, row_y1, now_t, step_qn, qn_to_x,
        timeline_x0, timeline_x1, selected_region_id
      )
      local lock_hover_col = nil
      if hovered and mx >= timeline_x0 and mx <= timeline_x0 + timeline_w
          and my >= row_y0 and my <= row_y1 and not hover_on_razor then
        local lock_hover_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
        lock_hover_col = math.max(0, math.min(step_count - 1, math.floor((lock_hover_qn - start_qn) / step_qn + 1e-9)))
        if not seq_visible_cell_is_locked(slot, lock_hover_col, start_qn, step_qn, active_cells) then
          lock_hover_col = nil
        end
      end
      draw_seq_lock_spans(dl, slot, row_y0, row_y1, start_qn, step_qn, step_count, col_x0, col_x1, timeline_x0, timeline_x1, active_cells, seq_is_lock_def(edit_def), lock_hover_col)
      pop_timeline_clip(note_clip)
    elseif row.type == "param" and slot and row.param then
      local def = row.param
      local lane_top = row_y0 + 2
      local lane_bot = row_y1 - 2
      local is_stutter_lane = def.key == "stutter"
      local bipolar = def.min < 0
      local lane_label = def.label
      if def.hotkey then
        lane_label = string.format("%s  %s", def.label, def.hotkey)
      end
      r.ImGui_DrawList_AddText(dl, x0 + 36, row_y0 + 3, lane_style.accent or UI_THEME.accent, lane_label)

      -- Baseline / zero reference for the lane.
      local base_y = lane_bot
      if not is_stutter_lane then
        if bipolar then
          base_y = seq_param_y_from_value(def, 0.0, lane_top, lane_bot, step_qn)
          r.ImGui_DrawList_AddLine(dl, timeline_x0, base_y, timeline_x0 + timeline_w, base_y, seq_lane_color_with_alpha(lane_style.accent, 90), 1.0)
        else
          r.ImGui_DrawList_AddLine(dl, timeline_x0, lane_bot, timeline_x0 + timeline_w, lane_bot, seq_lane_color_with_alpha(lane_style.accent, 90), 1.0)
        end
      end

      local param_clip = push_timeline_clip(row_y0, row_y1)
      for col = 0, step_count - 1 do
        local cx0 = col_x0(col)
        local cx1 = col_x1(col)
        if cx1 > timeline_x0 and cx0 < timeline_x1 then
        if col % 2 == 1 then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, row_y0, cx1, row_y1, seq_lane_color_with_alpha(lane_style.accent, 16), 0)
        end
        local active = active_cells[slot.id] and active_cells[slot.id][col]
        if active then
          seq_draw_param_lane_packed_notes(
            dl, ctx, slot, active, def, selected_region_id, start_qn, col, step_qn,
            qn_to_x, cx0, cx1, lane_top, lane_bot, base_y, bipolar, is_stutter_lane, lane_style, region
          )
        end
        end
      end
      pop_timeline_clip(param_clip)
    else
      r.ImGui_DrawList_AddText(dl, x0 + 8, row_y0 + 8, UI_THEME.text_dim, "No sequencer tracks configured")
    end
  end

  local slot_id_to_idx = {}
  for track_idx, track_slot in ipairs(state.seq_tracks) do
    slot_id_to_idx[track_slot.id] = track_idx
  end
  local map_icon_size = seq_icon_size_for_lane_h(note_lane_h)
  local map_ctrl_size = seq_ctrl_size_for_icon(map_icon_size)
  local map_nav_w = get_seq_track_sample_controls_width(map_ctrl_size, map_icon_size)
  local over_lane_mix_controls = false
  local mix_env_resync = false
  local env_resync_slot = nil

  local add_row_y0 = body_y0 + rows_h
  local add_row_y1 = add_row_y0 + add_track_row_h
  local label_col_w = timeline_x0 - x0
  r.ImGui_DrawList_AddRectFilled(dl, x0, add_row_y0, timeline_x0 - 1, add_row_y1, UI_THEME.bg_panel, 0)
  r.ImGui_DrawList_AddRectFilled(dl, timeline_x0, add_row_y0, timeline_x0 + timeline_w, add_row_y1, UI_THEME.bg, 0)
  r.ImGui_DrawList_AddLine(dl, x0, add_row_y0, x0 + width, add_row_y0, 0x607086FF, 1.5)
  r.ImGui_DrawList_AddLine(dl, x0, add_row_y1, x0 + width, add_row_y1, 0x40516AFF, 1.0)

  -- Draw visible region ownership again over row backgrounds so users can see which
  -- cells belong to each selected/copy/pooled region.
  local body_clip = push_timeline_clip(body_y0, body_y1)
  for _, reg in ipairs(state.seq_regions) do
    local reg_start = reg.start_qn or 0.0
    local reg_end = reg_start + get_seq_region_length_qn(reg)
    if reg_end >= start_qn and reg_start <= end_qn then
      local rx0 = math.max(timeline_x0, qn_to_x(reg_start))
      local rx1 = math.min(timeline_x1, qn_to_x(reg_end))
      local selected = region and reg.id == region.id
      local fill = seq_region_pool_color(reg.pool_id, selected and 32 or 16)
      local edge = seq_region_pool_color(reg.pool_id, selected and 255 or 170)
      r.ImGui_DrawList_AddRectFilled(dl, rx0, body_y0, rx1, body_y1, fill, 0)
      r.ImGui_DrawList_AddLine(dl, rx0, body_y0, rx0, body_y1, edge, selected and 2.5 or 1.5)
      r.ImGui_DrawList_AddLine(dl, rx1, body_y0, rx1, body_y1, edge, selected and 2.0 or 1.0)
    end
  end

  for col = 0, step_count do
    local qn = start_qn + col * step_qn
    local px = qn_to_x(qn)
    if px >= timeline_x0 and px <= timeline_x1 then
      local clr = (math.abs(qn - math.floor(qn + 0.5)) < 0.0001) and 0x45505EFF or 0x2A303AFF
      r.ImGui_DrawList_AddLine(dl, px, body_y0, px, body_y1, clr, 1.0)
    end
  end
  pop_timeline_clip(body_clip)
  -- Keep a hard edge so timeline graphics never read as overlapping track controls.
  r.ImGui_DrawList_AddLine(dl, timeline_x0, body_y0, timeline_x0, body_y1, 0x70829CFF, 1.5)

  local hovered_slot, hovered_col, hovered_qn, hovered_row = nil, nil, nil, nil
  local param_drag_active = seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
      and state.seq_param_drag.region_id == region.id
  if hovered and mx >= x0 and mx <= timeline_x0 + timeline_w and my >= body_y0 and my <= body_y1 then
    for _, row_pos in ipairs(row_positions) do
      if my >= row_pos.y0 and my <= row_pos.y1 then
        hovered_row = row_pos
        hovered_slot = row_pos.row.slot
        break
      end
    end
    if mx >= timeline_x0 then
      hovered_qn = seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span)
      hovered_col = math.max(0, math.min(step_count - 1, math.floor((hovered_qn - start_qn) / step_qn + 1e-9)))
    end
    local over_rand = random_edit_region
      and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and seq_lane_random_controls_hit(hovered_row, mx, my, timeline_x0, header_y1, body_viewport_y1)
    if hovered_slot and hovered_qn ~= nil and not over_rand then
      local hover_in_selected = hovered_qn >= region.start_qn and hovered_qn < region.start_qn + get_seq_region_length_qn(region)
      if not param_drag_active and hover_in_selected and not seq_razor_gesture_active() and not state.seq_razor_drag
          and not hover_on_razor then
        local hx0 = math.max(timeline_x0, col_x0(hovered_col))
        local hx1 = math.min(timeline_x1, col_x1(hovered_col))
        local hover_edge = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 255)) or 0xFFE599FF
        local hover_active = seq_resolve_hover_note(
          active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
          hovered_qn, start_qn, hovered_col, step_qn
        )
        local slip_empty = seq_note_slip_modifier() and not edit_def
          and hovered_row.row.type == "note" and not hover_active
        if slip_empty then
          local region_end_qn = (region.start_qn or 0.0) + get_seq_region_length_qn(region)
          hx0 = qn_to_x(hovered_qn)
          hx1 = qn_to_x(math.min(region_end_qn, hovered_qn + step_qn))
          hx0 = math.max(timeline_x0, hx0)
          hx1 = math.min(timeline_x1, hx1)
        end
        local hover_locked = hovered_row.row.type == "note"
          and seq_visible_cell_is_locked(hovered_slot, hovered_col, start_qn, step_qn, active_cells)
        if hx1 > hx0 and not (hover_active and hovered_row.row.type == "note") and not slip_empty and not hover_locked then
          local hover_fill = (edit_style and seq_lane_color_with_alpha(edit_style.accent, 51)) or 0xFFE59933
          r.ImGui_DrawList_AddRectFilled(dl, hx0, hovered_row.y0, hx1, hovered_row.y1, hover_fill, 0)
          r.ImGui_DrawList_AddRect(dl, hx0, hovered_row.y0, hx1, hovered_row.y1, hover_edge, 0, 0, 1.5)
        end
        if edit_def and hovered_row.row.type == "note" and not seq_is_decay_def(edit_def) then
          if hover_active then
            local hit_idx = seq_stutter_hit_param_key(edit_def.key) and seq_stutter_hit_index_at_qn(hover_active.note, hover_active.abs_qn, hovered_qn, step_qn) or nil
            local hover_val = seq_note_param_value(hover_active.note, edit_def.key, hit_idx)
            local value_text = format_seq_param_value(edit_def, hover_val)
            if hit_idx then
              value_text = string.format("%s  ·  %d/%d", value_text, hit_idx, seq_stutter_count(hover_active.note))
            end
            local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
            local text_w = text_size[1] or 0
            local text_h = text_size[2] or 0
            local text_x = hx0 + 4
            local text_y = hovered_row.y0 - 16
            r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
            r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, hover_edge, 3.0, 0, 1.0)
            r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
          end
        end
      end
    end
  end

  local over_lane_random_controls = seq_random_flyout_hit(mx, my)
  if random_edit_region and hovered_row and hovered_row.row and hovered_row.row.type == "note" then
    over_lane_random_controls = over_lane_random_controls or seq_lane_random_controls_hit(hovered_row, mx, my, timeline_x0, header_y1, body_viewport_y1)
  end
  if state.seq_random_knob_drag then
    over_lane_random_controls = true
  end
  if hover_on_razor or over_lane_random_controls then
    state.seq_grid_hover = nil
  else
    seq_set_grid_hover(hovered_slot, hovered_col, active_cells, start_qn, step_qn, hovered_qn)
  end

  over_lane_mix_controls = false
  if hovered_row and hovered_row.row and hovered_row.row.type == "note" then
    over_lane_mix_controls = seq_lane_mix_controls_hit(hovered_row, mx, my, x0, timeline_x0, map_nav_w)
  end
  if not over_lane_mix_controls then
    for _, row_pos in ipairs(row_positions) do
      if seq_lane_mix_controls_hit(row_pos, mx, my, x0, timeline_x0, map_nav_w) then
        over_lane_mix_controls = true
        break
      end
    end
  end

  if state.seq_razor_drag and state.seq_razor_drag.mode == "move" then
    if r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    end
  elseif (state.seq_note_drag and (state.seq_note_drag.mode == "copy" or state.seq_note_drag.mode == "move"))
      and r.ImGui_SetMouseCursor then
    if state.seq_note_drag.mode == "move" and r.ImGui_MouseCursor_ResizeAll then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    elseif r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif seq_note_copy_modifier() and not edit_def and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
    local hover_copy = seq_resolve_hover_note(
      active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
      hovered_qn, start_qn, hovered_col, step_qn
    )
    if hover_copy then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  elseif seq_note_slip_modifier() and not edit_def and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and hovered_row and hovered_row.row and hovered_row.row.type == "note"
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
    local hover_move = seq_resolve_hover_note(
      active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col],
      hovered_qn, start_qn, hovered_col, step_qn
    )
    if hover_move then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
    end
  elseif seq_razor_gesture_active() and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeNWSE then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNWSE())
  elseif hovered_slot and hovered_qn ~= nil and mx >= timeline_x0
      and seq_cell_in_any_razor(hovered_slot.id, hovered_qn)
      and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeAll then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeAll())
  elseif seq_is_decay_def(edit_def) then
    local decay_kind = nil
    if state.seq_note_drag and state.seq_note_drag.mode == "decay" then
      decay_kind = state.seq_note_drag.handle
    else
      local decay_hit = seq_decay_hit_at(mx, my)
      decay_kind = decay_hit and decay_hit.kind
    end
    if decay_kind == "end" and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeEW then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeEW())
    elseif seq_decay_kind_is_curve(decay_kind) and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_ResizeNS then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_ResizeNS())
    elseif decay_kind and r.ImGui_SetMouseCursor and r.ImGui_MouseCursor_Hand then
      r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    end
  end
  if seq_razor_gesture_active() and right_clicked and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and not over_lane_mix_controls and not over_lane_random_controls
      and not state.seq_region_drag and not state.pending_waveform_drop then
    seq_begin_razor_drag(hovered_slot.id, hovered_qn, seq_razor_additive_gesture())
  elseif left_clicked and seq_has_razors() and hovered_slot and hovered_qn ~= nil
      and mx >= timeline_x0 and not over_lane_mix_controls and not over_lane_random_controls
      and not state.seq_region_drag and not state.pending_waveform_drop
      and not state.seq_razor_drag
      and seq_cell_in_any_razor(hovered_slot.id, hovered_qn) then
    seq_begin_razor_move(hovered_slot.id, hovered_qn, step_qn, seq_razor_copy_modifier())
  end
  if state.seq_razor_drag then
    seq_update_razor_drag(hovered_slot and hovered_slot.id, hovered_qn, row_positions, my)
    if state.seq_razor_drag.mode == "move" then
      seq_razor_apply_move(state.seq_razor_drag, step_qn)
    end
  end

  if hovered and left_clicked and not over_lane_mix_controls then
    for _, row_pos in ipairs(row_positions) do
      local ctrl = row_pos.ctrl
      if row_pos.row.type == "note" and row_pos.row.slot and ctrl then
        if seq_layout_hit(ctrl.expand, mx, my) then
          local key = tostring(row_pos.row.slot.id)
          state.seq_expanded_tracks[key] = not state.seq_expanded_tracks[key] or nil
          save_config()
          break
        elseif (not state.pending_waveform_drop) and seq_layout_hit(ctrl.name, mx, my) then
          local track_idx = slot_id_to_idx[row_pos.row.slot.id]
          if track_idx then
            select_seq_track(track_idx)
          end
          break
        end
      end
    end
  end

  if hovered_slot and hovered_qn ~= nil and hovered_row and not state.seq_region_drag
      and not over_lane_random_controls and not over_lane_mix_controls
      and not seq_razor_blocks_grid_edit() then
    local step_idx = math.floor(((hovered_qn - region.start_qn) / step_qn) + 1e-9)
    local in_region = hovered_qn >= region.start_qn and hovered_qn < region.start_qn + get_seq_region_length_qn(region)
    local step_key = tostring(step_idx)
    local cell_id = tostring(hovered_slot.id) .. ":" .. step_key
    local cell_active = active_cells[hovered_slot.id] and active_cells[hovered_slot.id][hovered_col]
    local active = seq_resolve_hover_note(cell_active, hovered_qn, start_qn, hovered_col, step_qn)

    local decay_hit = seq_is_decay_def(edit_def) and (left_clicked or right_clicked) and mx >= timeline_x0
      and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
      and seq_decay_hit_at(mx, my)
    if decay_hit and decay_hit.note then
      local hit_region = get_seq_region_by_id(decay_hit.region_id) or region
      local hit_note = get_seq_note(hit_region, decay_hit.track_id, decay_hit.step_key) or decay_hit.note
      if right_clicked then
        local label = begin_seq_undo("Reset sequencer decay")
        local changed = false
        if decay_hit.kind == "end" then
          if seq_stutter_count(hit_note) > 1 then
            if math.abs((hit_note.length_qn or 0.0) - step_qn) > 1e-9 then
              hit_note.length_qn = step_qn
              changed = true
            end
          elseif hit_note.decay_qn ~= nil then
            hit_note.decay_qn = nil
            changed = true
          end
          seq_clamp_note_fades(hit_note, seq_note_current_decay_length_qn(hit_region, seq_find_slot_by_id(decay_hit.track_id), hit_note, decay_hit.step_key, step_qn))
        elseif decay_hit.kind == "fade_in" then
          changed = seq_note_clear_fade_side(hit_note, "in")
        elseif decay_hit.kind == "fade_out" then
          changed = seq_note_clear_fade_side(hit_note, "out")
        elseif decay_hit.kind == "curve_in" then
          changed = seq_note_set_fade_curve(hit_note, "in", 0)
        elseif decay_hit.kind == "curve_out" then
          changed = seq_note_set_fade_curve(hit_note, "out", 0)
        end
        if changed then
          local hit_slot = seq_find_slot_by_id(decay_hit.track_id)
          if hit_region and hit_slot then
            sync_seq_pattern_track(hit_region.pattern_id, hit_slot, { force_rebuild = true })
          end
          save_config()
        end
        end_seq_undo(label)
        state.selected_seq_note = { region_id = hit_region.id, track_id = decay_hit.track_id, step_key = decay_hit.step_key }
      else
        local label = begin_seq_undo("Edit sequencer decay")
        local which = (decay_hit.kind == "fade_in" or decay_hit.kind == "curve_in") and "in"
          or ((decay_hit.kind == "fade_out" or decay_hit.kind == "curve_out") and "out" or nil)
        local origin_shape = 1
        local origin_curve = 0.0
        local origin_fade_qn = 0.0
        if which then
          origin_fade_qn = seq_note_fade_qn(hit_note, which)
          if origin_fade_qn > 1e-6 then
            origin_shape = seq_note_fade_shape(hit_note, which)
            origin_curve = seq_note_fade_curve(hit_note, which)
          end
        end
        state.seq_note_drag = {
          mode = "decay",
          handle = decay_hit.kind,
          track_id = decay_hit.track_id,
          region_id = hit_region.id,
          step_key = decay_hit.step_key,
          origin_x = mx,
          origin_y = my,
          origin_shape = origin_shape,
          origin_curve = origin_curve,
          origin_fade_qn = origin_fade_qn,
          note_start_qn = seq_note_abs_qn(hit_region, hit_note, decay_hit.step_key, step_qn) + (hit_note.offset_qn or 0.0),
          max_length_qn = seq_note_decay_max_qn(hit_region, seq_find_slot_by_id(decay_hit.track_id), hit_note, decay_hit.step_key, step_qn),
          undo_label = label,
          undo_open = true,
          dirty = false,
        }
        apply_seq_decay_drag(
          state.seq_note_drag, hit_region, step_qn,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        )
      end
    elseif hovered_row.row.type == "param" and hovered_row.row.param and in_region and left_clicked and mx >= timeline_x0 then
      local def = hovered_row.row.param
      local start_value = def.default
      if active then
        start_value = seq_note_param_value(active.note, def.key, seq_stutter_hit_index_at_qn(active.note, active.abs_qn, hovered_qn, step_qn))
        if start_value == nil then
          start_value = def.default
        end
      else
        start_value = seq_param_value_for_drag(def, seq_param_value_from_y(def, my, hovered_row.y0 + 2, hovered_row.y1 - 2, step_qn), step_qn)
      end
      state.seq_param_drag = {
        track_id = hovered_slot.id,
        param = def.key,
        region_id = region.id,
        step_key = active and active.key or step_key,
        col = hovered_col,
        end_col = hovered_col,
        ramp = mod_active("velocity_ramp"),
        unify = mod_active("unify") and not mod_active("velocity_ramp"),
        start_value = start_value,
        button = 0,
      }
      if active then
        state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
      end
    elseif state.pending_waveform_drop then
      local track_idx = hovered_slot and slot_id_to_idx[hovered_slot.id]
      state.seq_timeline_drop_track_idx = track_idx
      state.seq_timeline_drop_time = qn_to_time(hovered_qn)
      state.seq_drop_target_idx = nil
      -- Highlight the cell under the cursor and draw an insertion marker so the
      -- exact drop position on the timeline is obvious.
      local cell_x0 = col_x0(hovered_col)
      local cell_x1 = col_x1(hovered_col)
      draw_drop_target_highlight(dl, cell_x0, hovered_row.y0, cell_x1, hovered_row.y1, 2)
      local pulse = drag_pulse()
      local line_col = build_color_rrgbbaa(120, 200, 255, math.floor(170 + 85 * pulse))
      r.ImGui_DrawList_AddLine(dl, cell_x0, body_y0, cell_x0, body_y1, line_col, 2.0)
      r.ImGui_DrawList_AddTriangleFilled(dl, cell_x0 - 5, body_y0, cell_x0 + 5, body_y0, cell_x0, body_y0 + 7, line_col)
    elseif hovered_row.row.type == "note" and not in_region and left_clicked and mx >= timeline_x0 then
      local hover_reg = seq_region_at_qn(hovered_qn)
      if hover_reg then
        seq_select_region(hover_reg)
        region = hover_reg
        selected_region_id = region.id
      end
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and is_alt_down() and not edit_def
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0)) then
      local label = begin_seq_undo("Create sequencer stutter")
      state.seq_note_drag = {
        mode = "stutter",
        track_id = hovered_slot.id,
        region_id = region.id,
        start_col = hovered_col,
        end_col = hovered_col,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
      if apply_seq_stutter_lane_drag(
        state.seq_note_drag, region, step_qn, start_qn, step_count,
        mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
      ) then
        state.seq_note_drag.dirty = true
      elseif not state.seq_note_drag.step_key then
        if state.seq_note_drag.undo_open then
          end_seq_undo(label)
        end
        state.seq_note_drag = nil
      end
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_copy_modifier() and not edit_def and not is_alt_down()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and active and active.note then
      local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn) or active
      local src_region = get_seq_region_by_id(picked.region_id) or region
      local src_key = tostring(picked.key)
      local src_note = get_seq_note(src_region, hovered_slot.id, src_key) or picked.note
      local src_abs = seq_note_abs_qn(src_region, src_note, src_key, step_qn)
      local baked = seq_clone_note_keeping_sample(src_note, src_region, hovered_slot.id, src_key, hovered_slot)
      local label = begin_seq_undo("Copy sequencer note")
      state.selected_seq_note = { region_id = src_region.id, track_id = hovered_slot.id, step_key = src_key }
      state.seq_note_drag = {
        mode = "copy",
        track_id = hovered_slot.id,
        region_id = src_region.id,
        src_step_key = src_key,
        src_abs_qn = src_abs,
        src_snap_qn = math.floor((src_abs / step_qn) + 1e-9) * step_qn,
        src_note = baked,
        src_length_qn = seq_note_length_qn_for_copy(src_region, hovered_slot, src_note, src_key, step_qn),
        patterns_backup = clone_table_deep(state.seq_patterns),
        origin_x = mx,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_slip_modifier() and not edit_def and not is_alt_down()
        and not seq_note_copy_modifier()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and active and active.note then
      local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn) or active
      local src_region = get_seq_region_by_id(picked.region_id) or region
      local src_key = tostring(picked.key)
      local src_note = get_seq_note(src_region, hovered_slot.id, src_key) or picked.note
      local src_abs = seq_note_abs_qn(src_region, src_note, src_key, step_qn)
      local baked = seq_clone_note_keeping_sample(src_note, src_region, hovered_slot.id, src_key, hovered_slot)
      local label = begin_seq_undo("Move sequencer note")
      state.selected_seq_note = { region_id = src_region.id, track_id = hovered_slot.id, step_key = src_key }
      state.seq_note_drag = {
        mode = "move",
        snap = false,
        track_id = hovered_slot.id,
        region_id = src_region.id,
        src_step_key = src_key,
        src_abs_qn = src_abs,
        grab_qn = hovered_qn,
        src_note = baked,
        src_length_qn = seq_note_length_qn_for_copy(src_region, hovered_slot, src_note, src_key, step_qn),
        patterns_backup = clone_table_deep(state.seq_patterns),
        origin_x = mx,
        origin_y = my,
        undo_label = label,
        undo_open = true,
        dirty = false,
      }
    elseif hovered_row.row.type == "note" and in_region and left_clicked and mx >= timeline_x0
        and seq_note_slip_modifier() and not edit_def and not is_alt_down()
        and not seq_note_copy_modifier()
        and not (r.ImGui_IsMouseDoubleClicked and r.ImGui_IsMouseDoubleClicked(ctx, 0))
        and not active
        and not seq_visible_cell_is_locked(hovered_slot, hovered_col, start_qn, step_qn, active_cells) then
      local insert_rel = seq_quantize_free_qn(hovered_qn - (region.start_qn or 0.0))
      local insert_step = tostring(math.floor((insert_rel / step_qn) + 1e-9))
      local note = make_default_seq_note(hovered_slot, insert_step, insert_rel)
      if note then
        local label = begin_seq_undo("Insert sequencer note")
        state.seq_note_drag = {
          mode = "move",
          snap = false,
          place_new = true,
          track_id = hovered_slot.id,
          region_id = region.id,
          src_abs_qn = hovered_qn,
          grab_qn = hovered_qn,
          src_note = note,
          patterns_backup = clone_table_deep(state.seq_patterns),
          origin_x = mx,
          origin_y = my,
          undo_label = label,
          undo_open = true,
          dirty = false,
        }
        if apply_seq_note_copy_drag(
          state.seq_note_drag, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions
        ) then
          state.seq_note_drag.dirty = true
        end
      else
        log("Sequencer slot has no assigned sample")
      end
    elseif hovered_row.row.type == "note" and in_region and (left_clicked or right_clicked) and mx >= timeline_x0 then
      if seq_is_decay_def(edit_def) then
        -- Clicks that miss decay handles do not paint or edit params.
      elseif seq_is_lock_def(edit_def) then
        local started_on_lock = seq_visible_cell_is_locked(
          hovered_slot, hovered_col, start_qn, step_qn, active_cells
        )
        local reset = right_clicked or (left_clicked and started_on_lock)
        local label = begin_seq_undo(reset and "Unlock sequencer cells" or "Lock sequencer cells")
        local changed = false
        if not reset then
          changed = seq_apply_lock_range(
            region, hovered_slot.id, hovered_col, hovered_col, start_qn, step_qn, true, active_cells
          )
        end
        state.seq_param_drag = {
          track_id = hovered_slot.id,
          param = edit_def.key,
          region_id = region.id,
          step_key = (active and active.key) or step_key,
          col = hovered_col,
          end_col = hovered_col,
          ramp = false,
          unify = true,
          start_value = reset and 0.0 or 1.0,
          source = "note",
          reset = reset,
          lock_click_span = reset and true or nil,
          button = right_clicked and 1 or 0,
          undo_label = label,
          undo_open = true,
          dirty = changed,
        }
        if active then
          state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
        end
      elseif edit_def then
        if active then
          local reset = right_clicked
          local ramp = (not reset) and mod_active("velocity_ramp")
          local label = begin_seq_undo(reset
            and ("Reset sequencer " .. (edit_def.mode_name or edit_def.label))
            or ("Edit sequencer " .. (edit_def.mode_name or edit_def.label)))
          local start_value = seq_note_param_value(active.note, edit_def.key, seq_stutter_hit_index_at_qn(active.note, active.abs_qn, hovered_qn, step_qn))
          if start_value == nil then
            start_value = edit_def.default
          end
          state.seq_param_drag = {
            track_id = hovered_slot.id,
            param = edit_def.key,
            region_id = region.id,
            step_key = active.key or step_key,
            col = hovered_col,
            end_col = hovered_col,
            ramp = ramp,
            unify = (not reset) and mod_active("unify") and not ramp,
            start_value = start_value,
            source = "note",
            reset = reset,
            button = right_clicked and 1 or 0,
            undo_label = label,
            undo_open = true,
          }
          state.selected_seq_note = { region_id = region.id, track_id = hovered_slot.id, step_key = active.key }
        end
      else
        local hover_locked = left_clicked and seq_visible_cell_is_locked(
          hovered_slot, hovered_col, start_qn, step_qn, active_cells
        )
        if hover_locked then
          local label = begin_seq_undo("Unlock sequencer cells")
          local lo, hi = seq_lock_span_cols(
            hovered_slot, hovered_col, start_qn, step_qn, step_count, active_cells
          )
          local changed = seq_apply_lock_range(
            region, hovered_slot.id, lo, hi, start_qn, step_qn, false, active_cells
          )
          if changed then
            sync_seq_pattern_track(region.pattern_id, hovered_slot, { force_rebuild = true })
            if seq_schedule_ingest_save then
              seq_schedule_ingest_save()
            else
              save_config()
            end
          end
          end_seq_undo(label)
        else
          local click_key = step_key
          local click_qn = step_idx * step_qn
          local picked = seq_pick_packed_note(active, hovered_qn, start_qn, hovered_col, step_qn)
          if picked and picked.note then
            click_key = picked.key
            click_qn = seq_note_qn_offset(picked.note, picked.key, step_qn)
          end
          local mode = right_clicked and "erase" or "paint"
          local label = begin_seq_undo(left_clicked and "Paint sequencer notes" or "Erase sequencer notes")
          local painted = toggle_seq_note(region, hovered_slot, click_key, click_qn, right_clicked and "erase" or nil, {
            defer_save = true,
          })
          state.seq_note_drag = {
            track_id = hovered_slot.id,
            region_id = region.id,
            start_col = hovered_col,
            end_col = hovered_col,
            applied_min = hovered_col,
            applied_max = hovered_col,
            mode = mode,
            undo_label = label,
            undo_open = true,
            dirty = painted,
          }
        end
      end
    end
  end

  local note_drag_active = state.seq_note_drag and state.seq_note_drag.region_id == region.id
  if note_drag_active and not state.seq_region_drag then
    local drag = state.seq_note_drag
    if drag.mode == "stutter" then
      if left_down then
        if apply_seq_stutter_lane_drag(
          drag, region, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        ) then
          drag.dirty = true
        end
      end
    elseif drag.mode == "decay" then
      if left_down then
        local drag_region = get_seq_region_by_id(drag.region_id) or region
        if apply_seq_decay_drag(
          drag, drag_region, step_qn,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span
        ) then
          drag.dirty = true
        end
      end
    elseif drag.mode == "copy" or drag.mode == "move" then
      if left_down and mx >= timeline_x0 then
        if apply_seq_note_copy_drag(
          drag, step_qn, start_qn, step_count,
          mx, my, timeline_x0, timeline_w, view_start_qn, qn_span, row_positions
        ) then
          drag.dirty = true
        end
      end
    else
      local drag_down = (drag.mode == "paint" and left_down) or (drag.mode == "erase" and right_down)
      if drag_down and mx >= timeline_x0 then
        local prev_min = drag.applied_min or drag.start_col
        local prev_max = drag.applied_max or drag.start_col
        local end_col = seq_param_mouse_col(mx, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, step_qn, step_count)
        local col_min = math.min(drag.start_col, end_col)
        local col_max = math.max(drag.start_col, end_col)
        if col_min < prev_min or col_max > prev_max then
          if apply_seq_note_lane_drag(drag, region, step_qn, start_qn, step_count, mx, timeline_x0, timeline_w, view_start_qn, qn_span) then
            drag.dirty = true
          end
        else
          drag.end_col = end_col
        end
      end
    end
  end

  param_drag_active = seq_param_drag_button_down(state.seq_param_drag, left_down, right_down)
      and state.seq_param_drag.region_id == region.id
  if param_drag_active then
    local drag = state.seq_param_drag
    local def = get_param_lane_def(drag.param)
    local lane_y0, lane_y1, lane_row
    if drag.source == "note" then
      lane_y0, lane_y1, lane_row = find_seq_note_lane_bounds(row_positions, drag.track_id)
    else
      lane_y0, lane_y1, lane_row = find_seq_param_lane_bounds(row_positions, drag.track_id, drag.param)
    end
    if def and lane_y0 and lane_row and not seq_is_decay_def(def) then
      if not drag.reset then
        if mod_active("velocity_ramp") and not drag.ramp then
          drag.ramp = true
          drag.unify = false
          local anchor = active_cells[drag.track_id] and active_cells[drag.track_id][drag.col]
          if anchor then
            drag.start_value = seq_note_param_value(anchor.note, def.key, seq_stutter_hit_index_at_qn(anchor.note, anchor.abs_qn, start_qn + drag.col * step_qn + step_qn * 0.5, step_qn))
            if drag.start_value == nil then
              drag.start_value = def.default
            end
          end
        elseif mod_active("unify") and not drag.ramp and not drag.unify then
          drag.unify = true
        end
      end

      local changed, current_value, highlight_col_min, highlight_col_max, mouse_col
      if drag.reset then
        changed, current_value, highlight_col_min, highlight_col_max, mouse_col = apply_seq_param_reset_drag(
          drag, def, mx, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells
        )
      else
        changed, current_value, highlight_col_min, highlight_col_max, mouse_col = apply_seq_param_lane_drag(
          drag, def, lane_y0, lane_y1, mx, my, step_qn, step_count, timeline_x0, timeline_w, view_start_qn, qn_span, start_qn, active_cells
        )
      end
      if changed then
        drag.dirty = true
      end

      local hx0 = math.max(timeline_x0, col_x0(highlight_col_min))
      local hx1 = math.min(timeline_x1, col_x1(highlight_col_max))
      if hx1 > hx0 then
        r.ImGui_DrawList_AddRectFilled(dl, hx0, lane_row.y0, hx1, lane_row.y1, 0xFFB84D44, 0)
        r.ImGui_DrawList_AddRect(dl, hx0, lane_row.y0, hx1, lane_row.y1, 0xFFB84DFF, 0, 0, 2.0)
      end

      if drag.ramp then
        local lane_top = lane_row.y0 + 2
        local lane_bot = lane_row.y1 - 2
        local start_val = drag.start_value or def.default
        local x0 = (col_x0(drag.col) + col_x1(drag.col)) * 0.5
        local x1 = (col_x0(drag.end_col) + col_x1(drag.end_col)) * 0.5
        local y0 = seq_param_y_from_value(def, start_val, lane_top, lane_bot, step_qn)
        local y1 = seq_param_y_from_value(def, current_value, lane_top, lane_bot, step_qn)
        r.ImGui_DrawList_AddLine(dl, x0, y0, x1, y1, 0xFFFFFFFF, 2.0)
        r.ImGui_DrawList_AddCircleFilled(dl, x0, y0, 3.0, 0xFFFFFFFF, 12)
        r.ImGui_DrawList_AddCircleFilled(dl, x1, y1, 3.0, 0xFFFFFFFF, 12)
      end

      local value_text
      if drag.reset then
        value_text = string.format("%s reset %s", def.label, string.format(def.fmt, def.default))
      elseif drag.ramp and drag.end_col ~= drag.col then
        value_text = string.format("%s ramp %s -> %s",
          def.label,
          string.format(def.fmt, drag.start_value or def.default),
          string.format(def.fmt, current_value))
      elseif drag.unify then
        value_text = string.format("%s unify %s", def.label, string.format(def.fmt, current_value))
      else
        local hover_active = active_cells[drag.track_id] and active_cells[drag.track_id][mouse_col]
        if hover_active then
          local hit_idx = seq_stutter_hit_index_at_qn(
            hover_active.note, hover_active.abs_qn,
            seq_x_to_qn(mx, timeline_x0, timeline_w, view_start_qn, qn_span),
            step_qn
          )
          local hover_val = seq_note_param_value(hover_active.note, def.key, hit_idx)
          value_text = format_seq_param_value(def, hover_val ~= nil and hover_val or current_value)
          if hit_idx then
            value_text = string.format("%s  ·  %d/%d", value_text, hit_idx, seq_stutter_count(hover_active.note))
          end
        else
          value_text = format_seq_param_value(def, current_value)
        end
      end
      local text_x = col_x0(mouse_col) + 4
      local text_y = lane_row.y0 - 16
      local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
      local text_w = text_size[1] or 0
      local text_h = text_size[2] or 0
      r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
      r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xFFB84DFF, 3.0, 0, 1.0)
      r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
    end
  end

  if note_drag_active and state.seq_note_drag and state.seq_note_drag.mode == "stutter" then
    local drag = state.seq_note_drag
    local count = drag.stutter or SEQ_STUTTER_MIN
    local length_qn = drag.length_qn or step_qn
    local value_text = string.format("Stutter ×%d over %.3g beats", count, length_qn)
    local text_size = { r.ImGui_CalcTextSize(ctx, value_text) }
    local text_w = text_size[1] or 0
    local text_h = text_size[2] or 0
    local text_x = mx + 12
    local text_y = my - 22
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xC9A8FFFF, 3.0, 0, 1.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, value_text)
  end

  local decay_readout = nil
  if note_drag_active and state.seq_note_drag and state.seq_note_drag.mode == "decay" then
    local drag = state.seq_note_drag
    if drag.handle == "end" then
      decay_readout = string.format("Length %.3g beats%s", drag.length_qn or 0, is_shift_down() and "  ·  free" or "")
    elseif drag.handle == "curve_in" or drag.handle == "curve_out" then
      local side = (drag.handle == "curve_in") and "in" or "out"
      decay_readout = string.format("Fade %s curve %+.2f  ·  %s", side, drag.fade_curve or 0, seq_fade_shape_name(drag.fade_shape))
    elseif drag.handle == "fade_in" then
      decay_readout = string.format("Fade in %.3g beats  ·  %s", drag.fade_qn or 0, seq_fade_shape_name(drag.fade_shape))
    else
      decay_readout = string.format("Fade out %.3g beats  ·  %s", drag.fade_qn or 0, seq_fade_shape_name(drag.fade_shape))
    end
  elseif seq_is_decay_def(edit_def) and not note_drag_active then
    local hit = seq_decay_hit_at(mx, my)
    if hit and hit.note then
      if hit.kind == "end" then
        decay_readout = string.format("Length %.3g beats", hit.note_len or 0)
      elseif hit.kind == "curve_in" then
        decay_readout = string.format("Fade in curve %+.2f  ·  %s", seq_note_fade_curve(hit.note, "in"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "in")))
      elseif hit.kind == "curve_out" then
        decay_readout = string.format("Fade out curve %+.2f  ·  %s", seq_note_fade_curve(hit.note, "out"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "out")))
      elseif hit.kind == "fade_in" then
        decay_readout = string.format("Fade in %.3g beats  ·  %s", seq_note_fade_qn(hit.note, "in"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "in")))
      else
        decay_readout = string.format("Fade out %.3g beats  ·  %s", seq_note_fade_qn(hit.note, "out"), seq_fade_shape_name(seq_note_fade_shape(hit.note, "out")))
      end
    end
  end
  if decay_readout then
    local text_size = { r.ImGui_CalcTextSize(ctx, decay_readout) }
    local text_w = text_size[1] or 0
    local text_h = text_size[2] or 0
    local text_x = mx + 12
    local text_y = my - 22
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddRect(dl, text_x - 3, text_y - 2, text_x + text_w + 3, text_y + text_h + 2, 0xFFD166FF, 3.0, 0, 1.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, decay_readout)
  end

  draw_seq_razors(dl, row_positions, timeline_x0, timeline_x1, view_start_qn, qn_span, step_qn, razor_hover_track_id, razor_hover_qn)

  local mouse_released = r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1)
  if r.ImGui_IsMouseReleased(ctx, 1) and state.seq_razor_drag and state.seq_razor_drag.mode ~= "move" then
    seq_commit_razor_drag(step_qn)
  end
  if r.ImGui_IsMouseReleased(ctx, 0) and state.seq_razor_drag and state.seq_razor_drag.mode == "move" then
    seq_commit_razor_drag(step_qn)
  end
  if r.ImGui_IsMouseReleased(ctx, 0) and state.seq_region_drag then
    local drag = state.seq_region_drag
    if drag.mode == "pool_copy" then
      local src = get_seq_region_by_id(drag.source_region_id)
      if src and drag.current_start_qn then
        local moved_qn = math.abs(drag.current_start_qn - (src.start_qn or 0.0)) >= step_qn * 0.25
        local moved_px = drag.start_mx and (math.abs(mx - drag.start_mx) > 4 or math.abs(my - drag.start_my) > 4)
        if moved_qn or moved_px then
          local label = begin_seq_undo(drag.undo_label or "Pool copy sequencer region")
          create_seq_region(drag.length_bars or src.length_bars, src, true, drag.current_start_qn)
          region = get_selected_seq_region()
          end_seq_undo(label)
        end
      end
    elseif drag.mode == "create" and drag.start_qn and drag.current_qn then
      local create_start = seq_snap_qn_for_region_drag(math.min(drag.start_qn, drag.current_qn), step_qn)
      local create_end = seq_snap_qn_for_region_drag(math.max(drag.start_qn, drag.current_qn), step_qn)
      local moved_px = drag.start_mx and (math.abs(mx - drag.start_mx) > 4 or math.abs(my - drag.start_my) > 4)
      local label = begin_seq_undo(drag.undo_label or "Create sequencer region")
      if not moved_px then
        create_seq_region(4, nil, false, drag.start_qn)
      elseif create_end - create_start < step_qn * 2 then
        create_seq_region(4, nil, false, create_start)
      else
        local bars = seq_qn_length_to_bars(create_start, create_end - create_start)
        create_seq_region(bars, nil, false, create_start)
      end
      region = get_selected_seq_region()
      end_seq_undo(label)
    elseif drag.undo_label and (drag.undo_started or seq_undo_is_open()) then
      end_seq_undo(drag.undo_label)
    end
    state.seq_region_drag = nil
  end
  if mouse_released then
    local note_drag = state.seq_note_drag
    if note_drag then
      if note_drag.dirty then
        if note_drag.mode == "stutter" or note_drag.mode == "decay" or note_drag.mode == "copy" or note_drag.mode == "move" then
          local seen = {}
          local function sync_one(region_id, track_id)
            local key = tostring(region_id or "") .. ":" .. tostring(track_id or "")
            if seen[key] then
              return
            end
            seen[key] = true
            local sync_region = get_seq_region_by_id(region_id) or region
            local sync_slot = seq_find_slot_by_id(track_id)
            if sync_region and sync_slot then
              sync_seq_pattern_track(sync_region.pattern_id, sync_slot, { force_rebuild = true })
            elseif sync_region then
              sync_seq_pattern_regions(sync_region.pattern_id)
            end
          end
          if note_drag.mode == "copy" or note_drag.mode == "move" then
            state.seq_force_item_crop = true
          end
          sync_one(note_drag.region_id, note_drag.track_id)
          if note_drag.mode == "copy" or note_drag.mode == "move" then
            sync_one(note_drag.dest_region_id, note_drag.dest_track_id)
            state.seq_force_item_crop = nil
          end
        end
        if seq_schedule_ingest_save then
          seq_schedule_ingest_save()
        else
          save_config()
        end
      end
      if note_drag.undo_open then
        local default_label = "Paint sequencer notes"
        if note_drag.mode == "erase" then
          default_label = "Erase sequencer notes"
        elseif note_drag.mode == "stutter" then
          default_label = "Create sequencer stutter"
        elseif note_drag.mode == "decay" then
          default_label = "Edit sequencer decay"
        elseif note_drag.mode == "copy" then
          default_label = "Copy sequencer note"
        elseif note_drag.mode == "move" then
          default_label = note_drag.place_new and "Insert sequencer note" or "Move sequencer note"
        end
        end_seq_undo(note_drag.undo_label or default_label)
      end
    end
    local param_drag = state.seq_param_drag
    if param_drag then
      if param_drag.lock_click_span and param_drag.reset then
        local param_region = get_seq_region_by_id(param_drag.region_id) or region
        local param_slot = seq_find_slot_by_id(param_drag.track_id)
        if param_region and param_slot then
          local lo, hi = seq_lock_span_cols(
            param_slot, param_drag.col, start_qn, step_qn, step_count, active_cells
          )
          if seq_apply_lock_range(param_region, param_drag.track_id, lo, hi, start_qn, step_qn, false, active_cells) then
            param_drag.dirty = true
          end
        end
      end
      if param_drag.dirty then
        local param_region = get_seq_region_by_id(param_drag.region_id) or region
        local param_slot = seq_find_slot_by_id(param_drag.track_id)
        if param_region and param_slot then
          sync_seq_pattern_track(param_region.pattern_id, param_slot, { force_rebuild = true })
        elseif param_region then
          sync_seq_pattern_regions(param_region.pattern_id)
        end
        if seq_schedule_ingest_save then
          seq_schedule_ingest_save()
        else
          save_config()
        end
      end
      if param_drag.undo_open then
        end_seq_undo(param_drag.undo_label or "Edit sequencer parameter")
      end
    end
    state.seq_note_drag = nil
    state.seq_param_drag = nil
  end

  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot then
      local track_idx = slot_id_to_idx[row.slot.id]
      if track_idx and row_pos.ctrl then
        local mix_changed, overlap_changed, mix_hovered = render_seq_track_mix_controls(
          dl, row.slot, row_pos.ctrl
        )
        if mix_hovered then
          over_lane_mix_controls = true
        end
        if mix_changed then
          begin_seq_undo("Adjust sequencer mix")
          seq_undo_commit_on_release = true
          seq_on_slot_mix_changed(row.slot, { resync = overlap_changed })
        end
      end
    end
  end

  if render_seq_midi_assign_popup() then
    save_config()
    if save_seq_project_state then save_seq_project_state() end
  end

  seq_random_flyout_begin_frame("lane")
  if not random_edit_region and state.seq_random_flyout and state.seq_random_flyout.host == "lane" then
    state.seq_random_flyout = nil
  end
  for _, row_pos in ipairs(row_positions) do
    local row = row_pos.row
    if row.type == "note" and row.slot then
      local track_idx = slot_id_to_idx[row.slot.id]
      if track_idx then
        if random_edit_region and random_edit_pattern then
          local random_settings = get_seq_track_settings(random_edit_pattern, row.slot.id, true)
          if random_settings then
            local changed, active_key, overlay_text, panel_x1, reseeded = seq_render_lane_random_controls(dl, row_pos, row.slot.id, random_settings, random_focus_effective, timeline_x0, header_y1, body_viewport_y1)
            if active_key then
              random_focus_next = active_key
              random_focus_effective = active_key
              random_overlay_text = overlay_text
              random_overlay_y = row_pos.y0
              random_overlay_x = panel_x1
            end
            if reseeded or changed then
              seq_queue_random_sync(random_edit_region.pattern_id, row.slot.id)
            end
            if changed then
              begin_seq_undo("Edit sequencer random")
              seq_undo_commit_on_release = true
            end
          end
        end
        local lane_h = row_pos.y1 - row_pos.y0
        r.ImGui_SetCursorScreenPos(ctx, timeline_x0 - map_nav_w - 4, row_pos.y0)
        r.ImGui_PushID(ctx, "seq_lane_nav_" .. row.slot.id)
        local nav = render_seq_track_sample_controls(row.slot, track_idx, {
          id_suffix = "seq_map_" .. row.slot.id,
          ctrl_size = map_ctrl_size,
          icon_size = map_icon_size,
          container_h = lane_h,
          y0 = row_pos.y0,
          y1 = row_pos.y1,
        })
        r.ImGui_PopID(ctx)
        if state.pending_waveform_drop then
          local row_drop_hovered = nav.row_drop_hovered
          if not row_drop_hovered and hovered and mx >= x0 and mx < timeline_x0
              and my >= row_pos.y0 and my <= row_pos.y1 then
            row_drop_hovered = true
          end
          if row_drop_hovered then
            state.seq_drop_target_idx = track_idx
            state.seq_timeline_drop_time = nil
            state.seq_timeline_drop_track_idx = nil
            draw_drop_target_highlight(dl, x0 + 1, row_pos.y0, timeline_x0 - 1, row_pos.y1, 3)
          end
        end
      end
    end
  end

  if mix_env_resync then
    -- Rebuild take envelopes after the drag frame so we don't resync every pixel.
    if not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
      local slot = env_resync_slot
      if not slot and state.seq_env_pending_resync_slot_id then
        slot = seq_find_slot_by_id(state.seq_env_pending_resync_slot_id)
      end
      if slot then
        sync_seq_slot_all_regions(slot, { force_rebuild = true })
      else
        seq_resync_all_regions()
      end
      state.seq_env_pending_resync = nil
      state.seq_env_pending_resync_slot_id = nil
    else
      state.seq_env_pending_resync = true
    end
  elseif state.seq_env_pending_resync
      and not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
    local slot = nil
    if state.seq_env_pending_resync_slot_id then
      slot = seq_find_slot_by_id(state.seq_env_pending_resync_slot_id)
    end
    if slot then
      sync_seq_slot_all_regions(slot, { force_rebuild = true })
    else
      seq_resync_all_regions()
    end
    state.seq_env_pending_resync = nil
    state.seq_env_pending_resync_slot_id = nil
  end

  state.seq_random_active_key = random_focus_next
  if not random_edit_region then
    state.seq_random_active_key = nil
  end
  if random_overlay_text and random_overlay_y then
    local text_w, text_h = r.ImGui_CalcTextSize(ctx, random_overlay_text)
    local text_x = (random_overlay_x or (timeline_x0 + 8)) + 8
    local text_y = random_overlay_y + 2
    r.ImGui_DrawList_AddRectFilled(dl, text_x - 3, text_y - 2, text_x + text_w + 4, text_y + text_h + 2, 0x000000CC, 3.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFE7A6DD, random_overlay_text)
  end

  if mouse_released or (state.seq_random_sync_pending and not state.seq_random_knob_drag) then
    state.seq_random_sync_run = true
  end
  if mouse_released and seq_undo_commit_on_release then
    if seq_undo_is_open() then
      end_seq_undo()
    end
    seq_undo_commit_on_release = false
  end

  r.ImGui_SetCursorScreenPos(ctx, x0, add_row_y0)
  if draw_ui_button("seq_add_track_popup_open_sequencer", nil, label_col_w, add_track_row_h, { icon = "plus", style = "primary" }) then
    open_seq_add_track_popup()
  end

  r.ImGui_Dummy(ctx, width, 0)

  render_seq_add_track_popup()
  r.ImGui_EndChild(ctx)

  -- Envelope editor + extras flyouts must live in the parent map window.
  -- Opening them inside the tracks child made ImGui treat the screen-space
  -- anchor as child-relative, so the editor jumped to a random place.
  if render_seq_env_editor_popup() then
    begin_seq_undo("Edit sequencer envelope")
    seq_undo_commit_on_release = true
    local popup_slot = nil
    for _, s in ipairs(state.seq_tracks or {}) do
      if s.id == state.seq_env_popup_slot_id then
        popup_slot = s
        break
      end
    end
    if popup_slot then
      seq_normalize_slot_mix(popup_slot)
    end
    if seq_schedule_ingest_save then
      seq_schedule_ingest_save()
    end
    if not (state.seq_env_graph_drag and state.seq_env_graph_drag.slot_id) then
      if popup_slot then
        sync_seq_slot_all_regions(popup_slot, { force_rebuild = true })
      else
        seq_resync_all_regions()
      end
      state.seq_env_pending_resync = nil
      state.seq_env_pending_resync_slot_id = nil
    else
      state.seq_env_pending_resync = true
      if popup_slot then
        state.seq_env_pending_resync_slot_id = popup_slot.id
      end
    end
  end
  if seq_undo_commit_on_release and r.ImGui_IsMouseReleased and
      (r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1)) then
    if seq_undo_is_open() then
      end_seq_undo()
    end
    seq_undo_commit_on_release = false
  end

  -- Flyout items must live in the parent map window. The tracks child clips
  -- mouse hits, so extras that overlap the pinned ruler would otherwise be inert.
  if random_edit_region and random_edit_pattern then
    local fly_slot = state.seq_random_flyout and state.seq_random_flyout.slot_id
    if seq_render_random_flyout(dl, random_edit_pattern, "lane") then
      begin_seq_undo("Edit sequencer random extras")
      seq_undo_commit_on_release = true
      seq_queue_random_sync(random_edit_region.pattern_id, fly_slot)
    end
    if r.ImGui_IsMouseReleased(ctx, 0) or r.ImGui_IsMouseReleased(ctx, 1) then
      if state.seq_random_sync_pending and not state.seq_random_knob_drag then
        state.seq_random_sync_run = true
      end
      if seq_undo_commit_on_release then
        if seq_undo_is_open() then
          end_seq_undo()
        end
        seq_undo_commit_on_release = false
      end
    end
  end

  render_seq_pattern_popup(region)
  r.ImGui_EndChild(ctx)
end


function render_view_tab_switcher()
  local icon_size = 15
  local btn_h = 28
  local pad_x = 10
  local icon_text_gap = 6
  local tab_gap = 3
  local track_pad = 3

  local function draw_sample_map_icon(dl, x0, y0, sz, color, accent)
    local pad = sz * 0.16
    local ix0 = x0 + pad
    local iy0 = y0 + pad
    local ix1 = x0 + sz - pad
    local iy1 = y0 + sz - pad
    local w = ix1 - ix0
    local h = iy1 - iy0
    r.ImGui_DrawList_AddRect(dl, ix0, iy0, ix1, iy1, color, 3.0, 0, 1.2)
    local mid_x = ix0 + w * 0.5
    local mid_y = iy0 + h * 0.5
    local cr, cg, cb = extract_rgb_rrgbbaa(color)
    local axis_color = build_color_rrgbbaa(cr, cg, cb, 70)
    r.ImGui_DrawList_AddLine(dl, mid_x, iy0 + 2, mid_x, iy1 - 2, axis_color, 1.0)
    r.ImGui_DrawList_AddLine(dl, ix0 + 2, mid_y, ix1 - 2, mid_y, axis_color, 1.0)
    local dots = {
      {0.20, 0.24, 2.2, accent},
      {0.58, 0.18, 1.6, color},
      {0.34, 0.56, 2.4, accent},
      {0.76, 0.58, 1.5, color},
      {0.16, 0.70, 1.8, color},
      {0.52, 0.80, 2.0, accent},
    }
    for _, dot in ipairs(dots) do
      r.ImGui_DrawList_AddCircleFilled(dl, ix0 + w * dot[1], iy0 + h * dot[2], dot[3], dot[4], 12)
    end
  end

  local function draw_sequencer_icon(dl, x0, y0, sz, color, accent)
    local pad = sz * 0.14
    local ix0 = x0 + pad
    local iy0 = y0 + pad
    local ix1 = x0 + sz - pad
    local iy1 = y0 + sz - pad
    local w = ix1 - ix0
    local h = iy1 - iy0
    local cols, rows, gap = 4, 3, 1.6
    local cell_w = (w - gap * (cols - 1)) / cols
    local cell_h = (h - gap * (rows - 1)) / rows
    local cr, cg, cb = extract_rgb_rrgbbaa(color)
    local inactive_color = build_color_rrgbbaa(cr, cg, cb, 90)
    local active_steps = { {1, 3}, {2, 1, 4}, {2, 3} }
    for row = 1, rows do
      for col = 1, cols do
        local cx0 = ix0 + (col - 1) * (cell_w + gap)
        local cy0 = iy0 + (row - 1) * (cell_h + gap)
        local is_active = false
        for _, active_col in ipairs(active_steps[row] or {}) do
          if active_col == col then is_active = true break end
        end
        if is_active then
          r.ImGui_DrawList_AddRectFilled(dl, cx0, cy0, cx0 + cell_w, cy0 + cell_h, accent, 2.0)
        else
          r.ImGui_DrawList_AddRect(dl, cx0, cy0, cx0 + cell_w, cy0 + cell_h, inactive_color, 2.0, 0, 1.0)
        end
      end
    end
  end

  local tabs = {
    { id = "sample_map", label = "Sample Map", icon = draw_sample_map_icon },
    { id = "sequencer", label = "Sequencer", icon = draw_sequencer_icon },
  }
  local widths = {}
  local total_w = track_pad * 2 + tab_gap * (#tabs - 1)
  for i, tab in ipairs(tabs) do
    local text_w = r.ImGui_CalcTextSize(ctx, tab.label)
    widths[i] = pad_x + icon_size + icon_text_gap + text_w + pad_x
    total_w = total_w + widths[i]
  end

  local track_x, track_y = r.ImGui_GetCursorScreenPos(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  ui_draw_panel(dl, track_x, track_y, track_x + total_w, track_y + btn_h, 9.0, UI_THEME.bg_panel, UI_THEME.border, false, false)
  local inner_h = btn_h
  r.ImGui_SetCursorScreenPos(ctx, track_x + track_pad, track_y)

  for i, tab in ipairs(tabs) do
    if i > 1 then
      r.ImGui_SameLine(ctx, 0, tab_gap)
    end
    local active = state.active_view == tab.id
    local clicked = r.ImGui_InvisibleButton(ctx, "##view_tab_" .. tab.id, widths[i], inner_h)
    local x0, y0 = r.ImGui_GetItemRectMin(ctx)
    local x1, y1 = r.ImGui_GetItemRectMax(ctx)
    local hovered = r.ImGui_IsItemHovered(ctx)
    local pressed = r.ImGui_IsItemActive(ctx)
    if clicked and state.active_view ~= tab.id then
      state.active_view = tab.id
      save_config()
    end

    local bg, border, icon_color, accent_color, text_color
    if active then
      bg = UI_THEME.accent_fill
      border = UI_THEME.accent
      icon_color = 0xF2F6FAFF
      accent_color = UI_THEME.accent_hvr
      text_color = 0xF2F6FAFF
    elseif hovered then
      bg = UI_THEME.surface_hvr
      border = UI_THEME.border_hvr
      icon_color = UI_THEME.text
      accent_color = UI_THEME.accent
      text_color = UI_THEME.text
    else
      bg = 0x00000000
      border = 0x00000000
      icon_color = UI_THEME.text_mute
      accent_color = 0x148A3AFF
      text_color = UI_THEME.text_dim
    end

    if active or hovered then
      ui_draw_panel(dl, x0, y0, x1, y1, inner_h * 0.5, bg, border, hovered, pressed)
    end

    local icon_x0 = x0 + pad_x
    local icon_y0 = y0 + (inner_h - icon_size) * 0.5 + (pressed and 1.0 or 0.0)
    tab.icon(dl, icon_x0, icon_y0, icon_size, icon_color, accent_color)
    local text_w, text_h = r.ImGui_CalcTextSize(ctx, tab.label)
    local text_x = icon_x0 + icon_size + icon_text_gap
    local text_y = y0 + (inner_h - text_h) * 0.5 + (pressed and 1.0 or 0.0)
    r.ImGui_DrawList_AddText(dl, text_x, text_y, text_color, tab.label)
  end
end

function render_filter_input()
  local function draw_search_icon(dl, x, y, height, color)
    local size = math.min(height - 4, 16)
    local lens_r = size * 0.32
    local cx = x + size * 0.45
    local cy = y + height * 0.5
    r.ImGui_DrawList_AddCircle(dl, cx, cy, lens_r, color, 16, 1.4)
    local hx = cx + lens_r * 0.62
    local hy = cy + lens_r * 0.62
    r.ImGui_DrawList_AddLine(dl, hx, hy, hx + size * 0.30, hy + size * 0.30, color, 1.6)
  end

  local function collect_active_tags_in_display_order()
    local ordered = {}
    if not state.active_tags or next(state.active_tags) == nil then
      return ordered
    end

    for tag, active in pairs(state.active_tags) do
      if active then
        ordered[#ordered + 1] = tag
      end
    end

    table.sort(ordered, function(a, b)
      return string.lower(a) < string.lower(b)
    end)

    return ordered
  end

  local function calc_tag_button_width(label)
    local text_w = r.ImGui_CalcTextSize(ctx, label)
    local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
    return text_w + (frame_padding[1] or 4) * 2
  end

  local function calc_compact_button_width(label)
    local text_w = r.ImGui_CalcTextSize(ctx, label)
    local frame_padding = {r.ImGui_GetStyleVar(ctx, r.ImGui_StyleVar_FramePadding())}
    return text_w + ((frame_padding[1] or 4) * 0.65) * 2
  end

  local avail_x = r.ImGui_GetContentRegionAvail(ctx)
  local loop_reserve = 132
  local filter_width
  if avail_x > 300 then
    filter_width = math.max(180, math.min(280, avail_x - loop_reserve))
  else
    filter_width = math.max(140, math.min(280, avail_x - 8))
  end
  local filter_height = 26
  local icon_pad = 22
  local min_input_width = 72
  local spacing = 4
  local all_active_tags = collect_active_tags_in_display_order()
  local has_active_tags = #all_active_tags > 0
  local active_tags = {}
  for _, tag in ipairs(all_active_tags) do
    if not should_hide_active_tag_in_search_bar(tag) then
      active_tags[#active_tags + 1] = tag
    end
  end
  local clear_label = "Clear"

  local child_flags = 0
  if r.ImGui_ChildFlags_Border then
    child_flags = r.ImGui_ChildFlags_Border
  end
  local child_window_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()

  r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_WindowPadding(), 0, 0)
  if r.ImGui_BeginChild(ctx, "sample_filter_field", filter_width, filter_height, 0, child_window_flags) then
    local dl = r.ImGui_GetWindowDrawList(ctx)
    local x0, y0 = r.ImGui_GetWindowPos(ctx)
    local hovered_field = r.ImGui_IsWindowHovered(ctx)
    ui_draw_panel(
      dl, x0, y0, x0 + filter_width, y0 + filter_height, filter_height * 0.5,
      hovered_field and UI_THEME.surface_hvr or UI_THEME.surface,
      hovered_field and UI_THEME.border_hvr or UI_THEME.border,
      hovered_field, false
    )
    draw_search_icon(dl, x0 + 6, y0 + 3, filter_height - 6, hovered_field and UI_THEME.text_dim or UI_THEME.text_mute)

    local clear_width = has_active_tags and calc_compact_button_width(clear_label) or 0
    local region_width = r.ImGui_GetContentRegionAvail(ctx)
    local max_tag_area = region_width - icon_pad - min_input_width
    if has_active_tags then
      max_tag_area = max_tag_area - clear_width - spacing
    end
    max_tag_area = math.max(0, max_tag_area)

    local visible_tags = {}
    local used_width = 0
    for _, tag in ipairs(active_tags) do
      local tag_width = calc_tag_button_width(tag)
      local extra_spacing = (#visible_tags > 0) and spacing or 0
      if used_width + extra_spacing + tag_width <= max_tag_area then
        visible_tags[#visible_tags + 1] = tag
        used_width = used_width + extra_spacing + tag_width
      else
        break
      end
    end

    local hidden_count = #active_tags - #visible_tags
    if hidden_count > 0 then
      local hidden_label = "+" .. tostring(hidden_count)
      local hidden_width = calc_tag_button_width(hidden_label)
      local extra_spacing = (#visible_tags > 0) and spacing or 0
      while #visible_tags > 0 and used_width + extra_spacing + hidden_width > max_tag_area do
        local removed = table.remove(visible_tags)
        used_width = used_width - calc_tag_button_width(removed)
        if #visible_tags > 0 then
          used_width = used_width - spacing
        end
        hidden_count = hidden_count + 1
        hidden_label = "+" .. tostring(hidden_count)
        hidden_width = calc_tag_button_width(hidden_label)
        extra_spacing = (#visible_tags > 0) and spacing or 0
      end
      if used_width + extra_spacing + hidden_width <= max_tag_area then
        visible_tags[#visible_tags + 1] = hidden_label
      end
    end

    r.ImGui_SetCursorPosX(ctx, icon_pad)
    r.ImGui_SetCursorPosY(ctx, 3)
    local first_item = true
    for _, tag in ipairs(visible_tags) do
      if not first_item then
        r.ImGui_SameLine(ctx, 0, spacing)
      end
      first_item = false
      if tag:sub(1, 1) == "+" then
        draw_tag_button(ctx, tag, false, "__hidden_tags__", "filter_active_")
      else
        if draw_tag_button(ctx, tag, true, tag, "filter_active_") then
          state.active_tags[tag] = nil
        end
      end
    end

    if has_active_tags then
      if not first_item then
        r.ImGui_SameLine(ctx, 0, spacing)
      end
      if draw_ui_button("filter_clear_active_tags", clear_label, nil, nil, { compact = true, style = "danger" }) then
        state.active_tags = {}
        state.selected_tag_parents = {}
      end
      first_item = false
    end

    if not first_item then
      r.ImGui_SameLine(ctx, 0, spacing)
    end
    local input_width = math.max(min_input_width, r.ImGui_GetContentRegionAvail(ctx))
    r.ImGui_SetNextItemWidth(ctx, input_width)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBg(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgHovered(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_FrameBgActive(), 0x00000000)
    r.ImGui_PushStyleColor(ctx, r.ImGui_Col_Border(), 0x00000000)

    local ret, input
    if r.ImGui_InputTextWithHint then
      ret, input = r.ImGui_InputTextWithHint(ctx, "##sample_filter", has_active_tags and "Type to refine..." or "Search samples...", state.filter)
    else
      ret, input = r.ImGui_InputText(ctx, "##sample_filter", state.filter, 256)
    end
    r.ImGui_PopStyleColor(ctx, 4)

    if ret then
      state.filter = input
    end

    r.ImGui_EndChild(ctx)
  end
  r.ImGui_PopStyleVar(ctx)
end

function render_header()
  if not r.ImGui_BeginMenuBar(ctx) then
    return
  end

  if r.ImGui_BeginMenu(ctx, "Library") then
    if r.ImGui_MenuItem(ctx, "Rescan") then
      enqueue_scan()
      log("Manual rescan triggered")
    end
    if r.ImGui_MenuItem(ctx, "Scan for Incomplete") then
      enqueue_incomplete_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Effective Range") then
      enqueue_effective_range_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Transient/Sustain") then
      enqueue_transient_sustain_analysis()
    end
    if r.ImGui_MenuItem(ctx, "Scan for Loop / One-shot") then
      enqueue_playback_type_analysis()
    end
    r.ImGui_Separator(ctx)
    if r.ImGui_MenuItem(ctx, "Clear All Folders and Samples") then
      state.folders = {}
      filter_samples_by_folders()  -- This will clear samples and tag data
      state.scan_queue = {}
      clear_sample_cache()
      save_config()
      log("Cleared folders and samples")
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_BeginMenu(ctx, "Tools") then
    if r.ImGui_MenuItem(ctx, "Copy Scan Logs") then
      local logs_text = get_scan_logs_text()
      if logs_text and logs_text ~= "" then
        r.ImGui_SetClipboardText(ctx, logs_text)
        log("Scan logs copied to clipboard (" .. tostring(#state.scan_logs) .. " entries)")
      else
        log("No scan logs to copy")
      end
    end
    if r.ImGui_MenuItem(ctx, "Debug Sample Coordinates") then
      log("=== DEBUG: Sample Coordinates ===")
      log("Total samples: " .. #state.samples)
      if #state.samples > 0 then
        local x_min, x_max = state.samples[1].x or 0.5, state.samples[1].x or 0.5
        local y_min, y_max = state.samples[1].y or 0.5, state.samples[1].y or 0.5
        local freq_min, freq_max = state.samples[1].dominant_freq or 440.0, state.samples[1].dominant_freq or 440.0
        local rms_min, rms_max = state.samples[1].rms_energy or 0.0, state.samples[1].rms_energy or 0.0
        local size_min, size_max = state.samples[1].file_size or 0, state.samples[1].file_size or 0
        for i, s in ipairs(state.samples) do
          local x = s.x or 0.5
          local y = s.y or 0.5
          local freq = s.dominant_freq or 440.0
          local rms = s.rms_energy or 0.0
          local size = s.file_size or 0
          log(string.format("Sample %d: name='%s', freq=%.1f Hz, rms=%.6f, size=%d bytes, x=%.6f, y=%.6f",
              i, s.name or "unknown", freq, rms, size, x, y))
          x_min = math.min(x_min, x)
          x_max = math.max(x_max, x)
          y_min = math.min(y_min, y)
          y_max = math.max(y_max, y)
          freq_min = math.min(freq_min, freq)
          freq_max = math.max(freq_max, freq)
          rms_min = math.min(rms_min, rms)
          rms_max = math.max(rms_max, rms)
          size_min = math.min(size_min, size)
          size_max = math.max(size_max, size)
        end
        log("--- Summary ---")
        log(string.format("X range: %.6f to %.6f (span: %.6f)", x_min, x_max, x_max - x_min))
        log(string.format("Y range: %.6f to %.6f (span: %.6f)", y_min, y_max, y_max - y_min))
        log(string.format("Frequency range: %.1f Hz to %.1f Hz", freq_min, freq_max))
        log(string.format("RMS range: %.6f to %.6f", rms_min, rms_max))
        log(string.format("File size range: %d to %d bytes", size_min, size_max))
      else
        log("No samples to debug")
      end
      log("=== End Debug ===")
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_BeginMenu(ctx, "View") then
    if r.ImGui_BeginMenu(ctx, "Collapse Children Tags") then
      local mode = state.collapse_children_tags or "off"
      if r.ImGui_MenuItem(ctx, "Off", nil, mode == "off") then
        set_collapse_children_tags_mode("off")
      end
      if r.ImGui_MenuItem(ctx, "On", nil, mode == "on") then
        set_collapse_children_tags_mode("on")
      end
      if r.ImGui_MenuItem(ctx, "Dynamic", nil, mode == "dynamic") then
        set_collapse_children_tags_mode("dynamic")
      end
      if r.ImGui_IsItemHovered(ctx) then
        local threshold = state.collapse_children_tags_width or 1100
        r.ImGui_SetTooltip(ctx, string.format(
          "On when the window is %.0f px wide or narrower.\nChange this width in Settings.",
          threshold
        ))
      end
      r.ImGui_EndMenu(ctx)
    end
    r.ImGui_EndMenu(ctx)
  end

  if r.ImGui_MenuItem(ctx, "Settings", nil, state.settings_open) then
    state.settings_open = not state.settings_open
  end

  local midi_h = 18
  local midi_w = seq_midi_arm_button_width(midi_h)
  local remain = r.ImGui_GetContentRegionAvail(ctx)
  if type(remain) == "number" and remain > midi_w + 16 then
    r.ImGui_SameLine(ctx)
    r.ImGui_Dummy(ctx, remain - midi_w - 10, 1)
  end
  r.ImGui_SameLine(ctx)
  render_seq_midi_arm_icon_button("seq_midi_arm_menubar", midi_h)

  r.ImGui_EndMenuBar(ctx)
end


function settings_section(label, default_open)
  state.settings_section_open = state.settings_section_open or {}
  if state.settings_section_open[label] == nil then
    state.settings_section_open[label] = default_open and true or false
  end
  local open = state.settings_section_open[label] and true or false
  local w = r.ImGui_GetContentRegionAvail(ctx)
  local h = 28
  r.ImGui_InvisibleButton(ctx, "##sec_" .. label, w, h)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local active = r.ImGui_IsItemActive(ctx)
  if r.ImGui_IsItemClicked(ctx, 0) then
    open = not open
    state.settings_section_open[label] = open
  end
  local x0, y0 = r.ImGui_GetItemRectMin(ctx)
  local x1, y1 = r.ImGui_GetItemRectMax(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local bg = open and UI_THEME.accent_fill or (hovered and UI_THEME.surface_hvr or UI_THEME.surface)
  local border = open and UI_THEME.accent or (hovered and UI_THEME.border_hvr or UI_THEME.border)
  ui_draw_panel(dl, x0, y0, x1, y1, 7.0, bg, border, hovered, active)
  local cy = (y0 + y1) * 0.5 + (active and 1.0 or 0.0)
  ui_button_draw_icon(dl, open and "chev_down" or "chev_right", x0 + 14, cy, 14, open and UI_THEME.accent_hvr or UI_THEME.text_dim)
  local tw, th = r.ImGui_CalcTextSize(ctx, label)
  r.ImGui_DrawList_AddText(dl, x0 + 28, cy - th * 0.5, open and UI_THEME.text or UI_THEME.text_dim, label)
  return open
end

function settings_render_scan_folders()
  if draw_ui_button("settings_add_folder", "Add Folder", nil, nil, { style = "primary" }) then
    local new_folder = ""

    -- Try JS_Dialog_BrowseForFolder first (from JS_ReaScriptAPI extension)
    if r.APIExists("JS_Dialog_BrowseForFolder") then
      local retval, selectedFolder = r.JS_Dialog_BrowseForFolder("Choose folder to scan", "")
      if retval == 1 and selectedFolder and selectedFolder ~= "" then
        new_folder = selectedFolder
        log("JS_Dialog_BrowseForFolder returned: " .. tostring(selectedFolder))
      else
        log("JS_Dialog_BrowseForFolder cancelled or failed. retval=" .. tostring(retval))
      end
    else
      log("JS_Dialog_BrowseForFolder not available - JS_ReaScriptAPI extension may not be installed")
    end

    -- Only show fallback dialog if JS dialog didn't work
    if new_folder == "" and not r.APIExists("JS_Dialog_BrowseForFolder") then
      r.ShowMessageBox("JS_ReaScriptAPI extension is required for folder browsing.\n\nPlease install it via ReaPack:\nExtensions > ReaPack > Browse Packages > Search for 'js_ReaScriptAPI'", "Extension Required", 0)
    end

    -- Normalize and validate folder path before adding
    if new_folder and new_folder ~= "" then
      new_folder = normalize_path(new_folder)
      if string.len(new_folder) < 2 or new_folder:match("^%d+$") then
        r.ShowMessageBox("Invalid folder path: " .. new_folder .. "\n\nPlease select a valid folder.", "Error", 0)
        log("Rejected invalid folder path: " .. new_folder)
      else
        local exists = false
        for _, f in ipairs(state.folders) do
          if f == new_folder then exists = true break end
        end
        if not exists then
          table.insert(state.folders, new_folder)
          refresh_scan_folder_availability()
          save_config()
          log("Added folder: " .. new_folder)
        else
          log("Folder already in list: " .. new_folder)
        end
      end
    end
  end

  if #state.folders > 0 then
    r.ImGui_SameLine(ctx)
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, string.format("%d folder%s", #state.folders, #state.folders == 1 and "" or "s"))

    local child_flags = 0
    if r.ImGui_ChildFlags_Border then child_flags = r.ImGui_ChildFlags_Border end

    -- Size the list to its contents (capped) so there is no large empty area.
    local row_h = r.ImGui_GetTextLineHeightWithSpacing(ctx)
    local visible_rows = math.min(#state.folders, 8)
    local list_h = visible_rows * row_h + 10
    if r.ImGui_BeginChild(ctx, "folder_list", 0, list_h, child_flags) then
      for idx, folder in ipairs(state.folders) do
        if draw_ui_button("settings_remove_folder_" .. idx, "Remove", nil, nil, { style = "danger", compact = true }) then
          table.remove(state.folders, idx)
          filter_samples_by_folders()
          refresh_scan_folder_availability()
          save_config()
          break
        end
        r.ImGui_SameLine(ctx)
        if draw_ui_button("settings_rescan_folder_" .. idx, "Rescan", nil, nil, { style = "primary", compact = true }) then
          enqueue_scan(folder)
        end
        r.ImGui_SameLine(ctx)
        r.ImGui_AlignTextToFramePadding(ctx)
        local norm_folder = normalize_path(folder)
        local vol = volume_root_from_path(norm_folder)
        local offline = (vol and state.missing_volumes[vol])
          or state.missing_scan_folders[norm_folder]
        if offline then
          r.ImGui_TextColored(ctx, UI_THEME.text_dim, folder .. "  (offline)")
        else
          r.ImGui_Text(ctx, folder)
        end
      end
      r.ImGui_EndChild(ctx)
    end
  else
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, "No folders yet. Click Add Folder to add scan folders.")
  end
end

