function settings_render_tag_layout()
  r.ImGui_Text(ctx, "Collapse children tags")
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "When on, Drum / Melodic / Genre sit on the search row. Select a parent to reveal its child tags on the right; they wrap to the next line if needed.")
  r.ImGui_Spacing(ctx)

  local mode = state.collapse_children_tags or "off"
  if draw_ui_radio("collapse_off", "Off", mode == "off") then
    set_collapse_children_tags_mode("off")
  end
  if draw_ui_radio("collapse_on", "On", mode == "on") then
    set_collapse_children_tags_mode("on")
  end
  if draw_ui_radio("collapse_dyn", "Dynamic (by window width)", mode == "dynamic") then
    set_collapse_children_tags_mode("dynamic")
  end

  r.ImGui_Spacing(ctx)
  r.ImGui_Text(ctx, "Dynamic width threshold")
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "In Dynamic mode, children tags collapse when the window is this wide or narrower.")
  local changed, width = draw_ui_number("collapse_width", "Window width (px)", state.collapse_children_tags_width or 1100, 10.0, 50.0, "%.0f", 400, 4000)
  if changed then
    state.collapse_children_tags_width = math.max(400, math.min(4000, width))
    save_config()
  end

  local current_w = state.main_window_rect and state.main_window_rect.w
  if current_w then
    local collapsed_now = collapse_children_tags_active()
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, string.format(
      "Current window width: %.0f px (%s)",
      current_w,
      collapsed_now and "collapsed" or "expanded"
    ))
  end
end

function settings_render_tag_colors()
  -- Load tag presets
  local tag_presets = {}
  local preset_file = io.open(CONFIG_DIR .. "/tag_presets.lua", "r")
  if preset_file then
    local content = preset_file:read("*all")
    preset_file:close()
    local success, presets = pcall(load, content)
    if success and type(presets) == "function" then
      tag_presets = presets() or {}
    end
  end

  local preset_names = {}
  for name, _ in pairs(tag_presets) do
    table.insert(preset_names, name)
  end
  table.sort(preset_names)

  if #preset_names > 0 then
    r.ImGui_Text(ctx, "Presets:")
    r.ImGui_SameLine(ctx)
    if draw_ui_button("settings_load_preset", "Load Preset") then
      r.ImGui_OpenPopup(ctx, "select_tag_preset")
    end

    if r.ImGui_BeginPopup(ctx, "select_tag_preset") then
      for _, preset_name in ipairs(preset_names) do
        if r.ImGui_Selectable(ctx, preset_name) then
          local preset = tag_presets[preset_name]
          if preset then
            for tag, color in pairs(preset) do
              state.tag_colors[tag] = color
            end
            state.current_preset_name = preset_name
            save_config()
          end
        end
      end
      r.ImGui_EndPopup(ctx)
    end
    r.ImGui_SameLine(ctx)
    r.ImGui_Text(ctx, "|")
    r.ImGui_SameLine(ctx)
  end

  if draw_ui_button("settings_save_preset", "Save as Preset") then
    r.ImGui_OpenPopup(ctx, "save_tag_preset")
  end

  if r.ImGui_BeginPopup(ctx, "save_tag_preset") then
    r.ImGui_Text(ctx, "Preset Name:")
    local preset_name = ""
    local changed, new_name = r.ImGui_InputText(ctx, "##preset_name", preset_name, 0)
    if changed then
      preset_name = new_name
    end

    if draw_ui_button("settings_save_preset_confirm", "Save") and preset_name ~= "" then
      tag_presets[preset_name] = {}
      for tag, color in pairs(state.tag_colors) do
        tag_presets[preset_name][tag] = color
      end
      state.current_preset_name = preset_name

      local preset_content = "return " .. serialize_table(tag_presets)
      local out_file = io.open(CONFIG_DIR .. "/tag_presets.lua", "w")
      if out_file then
        out_file:write(preset_content)
        out_file:close()
      end

      r.ImGui_CloseCurrentPopup(ctx)
    end
    r.ImGui_EndPopup(ctx)
  end

  r.ImGui_Spacing(ctx)

  local sorted_tags = {}
  for tag, _ in pairs(state.tag_colors) do
    table.insert(sorted_tags, tag)
  end
  table.sort(sorted_tags)

  for _, tag in ipairs(sorted_tags) do
    local tag_color = state.tag_colors[tag]
    local color_changed, new_color = draw_ui_color("tag_color_" .. tag, tag, tag_color)
    if color_changed then
      state.tag_colors[tag] = new_color & 0xFFFFFF
      save_config()
    end
  end
end

function settings_render_sequencer_controls()
  r.ImGui_Text(ctx, "Track folder")
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "New tracks created by this script go in a '" .. SEQ_TRACK_FOLDER_NAME .. "' folder in the TCP.")
  r.ImGui_Spacing(ctx)
  local group_on = state.group_seq_tracks_in_folder ~= false
  local group_changed, group_v = draw_ui_checkbox("settings_group_seq_folder", "Group sequencer tracks in a folder", group_on)
  if group_changed then
    state.group_seq_tracks_in_folder = group_v and true or false
    save_config()
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Turn off to create tracks at the end of the project instead.")
  end

  r.ImGui_Spacing(ctx)
  local peek_on = state.seq_follow_hovered_item == true
  local peek_changed, peek_v = draw_ui_checkbox(
    "settings_follow_hovered_item",
    "Follow hovered notes in the arrange",
    peek_on
  )
  if peek_changed then
    state.seq_follow_hovered_item = peek_v and true or false
    save_config()
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "When a sequencer note is hovered, scroll its track into view and highlight the audio item.")
  end

  r.ImGui_Spacing(ctx)
  r.ImGui_Separator(ctx)
  r.ImGui_Spacing(ctx)

  r.ImGui_Text(ctx, "Mouse wheel scrolling")
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "How the wheel behaves over the sequencer timeline. Shift+horizontal scroll zooms the timeline.")
  r.ImGui_Spacing(ctx)

  if draw_ui_radio("seq_scroll_classic", "Vertical wheel scrolls the timeline (classic)", state.seq_scroll_mode ~= "natural") then
    if state.seq_scroll_mode ~= "v_as_h" then
      state.seq_scroll_mode = "v_as_h"
      save_config()
    end
  end
  if draw_ui_radio("seq_scroll_natural", "Vertical wheel scrolls tracks, horizontal wheel scrolls timeline", state.seq_scroll_mode == "natural") then
    if state.seq_scroll_mode ~= "natural" then
      state.seq_scroll_mode = "natural"
      save_config()
    end
  end
  if r.ImGui_IsItemHovered(ctx) then
    r.ImGui_SetTooltip(ctx, "Best for trackpads and the Magic Mouse, which can send a horizontal wheel.")
  end

  r.ImGui_Spacing(ctx)
  r.ImGui_Separator(ctx)
  r.ImGui_Spacing(ctx)

  r.ImGui_Text(ctx, "Mouse modifiers")
  r.ImGui_TextColored(ctx, UI_THEME.text_dim, "Assign which key activates each sequencer gesture.")
  r.ImGui_Spacing(ctx)

  state.mouse_mods = state.mouse_mods or {}
  for _, action in ipairs(MOUSE_MOD_ACTIONS) do
    local current = state.mouse_mods[action.id] or MOUSE_MOD_DEFAULTS[action.id] or "none"
    local combo_changed, choice = draw_ui_combo(
      "mmod_" .. action.id,
      action.label,
      mouse_mod_label(current),
      MOUSE_MOD_CHOICES,
      current,
      mouse_mod_label
    )
    if combo_changed then
      state.mouse_mods[action.id] = choice
      save_config()
    end
    if r.ImGui_IsItemHovered(ctx) and action.hint then
      r.ImGui_SetTooltip(ctx, action.hint)
    end
  end

  r.ImGui_Spacing(ctx)
  if draw_ui_button("settings_reset_mouse_mods", "Reset to defaults", nil, nil, { compact = true }) then
    state.seq_scroll_mode = "v_as_h"
    state.mouse_mods = {}
    for k, v in pairs(MOUSE_MOD_DEFAULTS) do
      state.mouse_mods[k] = v
    end
    save_config()
  end
end

function render_settings()
  if not state.settings_open then
    return
  end

  r.ImGui_SetNextWindowSize(ctx, 560, 640, r.ImGui_Cond_FirstUseEver())
  local visible, open = r.ImGui_Begin(ctx, "Settings", true, r.ImGui_WindowFlags_None())

  if visible then
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 8, 6)
    r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 6, 4)

    if settings_section("Scan Folders", true) then
      r.ImGui_Spacing(ctx)
      settings_render_scan_folders()
      r.ImGui_Spacing(ctx)
    end

    if settings_section("Dot Appearance", false) then
      r.ImGui_Spacing(ctx)
      settings_render_dot_appearance()
      r.ImGui_Spacing(ctx)
    end

    if settings_section("Tag Layout", false) then
      r.ImGui_Spacing(ctx)
      settings_render_tag_layout()
      r.ImGui_Spacing(ctx)
    end

    if settings_section("Tag Colors", false) then
      r.ImGui_Spacing(ctx)
      settings_render_tag_colors()
      r.ImGui_Spacing(ctx)
    end

    if settings_section("Sequencer Controls", true) then
      r.ImGui_Spacing(ctx)
      settings_render_sequencer_controls()
      r.ImGui_Spacing(ctx)
    end

    r.ImGui_Spacing(ctx)
    r.ImGui_Separator(ctx)
  r.ImGui_TextColored(ctx, UI_THEME.text_mute, "Settings are saved globally and persist across projects.")

    r.ImGui_PopStyleVar(ctx, 2)
  end

  r.ImGui_End(ctx)

  -- Update settings_open state based on window open state
  if not open then
    state.settings_open = false
  end
end


function draw_map_status_overlay(dl, x0, y0, width, height)
  if #state.scan_queue > 0 then
    return
  end
  if (state.incomplete_analysis_total or 0) > 0
      and (#state.analyzer_queue > 0 or #state.active_processes > 0) then
    return
  end

  local lines = {}
  if #state.samples == 0 then
    lines[#lines + 1] = "Press Rescan to populate the map."
    if #state.folders > 0 then
      lines[#lines + 1] = "Folders configured: " .. #state.folders
    end
  else
    local filtered_count = map_cache.filtered_count or #state.samples
    if map_cache.dots_capped then
      lines[#lines + 1] = string.format(
        "Showing %d of %d in view (Zoom: %.1fx)",
        map_cache.draw_count or 0,
        map_cache.visible_total or 0,
        state.zoom
      )
    elseif filtered_count < #state.samples then
      lines[#lines + 1] = string.format(
        "Showing %d of %d samples (Zoom: %.1fx)",
        filtered_count,
        #state.samples,
        state.zoom
      )
    else
      lines[#lines + 1] = string.format("Showing %d samples on map (Zoom: %.1fx)", #state.samples, state.zoom)
    end
    local missing_volume_count = 0
    for _ in pairs(state.missing_volumes or {}) do
      missing_volume_count = missing_volume_count + 1
    end
    local missing_folder_count = 0
    for _ in pairs(state.missing_scan_folders) do
      missing_folder_count = missing_folder_count + 1
    end
    if missing_volume_count > 0 then
      lines[#lines + 1] = string.format(
        "%d removable drive(s) offline — gray dots unavailable",
        missing_volume_count
      )
    elseif missing_folder_count > 0 then
      lines[#lines + 1] = string.format(
        "%d scan folder(s) offline — gray dots unavailable",
        missing_folder_count
      )
    end
    if state.selected then
      lines[#lines + 1] = "Selected: " .. state.selected.name
    end
  end

  if #lines == 0 then
    return
  end

  local line_h = 16.0
  local padding = 8.0
  local text_y = y0 + height - (#lines * line_h) - padding
  for i, line in ipairs(lines) do
    local ty = text_y + (i - 1) * line_h
    r.ImGui_DrawList_AddText(dl, x0 + padding + 1, ty + 1, 0x000000AA, line)
    r.ImGui_DrawList_AddText(dl, x0 + padding, ty, 0xCCCCCCFF, line)
  end
end

function clamp_map_pan(width, height)
  local max_pan = width * 0.5 * state.zoom
  state.pan_x = math.max(-max_pan, math.min(max_pan, state.pan_x))
  local min_pan_y = height * 0.5 * (1 - state.zoom)
  local max_pan_y = height * 0.5 * (state.zoom - 1)
  state.pan_y = math.max(min_pan_y, math.min(max_pan_y, state.pan_y))
end

-- Don't treat a click as drag-audition until the mouse has moved this far.
-- Also ignores motion that happened while a slow preview was blocking.
local MAP_AUDITION_DRAG_THRESHOLD_SQ = 8 * 8

local function clear_map_left_press()
  state.map_press_x = nil
  state.map_press_y = nil
  state.map_press_pending = false
  state.map_audition_rearm = false
end

local function update_map_audition_drag(mx, my)
  if not r.ImGui_IsMouseDown(ctx, 0) then
    if not state.is_left_dragging and not state.pending_waveform_drop then
      clear_map_left_press()
    end
    return
  end
  if state.is_left_dragging or state.pending_waveform_drop or state.is_dragging then
    return
  end
  -- After a blocking preview, recapture origin on the next frame so mouse
  -- movement during disk load does not start a drag-audition.
  if state.map_audition_rearm then
    state.map_press_x = mx
    state.map_press_y = my
    state.map_press_pending = true
    state.map_audition_rearm = false
    return
  end
  if not state.map_press_pending then
    return
  end
  local dx = mx - (state.map_press_x or mx)
  local dy = my - (state.map_press_y or my)
  if dx * dx + dy * dy >= MAP_AUDITION_DRAG_THRESHOLD_SQ then
    state.is_left_dragging = true
  end
end

function handle_map_view_input(hovered, mx, my, width, height, x0, y0)
  local right_clicked = r.ImGui_IsMouseClicked(ctx, 1)  -- Right mouse button
  local right_down = r.ImGui_IsMouseDown(ctx, 1)
  local right_released = r.ImGui_IsMouseReleased(ctx, 1)
  -- Note: left_clicked detection moved to sample selection logic to prevent double detection
  
  -- Handle right-click drag for panning
  if hovered and right_clicked then
    -- Start right drag
    state.is_dragging = true
    state.is_left_dragging = false  -- Cancel left drag if right drag starts
    clear_map_left_press()
    state.drag_start_x = mx
    state.drag_start_y = my
    state.drag_start_pan_x = state.pan_x
    state.drag_start_pan_y = state.pan_y
  elseif state.is_dragging and right_down then
    -- Continue right drag
    local dx = mx - state.drag_start_x
    local dy = my - state.drag_start_y
    state.pan_x = state.drag_start_pan_x + dx
    state.pan_y = state.drag_start_pan_y + dy

    clamp_map_pan(width, height)
    -- Don't save during drag - only save when drag ends
  elseif right_released then
    -- End right drag
    state.is_dragging = false
    state.drag_start_x = nil
    state.drag_start_y = nil
    -- Pan position not saved
  end
  
  -- Handle left-click: preview on click, drag-audition only after movement threshold
  local left_clicked = r.ImGui_IsMouseClicked(ctx, 0)  -- Left mouse button (detected here for drag logic)
  local left_released = r.ImGui_IsMouseReleased(ctx, 0)

  if hovered and left_clicked and not state.is_dragging then
    -- Arm a press; do not start drag-audition until the mouse actually moves
    state.map_press_x = mx
    state.map_press_y = my
    state.map_press_pending = true
    state.map_audition_rearm = false
    state.is_left_dragging = false
    state.last_dragged_sample_path = nil
  elseif left_released then
    -- End left drag; cleanup happens in complete_pending_sample_drop()
  end

  update_map_audition_drag(mx, my)
  
  -- Handle mouse wheel zoom
  if hovered and not state.is_dragging then
    local wheel = r.ImGui_GetMouseWheel(ctx)
    if wheel ~= 0 then
      local old_zoom = state.zoom
      -- Multiplicative zoom so high magnification is reachable without dozens of wheel ticks
      local new_zoom = math.max(MAP_ZOOM_MIN, math.min(MAP_ZOOM_MAX, state.zoom * math.exp(wheel * 0.15)))
      
      -- Calculate mouse position relative to map area center
      local mouse_rel_x = mx - (x0 + width * 0.5)
      local mouse_rel_y = my - (y0 + height * 0.5)
      
      -- Calculate what normalized map coordinate (0-1) the mouse is over
      -- Current transformation: px = center_x + (base_x - width/2) * zoom
      -- Where base_x = s.x * width (normalized coord * width)
      -- So: px = center_x + (s.x * width - width/2) * zoom
      --     px = center_x + width * (s.x - 0.5) * zoom
      -- Reverse: s.x = ((px - center_x) / (width * zoom)) + 0.5
      
      local center_x = x0 + width * 0.5 + state.pan_x
      local center_y = y0 + height * 0.5 + state.pan_y
      
      -- Find normalized map coordinate under mouse
      local map_norm_x = ((mx - center_x) / (width * old_zoom)) + 0.5
      local map_norm_y = ((my - center_y) / (height * old_zoom)) + 0.5
      
      -- Update zoom
      state.zoom = new_zoom
      
      -- Adjust pan so the same normalized map coordinate stays under the mouse
      -- After zoom: mx = new_center_x + width * (map_norm_x - 0.5) * new_zoom
      -- Solve: new_center_x = mx - width * (map_norm_x - 0.5) * new_zoom
      local new_center_x = mx - width * (map_norm_x - 0.5) * new_zoom
      local new_center_y = my - height * (map_norm_y - 0.5) * new_zoom
      
      -- Convert back to pan offset
      state.pan_x = new_center_x - (x0 + width * 0.5)
      state.pan_y = new_center_y - (y0 + height * 0.5)

      -- Clamp pan position to prevent excessive panning
      local max_pan = width * 0.5 * state.zoom  -- Allow panning up to half screen width at current zoom
      state.pan_x = math.max(-max_pan, math.min(max_pan, state.pan_x))
      
      -- Clamp pan_y to prevent going beyond frequency boundaries (Y axis: 0 = top/20kHz, 1 = bottom/20Hz)
      local min_pan_y = height * 0.5 * (1 - state.zoom)   -- Can't pan up beyond Y=0 (20kHz at top)
      local max_pan_y = height * 0.5 * (state.zoom - 1)   -- Can't pan down beyond Y=1 (20Hz at bottom)
      state.pan_y = math.max(min_pan_y, math.min(max_pan_y, state.pan_y))
      -- Don't save during zoom - config is saved on script exit and after drag ends
    end
  end
end

function round_to_nice_map_freq(freq)
  if freq < 100.0 then
    return math.floor((freq + 5) / 10) * 10
  elseif freq < 500.0 then
    return math.floor((freq + 10) / 20) * 20
  elseif freq < 1000.0 then
    return math.floor((freq + 20) / 40) * 40
  elseif freq < 5000.0 then
    return math.floor((freq + 50) / 100) * 100
  else
    return math.floor((freq + 100) / 200) * 200
  end
end

function draw_map_grid(dl, x0, y0, width, height, padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y)
  -- Draw grid lines for frequency (horizontal) and time (vertical)
  if #state.samples > 0 and state.samples[1].x then
    local log10 = math.log(10)
    
    -- Use theoretical frequency range (20Hz-20kHz) for consistent grid
    local freq_min_log = math.log(20.0) / log10
    local freq_max_log = math.log(20000.0) / log10
    
    -- Calculate duration range from samples for X-axis grid (cached with filter rebuild)
    local len_min_log, len_max_log = nil, nil
    if map_cache.duration_min and map_cache.duration_max then
      len_min_log = math.log(math.max(map_cache.duration_min, 0.01)) / log10
      len_max_log = math.log(math.max(map_cache.duration_max, 0.01)) / log10
    end
    
    -- Use reasonable defaults for duration if no samples
    if not len_min_log then
      len_min_log = math.log(0.01) / log10  -- 10ms
      len_max_log = math.log(60.0) / log10   -- 60 seconds
    end
    
    -- Subtle grid color (semi-transparent gray)
    local grid_color = 0x40404040  -- RRGGBBAA: gray with ~25% opacity
    local text_color = 0x80808080  -- RRGGBBAA: lighter gray with ~50% opacity for text
    
    -- Draw evenly spaced horizontal frequency grid lines
    -- Generate evenly spaced normalized Y positions (every 10% = 0.1)
    local num_freq_lines = 10  -- 10 evenly spaced lines
    for i = 0, num_freq_lines do
      local normalized_y = i / num_freq_lines  -- 0.0 to 1.0, evenly spaced
      
      -- Convert normalized Y back to frequency (inverse of layout transform)
      -- normalized_y = 1.0 - y_normalized, so y_normalized = 1.0 - normalized_y
      local y_normalized = 1.0 - normalized_y
      local freq_log = freq_min_log + y_normalized * (freq_max_log - freq_min_log)
      local freq_val = 10 ^ freq_log
      
      -- Convert normalized Y to screen coordinate (using padded area)
      local base_y = normalized_y * padded_height
      local py = padded_center_y + (base_y - padded_height * 0.5) * state.zoom
      
      -- Only draw if line is visible in viewport
      if py >= padded_y0 - 1 and py <= padded_y0 + padded_height + 1 then
        -- Draw line across padded area (from label padding to right edge)
        r.ImGui_DrawList_AddLine(dl, padded_x0, py, x0 + width, py, grid_color, 1.0)
        
        -- Round frequency to nice round number for display
        local rounded_freq = round_to_nice_map_freq(freq_val)
        
        -- Add text label for frequency
        local freq_text
        if rounded_freq >= 1000.0 then
          freq_text = string.format("%.1fkHz", rounded_freq / 1000.0)
        else
          freq_text = string.format("%.0fHz", rounded_freq)
        end
        -- Draw text at left edge, slightly offset from line
        r.ImGui_DrawList_AddText(dl, x0 + 4, py - 7, text_color, freq_text)
      end
    end
    
    -- Draw vertical time/duration grid lines (seconds)
    local duration_min, duration_max = map_cache.duration_min, map_cache.duration_max
    
    if duration_min and duration_max then
      -- Draw evenly spaced vertical time/duration grid lines
      -- Generate evenly spaced normalized X positions (every 10% = 0.1, accounting for 5% padding)
      local padding = 0.05
      local num_time_lines = 10  -- 10 evenly spaced lines
      for i = 0, num_time_lines do
        -- Map i from 0-num_time_lines to normalized_x accounting for padding
        local normalized_x = padding + (i / num_time_lines) * (1.0 - 2.0 * padding)
        
        -- Convert normalized X back to duration (inverse of layout transform)
        local len_log = len_min_log + ((normalized_x - padding) / (1.0 - 2.0 * padding)) * (len_max_log - len_min_log)
        local time_val = 10 ^ len_log
        
        -- Convert normalized X to screen coordinate (using padded area)
        local base_x = normalized_x * padded_width
        local px = padded_center_x + (base_x - padded_width * 0.5) * state.zoom
        
        -- Only draw if line is visible in viewport
        if px >= padded_x0 - 1 and px <= padded_x0 + padded_width + 1 then
          -- Draw line across padded area (from label padding to bottom edge)
          r.ImGui_DrawList_AddLine(dl, px, padded_y0, px, y0 + height, grid_color, 1.0)
          
          -- Add text label for time
          local time_text
          if time_val < 1.0 then
            time_text = string.format("%.1fs", time_val)
          elseif time_val < 10.0 then
            time_text = string.format("%.1fs", time_val)
          else
            time_text = string.format("%.0fs", time_val)
          end
          -- Draw text at top edge, slightly offset from line
          r.ImGui_DrawList_AddText(dl, px + 4, y0 + 4, text_color, time_text)
        end
      end
    end
  end
end

function render_map_samples(dl, hovered, mx, my, padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y)
  local dot_radius = state.dot_radius or 2.0
  local clicked_sample = nil
  local click_handled_this_frame = false

  local outline_color = build_color_rrgbbaa(extract_rgb(state.dot_outline_color or 0xFF00FF))
  local hover_color = build_color_rrgbbaa(extract_rgb(state.dot_hover_color or 0xC84D))
  local outline_size = state.dot_outline_size or 4.0

  if #state.samples > 0 and not state.samples[1].x then
    log("WARNING: Samples found but not laid out yet. Count: " .. #state.samples)
    return nil
  end

  local max_radius = math.max(dot_radius * 5.0 + dot_radius * 5.0 * 0.3, dot_radius + outline_size)
  local _, _, cache = ensure_map_render_cache(
    padded_x0, padded_y0, padded_width, padded_height,
    padded_center_x, padded_center_y, max_radius + 8.0
  )
  local entries = cache.draw_entries or {}
  local playing_path = preview_sample_obj and preview_sample_obj.path or nil
  local zoom = state.zoom or 1.0
  -- Fewer polygon segments when zoomed out (many dots); smoother when zoomed in
  local segments = (zoom < 1.4) and 6 or 10

  local playing_entry = nil
  local assigned_entries = {}
  local assigned_info = seq_assigned_sample_info()
  for i = 1, #entries do
    local e = entries[i]
    local s = e.s
    local is_playing = playing_path and s.path == playing_path and not e.unavailable
    local assigned = assigned_info[s.path]
    if is_playing then
      playing_entry = e
    elseif assigned and not e.unavailable then
      assigned_entries[#assigned_entries + 1] = { e = e, info = assigned }
    else
      r.ImGui_DrawList_AddCircleFilled(dl, e.px, e.py, dot_radius, e.color, segments)
    end
  end

  -- Sequencer-assigned samples: larger fill + ring so they stay visible in the map
  local assigned_ring = 0xE8F4FFFF
  local selected_ring = 0x4DE8FFFF
  for i = 1, #assigned_entries do
    local item = assigned_entries[i]
    local e = item.e
    local assigned_r = dot_radius * 1.85
    r.ImGui_DrawList_AddCircleFilled(dl, e.px, e.py, assigned_r, e.color, 12)
    r.ImGui_DrawList_AddCircle(dl, e.px, e.py, assigned_r + 2.4, assigned_ring, 12, 1.8)
    if item.info.selected then
      r.ImGui_DrawList_AddCircle(dl, e.px, e.py, assigned_r + 5.0, selected_ring, 12, 2.0)
    end
  end

  -- Selected / playing sample drawn last (cheap pulse: 2 rings, not concentric glow stack)
  if playing_entry then
    local e = playing_entry
    local selected_dot_radius = dot_radius * 2
    if not state.breathing_start_time then
      state.breathing_start_time = r.time_precise()
    end
    local elapsed = r.time_precise() - state.breathing_start_time
    local pulse = 0.85 + 0.15 * math.sin((elapsed % 1.5) / 1.5 * 2.0 * math.pi)
    local ring_r = (selected_dot_radius + outline_size) * pulse
    r.ImGui_DrawList_AddCircleFilled(dl, e.px, e.py, selected_dot_radius, e.color, 16)
    local playing_assigned = assigned_info[e.s.path]
    if playing_assigned then
      r.ImGui_DrawList_AddCircle(dl, e.px, e.py, selected_dot_radius + 3.0, assigned_ring, 16, 1.8)
      if playing_assigned.selected then
        r.ImGui_DrawList_AddCircle(dl, e.px, e.py, selected_dot_radius + 6.0, selected_ring, 16, 2.0)
      end
    end
    r.ImGui_DrawList_AddCircle(dl, e.px, e.py, ring_r, outline_color, 16, state.dot_outline_thickness or 3.0)
    r.ImGui_DrawList_AddCircle(dl, e.px, e.py, ring_r * 1.35, (e.color & 0xFFFFFF00) | 0x55, 12, 1.5)
  end

  local closest = nil
  if hovered then
    local hit_radius_sq = dot_radius * dot_radius * (state.dot_detection_multiplier or 16.0)
    for i = 1, #entries do
      local e = entries[i]
      if not e.unavailable then
        local dx = mx - e.px
        local dy = my - e.py
        local dist_sq = dx * dx + dy * dy
        if dist_sq <= hit_radius_sq and (not closest or dist_sq < closest.dist_sq) then
          closest = { sample = e.s, px = e.px, py = e.py, dist_sq = dist_sq, color = e.color }
        end
      end
    end
  end

  if closest then
    local s = closest.sample
    local px, py = closest.px, closest.py
    local is_currently_playing = playing_path and playing_path == s.path

    if not is_currently_playing then
      r.ImGui_DrawList_AddCircle(dl, px, py, dot_radius + 2.0, closest.color, 12, 1.5)
    end
    r.ImGui_DrawList_AddCircle(dl, px, py, dot_radius + 1.5, s.hot_color or hover_color, 12, 1.5)

    r.ImGui_BeginTooltip(ctx)
    r.ImGui_Text(ctx, s.name)
    if s.tags and #s.tags > 0 then
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 4, 3)
      r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 4, 2)
      local max_row_w = 280
      local row_w = 0
      for idx, tag in ipairs(s.tags) do
        local chip_w = calc_tag_chip_width(tag)
        if idx > 1 then
          local spacing = 4
          if row_w + spacing + chip_w <= max_row_w then
            r.ImGui_SameLine(ctx, 0, spacing)
            row_w = row_w + spacing + chip_w
          else
            row_w = chip_w
          end
        else
          row_w = chip_w
        end
        draw_tag_button(ctx, tag, true, tag, "map_dot_tip_" .. tostring(idx) .. "_")
      end
      r.ImGui_PopStyleVar(ctx, 2)
    end
    r.ImGui_EndTooltip(ctx)

    if not click_handled_this_frame and r.ImGui_IsMouseClicked(ctx, 0) then
      if is_alt_down() then
        state.pending_waveform_drop = s
        state.is_left_dragging = false
        state.last_dragged_sample_path = nil
        clear_map_left_press()
        click_handled_this_frame = true
      elseif state.seq_swap_track_id then
        local slot = get_active_swap_slot()
        if slot and assign_sample_to_seq_track(slot, s, false) then
          preview_sample(s)
        end
        state.block_swap_bar_input = true
        click_handled_this_frame = true
      else
        clicked_sample = s
        click_handled_this_frame = true
        state.last_dragged_sample_path = s.path
      end
    elseif state.is_left_dragging and not state.pending_waveform_drop and s.path ~= state.last_dragged_sample_path then
      clicked_sample = s
      state.last_dragged_sample_path = s.path
    end
  end

  return clicked_sample
end

function draw_map_scan_progress_overlay(dl, x0, y0, width, height)
  local file_scanning = #state.scan_queue > 0
  local analyzing = (state.incomplete_analysis_total or 0) > 0
      and state.scan_started > 0
      and #state.scan_queue == 0
      and (#state.analyzer_queue > 0 or #state.active_processes > 0)

  if not file_scanning and not analyzing then
    return
  end

  local done, total, elapsed, label
  if file_scanning then
    done = state.scan_total - #state.scan_queue
    total = state.scan_total
    elapsed = r.time_precise() - state.scan_started
    label = "Scanning"
  else
    local remaining = #state.analyzer_queue + #state.active_processes
    total = math.max(state.incomplete_analysis_total or 0, remaining)
    done = math.max(0, total - remaining)
    elapsed = r.time_precise() - state.scan_started
    label = state.analyzer_job_label or "Analyzing incomplete"
  end
  local progress = total > 0 and (done / total) or 0.0

  -- Draw semi-transparent overlay background at the top of the map
  local overlay_height = 70.0
  local overlay_y = y0
  local overlay_bg_color = 0x000000CC  -- Semi-transparent black (RRGGBBAA format, last two digits are alpha)
  r.ImGui_DrawList_AddRectFilled(dl, x0, overlay_y, x0 + width, overlay_y + overlay_height, overlay_bg_color, 0, 0)

  -- Draw progress bar at the top of the map
  local bar_padding = 20.0
  local bar_y = overlay_y + 25.0
  local bar_width = width - (bar_padding * 2)
  local bar_height = 8.0

  -- Progress text (centered above bar)
  local text = string.format("%s: %.1f%% (%d/%d) - %.1fs", label, progress * 100.0, done, total, elapsed)
  local text_size_x, text_size_y = r.ImGui_CalcTextSize(ctx, text)
  local text_x = x0 + (width - text_size_x) * 0.5
  local text_y = overlay_y + 8.0
  -- Draw text with shadow for better visibility
  r.ImGui_DrawList_AddText(dl, text_x + 1, text_y + 1, 0x000000FF, text)
  r.ImGui_DrawList_AddText(dl, text_x, text_y, 0xFFFFFFFF, text)

  -- Background bar (dark gray)
  local bar_bg_color = 0x2A2A2AFF
  r.ImGui_DrawList_AddRectFilled(dl, x0 + bar_padding, bar_y, x0 + bar_padding + bar_width, bar_y + bar_height, bar_bg_color, 4.0, 0)

  -- Progress fill (bright green)
  local fill_width = bar_width * math.max(0.0, math.min(1.0, progress))
  if fill_width > 2.0 then
    local fill_color = 0x00FF00FF
    r.ImGui_DrawList_AddRectFilled(dl, x0 + bar_padding + 2, bar_y + 2, x0 + bar_padding + fill_width - 2, bar_y + bar_height - 2, fill_color, 2.0, 0)
  end

  -- Border (white)
  local border_color = 0xFFFFFFFF
  r.ImGui_DrawList_AddRect(dl, x0 + bar_padding, bar_y, x0 + bar_padding + bar_width, bar_y + bar_height, border_color, 4.0, 0, 1.5)

  -- Estimate time remaining (below bar)
  local remaining_count = file_scanning and #state.scan_queue or (#state.analyzer_queue + #state.active_processes)
  if done > 0 and elapsed > 0.1 and remaining_count > 0 then
    local rate = done / elapsed
    local remaining = remaining_count / rate
    if remaining > 0 then
      local remaining_text = string.format("Estimated time remaining: %.1fs", remaining)
      local remaining_size_x, remaining_size_y = r.ImGui_CalcTextSize(ctx, remaining_text)
      local remaining_x = x0 + (width - remaining_size_x) * 0.5
      local remaining_y = bar_y + bar_height + 8.0
      r.ImGui_DrawList_AddText(dl, remaining_x + 1, remaining_y + 1, 0x000000FF, remaining_text)
      r.ImGui_DrawList_AddText(dl, remaining_x, remaining_y, 0xCCCCCCFF, remaining_text)
    end
  end
end


function render_map()
  local avail_x, avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local width = math.max(0, avail_x)
  local height = math.max(0, avail_y)
  if width <= 0 or height <= 0 then
    return
  end

  local x0, y0 = r.ImGui_GetCursorScreenPos(ctx)

  r.ImGui_InvisibleButton(ctx, "map_area", width, height)
  local hovered = r.ImGui_IsItemHovered(ctx)
  local dl = r.ImGui_GetWindowDrawList(ctx)
  local mx, my = r.ImGui_GetMousePos(ctx)

  handle_map_view_input(hovered, mx, my, width, height, x0, y0)

  r.ImGui_DrawList_AddRectFilled(dl, x0, y0, x0 + width, y0 + height, UI_THEME.bg, 6)

  local label_padding_left = 70
  local label_padding_top = 25
  local padded_x0 = x0 + label_padding_left
  local padded_y0 = y0 + label_padding_top
  local padded_width = width - label_padding_left
  local padded_height = height - label_padding_top
  local padded_center_x = padded_x0 + padded_width * 0.5 + state.pan_x
  local padded_center_y = padded_y0 + padded_height * 0.5 + state.pan_y

  if map_cache.filter_key ~= compute_map_filter_key() or not map_cache.spatial then
    rebuild_map_filtered_cache()
  end

  draw_map_grid(dl, x0, y0, width, height, padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y)

  local clicked_sample = render_map_samples(dl, hovered, mx, my, padded_x0, padded_y0, padded_width, padded_height, padded_center_x, padded_center_y)
  if clicked_sample and not sample_scan_folder_unavailable(clicked_sample) then
    local was_drag_audition = state.is_left_dragging
    preview_sample(clicked_sample)
    if not was_drag_audition then
      -- preview_sample can block on a slow disk. Recapture the drag origin on
      -- the next frame so movement during that wait is not treated as a drag.
      state.map_audition_rearm = true
      state.is_left_dragging = false
    end
  end

  if state.pending_waveform_drop then
    r.ImGui_SetMouseCursor(ctx, r.ImGui_MouseCursor_Hand())
    update_pending_drop_tracking()
  end

  draw_map_scan_progress_overlay(dl, x0, y0, width, height)
  draw_map_status_overlay(dl, x0, y0, width, height)
end


function render_library_loading_view()
  local job = state.library_load
  local msg = (job and job.message) or "Loading sample library…"
  local progress = (job and job.progress) or 0

  local _, avail_y = r.ImGui_GetContentRegionAvail(ctx)
  local child_flags = 0
  if r.ImGui_ChildFlags_Border then
    child_flags = r.ImGui_ChildFlags_Border
  end

  local loading_open = r.ImGui_BeginChild(ctx, "library_loading", 0, avail_y, child_flags)
  if loading_open then
    local avail_x, inner_y = r.ImGui_GetContentRegionAvail(ctx)
    local bar_w = math.min(420, math.max(180, avail_x - 80))
    local bar_h = 8
    local text_w = select(1, r.ImGui_CalcTextSize(ctx, msg))
    local block_h = 54
    local start_y = math.max(24, (inner_y - block_h) * 0.35)
    r.ImGui_SetCursorPos(ctx, math.max(20, (avail_x - text_w) * 0.5), start_y)
    r.ImGui_TextColored(ctx, UI_THEME.text_dim, msg)
    r.ImGui_SetCursorPos(ctx, math.max(20, (avail_x - bar_w) * 0.5), start_y + 28)
    local bx, by = r.ImGui_GetCursorScreenPos(ctx)
    local dl = r.ImGui_GetWindowDrawList(ctx)
    ui_draw_panel(dl, bx, by, bx + bar_w, by + bar_h, 4.0, UI_THEME.surface, UI_THEME.border, false, false)
    local fill_w = math.max(0, math.min(bar_w, bar_w * progress))
    if fill_w > 2 then
      r.ImGui_DrawList_AddRectFilled(dl, bx + 1, by + 1, bx + fill_w - 1, by + bar_h - 1, UI_THEME.accent, 3.0)
    end
    r.ImGui_Dummy(ctx, bar_w, bar_h)
    local sub = "Preparing the map — first run builds a faster cache for next launch"
    local sub_w = select(1, r.ImGui_CalcTextSize(ctx, sub))
    r.ImGui_SetCursorPos(ctx, math.max(20, (avail_x - sub_w) * 0.5), start_y + 48)
    r.ImGui_TextColored(ctx, UI_THEME.text_mute, sub)
  end
  r.ImGui_EndChild(ctx)
end


-- --- Main loop ---------------------------------------------------------------
function loop()
  if not running then
    return
  end
  
  if not r.ImGui_ValidatePtr(ctx, "ImGui_Context*") then
    log("ImGui context invalid; stopping loop")
    running = false
    return
  end
  
  stop_preview_if_transport_started()
  sync_project_state_if_needed()
  ingest_seq_from_arrange()
  if state.seq_random_sync_run and not state.seq_random_knob_drag then
    state.seq_random_sync_run = false
    seq_flush_pending_random_sync()
  end

  local loading = is_library_loading()
  if loading then
    process_library_load_slice(LIBRARY_LOAD_SLICE_MS)
    loading = is_library_loading()
  end

  -- Start scan after a miss, but defer cache rewrite until after first interactive frame.
  if state._enqueue_scan_after_load then
    state._enqueue_scan_after_load = false
    enqueue_scan()
  end

  if not loading then
    process_scan_slice()
    process_waveform_slice(6.0)

    -- Poll removable-drive mount state so dots gray/restore without restarting.
    local now = r.time_precise()
    if (now - (state.last_volume_check_time or 0)) >= 1.5 then
      refresh_scan_folder_availability()
    end
    seq_midi_poll()
  end
  
  ui_push_theme()
  local visible, open, began = false, true, false
  local ui_ok, ui_err = pcall(function()
  visible, open, began = begin_window()
  if visible then
    if r.ImGui_GetWindowPos and r.ImGui_GetWindowSize then
      local wx, wy = r.ImGui_GetWindowPos(ctx)
      local ww, wh = r.ImGui_GetWindowSize(ctx)
      state.main_window_rect = { x = wx, y = wy, w = ww, h = wh }
    end
    state.block_swap_bar_input = false
    state.seq_drop_target_idx = nil
    state.seq_timeline_drop_track_idx = nil
    state.seq_timeline_drop_time = nil

    if loading then
      render_library_loading_view()
    else
      -- Handle keyboard input for history navigation (only when window is visible)
      if r.ImGui_IsKeyPressed and r.ImGui_Key_UpArrow and r.ImGui_Key_DownArrow then
        local up_pressed = r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_UpArrow(), false)
        local down_pressed = r.ImGui_IsKeyPressed(ctx, r.ImGui_Key_DownArrow(), false)

        if up_pressed then
          navigate_history(1)   -- Go back in history to older samples (up arrow increases index)
        elseif down_pressed then
          navigate_history(-1)  -- Go forward in history to newer samples (down arrow decreases index)
        end
      end

      render_header()

      handle_script_keyboard_shortcuts()
      stop_preview_if_transport_started()

      local _, avail_y = r.ImGui_GetContentRegionAvail(ctx)

      local child_flags = 0
      if r.ImGui_ChildFlags_Border then
        child_flags = r.ImGui_ChildFlags_Border
      end
      local no_scroll_flags = r.ImGui_WindowFlags_NoScrollbar() | r.ImGui_WindowFlags_NoScrollWithMouse()

      local main_open = r.ImGui_BeginChild(ctx, "main_content", 0, avail_y, child_flags)
      if main_open then
        r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_ItemSpacing(), 4, 3)
        r.ImGui_PushStyleVar(ctx, r.ImGui_StyleVar_FramePadding(), 5, 3)
        render_view_tab_switcher()

        if state.active_view == "sample_map" then
          r.ImGui_SameLine(ctx, 0, 10)
          render_filter_input()
          render_tag_filters()
        elseif state.active_view == "sequencer" then
          r.ImGui_SameLine(ctx, 0, 10)
          render_seq_top_toolbar()
        end
        r.ImGui_PopStyleVar(ctx, 2)

        if state.active_view == "sample_map" then
          local panel_width = state.seq_panel_width or 240
          local _, tab_avail_y = r.ImGui_GetContentRegionAvail(ctx)
          local tracks_open = r.ImGui_BeginChild(ctx, "sample_map_seq_tracks", panel_width, math.max(0, tab_avail_y), child_flags)
          if tracks_open then
            render_seq_tracks_panel()
          end
          r.ImGui_EndChild(ctx)
          r.ImGui_SameLine(ctx)
          local right_open = r.ImGui_BeginChild(ctx, "sample_map_right_column", 0, math.max(0, tab_avail_y), child_flags)
          if right_open then
            render_waveform()
            render_swap_mode_bar()
            local _, map_avail_y = r.ImGui_GetContentRegionAvail(ctx)
            local map_open = r.ImGui_BeginChild(ctx, "sample_map_area", 0, math.max(0, map_avail_y), child_flags, no_scroll_flags)
            if map_open then
              render_map()
            end
            r.ImGui_EndChild(ctx)
          end
          r.ImGui_EndChild(ctx)
        elseif state.active_view == "sequencer" then
          render_sequencer_map()
        end
      end
      r.ImGui_EndChild(ctx)

      draw_sample_drag_ghost()
      render_seq_layering_window()
      complete_pending_sample_drop()
    end
  end
  end)
  end_window(visible, began)
  if ui_ok and not loading then
    pcall(render_settings)
  elseif not ui_ok then
    log("ImGui frame skipped during window host change: " .. tostring(ui_err))
  end
  pcall(ui_pop_theme)

  if (not loading) and running then
    pcall(seq_update_arrange_item_follow)
    pcall(seq_render_arrange_item_overlay)
    pcall(seq_pump_script_refocus)
  end

  -- Migrate/stamp cache after the first ready frame so load UI stays smooth.
  if (not loading) and state._save_library_after_load then
    state._save_library_after_load = false
    save_samples()
    state.tag_schema_dirty = false
  end
  
  if (open ~= false) and running then
    r.defer(loop)
  else
    running = false
    stop_preview()
    seq_midi_stop_all_voices()

    -- Cancel any in-flight drag so we never leave a provisional item or tooltip behind.
    remove_provisional_drop()
    clear_drag_tooltip()

    -- Cleanup: Close all open analyzer pipes to prevent file handle leaks
    for i = #state.active_processes, 1, -1 do
      local proc = state.active_processes[i]
      if proc and proc.pipe then
        local close_ok, close_err = pcall(function() return proc.pipe:close() end)
        if not close_ok then
          log("Warning: failed to close pipe during cleanup: " .. tostring(close_err))
        end
      end
    end
    state.active_processes = {}
    
    -- Save samples before closing (to preserve scan progress)
    if #state.samples > 0 or #state.scan_queue > 0 then
      save_samples()
    end
    -- Try to destroy context if function exists
    if ctx and r.ImGui_ValidatePtr(ctx, "ImGui_Context*") then
      if r.APIExists("ImGui_DestroyContext") then
        r.ImGui_DestroyContext(ctx)
      end
    end
    ctx = nil
    seq_destroy_arrange_overlay_ctx()
    save_config()
  end
end


-- --- Main entry point --------------------------------------------------------
function main()
  log("Starting Sample Map Browser...")
  
  load_config()
  sync_project_state_if_needed()

  ctx = r.ImGui_CreateContext(SCRIPT_NAME, r.ImGui_ConfigFlags_DockingEnable())
  font = r.ImGui_CreateFont("sans-serif", 16)
  if font then
    r.ImGui_Attach(ctx, font)
  end
  ensure_seq_role_icons()
  ensure_vfx_icons()

  begin_library_load()
  log("ImGui context created; loading library asynchronously")
  loop()
end

main()



